\section{STABILITY ANALYSIS}

\subsection{The Basic State}
The steady-state solutions of Eqs.~(\ref{16})–(\ref{18}) and Eq.~(\ref{20}) subject to the boundary conditions must satisfy the following conditions
\begin{equation}\label{25}
\psi = 0, \quad \zeta = 0, \quad \boldsymbol{u} = 0, \quad n = n_b(z) \quad \text{and} \quad I = I_b(z,\theta)
\end{equation}
The total intensity \(G_b(z)\) and the radiative heat flux \(\boldsymbol{q_b}(z)\) in the steady state are given by
\begin{equation}\label{26}
	G_b(z) = \int_{0}^{4\pi} I_b(z,\theta) d \Omega \quad \text{and} \quad \boldsymbol{q_b}(z) = \int_{0}^{4\pi} I_b(z,\theta) \boldsymbol{s} d \Omega.
\end{equation} 
Since \(I_b(z,\theta)\) is independent of \(\phi\), so that the horizontal component of \(\boldsymbol{q_b}\) is zero. Therefore, \(\boldsymbol{q_b} = - q_b \hat{\boldsymbol{z}}\), where \(q_b = |\boldsymbol{q_b}|\).

The equation govern light intensity \(I_b(z,\theta)\) in the steady state is  
\begin{equation}\label{27}
	\nu \frac{\partial I_b}{\partial z} + \tau_H n_b(z) I_b(z,\theta) = \frac{\omega \tau_H n_b(z)}{4\pi}[G_b(z)-A\nu q_b(z)]
\end{equation}
We decompose the light intensity \(I_b(z,\theta)\) into two parts: the collimated component of the irradiation denoted by \(I_b^c(z,\theta)\) and the diffused part \(I_b^d(z,\theta)\), i.e., \(I_b(z,\theta) = I_b^c(z,\theta)+I_b^d(z,\theta)\). Then, the collimated part satisfies 
\begin{align}\label{28}
 	\frac{\partial I_b^{c}(z,\theta)}{\partial z} + \frac{\tau_H n_b(z)}{\nu} I_b^{c}(z,\theta) = 0
\end{align}
subject to the top boundary condition 
\begin{equation}\label{29}
 	I_b^{c}(1,\theta) =  \delta\,(\cos\theta+\cos\theta_0) \delta\, (\phi-\phi_0)
\end{equation}
On solving Eqs.~(\ref{28}) and (\ref{29}), we obtain
\begin{equation}\label{30}
	I_b^{c} = \exp\left(\int_{z}^{1}\frac{\tau_H n_b(z')}{\cos\theta} dz'\right) \delta\,(\cos\theta+\cos\theta_0) \delta\, (\phi-\phi_0)
\end{equation}
The governing equation for diffused part \(I_b^{d}(z,\theta)\) of the basic state light intensity  satisfies 
\begin{equation}\label{31}
	  \frac{\partial I_b^d}{\partial z} + \frac{\tau_H n_b(z)}{\nu} I_b^d(z,\theta) = \frac{\omega \tau_H n_b(z)}{4\pi \nu} [G_b(z) - A\nu q_b(z)]
\end{equation}
with boundary conditions 
\begin{equation}\label{32}
	\left.
	\begin{aligned}
		I_b^d(1,\theta) &= 0, && \pi/2 \leq \theta \leq \pi,\  \\
		I_b^d(0,\theta) &= 0, && 0 \leq \theta \leq \pi/2,\ 
	\end{aligned}
	\right\}
\end{equation}
The total intensity \(G_b(z)\) and radiative heat flux \(\boldsymbol{q_b}(z)\) is expressed as the sum of the collimated and diffused parts
\begin{equation}\label{33}
	G_b(z) = G_b^c(z) + G_b^d(z) \quad \text{and} \quad \boldsymbol{q_b}(z) = \boldsymbol{q_b}^c(z) + \boldsymbol{q_b}^d(z)
\end{equation}  
From Eq.~(\ref{30}), we get
\begin{equation}\label{34}
	G_b^{c} = \int_{0}^{4\pi} I_b^{c}(z,\theta) d\Omega = \exp\left(-\int_{z}^{1}\frac{\tau_H n_b(z')}{\cos\theta_0} dz'\right)
\end{equation}
and
\begin{equation}\label{35}
	\boldsymbol{q_b}^{c} = \int_{0}^{4\pi} I_b^{c}(z,\theta) \boldsymbol{s} d\Omega = -\cos \theta_0 \exp\left(-\int_{z}^{1}\frac{\tau_H n_b(z')}{\cos\theta_0} dz'\right)\hat{\boldsymbol{z}}
\end{equation}
The diffused part of basic total light intensity \(G_b(z)\) and radiative heat flux \(\boldsymbol{q_b}(z)\) satisfies 
\begin{equation}\label{36}
	G_b^{d} = \int_{0}^{4\pi} I_b^{d}(z,\theta) d\Omega, \quad \text{and} \quad \boldsymbol{q_b}^{d} = \int_{0}^{4\pi} I_b^{d}(z,\theta) \boldsymbol{s} d\Omega
\end{equation}
Now, we define a new variable 
\begin{equation}\label{37}
	\tau = \int_{z}^{1}\tau_H n_b(z') dz'
\end{equation}	
In terms of the variable \(\tau\), Eq.~(\ref{31}) for the outgoing \((0 \leq \theta \leq \pi/2)\) light intensity, \(I_b^{d^+}(\tau,\nu)\), is written as
\begin{equation}\label{38}
	\frac{\partial I_b^{d^+}}{\partial\tau} - \frac{1}{\nu} I_b^{d^+}(\tau
	,\nu) = -\frac{\omega}{4\pi \nu}[G_b(\tau)-A \,q_b(\tau) \nu], \quad 0 \leq \nu \leq 1	
\end{equation}
with boundary condition
\begin{equation}\label{39}
	I_b^{d^+}(\tau_H,\nu) =  0, \quad 0 \leq \nu \leq 1.
\end{equation}
Solving Eqs.~(\ref{38}) and (\ref{39}), we get
\begin{equation}\label{40}
	 I_b^{d^+}(\tau,\nu) = -\frac{\omega}{4\pi\nu}\int_{\tau_H}^{\tau}e^{(\tau-\tau')/\nu}[G_b(\tau')-A q_b(\tau') \nu]  d\tau', \quad 0 \leq \nu \leq 1	
\end{equation}
Similarly, the incoming \((\pi/2 \leq \theta \leq \pi)\) light intensity, \(I_b^{d^-}(\tau,\nu)\) is given by
\begin{equation}\label{41}
	I_b^{d^-}(\tau,\nu) = -\frac{\omega}{4\pi\nu}\int_{0}^{\tau}e^{(\tau-\tau')/\nu}[G_b(\tau')-A\, q_b(\tau') \nu]  d\tau', \quad -1 \leq \nu \leq 0	
\end{equation}
Substituting the Eqs.~(\ref{40}) and (\ref{41}) into Eq.~(\ref{33}), we get two coupled Fredholm integral equations 
\begin{align}\label{42}
	G_b(\tau) = e^{(-\tau/\cos\theta_0)} +  \frac{\omega}{2}\int_{0}^{\tau_H}[G_b(\tau')E_1(|\tau-\tau'|)+A\,sgn(\tau-\tau')q_b(\tau')E_2(|\tau-\tau'|)]d\tau'
\end{align}
\begin{align}\label{43}
	q_b(\tau) = \cos\theta_0 e^{(-\tau/\cos\theta_0)} + \frac{\omega}{2}\int_{0}^{\tau_H}[A\,q_b(\tau')E_3(|\tau-\tau'|)+sgn(\tau-\tau')G_b(\tau')E_2(|\tau-\tau'|)]d\tau'
\end{align}
where, `\(sgn(x)\)' is the sign function and \(E_n(x)\) is the exponential integral function of order \(n\).
Eqs.~(\ref{42}) and (\ref{43}) are solved using the subtraction of singularity method.
From Eq.~(\ref{11}), the average swimming direction in the steady state becomes
\begin{equation}\label{44}
	\langle \boldsymbol{p_b} \rangle = -T(G_b) \frac{\boldsymbol{q}_b}{q_b} = T(G_b)\hat{\boldsymbol{z}}.
\end{equation}
so that the steady-state concentration \( n_b(z) \) satisfies the equation	
\begin{equation}\label{45}
	\frac{\ud n_b}{\ud z} - V_c T_b n_b = 0,
\end{equation}	
where \( T_b = T(G_b) \) represents the phototaxis function evaluated at steady-state light intensity \( G_b \).	    
Eq.~(\ref{45}) is supplemented by the cell conservation relation 
\begin{equation}\label{46}
	\int_0^1 n_b(z)(\boldsymbol{z}) = 1
\end{equation}	
Next, Eqs.~(\ref{42})-(\ref{46}) constitute a boundary value problem which is numerically solved by using a shooting method.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%	   

\subsection{Linear Stability Analysis}
To analyze the stability of the system, a small perturbation of amplitude \( \epsilon \) (where \( 0 < \epsilon \ll 1 \)) is introduced to the steady-state solution, leading to	
\begin{equation}\label{47}
	\begin{pmatrix}
		\psi \\ \zeta \\ \boldsymbol{u} \\ n \\ I
	\end{pmatrix}
		=
	\begin{pmatrix}
		0 + \epsilon \psi_1 + O(\epsilon^{2}) \\ 0 + \epsilon \zeta_1 + O(\epsilon^{2}) \\ 0 + \epsilon \boldsymbol{u}_1 + O(\epsilon^{2}) \\ n_b + \epsilon n_1 + O(\epsilon^{2}) \\ I_b + \epsilon I_1 + O(\epsilon^{2}) 
		\end{pmatrix},
\end{equation}	 

Substituting these perturbed quantities into Eqs.~(\ref{16})–(\ref{18}) and retaining only terms of order \( O(\epsilon) \) results in the following linearized system		
\begin{equation}\label{48}
	Sc^{-1} \frac{\partial (\boldsymbol{\nabla}^2 \psi_1)}{\partial t} = \boldsymbol{\nabla}^4 \psi_1 + R\,\frac{\partial n_1}{\partial x},
\end{equation}	
\begin{equation}\label{49}
	\frac{\partial n_1}{\partial t} + V_c \boldsymbol{\nabla} \cdot \left( \langle \boldsymbol{p_b} \rangle n_1 + \langle \boldsymbol{p_1} \rangle n_b \right) - \boldsymbol{\nabla}^2 n_1 = \frac{\partial \psi_1}{\partial x} \frac{\ud n_b}{\ud z}.
\end{equation}	
Let \(G_1\) be the total perturbed radiation intensity, i.e., \(G=G_b+\epsilon G_1 + O(\epsilon^2)\). Since \(G_b=G_b^{c}+G_b^{d}\), so that 
\begin{equation}\label{50}
	G=(G_b^{c}+\epsilon G_1^{c}) + (G_b^{d}+\epsilon G_1^{d}) + O(\epsilon^2)
\end{equation}
then, we have 
\begin{equation}\label{51}
	G_1 = G_1^{c} + G_1^{d}
\end{equation}
where
\begin{equation*}
	G_1^{c} = \left(\int_{1}^{z}\frac{\tau_H n_1}{\cos\theta_0} dz'\right) \exp\left(-\int_{z}^{1}\frac{\tau_H n_b(z')}{\cos\theta_0} dz'\right) \quad \text{and} \quad G_1^{d} = \int_{0}^{4\pi} I_1^{d}(\boldsymbol{x},\boldsymbol{s}) d\Omega
\end{equation*}	
Similarly, the radiative heat flux \(\boldsymbol{q}=\boldsymbol{q_b}+\epsilon \boldsymbol{q_1} + O(\epsilon^2)\), then the perturbed total radiative heat flux
\begin{equation}\label{52}
	\boldsymbol{q_1} = \boldsymbol{q_1}^{c} + \boldsymbol{q_1}^{d}
\end{equation}
where
\begin{equation*}
	\boldsymbol{q_1}^{c} = -\cos\theta_0 \left(\int_{1}^{z}\frac{\tau_H n_1}{\cos\theta_0} dz'\right) \exp\left(-\int_{z}^{1}\frac{\tau_H n_b(z')}{\cos\theta_0} dz'\right) \hat{\boldsymbol{z}} \quad \text{and} \quad \boldsymbol{q_1}^{d} = \int_{0}^{4\pi} I_1^{d}(\boldsymbol{x},\boldsymbol{s}) \boldsymbol{s} d\Omega
\end{equation*} 
After solving the expression 
\begin{equation*}
	-T(G_b+\epsilon G_1 + O(\epsilon^2)) \frac{\boldsymbol{q_b}+\epsilon \boldsymbol{q_1} + O(\epsilon^2)}{|\boldsymbol{q_b}+\epsilon \boldsymbol{q_1} + O(\epsilon^2)|} - T(G_b)\hat{\boldsymbol{z}},
\end{equation*}
the perturbed swimming orientation is 
\begin{equation}\label{53}
	\langle \boldsymbol{p_1} \rangle = G_1 \frac{\ud T_b}{\ud G} \hat{\boldsymbol{z}} - T(G_b) \frac{\boldsymbol{q_1}^{H}}{q_b}
\end{equation}
where \(\boldsymbol{q_1}^{H}\) is the horizontal component of the perturbed radiative heat flux \(\boldsymbol{q_1}\). 
Now, the Eqs.~(\ref{48}) and (\ref{49}) are simplified into a pair of equations involving \(\psi_1\) and \(n_1\) and these perturbed quantities can be decomposed into normal modes such that 
\begin{equation}\label{54}
	\psi_1 = \Psi(z)\,e^{\gamma \,t + ikx} \quad \text{and} \quad n_1 = \Theta(z)\, e^{\gamma \,t + ikx}
\end{equation}
where \(\gamma\) is the growth rate and \(k\) is the non-dimensional horizontal wave number.
The diffuse component of the perturbed intensity \(I_1^{d}\) satisfies
\begin{equation}\label{55}
	\xi \frac{\partial I_1^{d}}{\partial x} + \nu \frac{\partial I_1^{d}}{\partial z} + \tau_H n_b I_1^{d}(\boldsymbol{x},\boldsymbol{s}) = \frac{\omega \tau_H }{4\pi} \left( n_b G_1 + n_1 G_b + A \nu (n_b \boldsymbol{q_1} \cdot \hat{\boldsymbol{z}} - q_b n_1) \right) - \tau_H n_1 I_b
\end{equation}
subject to the boundary conditions 
\begin{equation}\label{56}
	\left.
	\begin{aligned}
		I_1^d(x, 1, \theta, \phi) &= 0, && \pi/2 \leq \theta \leq \pi,\ 0 \leq \phi \leq 2\pi \\
		I_1^d(x, 0, \theta, \phi) &= 0, && 0 \leq \theta \leq \pi/2,\ 0 \leq \phi \leq 2\pi
	\end{aligned}
	\right\}
\end{equation}
The perturbed intensity \(I_1^{d}\) can be represented by the following expression
\begin{equation}\label{57}
	I_1^{d} = \Phi^{d}(z,\xi,\nu) e^{(\gamma \,t + ikx)}
\end{equation}
From Eq.(\ref{51}), we get
\begin{equation}\label{58}
	G_1^{c} = \left(\frac{\tau_H}{\cos\theta_0}\int_{1}^{z}\Theta(z') dz'\right) \exp\left(-\frac{\tau_H}{\cos\theta_0}\int_{z}^{1} n_b(z') dz'\right) e^{(\gamma \,t + ikx)} = g_1^{c}(z) e^{(\gamma \,t + ikx)}
\end{equation}
and 
\begin{equation}\label{59}
	G_1^{d} = g_1^{d}(z) e^{(\gamma \,t + ikx)} = \left( \int_{0}^{4 \pi} \Phi^{d}(z,\xi,\nu) d \Omega \right) e^{(\gamma \,t + ikx)}
\end{equation}
Here, \(g_1(z)\) is the perturbed total intensity, expressed as the sum of \(g_1^{c}(z)\) and \(g_1^{d}(z)\). Similarly, from Eq.~(\ref{52}), we have
\begin{equation}\label{60}
	\boldsymbol{q_1} = (q_1^{x},q_1^{z}) = [P_x(z),P_z(z)] e^{(\gamma \,t + ikx)}
\end{equation}
where
\begin{equation}\label{61}
	P_x(z) = \int_{0}^{4 \pi} \Phi^{d}(z,\xi,\nu) \xi d \Omega \quad \text{and} \quad P_z(z) = -g_1^c(z) + \int_{0}^{4 \pi} \Phi^{d}(z,\xi,\nu) \nu d \Omega
\end{equation}
From Eq.~\ref{55} , \(\Phi^{d}\) satisfies 
\begin{equation}\label{62}
	\frac{d \Phi^{d}}{dz} + \frac{[ik \xi +  \tau_H n_b]}{\nu} \Phi^{d} = \frac{\omega \tau_H}{4 \pi} [n_b g_1 + G_b \Theta + A\, \nu (n_b P_z(z) - q_b \Theta)] - \frac{\tau_H}{\nu} I_b \Theta(z)
\end{equation}
with boundary conditions 
\begin{equation}\label{63}
	\left.
	\begin{aligned}
		\Phi^d(1, \xi, \nu) &= 0, && \pi/2 \leq \theta \leq \pi,\ 0 \leq \phi \leq 2\pi \\
		\Phi^d(0, \xi, \nu) &= 0, && 0 \leq \theta \leq \pi/2,\ 0 \leq \phi \leq 2\pi
	\end{aligned}
	\right\}
\end{equation}
Thus, the governing equations become	
\begin{equation}\label{64}
	 \left( \gamma \, S_c^{-1} + k^2 - \frac{\ud^2}{\ud z^2} \right) \left( \frac{\ud^2}{\ud z^2} - k^2 \right) \Psi(z) = R (ik) \Theta(z),	
\end{equation}
\begin{equation}\label{65}
	\left( \gamma  + k^2 - \frac{\ud^2}{\ud z^2} \right) \Theta + V_c \frac{\ud}{\ud z} \left( T_b\,\Theta + n_b \frac{\ud T_b}{\ud G} g_1 \right) - \frac{i k V_c n_b T_b P_x(z)}{q_b} = (ik) \frac{\ud n_b}{\ud z} \Psi(z)	
\end{equation}	
subject to the boundary conditions 	
\begin{equation}\label{66}
	\Psi = \frac{\ud \Psi}{\ud z}  = \frac{d\Theta}{dz} - V_c T_b \Theta - V_c \,n_b \frac{\ud T_b}{\ud G}\,g_1 = 0 \quad \text{on} \quad z = 0,
\end{equation}	
\begin{equation}\label{67}
	\Psi = \frac{\ud^2 \Psi}{\ud z^2} = \frac{d\Theta}{dz} - V_c T_b \Theta - V_c \,n_b \frac{\ud T_b}{\ud G}\,g_1 = 0 \quad \text{on} \quad z = 1.
\end{equation}
The system forms an eigenvalue problem for \( \gamma \), determining the stability of the perturbations.	Eq.~(\ref{65}) represents a linear integro-differential equation with non-constant coefficients arising from the functional form of \(g_1\) so that we introduce a new variable	
\begin{equation}\label{68}
	\varphi(z) = \int_1^z \Theta(z') dz'.
\end{equation}	
The perturbed equations, rewritten using \( D \equiv d/dz \), take the following form	
\begin{equation}\label{69}
	 ( \gamma \, S_c^{-1} + k^{2} - D^{2})( D^{2} - k^{2}) \Psi(z) = R (ik) D\varphi,	
\end{equation}
\begin{equation}\label{70}
	D^3\varphi - V_c T_b D^2\varphi - [\gamma + k^2 + \Gamma_3(z)] D\varphi - \Gamma_2(z) \varphi - \Gamma_1(z) = -(ik) Dn_b \Psi(z)
\end{equation}
where
\begin{equation*}
	\Gamma_1 = V_c \frac{\ud}{\ud z} \left(n_b \frac{\ud T_b}{\ud G} g_1^{d} \right) - \frac{i k V_c n_b T_b P_x(z)}{q_b},
\end{equation*}	
\begin{equation*}
	\Gamma_2 = (\tau_H/\cos\theta_0) V_c \frac{\ud}{\ud z} \left(n_b G_b^{c} \frac{\ud T_b}{\ud G} \right),
\end{equation*}	
\begin{equation*}
	\Gamma_3 = 2(\tau_H/\cos\theta_0) V_c n_b G_b^{c} \frac{\ud T_b}{\ud G} + V_c \frac{\ud T_b}{\ud G} \frac{\ud G_b^{d}}{\ud z}.
\end{equation*}	
The boundary conditions become
\begin{equation}\label{71}
	\Psi = D\Psi  = D^2\varphi - V_c T_b D\varphi - V_c \,n_b \frac{\ud T_b}{\ud G}\,g_1 = 0 \quad \text{on} \quad z = 0,
\end{equation}	
\begin{equation}\label{72}
	\Psi = D^2\Psi = D^2\varphi - V_c T_b D\varphi - V_c \,n_b \frac{\ud T_b}{\ud G}\,g_1 = 0 \quad \text{on} \quad z = 1.
\end{equation}
and there is an extra boundary condition	
\begin{equation}\label{73}
	\varphi(z) = 0 \quad \text{on} \quad z = 1.
\end{equation}
which directly follows from Eq.~(\ref{68}). \\
The system governed by Eqs.~(\ref{69})–(\ref{73}) forms an eigen-value problem for \(\gamma\), determining the stability of the disturbances. To analyze the linear stability of this system, we used a fourth-order accurate finite difference scheme based on the Newton-Raphson-Kantorovich (NRK) iterations~\cite{11cash1980}. This method facilitates the computation of the growth rate, Re$(\gamma)$, and calculation of the neutral stability curves in the $(k, R)$-plane for specific parameter settings. A neutral curve is defined as the locus of points where \( \text{Re}(\gamma) = 0 \). If in addition \( \text{Im}(\gamma) = 0 \) along this curve, then the principle of exchange of stabilities is said to be valid and the disturbance is stationary or non-oscillatory. Alternatively, if \( \text{Im}(\gamma) \neq 0 \), then the oscillatory or overstable solutions exist for governing system. For a fixed set of parameters, the neutral curve, denoted by \( R^{(n)}(k) \), where \( n = 1, 2, 3, \dots \), has an infinite number of branches, each of which represents a distinct solution to the linear stability problem. The solution branch of most interest is that on which the critical value \(R_c\) of \(R\) occurs at the critical wave number \(k_c\). The most unstable solution corresponds to this branch and the wavelength of initial perturbation can be calculated by using the expression \( \lambda_c = \frac{2\pi}{k_c} \).

