\caption{}
    \begin{center}
    \def\arraystretch{1.5}
    \begin{tabular}{c|ccccc}\hline
     $\mathbb{M}^d$ & $\mathbb S^d$ & $\mathbb{P}^d(\mathbb R)$ & $\mathbb{P}^d(\mathbb C)$ & $\mathbb{P}^d(\mathbb H)$ & $\mathbb P^d(\operatorname{Cay})$ \\ \hline
   Dimension& $d=1,2,\dots$ & $d=2,3,\dots$ & $d=4,6,\dots$ & $d=8,12,\dots$ & $d=16$ \\
   $\alpha$ & $(d-2)/2$ & $(d-2)/2$ & $(d-2)/2$ & $(d-2)/2$ & 7 \\
