    For every $\ell \in \Lambda$, the eigenfunctions corresponding to the same eigenvalue $\lambda_\ell$ form a finite dimensional vector space, denoted by $\mathcal{Y}_\ell = \mathcal{Y}_\ell (\mathbb{M}^d)$, with dimension $\dime$ that is uniquely identified through
    \begin{equation*}
\dime = \frac{(2\ell + \alpha + \beta + 1) \Gamma(\beta +1) \Gamma(\ell +\alpha + \beta +1)\Gamma(\ell +\alpha +1)}{\Gamma(\alpha +1) \Gamma(\alpha + \beta +2)\Gamma(\ell +1)\Gamma(\ell +\beta+1)}. 
\end{equation*}
   Then, 
\begin{equation*}
    L^2(\mathbb M^d) = \bigoplus_{\ell \in \Lambda} \mathcal{Y}_\ell.
\end{equation*}
Moreover, given an orthonormal basis of $\mathcal{Y}_\ell$, say $\{ Y_{\ell,m}, m=1,\dots, \dime \}$, any function $f \in L^2(\mathbb{M}^d)$ can be expanded as 
\begin{equation*}
    f = \sum_{\ell \in \Lambda} \sum_{m =1}^{\dime} \langle f , Y_{\ell,m} \rangle_\rangleL Y_{\ell,m}.
\end{equation*}
In order to deal with covariance functions, we will also consider functions $g \in L^2(\mathbb{M}^d \times \mathbb{M}^d)$, for which it holds
\begin{equation*}
   g= \sum_{\ell, \ell' \in \Lambda} \sum_{m =1}^{\dime}  \sum_{m' =1}^{\dimep}  \langle g , Y_{\ell,m} \otimes Y_{\ell', m'} \rangle_\rangleLL Y_{\ell,m} \otimes Y_{\ell',m'}.
\end{equation*}

A crucial result of \cite[Theorem 3.2]{gine} ensures that also for general $\mathbb{M}^d$ an \emph{addition formula} holds, that is, for any $\ell \in \Lambda,$
\begin{equation*}
\sum_{m=1}^{\dime } Y_{\ell, m}(u) Y_{\ell,m}(v) = \kappa_{\ell}  P_{\ell }^{(\alpha, \beta)}(\cos \epsilon \rho(u,v)),
\end{equation*}
where $\epsilon=1/2$ if $\mathbb{M}^d = \mathbb{P}^d(\mathbb R)$, $\epsilon=1$ otherwise, 
\begin{equation*}
    \kappa_\ell = \kappa_{\ell}({\mathbb{M}^d}) %= \frac{\Gamma(\beta+1)(2\ell +\alpha+\beta+1)\Gamma(\ell +\alpha+\beta+1)}{\Gamma(\alpha +\beta+2)\Gamma(\ell +\beta+1)} 
    = \frac{\dime}{P_{\ell}^{(\alpha, \beta)}(1)}. 
    \end{equation*}      
   The functions $P_{\ell }^{(\alpha, \beta)}:[-1,1]\to \mathbb{R}, \ \ell \in \mathbb{N}_0,$ are the well-known \emph{Jacobi polynomials}. Note that when $\mathbb{M}^d = \mathbb{S}^2$ they reduce to the \emph{Legendre polynomials}.

In general, the reason for the exceptional behaviour of the real projective spaces is discussed for instance in \cite{kushpel1}. See also \cite{kushpel2} and the references therein.

    \subsection{Sobolev Spaces on $\mathbb{M}^d$ and $\mathbb{M}^d\times \mathbb{M}^d$}
    \label{sec:sobolevspaces}
    We now give the definition of Sobolev spaces on $\mathbb{M}^d$ and $\mathbb{M}^d\times \mathbb{M}^d$ which will be essential later to introduce the smoothness properties of the random field $\{X(u), \ u \in \mathbb{M}^d\}$ and its covariance function.

   % $$
    %\mathscr{D}_p f = \sum_{\ell \in \Lambda} \sum_{m=1}^{\dime} (1-\lambda_\ell)^{p/2} Y_{\ell,m},
    %$$

\begin{definition} \label{def:sobospace}
Let $p \geq 0$. The Sobolev space of order $p$ on $\mathbb{M}^d$ is defined as
\begin{equation*}
    \Hp \!=\!  \Hp (\mathbb{M}^d) \!= \!
    \left\{ f \!\in\! L^2(\mathbb{M}^d) ,\|f\|_{\Hp} < \infty \right\},
  \end{equation*}
  where 
  $$
  \|f\|^2_{\Hp} = \sum_{\ell\in \Lambda} \sum_{m=1}^{\dime} (1-\lambda_\ell)^p  \langle f, Y_{\ell,m} \rangle^2_\rangleL .
  $$
The tensorial Sobolev space of order $p$ on $\mathbb{M}^d \times \mathbb{M}^d$ is
\begin{equation*}
    \Hprod =  \Hprod (\mathbb{M}^d \times \mathbb{M}^d) = \Hp \otimes \Hp \subset L^2 (\mathbb{M}^d \times \mathbb{M}^d).
\end{equation*}
\end{definition}
The parameter $p$ in Definition~\ref{def:sobospace} quantifies the regularity: the higher $p$, the smoother the functions  $f \in \Hp$ and  $g \in \Hprod$. 
Indeed, if we consider the Sobolev operator
    $$
    \mathscr{D} = (\operatorname{Id}-\Delta_{\mathbb{M}^d})^{p/2}, \qquad p \ge 0,
    $$
    we can readily see that
    $$
    \|f\|_\Hp = \|\mathscr{D}f\|_\rangleL, \qquad \|g\|_\Hprod  = \|(\mathscr{D} \otimes \mathscr{D}) g \|_\rangleLL.
    $$          
In the next section, we will only consider Sobolev spaces $\Hp$ and $\Hprod$ that are Reproducing Kernel Hilbert Spaces (RKHS). %~\cite{aronszajn1950theory}
      It turns out that 
    \begin{equation*}
        \Hp \text{ is a RKHS} \quad \Longleftrightarrow \quad  \Hprod \text{ is a RKHS} \quad \Longleftrightarrow  \quad p > d/2   .
    \end{equation*}
    See \cite[Proposition 1]{ejs} and \cite[Corollary 3.4]{gine}.


\section{Covariance Estimation}
In this section, we present the estimation of the covariance function $C$ and the asymptotic theory behind. 

We assume that $\{X(u), \ u \in \mathbb{M}^d\}$ is a random element of $\Hq$, for some $q>d/2$.
For a given $p \ge q$ and $\pen > 0 $, we can define the estimator $C_\pen$ of the covariance function as the solution of the following minimization problem
\begin{equation}\label{eq::cov-est}
\min_{g \in \Hprod}   \sum_{i=1}^n \frac{1}{nr_i(r_i-1)} \sum_{1\le j \ne k \le r_i } (\W_{ij}\W_{ik}  - g(U_{ij}, U_{ik}))^2 + \pen \| g\|^2_\Hprod,
\end{equation}
It is possible to prove that the solution is unique and it is given by
    \begin{equation*}\label{eq:RTformR}
        C_{\eta} =  \sum_{i=1}^n \frac{1}{\sqrt{r_i(r_i-1)}} \sum_{1 \leq j \neq k \leq r_i} \beta^{(\pen)}_{ijk} \,\psi_{\mathscr{D}^* \mathscr{D}} ( \cos \epsilon \rho ( \cdot ,U_{ij}) ) \otimes \psi_{\mathscr{D}^* \mathscr{D}} ( \cos \epsilon \rho ( \cdot ,U_{ik}) )
    \end{equation*}
    for some random $\{\beta^{(\pen)}_{ijk},\ 1 \leq i \leq n, \ 1\leq j \neq k \leq r_i\}$. The function $\psi_{\mathscr{D}^* \mathscr{D}}$ is the \emph{zonal Green's kernel} of $\mathscr{D}^* \mathscr{D}$, defined as
    $$
    \psi_{\mathscr{D}^* \mathscr{D}} ( \cos \epsilon \rho (u,v) ) = \sum_{\ell \in \Lambda} \frac{\kappa_\ell}{(1-\lambda_\ell)^p} P_\ell^{(\alpha,\beta)} (\cos \epsilon \rho (u,v)), \qquad u,v \in \mathbb{M}^d.
    $$
However, the penalty (and hence the solution) can be expressed in terms of any \emph{admissible} operator $\mathscr{D}$ with \emph{spectral growth order} $p$, which induces an equivalent norm -- see \cite[Section 2.2]{ejs}. 
% see also \cite[Definition 3]{ejs}. 


Theorem 1 below establishes a (uniform) rate of convergence for the estimator $C_\eta$, under a suitable condition on the decay of the penalty parameter $\pen$. Such rate is expressed in terms of the number of replicates $n$ and the \emph{average} number of measurement locations $r$, defined as the harmonic mean of the $r_i$'s. The result can thus be interpreted in both the \emph{dense} and \emph{sparse} sampling regimes. In a dense design, $r=r(n)$ is required to diverge with $n$ and it is larger than some order of $n$; on the other hand, in a sparse design, the sampling frequency $r$ is bounded and can be arbitrary small (as small as two). 

In the following, we define the class of probability measures for which our rate is achieved.
\begin{definition}\label{def:pq-cov}
Consider $p>d$, $d/2<q\le p$. Let $\pit$ be the collection of probability measures for $\Hq$-valued processes, such that for any $X$ with probability law $\mathbb{P}_X \in \pit$
$$\mathbb{E}\|X\|^4_{\Hq}\le L, \qquad
\|C\|^2_{\rangleHH} \le K,
$$
for some constants $L, K > 0$. The constants may depend on the manifold $\mathbb{M}^d$.
\end{definition}

\begin{theorem}\label{th::R}
Assume that 
$\mathbb{E}[\epsilon_{11}^4]<\infty$ and the $U_{ij}, i=1,\dots,n, j=1,\dots,r_i$, are independent copies of $U\sim \operatorname{Unif}(\mathbb{M}^d)$. Let $p>d$ and $d/2<q\le p$, and consider the covariance estimator obtained as the minimizer of Equation \eqref{eq::cov-est}. If $\pen \asymp (n r/\log n )^{-2p/(2p+d)}$, then
\begin{align*}
&\lim_{D\to \infty}  \limsup_{n\to\infty} \sup_{\mathbb{P}_X \in \pit}  \mathbb{P}\left (\| C_\pen  - C \|^2_\rangleLL > D\left (\left( \frac{\log n}{nr}\right)^{\frac{2p}{2p+d}} + \frac1n\right ) \right ) \\ &= 0.
\end{align*}
\end{theorem} 

The proof follows the same lines of arguments as \cite[Theorem 4]{ejs}.

