    \node (01) at (2,0) {(0,1)};
    \node (11) at (2,2) {(1,1)};
    \node (10) at (0,2) {(1,0)};

    % Draw the edges of the square
    \draw[dashed] (00) -- (01) -- (11) -- (10) -- (00);

