\label{algorithm:coherent}
\begin{algorithmic}[1]
\Statex \textbf{Input:} List of basin sizes, integer $N$
\Statex \textbf{Output:} Mapping from basin to list of states
\Function{CoherentNetwork}{basin\_sizes, $N$}
    \If{$N = 1$}
        \If{$|\text{basin\_sizes}| = 1$}
            \If{\text{basin\_sizes[0]} $= 2$}
                \State \Return $\{1 \mapsto [0,1]\}$ 
            \Else
                 \State \Return $\{1 \mapsto [0]\}$
            \EndIf
        \Else
            \State \Return $\{1 \mapsto [0],\; 2 \mapsto [1]\}$
        \EndIf
    \EndIf
    \State half\_sizes $\gets$ \texttt{EmptyList}()
    \ForAll{$s$ in basin\_sizes}
        \If{$\lfloor s/2 \rfloor > 0$}
            \State append  $\lfloor s/2 \rfloor$ to half\_sizes
        \EndIf
    \EndFor
    \State arr $\gets$ \Call{CoherentNetwork}{half\_sizes, $N-1$}
    \ForAll{(basin $\mapsto$ states) in arr}
        \ForAll{$x$ in states}
            \State append $x + 2^{N-1}$ to arr[basin]
        \EndFor
    \EndFor
    \State assigned\_states $\gets$ \texttt{Set of all states in arr}
%    \State available\_states $\gets$ \texttt{range}($2^N$)- assigned\_states
    \State available\_states $\gets$ $\{0,1,\ldots,2^N-1\}\ -$ assigned\_states

    \ForAll{$s$ in basin\_sizes}
        \If{$s$ is odd}
            \State new\_state $\gets$ Pop(available\_states)
            \If{$s > 1$ }
                \State append new\_state to the corresponding basin in arr
            \Else
                \State new\_key $\gets$ \texttt{len}(arr) + 1
                \State arr[new\_key] $\gets$ [new\_state]
