\begin{proof}
The claim is trivial for $0 \leq t \leq g$, as both sequences are explicitly defined $A_t = B_t = 2^t$ (eqs.~\ref{eq:recursion} and \ref{eq:Bt_recursion}). For $t \geq g+1$, we use induction. For the base case, $t=g+1$, we have 
\begin{align}
    A_{g+1} & = 2A_g-A_1 = 2(2^g -1), \nonumber \\
    B_{g+1} & =\bigg( \sum_{i=1}^{g-1}
    B_{g+1-i} \bigg) + 2 = \bigg(\sum_{i=1}^{g-1} 2^{g+1-i} \bigg) + 2 = \sum_{i=1}^g 2^g = 2(2^g-1). \nonumber
    \end{align}
For the inductive step, suppose $A_t = B_t$ for all $t$, $0 \leq t \leq g+x$, for some $x \geq 1$. We show $A_{g+x+1}=B_{g+x+1}$.

From the definition of $A_t$ (eq.~\ref{eq:recursion}), we have:
$$A_{g+x+1} = 2A_{g+x} - A_{x+1}.$$
From the inductive hypothesis and the definition of $B_t$ (eq.~\ref{eq:Bt_recursion}), we have
\begin{align}
A_{g+x+1} &= 2B_{g+x} - B_{x+1} \nonumber \\
&= 2\bigg[ \bigg( \sum_{i=1}^{g-1} B_{g+x-i} \bigg) + 2 \bigg] - B_{x+1} \nonumber \\
&= 2\bigg[ \bigg( \sum_{i=1}^{g-1} A_{g+x-i} \bigg) + 2 \bigg]- A_{x+1} 
\nonumber \\
&= 2 \bigg[ \bigg( \sum_{i=1}^{g-1} A_{x+i} \bigg) + 2 \bigg] - A_{x+1}. \nonumber
\end{align}
From the definition of $B_t$ (eq.~\ref{eq:Bt_recursion}) and the inductive hypothesis, 
\begin{align}
B_{g+x+1} &= \bigg( \sum_{i=1}^{g-1} B_{g+x+1-i} \bigg) + 2 \nonumber  \\
&= \bigg( \sum_{i=1}^{g-1} A_{g+x+1-i} \bigg) + 2 \nonumber \\
&= \bigg( \sum_{i=2}^g A_{x+i} \bigg) + 2. \nonumber 
\end{align}
Simplifying and using the inductive hypothesis, we have
\begin{align}
A_{g+x+1}-B_{g+x+1} &= \bigg( 2\sum_{i=1}^{g-1} A_{x+i} \bigg) + 4 - A_{x+1}  - \bigg( \sum_{i=2}^g A_{x+i} \bigg) - 2 \nonumber \\
&= \bigg( \sum_{i=2}^{g-1} A_{x+i} \bigg) + 2A_{x+1} + 2 -A_{x+1} - A_{x+g}\nonumber \\
&= \nonumber \bigg[ \bigg( \sum_{i=1}^{g-1} A_{x+i} \bigg) + 2 \bigg]  - A_{x+g} \\
&= \bigg[ \bigg( \sum_{i=1}^{g-1} B_{x+i} \bigg) + 2 \bigg]  - B_{x+g} \nonumber \\
&= \bigg[ \bigg( \sum_{i=1}^{g-1} B_{x+g-i} \bigg) + 2 \bigg]  - B_{x+g}.
\label{eq:laststep}
\end{align} 
Eq.~\ref{eq:laststep} is equal to 0 by the definition of $B_t$ (eq.~\ref{eq:Bt_recursion}), completing the proof.
\end{proof}

We immediately obtain a corollary that in the second-cousin model ($n=2$, $g=3$), the coefficients $A_t$ are closely related to the Fibonacci sequence. 
\begin{corollary}
The sequence $\{A_t\}_{t \geq 1}$ in the case of $g=3$ satisfies $A_t = 2f_{t+2}-2$, where $\{f_t\}_{t \geq 0}$ is the Fibonacci sequence $f_0=0$, $f_1=1$, and $f_t=f_{t-1}+f_{t-2}$ for $t \geq 2$.  
\end{corollary}
\begin{proof}
The result holds for $t=1$, 2, and 3, with $(f_3, f_4, f_5) = (2, 3, 5)$ and $A_1=2f_3-2=2$, $A_2=2f_4-2=4$, and $A_3=2f_5-2=8$.

The base case for induction is $t=4$, for which $f_6=8$ and $A_4=2f_6-2=14$. For the inductive step, suppose $A_{3+x}=2f_{5+x}-2$ for all positive $x\leq c$. Then $A_{3+(x+1)}=A_{2+(x+1)}+A_{1+(x+1)}+2$ by the equivalence of $A_t$ and $B_t$ and the definition of $B_t$ (Proposition \ref{prop:AequalsB}), so that by the inductive hypothesis, $A_{3+(x+1)}=[2f_{4+(x+1)} -2] + [2f_{3+(x+1)} - 2] + 2 = 2f_{5+(x+1)} - 2$, completing the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%% Section 4 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Generating function for \texorpdfstring{$A_t$}{At}}

We use the equivalence between $A_t$ and $B_t$ to analyze the growth rate $r_g$ of the number of ancestors in the $n$th-cousin mating model, $g=n+1$, with $n \geq 1$. To do so, we derive the generating function for $\{A_t\}_{t \geq 0}$.

\begin{prop}
Write $G_g(z) = \sum_{t=0}^\infty A_t z^t$ for the generating function for the sequence $\{A_t\}_{t \geq 0}$ with parameter $g$. Then
\begin{equation*}
G_g(z) = \frac{1 + z^g}{1 - 2z + z^g}.
\end{equation*}
\end{prop}

\begin{proof}
Recalling from eq.~\ref{eq:recursion} that $A_t = 2^t$ for $0 \leq t \leq g$, we have $G_g(z) = \sum_{t=0}^g 2^t z^t + \sum_{t=g+1}^\infty A_t z^g$. The first term is $\sum_{t=0}^g 2^t z^t = [1-(2z)^{g+1}]/(1-2z)$.

For the second term, following the recurrence in eq.~\ref{eq:recursion} for $t \geq g+1$, we have
\begin{align}
\sum_{t=g+1}^\infty A_t z^t &= 2 \sum_{t=g+1}^\infty A_{t-1} z^t - \sum_{t=g+1}^\infty A_{t-g} z^t. \nonumber \\
&= 2z \sum_{t=g}^\infty A_t z^t - z^g \sum_{t=1}^\infty A_t z^t. \nonumber
\end{align}
We substitute $\sum_{t=g}^\infty A_t z^t = G_g(z) - [1-(2z)^{g+1}]/(1-2z) + 2^g z^g$ and $\sum_{t=1}^\infty A_t z^t = G_g(z)-1$, obtaining
\begin{align*}
\sum_{t=g+1}^\infty A_t z^t &= 2z \bigg[G_g(z) - \frac{1-(2z)^{g+1}}{1-2z} + 2^g z^g\bigg] - z^g \big[ G(z) - 1 \big]. \nonumber
\end{align*}
Adding $\sum_{t=0}^g 2^t z^t$, we have 
\begin{align*}
G_g(z) = \sum_{t=0}^\infty A_t z^t &= \frac{1-(2z)^{g+1}}{1-2z} + 2z \bigg[G_g(z) - \frac{1-(2z)^{g+1}}{1-2z} + 2^g z^g\bigg] - z^g \big[ G_g(z) - 1 \big].
\end{align*}
Solving for $G_g(z)$ and simplifying yields the result.
\end{proof}

The generating function $G_g(z)$ can be written 
\begin{equation}
\label{eq:gf}
    G_g(z) = \frac{1+z^g}{z(1-z)} F_n(z),
\end{equation}
where $n=g-1$ and 
\begin{equation}
\label{eq:fn}
    F_n(z) = \frac{z}{1 - z - z^2 - \ldots - z^n}.
\end{equation}
$F_n(z)$ is the generating function for an $n$-anacci sequence~\cite[p.~270]{Knuth98}. For example, $F_2(z) = z/(1-z-z^2)$ is the generating function for the classic Fibonacci (2-anacci) sequence $f_n$~\cite[p.~297]{GrahamEtAl94}. The generating function $G_3(z)$ is the product of $(1+z^3)/[z(1-z)]$ and the Fibonacci generating function. That $G_g(z)$ can be written as a product of an $n$-anacci generating function and a second term $(1+z^g)/[z(1-z)]$ explains why the growth rate $r_g$ follows the growth rate of the $n$-anacci sequence. 

%%%%%%%%%%%%%%%%%%%%%%%%%% Section 5 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Asymptotic analysis of pedigree growth}
For $n \geq 1$, to find the asymptotic growth of the coefficients $A_t$ in the $n$th-cousin mating model, $r_g = \lim_{t \rightarrow \infty} (A_{t}/A_{t-1})$, we find the singularity nearest the origin~\cite[section 5.2]{Wilf94} of generating function $G_g(z)$ in eq.~\ref{eq:gf} (and hence of $F_n(z)$ in eq.~\ref{eq:fn}). This singularity occurs at $z=1/r_g$. For first cousins ($g=2$), $r_2=1$, and for second cousins ($g=3$), $r_3$ is the familiar $(1 + \sqrt{5})/2$. 

Table \ref{tab:table1} reports numerical solutions for $r_g$ for $g=4, 5, 6$. We can observe informally that as $n$ increases, $r_g=r_{n+1}$ increases as well. We establish formally that the singularity of $F_n(z)$ of smallest modulus decreases toward $\frac{1}{2}$ as $n$ increases, so that the generation-wise growth rates $r_g$ increase toward 2.
\begin{prop}
\label{prop:singularity}
   For $n \geq 1$, denote by $c_n$ the singularity of $F_n(z)$ of smallest modulus. Then (i) $c_{n+1} < c_n$, and (ii) $\lim_{n \rightarrow \infty} c_n = \frac{1}{2}$. 
\end{prop}
\begin{proof}
(i) First, $c_1=1$. For $n \geq 2$, let $Q_n(z)$ denote the denominator of $F_n(z)$, $Q_n(z)=1-z-z^2-\ldots-z^n$. Then $Q_{n+1}(c_n)=1 - c_n - c_n^2 - \ldots - c_n^n - c_n^{n+1} = -c_n^{n+1}$, as $c_n$ is a root of $Q_n(z)$. We have $Q_{n+1}(\frac{1}{2}) > 0$ and $Q_{n+1}(1)<0$, so that by the intermediate value theorem, a root for $Q_{n+1}$ must exist in $(\frac{1}{2},1)$. $Q_{n+1}(z)$ decreases monotonically in $(\frac{1}{2},1)$. Because $Q_{n+1}(c_n)<0$, a root for $Q_{n+1}$ must occur in $(\frac{1}{2}, c_n)$. 

(ii) To show $\lim_{n \rightarrow \infty} c_n = \frac{1}{2}$, choose $\epsilon$ with $0 < \epsilon < \frac{1}{2}$. We show that there exists $n$ such that $c_n < \frac{1}{2} + \epsilon$. First, $Q_n(\frac{1}{2}) = 2^{-n} > 0$. Next, $Q_n(\frac{1}{2} + \epsilon) = 1 - (\frac{1}{2} + \epsilon) - (\frac{1}{2} + \epsilon)^2 - \ldots - (\frac{1}{2} + \epsilon)^n = 2^{-n} - P_n(\epsilon)$, where $P_n(\epsilon)$ is a polynomial in $\epsilon$ with positive coefficients and no constant term. In particular, $P_n(\epsilon) > \epsilon$ for the permissible $\epsilon$ values, $0 < \epsilon < \frac{1}{2}$.

Then $Q_n(\frac{1}{2} + \epsilon) = 2^{-n} - P_n(\epsilon) < 2^{-n} - \epsilon$. Choose $n > -\log_2 \epsilon$, so that $Q_n(\frac{1}{2} + \epsilon) < 2^{-n} - \epsilon < 0$. Because $Q_n(\frac{1}{2}) > 0$ and $Q_n(\frac{1}{2}+\epsilon) < 0$, using the intermediate value theorem, we have shown that given $\epsilon$, for sufficiently large $n$, the root $c_n$ lies in $(\frac{1}{2}, \frac{1}{2}+\epsilon)$. We then take $\epsilon$ to 0. 
\end{proof}

