One more formally defines the events as follows.
\begin{itemize}
	\item The good case $G_i^t$, when there is a young arrow ($s\leq (a-2)k$) that defines a large synchronized zone, defined by
	\[
		G_i^t = \bigcup_{s=0}^{(a-2)k} \left[A_i^t(s) \cap \bigcap_{\substack{1 \leq j\leq (a-2)k-s\\ 1 \leq n\leq (a-2)k-s \\ n-j \geq t-i}} \left( E_{i+2k+j}^{t+2k+n} = \bot \right) \right]  \cap \bigcap_{m=1}^{2k-1} \left( E_{i+m}^{t+m} = \bot \right).
	\]
	The probability of this event is 
    \[
    		p_{good}^{\epsilon} \coloneqq \sum_{s=0}^{(a-2)k}P\left(A_i^t(s) \right) (1-\epsilon)^{2k-1+\frac{((a-2)k-s)^2}{2}} \underset{\epsilon\to0}{\sim} \frac{((a-2)k+1)((a-2)k+2)}{2(a+1)k}\epsilon \underset{a\to\infty}{\sim} \frac{ak\epsilon}{2}.
    \]
	\item The bad case $B_i^t$, when there is an arrow with a type too large or a error on its path:
	\[
		B_i^t = \left( \bigcup_{s=(a-2)k+1}^{ak-1} A_i^t(s) \right) \cup \bigcup_{s=0}^{(a-2)k} \left[A_i^t(s) \cap \bigcup_{\substack{1 \leq j\leq (a-2)k-s\\ 1 \leq n\leq (a-2)k-s \\ n-j \geq t-i}} \left( E_{i+2k+j}^{t+2k+n} \neq \bot \right)  \right] \cup \bigcup_{m=1}^{2k-1} \left( E_{i+m}^{t+m} \neq \bot \right).
	\]
	The probability of this event is
	\begin{align*}
    	p_{bad}^{\epsilon} &\coloneqq 1-\left(1-\epsilon\right)^{2k-1}\left(1-\sum_{s=(a-2)k+1}^{ak-1}P\left(A_i^t(s) \right) - \sum_{s=0}^{(a-2)k}P\left(A_i^t(s) \right)\left(1-(1-\epsilon)^{\frac{((a-2)k-s)^2}{2}} \right) \right) \\
    	&\underset{\epsilon\to0}{\sim} \left(2k-1+\frac{ak(ak+1) - ((a-2)k+1)((a-2)k+2)}{2(a+1)k}\right)\epsilon \underset{a\to\infty}{\sim} (4k-3)\epsilon.
    \end{align*}
	\item The other case $O_i^t = \overline{G_i^t \cup B_i^t}$, when there is no arrow and no error in the path:
	\[
		O_i^t = \bigcap_{s=0}^{ak-1} \overline{A_i^t(s)} \cap \bigcap_{m=1}^{2k-1} \left( E_{i+m}^{t+m} = \bot \right).
	\]
	Its probability is then
    \[
    p_{other}^{\epsilon}\coloneqq1-p_{bad}^{\epsilon}-p_{good}^{\epsilon}=1-s(\epsilon)
    \]
    with $s(\epsilon)\tendsto{\epsilon}00$.
  \end{itemize}

  The following property is crucial.

  \begin{lem}
    \label{lem:independent-good-bad-other}
    The event $O_i^t$ is independent of $O_i^{t'}$, $G_i^{t'}$ and $B_i^{t'}$ for all $t' \neq t$.
  \end{lem}

  \begin{proof}
  The event $O_i^t$ only depends on the values $E_{i+m}^{t+m}$ for $-ak \leq m \leq 2k-1$, while the other events depend on the values $E_{i+m}^{t'+m}$ for $-ak \leq m \leq 2k-1$ and $E_{i+2k+j}^{i+2k+n}$ for some $j,n \geq 1$.
  As these are disjoint sets of independent random variables, the events are independent.
  \end{proof}

\begin{rem}
The ratio $\frac{p_{good}^{\epsilon}}{s(\epsilon)}=\frac{p_{good}^{\epsilon}}{p_{good}^{\epsilon}+p_{bad}^{\epsilon}}$ often appear in the computations. Using the definitions of $p_{good}^\epsilon$ and $p_{bad}^\epsilon$, one can observe that when $\epsilon\to0$, the ratio has a limit $C_{a,k}$ which verifies: 
\begin{equation}
C_{a,k} \underset{a\to\infty}{=}1-\frac{8-\frac{6}{k}}{a}+o\left(\frac{1}{a}\right).
\label{eq:ratio}
\end{equation}
\end{rem}

\begin{figure}[h]
\centering{}\includegraphics[scale=0.6]{LeftBorder} \caption{Suppose $L_{n}=i$ and $t_{n}=t$. In green, the column where the first arrow is looked for: it appears after $M-1$ ``other" cases (no errors on the $2k$ cells in diagonal, in blue). As the arrow is of type $s$ and there is no error on its path (yellow cells), it's a success: the arrow has created a synchronized zone of size greter than $2k$, which does not let information go through from the left. We then define $L_{n+1}=i+(a-2)k-s$ and $t_{n+1}=t-M+\left(a-2\right)k-s-1$.\label{fig:LeftBorder}}
\end{figure}

Figure \ref{fig:LeftBorder} illustrates a transition of the MAC $(L_{n},J_{n})$ which is defined with a random sequence of times $(t_{n})$ by induction, the base case being $L_{0}=0$, $J_{0}=1$, $t_{0}=0$.
Suppose that $L_{n}$, $J_{n}$ and $t_{n}$ have been defined.
If $J_n = 1$ (meaning that the chain has not recently moved to the left), then let $M \coloneqq \min \left\{ 0 \leq m \leq H \mid O_{L_n-2k}^{t_n-2k-m} \text{ does not occur}\right\}$ with $H = H(\epsilon,a)$ a \define{barrier}, to be defined later.
If the set is empty or $M < (a-2)k$ or $B_{L_n-2k}^{t_n-2k-M}$ occurs, we have a \textbf{failure}, and the chain moves to the left:
\begin{equation}
  \label{eq:Ln-failure}
  L_{n+1} = L_n - 4ak, \: J_{n+1} = 2 \text{ and } t_{n+1} = t_n-4ak.
\end{equation}
Otherwise, $G_{L_n-2k}^{t_n-2k-M}$ occurs with the arrow $A_{L_n-2k}^{t_n-2k-M}(s)$ for some $s \leq (a-2)k$, and we have a \textbf{success}.
The chain now moves to the right, onto the position where the arrow disappears naturally:
\[
  L_{n+1} = L_n + (a-2)k-s, \: J_{n+1} = 1 \text{ and } t_{n+1} = t_n - M + (a-2)k -s -1.
\]
Denote the probability of \textbf{success} by $\alpha_\epsilon$.

In the case $J_n = 2$, the process is a little more involved.
As in the first case, define $M_1 \coloneqq \min\left\{ 0 \leq m \leq H \mid O_{L_n-2k}^{t_n-2k-m} \text{ does not occur}\right\}$.
If we have a \textbf{failure}, then we use Equation \eqref{eq:Ln-failure} as before.

Suppose then that we have a \textbf{success} with some $s \leq (a-2)k$.
If $M_1 - (a-2)k +s +1 < H$, then the barrier has not been overcome and we call it a \textbf{jump}.
We then fix a new $M_2$ and iterate the last step.
More precisely, if the first $l > 0$ attempts have resulted in \textbf{jumps}, then let $M_{l+1} \coloneqq \min\left\{ m \leq H \mid O_{L_n-2k}^{t_n-2k-m-\sum_{r=1}^{l}M_r } \text{ does not occur}\right\}$.
If the set is empty or $B_{L_n-2k}^{t_n-2k-\sum_{r=1}^{l+1}M_r}$ occurs, we have a \textbf{failure} and apply Equation \eqref{eq:Ln-failure}.
Otherwise, if $\sum_{r=1}^{l}M_r - (a-2)k +s_l +1 < H$ (with $s_l$ the $s$ of the last success) we have a \textbf{jump}.
If we have neither a \textbf{failure} nor a \textbf{jump}, then the barrier $H$ has been overcome and the chain moves to the right:
\[
  L_{n+1} = L_n + (a-2)k-s_l, \: J_{n+1} = 1 \text{ and } t_{n+1} = t_n - \sum_{r=1}^{l}M_r + (a-2)k -s_l -1.
\]
Denote the probability of overcoming a barrier by $\beta_\epsilon$.

A transition of $L_{n}$ with $J_{n}=1$ (a check) is illustrated on Figure \ref{fig:LeftBorder}, and a trajectory of $\left(L_{n},J_{n}\right)$ on Figure \ref{fig:MAC}. A success is obtained when the arrow defining the synchronized zone the considered cell is part of is encountered, and this zone is sufficiently large. Otherwise, it is a failure. The barrier $H$ has no physical reality in the trajectory: it is only defined to ensure the mutual independence between the different jumps. Aiming for a large probability of success (encountering a good case before $H$ tries) while also having a great chance to overcome a barrier of size $H$, a good choice for $H$ is $H\coloneqq\frac{\ln(a)}{s(\epsilon)}$ (where $s\left(\epsilon\right)=1-p_{other}^{\epsilon}$).

\begin{figure}[!h]
\centering{}\includegraphics[scale=0.5]{MAC} \caption{First steps of $(L_{n},J_{n})$ and $\overline{L_{t}}$ (in blue). The red-and-blue cells are at times $t_{n}$ in position $L_{n}$. The initial state is $(L_{0},J_{0})=(0,1)$. The first steps represented are: \protect \\
(1) The initial cell is not in a good synchronized zone: we encounter a bad case before $H$ checks, it's a failure. We represent a barrier of size $H$ and the new state is $(L_{1},2)$ with $L_{1}<L_{0}$.\protect \\
(2) The first result is a success (the synchronized zone is large enough), but before $H$ checks: it's a jump. The second one succeed after enough checks to overcome the barrier: the last success defines the new state $L_{2}\protect\geq L_{1}$ and $J_{2}=1$.\protect \\
(3) The check fails, so $L_{3}<L_{2}$ and a barrier is represented.\protect \\
(4) The first check is a jump, but the second is a failure: $L_{4}<L_{3}$ and a new barrier is represented. \label{fig:MAC}}
\end{figure}

The sequence $(J_{n})$ is an ergodic Markov chain on $\{1,2\}$ with unique invariant probability vector $\pi=(\pi_{1},\pi_{2})\coloneqq\frac{1}{1-\alpha_{\epsilon}+\beta_{\epsilon}}(\beta_{\epsilon},1-\alpha_{\epsilon})$. Moreover, the level change $L_{1}-L_{0}$ knowing $J_{1}$ is independent from $J_{0}$: it equals $-4ak$ if $J_{1}=2$, and $(a-2)k-s$ if $J_{1}=1$, with $s$ independent from $J_{0}$.

\subsection{Interpretation of $L_n$}

The sequence of spacetime positions $\left(L_{n},t_{n}\right)$ is used to represent points such that the information to its left on the $\G$-layer cannot affect the right half-configuration at $t=0$. After a failure, the sequence moves to the left with slope $1$, the maximum speed of information propagation in $T_\epsilon$ (Lemma \ref{lem:passageOfTime}). After a success, $L_{n}$ is at the border of a synchronized zone of size greater than $2k$, through which information cannot flow.
This is formalized in the following result.

\begin{prop}
  \label{prop:Ln-lt}
  For all $\omega\in\Omega$ and  $n\in\N$, 
  \[
    l_{-t_n+2ak} \geq L_n - 2ak.
  \]
\end{prop}

\begin{proof}
  For $s\geq -t_n$ define 
  \[
    l_{s}^{n}\coloneqq
    \min\left\{ m\geq L_{n}-s-t_{n}\mid\exists\beta\in\A^{\N},\,
      \begin{array}{ccl}
        \A^{h\left(m,n\right)} & \to & \A^{\N}\\
        \alpha & \mapsto & \Psi_{L_{n}^{+}}^{s+t_{n}}\left(\alpha\beta,U^{+t_{n}}\right)
      \end{array}
      \text{ is not constant}\right\} 
  \]
  where $h\left(m,n\right)=m+s+t_{n}-L_{n}+1$ and $\left(U^{+t_{n}}\right)^{t}=U^{t+t_{n}}$. It is the left border of the dependence cone at time $-s$ of the semi-configuration on $[L_n, +\infty)$ at time $t_n$.

  For a given $\omega \in \Omega$, let us prove the following proposition by induction on $n\in\N$:
  \begin{equation}
    \label{eq:ln-lnt-bound}
    \forall t \leq t_n -2ak, \quad l_{-t} \geq l^n_{-t}
  \end{equation}
  Intuitively, this states that any information at time $t \leq t_n -2ak$ that cannot influence the half-configuration on $[L_n, \infty)$ at time $t$, also cannot influence the half-configuration on $[0, \infty)$ at time $0$.
  This implies the original claim, as information can propagate at speed at most $1$ (Lemma \ref{lem:passageOfTime}).

  The base case $n=0$ is immediate by definition, $l_{t} = l^0_{t}$.
  Suppose now that \eqref{eq:ln-lnt-bound} is true for a fixed $n\in\N$. By $t_{n+1} < t_n$, the inequality $l_{-t} \geq l^n_{-t}$ is true for all $t\leq t_{n+1}-2ak$.

  If $J_{n+1} = 2$, the last step is a failure: $L_{n+1} = L_n -4ak$ and $t_{n+1} = t_n-4ak$. By Lemma \ref{lem:passageOfTime}, 
  \[
    l^n_{t_{n+1}} \geq L_n -4ak = L_{n+1}.
  \]
  Therefore the value of the configuration on $[L_n, +\infty)$ at $t_n$ is determined by the value of the configuration on $[L_{n+1}, +\infty)$ at $t_{n+1}$, which gives by definition $l^n_{-t} \geq l^{n+1}_{-t}$ for $t\leq t_{n+1}-2ak$ and the result.

  If $J_{n+1} = 1$, the last step is a success: the cell at $L_n$ is at the right end of a zone of size greater than $2k$ of synchronized values on the $\F$-layer.
  This zone is created by an arrow that dies at the position $(J_{n+1}, t_{n+1})$.
  Any information on the $\G$-layer that is to the left of the arrow at time $t_{n+1}$ cannot influence the value of the configuration on $[L_n; +\infty)$ at time $t_n$, as it would have to pass through a region whose cells are forced to take a value $0_{\G}$ every $k$ steps, the last of which happens at time $t_{n+1}+1$.
  Likewise, no arrows on the $\F$-layer cross this region.
  Hence the value of the configuration on $[L_n, +\infty)$ at $t_n$ is determined by the value of the configuration on $[L_{n+1}, +\infty)$ at $t_{n+1}$, which gives the result. Figure \ref{fig:Ln-lt} illustrates the right shift of the left border of the dependence cone after a success. 
\end{proof}

