To more easily represent the bound of $l_t$ by $L_n$, we define its ``hull'' as $\overline{L_{t}} \coloneqq L_n - (t_n - t)$, where $n$ is such that $t_{n+1} < t \leq t_n$. The following corollary is a direct application of the last proposition and Lemma \ref{lem:passageOfTime}:
\begin{cor}
For a given $\omega\in\Omega$ we have $l_{-t+2ak} \geq \overline{L_t} - 2ak$.
\end{cor}

\begin{cor}
For a given $\omega\in\Omega$, if $L_n \tendsto{n}{\+\infty}+\infty$, then $l_t \tendsto{t}{+\infty}+\infty$.
\end{cor}
\begin{proof}
By construction, $(t_n)$ is a decreasing sequence such that $t_n - t_{n+1} \leq 2H$ for all $n$. Therefore for any $t_{n+1} < t \leq t_n$, we have $\overline{L_t} \geq L_n - 2H$
and $\overline{L_t} \tendsto{t}{-\infty}+\infty$. The previous corollary then gives the result.
\end{proof}


\subsection{Mean drift of the left border}

By the properties verified by the MAC $(L_n,J_n)$, its mean drift is
\begin{align*}
	\kappa^\prime &= \pi_1 \sum_{m\in\Z} m P\left(L_1 = m \mid J_1=1\right) + \pi_2 \sum_{m\in\Z} m P\left(L_1 = m \mid J_1=2\right)\\
		&= \pi_1 \sum_{s=0}^{(a-2)k}((a-2)k-s)  P\left(L_1 = ((a-2)k-s) \mid J_1=1\right) - \pi_{2}4ak
\end{align*}
Knowing that $J_1=1$, the step to the right is $(a-2)k-s$ if $\nearrow_s$ is the arrow involved in the last success (independently of $J_0 = 1$ or $2$). As it is a success, the arrow can only be $\nearrow_s$ with $s \leq (a-2)k$, and the probability is independent of the actual cell the event $A_i^t(s)$ occurred: 
\[
	P\left(L_1 = ((a-2)k-s) \mid J_1=1\right) = \frac{P\left(A_0^0(s)\right)}{P\left(\bigcup_{l=0}^{(a-2)k}A_0^0(l)\right)}.
\]


Therefore the mean drift is strictly positive if $\beta_{\epsilon}$ and $\alpha_{\epsilon}$ verify the following inequality
\[
	\pi_{1} \sum_{s=0}^{(a-2)k}(ak-s-2k) \frac{P\left(A_0^0(s)\right)}{P\left(\bigcup_{l=0}^{(a-2)k}A_0^0(l)\right)} > \pi_{2}4ak
\]
which becomes when we multiply both side by $1-\alpha_\epsilon + \beta_\epsilon$:
\begin{equation}
\underset{\text{Section \ref{sec:beta}}}{\underbrace{\beta_{\epsilon}}} \underset{\text{Section \ref{sec:rightStep}}}{\underbrace{\sum_{s=0}^{(a-2)k}(ak-s-2k)\frac{P\left(A_0^0(s)\right)}{P\left(\bigcup_{l=0}^{(a-2)k}A_0^0(l)\right)}}} > \underset{\text{Section \ref{sec:alpha}}}{\underbrace{\left(1-\alpha_{\epsilon}\right)}}4ak.
\label{eq:driftLeftBorder}
\end{equation}


\subsection{Mean step to the right}
\label{sec:rightStep}

We already computed $P\left(A_{i}^{t}(s)\right)=\sum_{m=0}^{s}\frac{\epsilon}{(a+1)k}(1-\epsilon)^{m}\underset{\epsilon\to0}{\sim}\frac{s+1}{(a+1)k}\epsilon$ for all $\left(i,t\right)$. As the $A_{0}^{0}\left(l\right)$ are disjoints for $l\in\left\llbracket 0,\left(a-2\right)k\right\rrbracket $, we can show that
\[
	\frac{P\left(A_{0}^{0}(s)\right)}{P\left(\bigcup_{l=0}^{(a-2)k}A_{0}^{0}(l)\right)}\tendsto{\epsilon}0\frac{\left(s+1\right)}{\sum_{l=0}^{\left(a-2\right)k}\left(l+1\right)}=\frac{2\left(s+1\right)}{\left(\left(a-2\right)k+1\right)\left(\left(a-2\right)k+2\right)}
\]
and so 
\[
	\sum_{s=0}^{(a-2)k}(ak-s-2k)  \frac{P\left(A_0^0(s)\right)}{P\left(\bigcup_{l=0}^{(a-2)k}A_0^0(l)\right)}  \tendsto{\epsilon}{0} \frac{(a-2)k}{3}.
\]

Thus inequality (\ref{eq:driftLeftBorder}) is verified for $\epsilon$ small enough if 
\[
	\liminf_{\epsilon\to0}\beta_{\epsilon}>\frac{12a}{a-2}\limsup_{\epsilon\to0}\left(1-\alpha_{\epsilon}\right).
\]

\subsection{Computation of $\alpha_{\epsilon}$, the probability of success}
\label{sec:alpha}

Recall that the number $\alpha_{\epsilon}$ is the probability of success when determining the direction of the next step of $L_{n}$ with $J_{n} = 1$ (see Section \ref{subsec:L_n}), i.e. seeing a good case before a bad one and between $ak$ and $H$ timesteps.
By Lemma \ref{lem:independent-good-bad-other}, we have
\[
	\alpha_{\epsilon} = \sum_{n=ak}^{H}(p_{other}^{\epsilon})^{n-2k}p_{good}^\epsilon = \frac{p_{good}^{\epsilon}}{1-p_{other}^{\epsilon}}\left(1-(p_{other}^{\epsilon})^{H-2k}\right)(p_{other}^\epsilon)^{(a-2)k}
\]
As $H=\frac{\ln(a)}{s(\epsilon)}$, one has $(p_{other}^{\epsilon})^{H}=\exp\left(\ln(a)\frac{\ln(1-s(\epsilon))}{s(\epsilon)}\right)\tendsto{\epsilon}0\frac{1}{a}$, $(p_{other}^{\epsilon})^{-2k} \tendsto{\epsilon}{0}1$, $(p_{other}^{\epsilon})^{(a-2)k} \tendsto{\epsilon}{0}1$ and
\[
	\alpha_{\epsilon}\tendsto{\epsilon}0 C_{a,k} \left(1-\frac{1}{a}\right)\eqqcolon\alpha
\]

Thus inequality (\ref{eq:driftLeftBorder}) is verified for $\epsilon$ small enough if $\liminf_{\epsilon\to0}\beta_{\epsilon}>\frac{12a}{a-2}(1-\alpha).$
Moreover, by equation (\ref{eq:ratio}) we have the expansion $\alpha\underset{a\to\infty}{=}1-\frac{9-\frac{6}{k}}{a}+o\left(\frac{1}{a}\right)$ so to conclude one only needs that for $a$ large enough
\[
	\liminf_{\epsilon\to0}\beta_{\epsilon} \geq \frac{109}{a}.
\]


\subsection{Distribution of the jumps}

Suppose that the MAC is in state $J_n = 2$ at step $n > 0$, so that there is a barrier of height $H$ on the right.
Now we iterate the check of the $J_n = 1$ case.
Each check has a probability $\alpha_\epsilon$ of \textbf{success}, that is, seeing a ``good'' case $G_i^t$ before a ``bad'' case $B_i^t$.
The \define{size} of the \textbf{success} is the number of ``other'' cases $O_i^t$ before the first ``good'' case.
We keep repeating the check until either a \textbf{failure} occurs or the sum of the sizes of the \textbf{success}es so far is more than $H$; before that, each \textbf{success} is a \textbf{jump}.
If Figure \ref{fig:LeftBorder} depicted a \textbf{jump}, the new cell would be at position $(i,t-n+2k)$, so its size would be $n-2k$.
% With a barrier on its right, we iterate the previous check (but ignore the level change, see steps 2 and 4 on Figure \ref{fig:MAC}). Each check has a probability $\alpha_\epsilon$ of success. The \define{jump} is the difference in time between each check. Because we ignore the level change, it corresponds to the number of ``other'' cases encountered before a ``good'' one.

We now analyze the size distribution of a \textbf{success}.
Denote by $N$ the size of a \textbf{success}.
Supposing that a \textbf{success} actually occurs, we find for $(a-2)k\leq d \leq H-2k$ that
\[
	P\left(N=d\mid\text{success}\right) = \frac{(p_{other}^{\epsilon})^{d} \, p_{good}^{\epsilon}}{\sum_{l=ak}^{H}(p_{other}^{\epsilon})^{l-2k} \, p_{good}^{\epsilon}} = (p_{other}^{\epsilon})^{d-(a-2)k}  \frac{s(\epsilon)}{1-(p_{other}^{\epsilon})^{H-ak}}
\]
and thus for $\frac{H}{i}\geq (a-2)k$,
\begin{align*}
P\left(N\geq\frac{H}{i}\mid\text{success}\right) & =\sum_{d=\frac{H}{i}}^{H}P\left(N=d\mid\text{success}\right)\\
	& = \frac{s(\epsilon)}{1-(p_{other}^{\epsilon})^{H-ak}} \sum_{d=\frac{H}{i}}^{H}(p_{other}^{\epsilon})^{d-(a-2)k}\\
	& = (p_{other}^{\epsilon})^{\frac{H}{i}-(a-2)k} \frac{1-(p_{other}^{\epsilon})^{\frac{i-1}{i}H}}{1-(p_{other}^{\epsilon})^{H-ak}}
\end{align*}

Using the previous computation of $(p_{other}^{\epsilon})^{H}$, we can deduce that 
\[
P\left(N\geq\frac{H}{i}\mid\text{success}\right) \tendsto{\epsilon}0 \left(\frac{1}{a}\right)^{1/i} \frac{1-\left(\frac{1}{a}\right)^{\frac{i-1}{i}}}{1-\frac{1}{a}}.
\]


\subsection{Computation of $\beta_{\epsilon}$, the probability of overcoming a barrier}
\label{sec:beta}

Recall that $\beta_{\epsilon}$ is the probability of overcoming a barrier. Let us fix $m \geq 1$.
For $i \geq 1$, let $A_{i}$ be the event that we have $i$ \textbf{success}es in a row and each has size at least $H/i$.
If $A_{i}$ occurs, then we realize $i$ \textbf{success}es in a row, which are all large enough so that added together, they overcome a barrier $H$.

Let $N_{l}$ be the size of the $l^{th}$ jump.
The random variables $(N_l)_{1 \leq l \leq i}$ are independent and identically distributed given $i$ \textbf{success}es in a row. Finally, define $\mathbf{A}_m = \bigcup_{i=1}^{m}A_{i}$. Then
\begin{align}
\beta_{\epsilon} & \geq P\left(\text{overcoming the barrier in at most }m\text{ jumps}\right) \notag \\
	& \geq P(\mathbf{A}_m) \notag \\
	& =\sum_{n=1}^{m}\left(-1\right)^{n+1}\sum_{1\leq i_{1}<\dots<i_{n}\leq m}P\left(A_{i_{1}}\cap\dots\cap A_{i_{n}}\right).\label{eq:beta_epsilon}
\end{align}
With the convention $i_{0}=0$, we have
\begin{align*}
P\left(A_{i_{1}}\cap\dots\cap A_{i_{n}}\right) & = P\left(\left(\bigcap_{j=1}^{n}\bigcap_{l=i_{j-1}+1}^{i_{j}}N_{l}\geq\frac{H}{i_{j}}\right) \cap i_{n}\text{ \textbf{success}es in a row}\right)\\
	& = \left(\prod_{j=1}^{n}\prod_{l=i_{j-1}+1}^{i_{j}}P\left(N\geq\frac{H}{i_{j}}\mid\text{\textbf{success}}\right)\right) \alpha_{\epsilon}^{i_{n}}\\
	& =\prod_{j=1}^{n}P\left(N\geq\frac{H}{i_{j}}\mid\text{\textbf{success}}\right)^{i_{j}-i_{j-1}} \alpha_{\epsilon}^{i_{n}}.
\end{align*}

Finally, using the computation of the previous section (supposing that $m\leq \frac{H}{ak}$, which is true for $\epsilon$ close enough to $0$) gives
\[
	P\left(A_{i_{1}}\cap\dots\cap A_{i_{n}}\right) \tendsto{\epsilon}0 \prod_{j=1}^{n} \left(\frac{1}{a}\right)^{\frac{i_{j}-i_{j-1}}{i_{j}}}  \underset{\tendsto a{\infty}1}{\underbrace{\left(\frac{1-\left(\frac{1}{a}\right)^{\frac{i_j-1}{i_j}}}{1-\frac{1}{a}} \right)^{i_{j}-i_{j-1}}}} \underset{\tendsto a{\infty}1}{\underbrace{\alpha^{i_{n}}}}.
\]
So when $n\geq2$, this product is equivalent to 
\[
	\prod_{j=1}^{n} \left(\frac{1}{a}\right)^{\frac{i_{j}-i_{j-1}}{i_{j}}} = \left(\frac{1}{a}\right)^{1 + \sum_{j=2}^n \frac{i_{j}-i_{j-1}}{i_{j}}} 
\] 
and so negligible with respect to $\frac{1}{a}$, while in the case $n=1$, $P(A_{i})\underset{a\to\infty}{\sim}\frac{1}{a}$. 

Thus, the limit when $\epsilon\to0$ of the sum in (\ref{eq:beta_epsilon}) is equivalent to $\frac{m}{a}$ when $a\to +\infty$. Taking $m$ greater than $109$ and $a$ big enough, the following holds:
\begin{equation}
\liminf_{\epsilon\to0}\beta_{\epsilon}\geq \lim_{\epsilon\to0} P(\mathbf{A}_m) \geq \frac{109}{a} \label{eq:conclusionDerive1}
\end{equation}
Thus, equation (\ref{eq:driftLeftBorder}) is verified: the level $L_n$ tends to $+\infty$ a.s..

\subsection{The right border}
\label{subsec:Bordure-Droite} 

We can use analogous definitions as for the left border to define a MAC $(R_n,K_n)$ on $\Z\times\{1,2\}$ bounding $r_t$, with the same ideas of synchronized zones and barriers. This time, we prove that the mean drift $\kappa^\prime$ is strictly negative to deduce that $R_n \tendsto{n}{\infty}-\infty$.
We skip some of the details that are analogous to the case of $(L_n, J_n)$, and reuse some of the notation with possibly different definitions.

\subsubsection{Definition of $R_n$}

The error variables $E_{i}^{t}$ are the same as in the definition of $L_{n}$. For the right border, the type $s$ of the arrow $\nearrow_s$ is less important than its age $l$ (the number of iterations since its creation by an error). For $0\leq l<ak$, the event $F_{i}^{t}\left(l\right)$ ``having an arrow with age $l$ at $\left(i,t\right)$" is defined by
\[
	F_{i}^{t}\left(l\right)\coloneqq\left(\bigcup_{s=0}^{ak-l-1}\left(E_{i-l}^{t-l}=\nearrow_{s}\right)\right)\cap\left(\bigcap_{n=0}^{l-1}\left(E_{i-n}^{t-n}=\bot\right)\right)
\]
with probability
\[
	P\left(F_{i}^{t}\left(l\right)\right)=\sum_{s=0}^{ak-l-1}\frac{\epsilon}{\left(a+1\right)k}\left(1-\epsilon\right)^{l}=\frac{ak-l}{\left(a+1\right)k}\epsilon\left(1-\epsilon\right)^{l}.
\]
We reuse the notations $O_{i}^{t}$, $B_{i}^{t}$ and $G_{i}^{t}$ for the other, bad and good cases, here defined by the decision process of Figure \ref{fig:GoodBadOtherDroite}.

\begin{figure}[!h]
