\end{figure}

We can then compute the respective probabilities of these events:

\[
	P\left(G_{i}^{t}\right)=p_{good}^{\epsilon}\coloneqq\sum_{l=2k+1}^{ak-1}P\left(F_{i}^{t}\left(l\right)\right)\left(1-\epsilon\right)^{\left(l-2k+1\right)2k}\underset{\epsilon\to0}{\sim}\frac{(a-2)k((a-2)k-1)}{2(a+1)k}\epsilon\underset{a\to\infty}{\sim}\frac{ak\epsilon}{2}
\]
\[
	P\left(B_{i}^{t}\right)=p_{bad}^{\epsilon}\coloneqq1-\left(1-\epsilon\right)^{2k+1}+\sum_{l=2k+1}^{ak-1}P\left(F_{i}^{t}\left(l\right)\right)\left(1-\left(1-\epsilon\right)^{\left(l-2k+1\right)2k}\right)\underset{\epsilon\to0}{\sim}(2k+1)\epsilon.
\]
and $P\left(O_{i}^{t}\right)=p_{other}^{\epsilon}=1-p_{good}^{\epsilon}-p_{bad}^{\epsilon}=1-s\left(\epsilon\right)$ with $s\left(\epsilon\right)\tendsto{\epsilon}00$.
We can also compute the limit
\[
	\frac{p_{good}^{\epsilon}}{p_{good}^{\epsilon}+p_{bad}^{\epsilon}}\tendsto{\epsilon}0 D_{a,k} \underset{a\to\infty}{=}1-\frac{4+\frac{2}{k}}{a}+o\left(\frac{1}{a}\right)
      \]

The barrier size is again defined to be $H=\frac{\ln a}{s\left(\epsilon\right)}$. For $\left(i,t\right)\in\Z^{2}$, denote by
\[
	CI\left(i,t\right)=\left\{ \left(i+c,t-l\right)\mid0\leq c<2k,\,c\leq l<4k-c\right\} 
\]
the light blue zone illustrated on Figure \ref{fig:RightBorder}. The MAC $\left(R_{n},K_{n}\right)$ and its associated random time sequence $\left(t_{n}^{\prime}\right)$ is then defined analogously to $\left(L_{n},J_{n}\right)$.
The base case is $R_{0}=0$, $K_{0}=1$, $t_{0}^{\prime}=0$.
For all $n\in\N$, in the case $K_n = 1$ we define as follows.
	\begin{itemize}
		\item Fix $M\coloneqq\min\left\{ 0\leq m\leq H\mid O_{R_{n}+2k}^{t_{n}^{\prime}-2k-m}\text{ does not hold}\right\} $. 
		\item If the set is empty, or $\bigcup_{j,s\in CI\left(R_{n},t_{n}^{\prime}\right)}E_{j}^{s}\neq\bot$, or $B_{R_{n}+2k}^{t_{n}-2k-M}$ holds, we have a \textbf{failure}: 
                  \begin{equation}
                    \label{eq:Rn-failure}
			R_{n+1}=R_{n}+4ak,\:K_{n+1}=2\text{ and }t_{n+1}^{\prime}=t_{n}^{\prime}-4ak.
		\end{equation}
		\item Otherwise, if $G_{R_{n}+2k}^{t_{n}-2k-M}$ holds with $F_{R_{n}+2k}^{t_{n}-2k-M}(l)$, we have a \textbf{success}: 
		\[
			R_{n+1}=R_{n}+4k+1-l,\:K_{n+1}=1\text{ and }t_{n+1}^{\prime}=t_{n}^{\prime}-M-l.
		\]
		Denote by $\alpha_{\epsilon}$ the probability of \textbf{success}.
              \end{itemize}
In the case $K_n = 2$, we define as follows.
	\begin{itemize}
		\item Fix $M_{1}\coloneqq\min\left\{ 0\leq m\leq H\mid O_{R_{n}+2k}^{t_{n}^{\prime}-2k-m}\text{ does not hold}\right\} $ as in the case $K_n = 1$.
		\item If we have a \textbf{failure}, we apply Equation \ref{eq:Rn-failure}.
              \item If we have a \textbf{success} but $M_{1}+l<H$, then it's only a \textbf{jump}.
                Then we fix a new $M_2$ and iterate the last step.
                In general, fix $M_{j+1}\coloneqq\min\left\{ m\leq H\mid O_{R_{n}+2k}^{t_{n}^{\prime}-\left(4j+2\right)k-m-\sum_{r=1}^{j}M_{r}}\text{ is not verified}\right\} $.
                If we have enough \textbf{success}es in a row with $\sum_{r=1}^{l}M_{r}+4jk+l_{j}\geq H$ (with $l_{j}$ the $l$ of the last success), then the barrier $H$ is overcome:
		\[
			R_{n+1}=R_{n}+4k+1-l_{j},\:K_{n+1}=1\text{ and }t_{n+1}^{\prime}=t_{n}^{\prime}-\sum_{r=1}^{l}M_{r}-4jk-l_{j}.
                      \]
                      If we have a \textbf{failure} before this, the entire process is a \textbf{failure} and we apply Equation \eqref{eq:Rn-failure}.
		Denote by $\beta_{\epsilon}$ the probability of overcoming a barrier.
	\end{itemize}
A step is illustrated on Figure \ref{fig:RightBorder}, while Figure \ref{fig:MAC-R} illustrates a trajectory of $(R_n,K_n)$.

