\subsection{Mean drift of the right border}
\label{subsec:Derive-Bordure-droite}

We can re-use the computations made for the left border with our new parameters:
\[
\alpha_{\epsilon}=\left(1-\epsilon\right)^{2k\left(2k+1\right)}\sum_{m=1}^{H}\left(p_{other}^{\epsilon}\right)^{m-1}p_{good}^{\epsilon}\tendsto{\epsilon}0 D_{a,k} \left(1-\frac{1}{a}\right)\eqqcolon\alpha
\]
and $\alpha\underset{a\to\infty}{=}1-\frac{5+\frac{2}{k}}{a}+o\left(\frac{1}{a}\right)$.

For the jump computations: if $N$ is the size of a jump,

\[
P\left(N=d\mid\text{\textbf{success}}\right)=\frac{\left(1-\epsilon\right)^{2k\left(2k+1\right)}(p_{other}^{\epsilon})^{d}\,p_{good}^{\epsilon}}{\left(1-\epsilon\right)^{2k\left(2k+1\right)}\sum_{m=1}^{H}(p_{other}^{\epsilon})^{m-1}\,p_{good}^{\epsilon}}
\]
and the same computations give
\[
P\left(N\geq\frac{H}{i}\mid\text{\textbf{success}}\right)\tendsto{\epsilon}0\left(\frac{1}{a}\right)^{1/i}\frac{1-\left(\frac{1}{a}\right)^{\frac{i-1}{i}}}{1-\frac{1}{a}}.
\]
The conclusion is then the same: for a fixed $m\in\N^{*}$, one can find a function $h:[0,1]\times\N\to[0,1]$ such that $\lim_{\epsilon\to0}h\left(\epsilon,a\right)\underset{a\to\infty}{\sim}\frac{m}{a}$ and $\beta_{\epsilon}\geq h\left(\epsilon,a\right)$. The mean drift of $\left(R_{n},K_{n}\right)$ is
\begin{align*}
\kappa^{\prime} & =\pi_{1}\sum_{m\in\Z}mP\left(R_{1}=m\mid K_{1}=1\right)+\pi_{2}\sum_{m\in\Z}mP\left(R_{1}=m\mid K_{1}=2\right)\\
 & =\pi_{1}\sum_{l=2k+1}^{ak-1}\left(4k+1-l\right)P\left(R_{1}=4k+1-l\mid K_{1}=1\right)+\pi_{2}4ak
\end{align*}
with $\pi=(\pi_{1},\pi_{2})\coloneqq\frac{1}{1-\alpha_{\epsilon}+\beta_{\epsilon}}(\beta_{\epsilon},1-\alpha_{\epsilon})$. The mean drift is then strictly negative if 

\begin{equation}
\beta_{\epsilon}\sum_{l=2k+1}^{ak-1}\left(l-4k-1\right)P\left(R_{1}=4k+1-l\mid K_{1}=1\right)>\left(1-\alpha_{\epsilon}\right)4ak.\label{eq:driftRightBorder}
\end{equation}
Observe that
\[
P\left(R_{1}=4k+1-l\mid K_{1}=1\right)=\frac{P\left(F_{0}^{0}\left(l\right)\right)}{P\left(\bigsqcup_{j=2k+1}^{ak-1}F_{0}^{0}\left(j\right)\right)}\tendsto{\epsilon}0\frac{2\left(ak-l\right)}{\left(\left(a-2\right)k-1\right)\left(a-2\right)k}
\]
and thus
\begin{align*}
\lim_{\epsilon\to0}\sum_{l=2k+1}^{ak-1}\left(l-4k-1\right)P\left(R_{1}=4k+1-l\mid K_{1}=1\right) & =\frac{2\sum_{l=2k+1}^{ak-1}\left(l-4k-1\right)\left(ak-l\right)}{\left(\left(a-2\right)k-1\right)\left(a-2\right)k}\\
 & \underset{a\to\infty}{\sim}\frac{ak}{3}.
\end{align*}
Finally, a sufficient condition is
\begin{equation}
\liminf_{\epsilon\to0}\beta_{\epsilon}>\frac{\left(1-\alpha\right)4ak}{\lim_{\epsilon\to0}\sum_{l=2k+1}^{ak-1}\left(l-4k-1\right)P\left(R_{1}=4k+1-l\mid K_{1}=1\right)}.\label{eq:conclusionDerive2}
\end{equation}
As $a\to\infty$, the right hand side is equivalent to $\frac{60+\frac{24}{k}}{a}<\frac{61}{a}$ (for $k>24$). The condition is then verified by choosing $m=61$: for $a$ large enough, $\kappa^{\prime}<0$ for $\epsilon$ small enough, thus $R_{n}\tendsto n{\infty}-\infty$ almost surely.

\subsection{Combining the left and right borders}

\begin{prop}\label{prop:Croisement p.s.}
If $L_n \tendsto{n}{\+\infty}+\infty$ and $R_n\tendsto{n}{+\infty}-\infty$ a.s., then $p_t(T_\epsilon)\tendsto{t}{+\infty}1$.
\end{prop}
\begin{proof}
Fix $\omega\in\Omega$ such that $L_n \tendsto{n}{\+\infty}+\infty$ and $R_n\tendsto{n}{+\infty}-\infty$. This implies that $l_t \tendsto{t}{+\infty}+\infty$ and $r_t \tendsto{t}{+\infty}-\infty$. So there exists a $T(\omega) < \infty$ such that $l_T > r_T$.

Then almost surely, there exists $T < \infty$ such that $x\mapsto \Psi^{T} \left(x ; U(\omega)\right)_0$ is constant by Lemma \ref{lem:emptyDependenceCone}. Therefore, $P\left(x\mapsto \Psi^t\left(x ; U(\omega)\right)_0 \text{ is constant}\right) \tendsto{t}{+\infty}1$.
\end{proof}

We can then finish the proof of Theorem \ref{thm:TransitionDePhase}. First fix a $k$ large enough so that it verifies the conditions stated in Section \ref{sec:errorsGLayer}. Then, fix $a$ large enough so that Equations \ref{eq:conclusionDerive1} and \ref{eq:conclusionDerive2} are verified. This means that for $\epsilon$ small enough, Equations \ref{eq:driftLeftBorder} and \ref{eq:driftRightBorder} are verified, and thus $L_{n}\tendsto n{+\infty}+\infty$ and $R_{n}\tendsto n{+\infty}-\infty$ almost surely. In other words, there exists an error rate $\epsilon_{1}$ such that for all $\epsilon\leq\epsilon_1$, the hypotheses of Proposition \ref{prop:Croisement p.s.} are verified and $T_{\epsilon}$ is ergodic. With our choice of $k$, $T_{\epsilon_2}$ is not ergodic.

\section{Conclusions}

This work shows that the ergodicity of a perturbed cellular automata with positive rate can have more than one phase transition depending on the value of the noise. An interesting direction to continue this work would be to understand which sets can be obtained as 
\[\{\epsilon\in[0,1]:\textrm{$F_\epsilon$ is ergodic}\}\]
where $F_\epsilon$ is a perturbation of a cellular automaton $F$ by a uniform noise of rate $\epsilon$.
Our construction is hardly adaptable, in part because we do not understand fully the invariant measures of the perturbation of the G\'acs cellular automaton.
In particular, we do not know how many phase transitions for ergodicity the perturbation of G\'acs cellular automaton realizes, nor do we know that our CA $T$ only realizes two.


