\section{Preliminaries} \label{S:Prelim}
This section gives basic notations and results used in the following sections.

\subsection{Basic notations} \label{SS:Pre_Not}
Throughout this paper, the symbol $c$ stands for a general positive constant independent of $\varepsilon$, $t$, and the viscosity coefficient $\nu$.

Vectors $\mathbf{a}\in\mathbb{R}^3$ and matrices $\mathbf{A}\in\mathbb{R}^{3\times 3}$ are written as
\begin{align*}
  \mathbf{a} =
  \begin{pmatrix}
    a_1 \\ a_2 \\ a_3
  \end{pmatrix}
  = (a_1,a_2,a_3)^{\mathrm{T}}, \quad \mathbf{A} = (A_{ij})_{i,j} =
  \begin{pmatrix}
    A_{11} & A_{12} & A_{13} \\
    A_{21} & A_{22} & A_{23} \\
    A_{31} & A_{32} & A_{33}
  \end{pmatrix}.
\end{align*}
Let $\mathbf{0}\in\mathbb{R}^3$ be the zero vector and $\mathbf{O}_3,\mathbf{I}_3\in\mathbb{R}^{3\times3}$ be the zero and identity matrices.
Also, let $\mathbf{A}^{\mathrm{T}}$ be the transpose of $\mathbf{A}\in\mathbb{R}^{3\times3}$.
The symmetric part of $\mathbf{A}$ and the tensor product of $\mathbf{a},\mathbf{b}\in\mathbb{R}^3$ are denoted by
\begin{align*}
  \mathbf{A}_{\mathrm{S}} := \frac{\mathbf{A}+\mathbf{A}^{\mathrm{T}}}{2}, \quad \mathbf{a}\otimes\mathbf{b}:=(a_ib_j)_{i,j}, \quad \mathbf{a} = (a_1,a_2,a_3)^{\mathrm{T}}, \quad \mathbf{b} = (b_1,b_2,b_3)^{\mathrm{T}}.
\end{align*}
Moreover, we define the inner product and the Frobenius norm of matrices by
\begin{align*}
  \mathbf{A}:\mathbf{B} := \mathrm{tr}[\mathbf{A}^{\mathrm{T}}\mathbf{B}], \quad |\mathbf{A}| := \sqrt{\mathbf{A}:\mathbf{A}}, \quad \mathbf{A},\mathbf{B}\in\mathbb{R}^{3\times 3}.
\end{align*}
For $\mathbf{A},\mathbf{B},\mathbf{C}\in\mathbb{R}^{3\times3}$, we easily observe by $\mathbf{A}:\mathbf{B}=\sum_{i,j=1}^3A_{ij}B_{ij}$ that
\begin{align} \label{E:Mat_Inn}
  \mathbf{A}:\mathbf{B} = \mathbf{A}^{\mathrm{T}}:\mathbf{B}^{\mathrm{T}}, \quad [\mathbf{A}\mathbf{B}]:\mathbf{C} = \mathbf{B}:[\mathbf{A}^{\mathrm{T}}\mathbf{C}] = \mathbf{A}:[\mathbf{C}\mathbf{B}^{\mathrm{T}}].
\end{align}
When $\mathbf{u}=(u_1,u_2,u_3)^{\mathrm{T}}$ and $\bm{\psi}$ are mappings from a subset of $\mathbb{R}^3$ into $\mathbb{R}^3$, we write
\begin{align*}
  \nabla\mathbf{u} := (\partial_iu_j)_{i,j}, \quad \mathbf{D}(\mathbf{u}) := (\nabla\mathbf{u})_{\mathrm{S}}, \quad (\bm{\psi}\cdot\nabla)\mathbf{u} := (\bm{\psi}\cdot\nabla u_1,\bm{\psi}\cdot\nabla u_2,\bm{\psi}\cdot\nabla u_3)^{\mathrm{T}}.
\end{align*}
Note that the indices of $\partial_iu_j$ are reversed in some literature.
Our choice makes
\begin{align*}
  \nabla[\varphi\mathbf{u}] = (\nabla\varphi)\otimes\mathbf{u}+\varphi\nabla\mathbf{u}, \quad \nabla[\mathbf{u}\circ\Phi] = [\nabla\Phi][(\nabla\mathbf{u})\circ\Phi]
\end{align*}
for $\varphi\colon\mathbb{R}^3\to\mathbb{R}$ and $\Phi\colon\mathbb{R}^3\to\mathbb{R}^3$.
Also, we set
\begin{align*}
  \mathrm{div}\,\mathbf{A} := ([\mathrm{div}\,\mathbf{A}]_1,[\mathrm{div}\,\mathbf{A}]_2,[\mathrm{div}\,\mathbf{A}]_3)^{\mathrm{T}}, \quad [\mathrm{div}\,\mathbf{A}]_j := \textstyle\sum_{i=1}^3\partial_iA_{ij}
\end{align*}
for an $\mathbb{R}^{3\times3}$-valued function $\mathbf{A}=(A_{ij})_{i,j}$.



\subsection{Bochner spaces} \label{SS:Pre_Boch}
Let us recall some results on Bochner spaces.

For a Banach space $\mathcal{X}$, let $\mathcal{X}^\ast$ be the dual space of $\mathcal{X}$ and $\langle\cdot,\cdot\rangle_{\mathcal{X}}$ be the duality product between $\mathcal{X}^\ast$ and $\mathcal{X}$.
Also, for an interval $I$ in $\mathbb{R}$, let $C_{\mathrm{weak}}(I;\mathcal{X})$ be the space of weakly continuous functions on $I$ with values in $\mathcal{X}$.
Clearly, $C(I;\mathcal{X}) \subset C_{\mathrm{weak}}(I;\mathcal{X})$.

\begin{lemma} \label{L:BS_WeCo}
  Let $\mathcal{X}$ and $\mathcal{Y}$ be Banach spaces such that $\mathcal{X}$ is reflexive and continuously embedded into $\mathcal{Y}$.
  Then,
  \begin{align*}
    L^\infty(0,T;\mathcal{X})\cap C_{\mathrm{weak}}([0,T];\mathcal{Y})\subset C_{\mathrm{weak}}([0,T];\mathcal{X}).
  \end{align*}
\end{lemma}

\begin{proof}
  We refer to \cite[Chapter 3, Lemma 1.4]{Tem01} and \cite[Lemma II.5.9]{BoyFab13} for the proof.
\end{proof}


Let $u,v\in L^1(0,T;\mathcal{X})$.
We write $v=\partial_tu$ if
\begin{align*}
  \int_0^T\langle\varphi(t),v(t)\rangle_{\mathcal{X}}\,dt = -\int_0^T\langle\partial_t\varphi(t),u(t)\rangle_{\mathcal{X}}\,dt
\end{align*}
for all $\varphi\in C_c^1(0,T;\mathcal{X}^\ast)$.
In this case, $u\in C([0,T];\mathcal{X})$.

\begin{lemma} \label{L:BS_Ipl}
  Let $\mathcal{H}$ and $\mathcal{V}$ be Hilbert spaces such that $\mathcal{V}$ is continuously and densely embedded into $\mathcal{H}$.
  We consider $\mathcal{V}\hookrightarrow\mathcal{H}\hookrightarrow\mathcal{V}^\ast$ by
  \begin{align*}
    \langle u,v\rangle_{\mathcal{V}} := (u,v)_{\mathcal{H}}, \quad u\in\mathcal{H}, \, v\in\mathcal{V},
  \end{align*}
  where $(\cdot,\cdot)_{\mathcal{H}}$ is the inner product of $\mathcal{H}$.
  For $T>0$, we define
  \begin{align} \label{E:Def_ETV}
    \mathbb{E}_T(\mathcal{V}) := \{u\in L^2(0,T;\mathcal{V}) \mid \partial_tu\in L^2(0,T;\mathcal{V}^\ast)\}.
  \end{align}
  Then, $\mathbb{E}_T(\mathcal{V})\subset C([0,T];\mathcal{H})$.
  Moreover,
  \begin{align} \label{E:Dt_IbP}
    \frac{d}{dt}\bigl(u_1(t),u_2(t)\bigr)_{\mathcal{H}} = \langle\partial_tu_1(t),u_2(t)\rangle_{\mathcal{V}}+\langle\partial_tu_2(t),u_1(t)\rangle_{\mathcal{V}}
  \end{align}
  for all $u_1,u_2\in\mathbb{E}_T(\mathcal{V})$ and a.a. $t\in(0,T)$.
\end{lemma}

\begin{proof}
  We refer to \cite[Chapter 3, Lemma 1.2]{Tem01} and \cite[Theorems II.5.12 and II.5.13]{BoyFab13} for the proof.
\end{proof}



\subsection{Unit sphere} \label{SS:Pre_Sph}
Let $S^2$ be the unit sphere in $\mathbb{R}^3$ and $\mathbf{n}(y):=y$ be the unit outward normal vector field of $S^2$.
Also, let $\mathbf{P}:=\mathbf{I}_3-\mathbf{n}\otimes\mathbf{n}$ be the orthogonal projection onto the tangent plane of $S^2$.
Then, we easily find that
\begin{align*}
  \mathbf{P}^{\mathrm{T}} = \mathbf{P}^2 = \mathbf{P}, \quad |\mathbf{P}|^2 = \mathrm{tr}[\mathbf{P}^{\mathrm{T}}\mathbf{P}] = \mathrm{tr}[\mathbf{P}] = 2 \quad\text{on}\quad S^2.
\end{align*}
In what follows, we frequently use these relations (sometimes without mention).

We define the tangential gradient of a function $\eta$ on $S^2$ by
\begin{align*}
  \nabla_{S^2}\eta = (\underline{D}_1\eta,\underline{D}_2\eta,\underline{D}_3\eta)^{\mathrm{T}} := \mathbf{P}\nabla\tilde{\eta} \quad\text{on}\quad S^2.
\end{align*}
Here, $\tilde{\eta}$ is an extension of $\eta$ to an open neighborhood of $S^2$ in $\mathbb{R}^3$ and the value of $\nabla_{S^2}\eta$ does not depend on the choice of $\tilde{\eta}$.
Next, we define the tangential gradient matrix, the surface divergence, and the surface strain rate tensor of a vector field $\mathbf{v}$ on $S^2$ by
\begin{align*}
  \nabla_{S^2}\mathbf{v} := (\underline{D}_iv_j)_{i,j}, \quad \mathrm{div}_{S^2}\mathbf{v} := \mathrm{tr}[\nabla_{S^2}\mathbf{v}], \quad \mathbf{D}_{S^2}(\mathbf{v}) := \mathbf{P}(\nabla_{S^2}\mathbf{v})_{\mathrm{S}}\mathbf{P} \quad\text{on}\quad S^2,
\end{align*}
respectively, where $\mathbf{v}=(v_1,v_2,v_3)^{\mathrm{T}}$.
The indices of $\underline{D}_iv_j$ are reversed in some literature.
Our notation yields $\nabla_{S^2}\mathbf{v}=\mathbf{P}\nabla\tilde{\mathbf{v}}$ for any extension $\tilde{\mathbf{v}}$ of $\mathbf{v}$.
In particular, we have
\begin{align} \label{E:TGr_Nor}
  \nabla_{S^2}\mathbf{n} = \mathbf{P}, \quad \mathrm{div}_{S^2}\mathbf{n} = \mathrm{tr}[\mathbf{P}] = 2 \quad\text{on}\quad S^2
\end{align}
by taking the extension $\tilde{\mathbf{n}}(x):=x$.
Note that $H:=-\mathrm{div}_{S^2}\mathbf{n}=-2$ is the mean curvature of $S^2$.
We define the Laplace--Beltrami operator on $S^2$ by
\begin{align*}
  \Delta_{S^2}\eta := \mathrm{div}_{S^2}(\nabla_{S^2}\eta) \quad\text{on}\quad S^2, \quad \eta\colon S^2\to\mathbb{R}.
\end{align*}
Let $\mathbf{v}=(v_1,v_2,v_3)^{\mathrm{T}}$ and $\mathbf{w}$ be vector fields on $S^2$.
We set
\begin{align*}
  (\mathbf{w}\cdot\nabla_{S^2})\mathbf{v} := (\mathbf{w}\cdot\nabla_{S^2}v_1,\mathbf{w}\cdot\nabla_{S^2}v_2,\mathbf{w}\cdot\nabla_{S^2}v_3)^{\mathrm{T}} \quad\text{on}\quad S^2.
\end{align*}
When $\mathbf{v}$ and $\mathbf{w}$ are tangential (i.e. $\mathbf{v}\cdot\mathbf{n}=\mathbf{w}\cdot\mathbf{n}=0$) on $S^2$, we define
\begin{align*}
  \nabla_{\mathbf{w}}\mathbf{v} := \mathbf{P}[(\mathbf{w}\cdot\nabla_{S^2})\mathbf{v}] \quad\text{on}\quad S^2
\end{align*}
and call it the covariant derivative of $\mathbf{v}$ along $\mathbf{w}$.
We also set
\begin{align*}
  \mathrm{div}_{S^2}\mathbf{A} := ([\mathrm{div}_{S^2}\mathbf{A}]_1,[\mathrm{div}_{S^2}\mathbf{A}]_2,[\mathrm{div}_{S^2}\mathbf{A}]_3)^{\mathrm{T}}, \quad [\mathrm{div}_{S^2}\mathbf{A}]_j := \textstyle\sum_{i=1}^3\underline{D}_iA_{ij}
\end{align*}
on $S^2$ for an $\mathbb{R}^{3\times3}$-valued function $\mathbf{A}=(A_{ij})_{i,j}$ on $S^2$.
Let us give basic formulas.

\begin{lemma} \label{L:Vec_Tan}
  For $\mathbf{v}\colon S^2\to\mathbb{R}^3$, let $\mathbf{v}_\tau:=\mathbf{P}\mathbf{v}$ be its tangential component.
  Then,
  \begin{align}
    \nabla_{S^2}\mathbf{v}_\tau &= (\nabla_{S^2}\mathbf{v})\mathbf{P}-\mathbf{v}_\tau\otimes\mathbf{n}-(\mathbf{v}\cdot\mathbf{n})\mathbf{P} \quad\text{on}\quad S^2, \label{E:Vec_Tan} \\
    \mathbf{D}_{S^2}(\mathbf{v}_\tau) &= \mathbf{D}_{S^2}(\mathbf{v})-(\mathbf{v}\cdot\mathbf{n})\mathbf{P} \quad\text{on}\quad S^2. \label{E:VT_str}
  \end{align}
\end{lemma}

\begin{proof}
  Since $\mathbf{v}_\tau=\mathbf{P}\mathbf{v}=\mathbf{v}-(\mathbf{v}\cdot\mathbf{n})\mathbf{n}$ on $S^2$,
  \begin{align*}
    \nabla_{S^2}\mathbf{v}_\tau = \nabla_{S^2}\mathbf{v}-[\nabla_{S^2}(\mathbf{v}\cdot\mathbf{n})]\otimes\mathbf{n}-(\mathbf{v}\cdot\mathbf{n})\nabla_{S^2}\mathbf{n}
  \end{align*}
  on $S^2$.
  Moreover, we see by \eqref{E:TGr_Nor} that
  \begin{align*}
    \nabla_{S^2}(\mathbf{v}\cdot\mathbf{n}) = (\nabla_{S^2}\mathbf{v})\mathbf{n}+(\nabla_{S^2}\mathbf{n})\mathbf{v} = (\nabla_{S^2}\mathbf{v})\mathbf{n}+\mathbf{P}\mathbf{v} = (\nabla_{S^2}\mathbf{v})\mathbf{n}+\mathbf{v}_\tau
  \end{align*}
  on $S^2$.
  Combining the above relations and using \eqref{E:TGr_Nor} and
  \begin{align*}
    \nabla_{S^2}\mathbf{v}-[(\nabla_{S^2}\mathbf{v})\mathbf{n}]\otimes\mathbf{n} = \nabla_{S^2}\mathbf{v}-(\nabla_{S^2}\mathbf{v})(\mathbf{n}\otimes\mathbf{n}) = (\nabla_{S^2}\mathbf{v})\mathbf{P},
  \end{align*}
  we obtain \eqref{E:Vec_Tan}.
  Also, applying $\mathbf{P}$ to \eqref{E:Vec_Tan} from both sides, and using
  \begin{align*}
    \mathbf{P}^2 = \mathbf{P}^{\mathrm{T}} = \mathbf{P}, \quad (\mathbf{v}_\tau\otimes\mathbf{n})\mathbf{P} = \mathbf{v}_\tau\otimes[\mathbf{P^{\mathrm{T}}\mathbf{n}}] = \mathbf{v}_\tau\otimes[\mathbf{P}\mathbf{n}] = \mathbf{v}_\tau\otimes\mathbf{0} = \mathbf{O}_3,
  \end{align*}
  we get $\mathbf{P}(\nabla_{S^2}\mathbf{v}_\tau)\mathbf{P}=\mathbf{P}(\nabla_{S^2}\mathbf{v})\mathbf{P}-(\mathbf{v}\cdot\mathbf{n})\mathbf{P}$, whose symmetric part gives \eqref{E:VT_str}.
\end{proof}

\begin{lemma} \label{L:Gauss}
  For tangential vector fields $\mathbf{v}$ and $\mathbf{w}$ on $S^2$, we have
  \begin{align}
    (\mathbf{w}\cdot\nabla_{S^2})\mathbf{v} &= \nabla_{\mathbf{w}}\mathbf{v}-(\mathbf{v}\cdot\mathbf{w})\mathbf{n} \quad\text{on}\quad S^2, \label{E:Gauss} \\
    \nabla_{S^2}\mathbf{v} &= \mathbf{P}(\nabla_{S^2}\mathbf{v})\mathbf{P}-\mathbf{v}\otimes\mathbf{n} \quad\text{on}\quad S^2. \label{E:TGr_Dec}
  \end{align}
  Note that the first formula is the Gauss formula.
\end{lemma}

\begin{proof}
  Applying $\nabla_{S^2}$ to $\mathbf{v}\cdot\mathbf{n}=0$ on $S^2$ and using \eqref{E:TGr_Nor}, we have
  \begin{align*}
    (\nabla_{S^2}\mathbf{v})\mathbf{n}+(\nabla_{S^2}\mathbf{n})\mathbf{v} = \mathbf{0}, \quad (\nabla_{S^2}\mathbf{v})\mathbf{n} = -(\nabla_{S^2}\mathbf{n})\mathbf{v} = -\mathbf{P}\mathbf{v} = -\mathbf{v}.
  \end{align*}
  Hence, $[(\mathbf{w}\cdot\nabla_{S^2})\mathbf{v}]\cdot\mathbf{n}=\mathbf{w}\cdot[(\nabla_{S^2}\mathbf{v})\mathbf{n}]=-\mathbf{w}\cdot\mathbf{v}$ and \eqref{E:Gauss} follows.
  Also, by
  \begin{align*}
    \nabla_{S^2}\mathbf{v} = (\nabla_{S^2}\mathbf{v})\mathbf{P}+(\nabla_{S^2}\mathbf{v})(\mathbf{n}\otimes\mathbf{n}) = (\nabla_{S^2}\mathbf{v})\mathbf{P}+[(\nabla_{S^2}\mathbf{v})\mathbf{n}]\otimes\mathbf{n},
  \end{align*}
  and by $\nabla_{S^2}\mathbf{v}=\mathbf{P}\nabla_{S^2}\mathbf{v}$ and $(\nabla_{S^2}\mathbf{v})\mathbf{n}=-\mathbf{v}$, we have \eqref{E:TGr_Dec}.
\end{proof}

\begin{lemma} \label{L:Const}
  For a function $\eta$ on $S^2$ and $x\in\mathbb{R}^3\setminus\{0\}$, let $\bar{\eta}(x):=\eta(x/|x|)$ be the constant extension of $\eta$ in the radial direction.
  Then,
  \begin{align} \label{E:Const}
    \nabla\bar{\eta}(x) = \frac{1}{|x|}\,\overline{\nabla_{S^2}\eta}(x), \quad x\in\mathbb{R}^3\setminus\{0\}.
  \end{align}
\end{lemma}

\begin{proof}
  Since $\mathbf{P}(y)=\mathbf{I}_3-y\otimes y$ for $y\in S^2$, we have
  \begin{align} \label{Pf_Co:Gr_x}
    \nabla\left(\frac{x}{|x|}\right) = \frac{1}{|x|}\left(\mathbf{I}_3-\frac{x}{|x|}\otimes\frac{x}{|x|}\right) = \frac{1}{|x|}\mathbf{P}\left(\frac{x}{|x|}\right) = \frac{1}{|x|}\overline{\mathbf{P}}(x)
  \end{align}
  for $x\in\mathbb{R}^3\setminus\{0\}$.
  We differentiate $\bar{\eta}(x)=\bar{\eta}(x/|x|)$ in $x$.
  Then, we see that
  \begin{align*}
    \nabla\bar{\eta}(x) = \frac{1}{|x|}\,\mathbf{P}\left(\frac{x}{|x|}\right)[\nabla\bar{\eta}]\left(\frac{x}{|x|}\right) = \frac{1}{|x|}\nabla_{S^2}\eta\left(\frac{x}{|x|}\right) = \frac{1}{|x|}\overline{\nabla_{S^2}\eta}(x)
  \end{align*}
  by \eqref{Pf_Co:Gr_x} and $\mathbf{P}(y)\nabla\bar{\eta}(y)=\nabla_{S^2}\eta(y)$ for $y=x/|x|\in S^2$.
  Hence, \eqref{E:Const} holds.
\end{proof}

Let $\mathcal{H}^2$ be the two-dimensional Hausdorff measure.
For functions $\eta$ and $\zeta$ on $S^2$, it is known that the integration by parts formula
\begin{align} \label{E:IbP_S2}
  \int_{S^2}(\underline{D}_i\eta)\zeta\,d\mathcal{H}^2 = -\int_{S^2}\eta(\underline{D}_i\zeta-2\zeta n_i)\,d\mathcal{H}^2, \quad i=1,2,3
\end{align}
holds (see \cite[Lemma 16.1]{GilTru01} and \cite[Theorem 2.10]{DziEll13_AN}), where $-2=H$ is the mean curvature of $S^2$ and $\mathbf{n}=(n_1,n_2,n_3)^{\mathrm{T}}$.
For $\eta\in L^2(S^2)$, we define $\underline{D}_i\eta\in L^2(S^2)$ as a function satisfying \eqref{E:IbP_S2} for all $\zeta\in C^1(S^2)$ (if exists), and set the Sobolev space
\begin{align*}
  H^1(S^2) := \{\eta\in L^2(S^2) \mid \nabla_{S^2}\eta = (\underline{D}_1\eta,\underline{D}_2\eta,\underline{D}_3\eta)^{\mathrm{T}}\in L^2(S^2)^3\}
\end{align*}
with inner product $(\eta_1,\eta_2)_{H^1(S^2)}:=(\eta_1,\eta_2)_{L^2(S^2)}+(\nabla_{S^2}\eta_1,\nabla_{S^2}\eta_2)_{L^2(S^2)}$.

We define the spaces of tangential vector fields on $S^2$ of class $\mathcal{X}$ by
\begin{align*}
  \mathcal{X}_\tau(S^2) := \{\mathbf{v}\in\mathcal{X}(S^2)^3 \mid \text{$\mathbf{v}\cdot\mathbf{n}=0$ on $S^2$}\}.
\end{align*}
Note that $\mathcal{X}_\tau(S^2)$ is a closed subspace of $\mathcal{X}(S^2)^3$.
Next, we define the spaces of tangential and solenoidal vector fields on $S^2$ by
\begin{align*}
  \mathcal{H}_0 := \{\mathbf{v}\in L_\tau^2(S^2) \mid \text{$\mathrm{div}_{S^2}\mathbf{v}=0$ on $S^2$}\}, \quad \mathcal{V}_0 := \mathcal{H}_0\cap H_\tau^1(S^2).
\end{align*}
In the above, we consider $\mathrm{div}_{S^2}\mathbf{v}$ for $\mathbf{v}\in L_\tau^2(S^2)$ as an element of $[H^1(S^2)]^\ast$ by
\begin{align*}
  \langle\mathrm{div}_{S^2}\mathbf{v},\eta\rangle_{H^1(S^2)} := -(\mathbf{v},\nabla_{S^2}\eta)_{L^2(S^2)}, \quad \eta\in H^1(S^2).
\end{align*}
We easily see that $\mathcal{H}_0$ and $\mathcal{V}_0$ are closed subspaces of $L_\tau^2(S^2)$ and $H_\tau^1(S^2)$, respectively.
Let $\mathbb{L}_0$ be the Helmholtz--Leray projection on $L_\tau^2(S^2)$, i.e. the orthogonal projection from $L_\tau^2(S^2)$ onto $\mathcal{H}_0$.
As in the planar case, $\mathbb{L}_0\mathbf{v}=\mathbf{v}-\nabla_{S^2}\eta$ for $\mathbf{v}\in L_\tau^2(S^2)$, where $\eta$ is a weak solution to Poisson's equation
\begin{align} \label{E:Pois_S2}
  \Delta_{S^2}\eta = \mathrm{div}_{S^2}\mathbf{v} \quad\text{on}\quad S^2, \quad \eta\in H^1(S^2), \quad \int_{S^2}\eta\,d\mathcal{H}^2 = 0,
\end{align}
which is uniquely solvable by Poincare's inequality and the Lax--Milgram theorem.

Let us state basic results related to functions on $S^2$.

\begin{lemma} \label{L:Den_S2}
  Let $\mathcal{X}=L^2,H^1$.
  The space $C_\tau^\infty(S^2)$ is dense in $\mathcal{X}_\tau(S^2)$.
\end{lemma}

\begin{proof}
  We first note that $C^\infty(S^2)$ is dense in $\mathcal{X}(S^2)$.
  This is shown by standard localization and mollification arguments, so we omit details here.

  Let $\mathbf{v}\in\mathcal{X}_\tau(S^2)\subset \mathcal{X}(S^2)^3$.
  We can take $\mathbf{w}_k\in C^\infty(S^2)^3$ such that $\mathbf{w}_k\to\mathbf{v}$ strongly in $\mathcal{X}(S^2)^3$ as $k\to\infty$.
  Then, $\mathbf{v}_k:=\mathbf{P}\mathbf{w}_k \in C_\tau^\infty(S^2)$ by the smoothness of $\mathbf{P}$.
  Moreover,
  \begin{align*}
    \|\mathbf{v}-\mathbf{v}_k\|_{\mathcal{X}(S^2)} = \|\mathbf{P}(\mathbf{v}-\mathbf{w}_k)\|_{\mathcal{X}(S^2)} \leq c\|\mathbf{v}-\mathbf{w}_k\|_{\mathcal{X}(S^2)} \to 0
  \end{align*}
  as $k\to\infty$, since $\mathbf{P}\mathbf{v}=\mathbf{v}$ by $\mathbf{v}\cdot\mathbf{n}=0$ on $S^2$.
  Hence, $C_\tau^\infty(S^2)$ is dense in $\mathcal{X}_\tau(S^2)$.
\end{proof}

\begin{lemma} \label{L:Lad_S2}
  For $\eta\in H^1(S^2)$, we have Ladyzhenskaya's inequality
  \begin{align} \label{E:Lad_S2}
    \|\eta\|_{L^4(S^2)} \leq c\|\eta\|_{L^2(S^2)}^{1/2}\|\eta\|_{H^1(S^2)}^{1/2}.
  \end{align}
\end{lemma}

\begin{proof}
  We refer to \cite[Lemma 4.1]{Miu21_02} for the proof.
\end{proof}

\begin{lemma} \label{L:Korn_S2}
  For $\mathbf{v}\in H_\tau^1(S^2)$, we have Korn's inequality
  \begin{align} \label{E:Korn_S2}
    \|\nabla_{S^2}\mathbf{v}\|_{L^2(S^2)} \leq c\Bigl(\|\mathbf{D}_{S^2}(\mathbf{v})\|_{L^2(S^2)}+\|\mathbf{v}\|_{L^2(S^2)}\Bigr).
  \end{align}
\end{lemma}

\begin{proof}
  We refer to \cite[Lemma 4.1]{JaOlRe18} and \cite[Lemma 4.2]{Miu20_03} for the proof.
\end{proof}

\begin{lemma} \label{L:HLH1_S2}
  If $\mathbf{v}\in H_\tau^1(S^2)$, then $\mathbb{L}_0\mathbf{v}\in\mathcal{V}_0$ and
  \begin{align} \label{E:HLH1_S2}
    \|\mathbf{v}-\mathbb{L}_0\mathbf{v}\|_{H^1(S^2)} \leq c\|\mathrm{div}_{S^2}\mathbf{v}\|_{L^2(S^2)}, \quad \|\mathbb{L}_0\mathbf{v}\|_{H^1(S^2)} \leq c\|\mathbf{v}\|_{H^1(S^2)}.
  \end{align}
\end{lemma}

\begin{proof}
  Since $\mathrm{div}_{S^2}\mathbf{v}\in L^2(S^2)$, the weak solution $\eta$ to \eqref{E:Pois_S2} satisfies
  \begin{align*}
    \eta \in H^2(S^2), \quad \|\eta\|_{H^2(S^2)} \leq c\|\mathrm{div}_{S^2}\mathbf{v}\|_{L^2(S^2)}
  \end{align*}
  by the elliptic regularity theorem (see e.g. \cite[Theorem 3.3]{DziEll13_AN}).
  Since $\mathbb{L}_0\mathbf{v}=\mathbf{v}-\nabla_{S^2}\eta$, the above results show that $\mathbb{L}_0\mathbf{v}\in\mathcal{V}_0$ and \eqref{E:HLH1_S2} holds.
\end{proof}

\begin{lemma} \label{L:Sol_S2}
  The space $\mathcal{V}_0$ is dense in $\mathcal{H}_0$.
\end{lemma}

\begin{proof}
  Let $\mathbf{v}\in\mathcal{H}_0\subset L_\tau^2(S^2)$.
  By Lemma \ref{L:Den_S2}, we can take $\mathbf{w}_k\in C_\tau^\infty(S^2)$ such that $\mathbf{w}_k\to\mathbf{v}$ strongly in $L^2(S^2)^3$ as $k\to\infty$.
  Then, $\mathbf{v}_k:=\mathbb{L}_0\mathbf{w}_k\in\mathcal{V}_0$ by Lemma \ref{L:HLH1_S2} and
  \begin{align*}
    \|\mathbf{v}-\mathbf{v}_k\|_{L^2(S^2)} = \|\mathbb{L}_0(\mathbf{v}-\mathbf{w}_k)\|_{L^2(S^2)} \leq \|\mathbf{v}-\mathbf{w}_k\|_{L^2(S^2)} \to 0
  \end{align*}
  as $k\to\infty$, since $\mathbf{v}\in\mathcal{H}_0$ and $\mathbb{L}_0$ is the orthogonal projection from $L_\tau^2(S^2)$ onto $\mathcal{H}_0$.
  Hence, $\mathcal{V}_0$ is dense in $\mathcal{H}_0$.
\end{proof}

By Lemma \ref{L:Sol_S2}, we can apply Lemma \ref{L:BS_Ipl} with $\mathcal{H}=\mathcal{H}_0$ and $\mathcal{V}=\mathcal{V}_0$.



\subsection{Thin spherical shell} \label{SS:Pre_TSS}
For a sufficiently small $\varepsilon\in(0,1)$, let
\begin{align*}
  \Omega_\varepsilon = \{x\in\mathbb{R}^3 \mid 1<|x|<1+\varepsilon\}
\end{align*}
be the thin spherical shell in $\mathbb{R}^3$ and $\mathbf{n}_\varepsilon$ be the unit outward normal vector field of $\partial\Omega_\varepsilon$.
The following results are shown in \cite{Miu21_02,Miu22_01} for curved thin domains around general closed surfaces including the thin spherical shell.
Recall that $c$ denotes a general positive constant independent of $\varepsilon$ and $\bar{\eta}(x)=\eta(x/|x|)$ is the constant extension of a function $\eta$ on $S^2$.

\begin{lemma} \label{L:Korn_Thin}
  For $\mathbf{u}\in H^1(\Omega_\varepsilon)^3$ satisfying $\mathbf{u}\cdot\mathbf{n}_\varepsilon=0$ on $\partial\Omega_\varepsilon$, we have
  \begin{align} \label{E:Korn_Thin}
    \|\nabla\mathbf{u}\|_{L^2(\Omega_\varepsilon)}^2 \leq 4\|\mathbf{D}(\mathbf{u})\|_{L^2(\Omega_\varepsilon)}^2+c\|\mathbf{u}\|_{L^2(\Omega_\varepsilon)}^2.
  \end{align}
\end{lemma}

\begin{proof}
  We refer to \cite[Lemma 5.1]{Miu22_01} for the proof.
\end{proof}

\begin{lemma} \label{L:Nor_Thin}
  For $\mathbf{u}\in H^1(\Omega_\varepsilon)^3$ satisfying $\mathbf{u}\cdot\mathbf{n}_\varepsilon=0$ on $\partial\Omega_\varepsilon$, we have
  \begin{align} \label{E:Nor_Thin}
    \|\mathbf{u}\cdot\bar{\mathbf{n}}\|_{L^2(\Omega_\varepsilon)} \leq c\varepsilon\|\mathbf{u}\|_{H^1(\Omega_\varepsilon)}.
  \end{align}
\end{lemma}

\begin{proof}
  We refer to \cite[Lemma 4.5]{Miu21_02} for the proof.
\end{proof}

\begin{lemma} \label{L:Quad_Thin}
  For $\eta\in H^1(S^2)$ and $\varphi\in H^1(\Omega_\varepsilon)$, we have
  \begin{align} \label{E:Quad_Thin}
    \|\bar{\eta}\varphi\|_{L^2(\Omega_\varepsilon)} \leq c\|\eta\|_{L^2(S^2)}^{1/2}\|\eta\|_{H^1(S^2)}^{1/2}\|\varphi\|_{L^2(\Omega_\varepsilon)}^{1/2}\|\varphi\|_{H^1(\Omega_\varepsilon)}^{1/2}.
  \end{align}
\end{lemma}

\begin{proof}
  We refer to \cite[Lemma 6.19]{Miu21_02} for the proof.
\end{proof}

We define the space of $L^2$ solenoidal vector fields on $\Omega_\varepsilon$ by
\begin{align*}
  \mathcal{H}_\varepsilon := \{\mathbf{u}\in L^2(\Omega_\varepsilon)^3 \mid \text{$\mathrm{div}\,\mathbf{u}=0$ in $\Omega_\varepsilon$, $\mathbf{u}\cdot\mathbf{n}_\varepsilon=0$ on $\partial\Omega_\varepsilon$}\}.
\end{align*}
It is known that $\mathcal{H}_\varepsilon$ is the closure in $L^2(\Omega_\varepsilon)^3$ of
\begin{align*}
  C_{c,\sigma}^\infty(\Omega_\varepsilon) := \{\mathbf{u}\in C_c^\infty(\Omega_\varepsilon)^3 \mid \text{$\mathrm{div}\,\mathbf{u}=0$ in $\Omega_\varepsilon$}\},
\end{align*}
see \cite[Chapter 1, Theorem 1.4]{Tem01} and \cite[Theorem IV.3.5]{BoyFab13}.
In particular, $\mathcal{H}_\varepsilon$ is a closed subspace of $L^2(\Omega_\varepsilon)^3$.
We also define the space of $H^1$ solenoidal vector fields
\begin{align*}
  \mathcal{V}_\varepsilon := \mathcal{H}_\varepsilon\cap H^1(\Omega_\varepsilon) = \{\mathbf{u}\in H^1(\Omega_\varepsilon)^3 \mid \text{$\mathrm{div}\,\mathbf{u}=0$ in $\Omega_\varepsilon$, $\mathbf{u}\cdot\mathbf{n}_\varepsilon=0$ on $\partial\Omega_\varepsilon$}\}.
\end{align*}
It is a closed subspace of $H^1(\Omega_\varepsilon)^3$.
Also, $\mathcal{V}_\varepsilon$ is dense in $\mathcal{H}_\varepsilon$, since $C_{c,\sigma}^\infty(\Omega_\varepsilon)\subset\mathcal{V}_\varepsilon$.
Thus, we can use Lemma \ref{L:BS_Ipl} with $\mathcal{H}=\mathcal{H}_\varepsilon$ and $\mathcal{V}=\mathcal{V}_\varepsilon$.
Note that
\begin{align*}
  \mathcal{V}_\varepsilon \neq \{\mathbf{u} \in H^1(\Omega_\varepsilon)^3 \mid \text{$\mathrm{div}\,\mathbf{u}=0$ in $\Omega_\varepsilon$, $\mathbf{u}=\mathbf{0}$ on $\partial\Omega_\varepsilon$}\},
\end{align*}
where the latter space is the closure of $C_{c,\sigma}^\infty(\Omega_\varepsilon)$ in $H^1(\Omega_\varepsilon)^3$.





