\section{SICov in terms of static response}
\label{sec:response}

We express the SICov and the difference of excess observables $X_k - X_l$ to static responses. 
The static response describes the change of steady state probability due to the perturbations of a model parameter $p$ controlling the rates $\mathbb{W}(p)$. Following \cite{cho2000markov, harvey2023universal, ptaszynski2024critical, ptaszynski2024frr, bao2024nonequilibrium}, it can be written as
\begin{align}
\label{eq:response-1}
    \frac{d\boldsymbol{\pi}}{dp} = - \mathbb{W}^D \frac{\partial \mathbb{W}}{\partial p}\boldsymbol{\pi}\,,
\end{align}
which is an alternative approach to \cite{aslyamov2024nonequilibrium,aslyamov2024general}. 
Choosing $p = W_{mn}$ and $p = W_{nm}$, $\partial_p \mathbb{W}$ reads 
\begin{align}
\label{eq:response-2}
\partial_{W_{mn}}\mathbb{W}=
\begin{blockarray}{ccccccccc}
& &  \color{gray} \dots & \color{gray} n & \color{gray}\dots & \\
\begin{block}{cc (ccccccc)}
\color{gray} \vdots & &  \phantom{0} & \phantom{0} & \phantom{0} & \phantom{0} \\
\color{gray} m & & \phantom{0} & 1 & \phantom{0} & \phantom{0} \\
\color{gray} \vdots & &  \phantom{0} & \phantom{0} & \phantom{0} & \phantom{0} \\
\color{gray} n & & \phantom{0} & -1 & \phantom{0} & \phantom{0} \\
\color{gray} \vdots & &  \phantom{0} & \phantom{0} & \phantom{0} & \phantom{0}\\
\end{block}
\end{blockarray}\,\,,
\quad
\partial_{W_{nm}}\mathbb{W}=
\begin{blockarray}{ccccccccc}
& &  \color{gray} \dots & \color{gray} m & \color{gray}\dots & \\
\begin{block}{cc (ccccccc)}
\color{gray} \vdots & &  \phantom{0} & \phantom{0} & \phantom{0} & \phantom{0} \\
\color{gray} m & & \phantom{0} & -1 & \phantom{0} & \phantom{0} \\
\color{gray} \vdots & &  \phantom{0} & \phantom{0} & \phantom{0} & \phantom{0} \\
\color{gray} n & & \phantom{0} & 1 & \phantom{0} & \phantom{0} \\
\color{gray} \vdots & &  \phantom{0} & \phantom{0} & \phantom{0} & \phantom{0}\\
\end{block}
\end{blockarray}\,\,,
\end{align}
where only non-zero elements are shown. Combining \cref{eq:response-1,eq:response-2}, we find
\begin{align}
\label{eq:response-3}
    \frac{d\pi_k}{dW_{mn}} = -(W^D_{km} - W^D_{kn})\pi_n\,,\,\,
    \frac{d\pi_k}{dW_{nm}} = (W^D_{km} - W^D_{kn})\pi_m \;.
\end{align}

We proceed using the Arrhenius-like parameterization 
\begin{align}
\label{eq:response-4}
    W_{mn}=e^{B_{mn}+S_{mn}/2}\,,\quad W_{nm}=e^{B_{mn} - S_{mn}/2}\,,
\end{align}
where $B_{mn}=B_{nm}$ and $S_{mn}=-S_{nm}$ are the symmetric and antisymmetric parts of the rates. The physical interpretation of these quantities is discussed in \cite{aslyamov2025frr,ptaszynski2024frr}. Then, using \cref{eq:response-1,eq:response-3}, the symmetric response can be written as
\begin{align}
\label{eq:response-5}
    \frac{d\pi_k}{dB_{mn}}&=W_{mn}\frac{d\pi_k}{dW_{mn}} + W_{nm}\frac{d\pi_k}{dW_{nm}} \nonumber\\
    &= -J_{mn}(W^D_{km} - W_{kn}^D) = -J_{mn}\pi_k(T_{km} - T_{kn})\,,
\end{align}
where \cref{eq:MFPT-Drazin} was used for the last identity. 
Multiplying both sides of \cref{eq:response-5} by $x_k$, and calculating the sum over $k$, we arrive at
\begin{align}
    \label{eq:response-6}
    \sum_{k}x_k\frac{d\pi_k}{dB_{mn}} = J_{mn}(X_m - X_n)\,.
\end{align}
We can now use this result to express the SICov, \cref{eq:FRR-excess}, in terms of static responses, in a way that is reminiscent of the recently derived fluctuation response relations \cite{ptaszynski2024frr}
\begin{align}
    \langle\langle y, x \rangle\rangle_+ &= \sum_{n,m}x_ny_m\sum_{k<l}\frac{A_{kl}}{J_{kl}^2}\frac{d\pi_n}{dB_{kl}}\frac{d\pi_m}{dB_{kl}}\,.
\end{align}


\section{Derivation of \cref{eq:Activity-bound}}
\label{sec:activity-bound}

To prove \cref{eq:Activity-bound}, we start with a bound for $|X_l - X_k|$ derived with \cref{eq:X-MFTS}:
\begin{align}
\label{eq:Activity-bound-1}
    &|X_l - X_k| =  \Big|\sum_{n}(x_n-\min_q x_q)\pi_n(T_{nl} - T_{nk})\Big|\\
    &\leq \sum_n(x_n-\min_q x_q)\pi_n\big|T_{nl}-T_{nk}\big|\leq \big|\min_{n}\Delta x_n\big|\max\{T_{lk}, T_{kl}\}\,.\nonumber
\end{align}
In the first identity, we used the property of MFPTs: $\sum_{n}\pi_n T_{nl} =\sum_{n}\pi_n T_{nk} = K$, where $K$ is the Kemeney constant \cite{kemeny1969finite}. In the second step, we used $x_n-\min_q x_q \geq 0$. 
In the last step, we used $T_{nk}-T_{nl}\leq T_{lk}$ and $T_{nl}-T_{nk}\leq T_{kl}$, ($T_{nk}-T_{nl}\geq - T_{kl}$). 
We note that the derivation of \cref{eq:Activity-bound-1} also holds when substituting $\min_q x_q$ by $\max_q x_q$. As a result: 
$|X_l - X_k| \leq ||x||\max\{T_{lk}, T_{kl}\}$, with $||x|| = \min\{|\min_{n}\Delta x_n |, \max_{n}\Delta x_n\}$. Inserting this result in \cref{eq:FRR-excess}, we arrive at \cref{eq:Activity-bound}. 
%$T_{nl}+T_{lk}\geq T_{nk}$ and $T_{nk}+T_{kl}>T_{nl}$. 



\section{Derivation of \cref{eq:excess-bound}}
\label{sec:excess-bound}

To prove \cref{eq:excess-bound}, we first note that $\sum_{k<l}J_{kl}(X_{k}Y_{k} - X_{l}Y_{l})= 0$ and rewrite \cref{eq:asymmetry-result-nonreciprocity} as
\begin{align}
\label{eq:bounds-1}
    \langle\langle y, x \rangle\rangle_-
    &= \sum_{k<l} J_{kl} (X_l - X_k) (Y_{k} + Y_{l})  \nonumber\\
    &= \sum_{k<l} \sqrt{A_{kl}}(X_l - X_k) \frac{J_{kl}}{\sqrt{A_{kl}}}(Y_{k} + Y_{l} - \mu_1 - \mu_2)\nonumber\\
    &\leq \sqrt{\langle\langle x, x \rangle\rangle_+}
    % \Bigg\{\sqrt{\sum_{k<l} \frac{J_{kl}^2}{A_{kl}}(Y_{k} - c_1)^2}+\sqrt{\sum_{k<l} \frac{J_{kl}^2}{A_{kl}}(Y_{l} - c_2)^2}\Bigg\}
    \big[\sqrt{ V_1} + \sqrt{ V_2}\big]\sqrt{\Pi}
    \,,
\end{align}
which is defined up to an arbitrary constants $\mu_1$ and $\mu_2$ due to [$\sum_{k<l} (X_l - X_k)J_{kl}=0$]. We used the Cauchy--Schwarz inequality with \cref{eq:FRR-excess} and introduced 
%$\Pi=\sum_{\rho}j_\rho^2/a_\rho$ is the pseudo-entropy production rate and
\begin{align}
     V_1 = \Pi^{-1}\sum_{k<l} \frac{J_{kl}^2}{A_{kl}}(Y_{k} - \mu_1)^2\,,\quad  V_2 = \Pi^{-1}\sum_{k<l} \frac{J_{kl}^2}{A_{kl}}(Y_{l} - \mu_2)^2\,,
\end{align}
where $\mu_1$ and $\mu_2$ are chosen to minimize $ V_1$ and $ V_2$ as
\begin{align}
\label{eq:center}
   \frac{\partial V_i}{\partial \mu_i} = 0\,\rightarrow\,\mu_1 = \sum_{k<l}  M_{kl} Y_k\,,\,\, \mu_2 = \sum_{k<l} M_{kl} Y_l\,,
\end{align} 
with the weights $M_{kl}=\Pi^{-1}J_{kl}^2/A_{kl}$ normalized as $\sum_{k<l}M_{kl}=1$. We note that $\mu_1$ and $\mu_2$ in \cref{eq:center} are the averages of the excess observables $\boldsymbol{Y}$ over the weights $\mathbb{M}$. Therefore, $V_1=\sum_{k<l}M_{kl}(Y_k - \mu_1)^2$ and $V_2=\sum_{k<l}M_{kl}(Y_l - \mu_2)^2$ are the weighted variances. Using the Bhatia--Davis bound first, followed by the Popoviciu inequalities for the variances $V_i$, we get
\begin{align}
\label{eq:bound-for-weighted-var}
    V_{i} \leq (\max_n Y_n - \mu_i)(\mu_i - \min_n Y_n) \leq \frac{(\Delta Y)^2}{4}\,,
\end{align}
where $i=1,2$ and $\Delta Y = \max_{n}Y_n - \min_{n}Y_n$. Similar bounds could be derived for $\boldsymbol{X}$ observables using $\Delta X = \max_{n}X_n - \min_{n}X_n$. 
Using the second inequality in \cref{eq:bound-for-weighted-var} with \cref{eq:bounds-1}, we arrive at \cref{eq:excess-bound}.


