\title{Einstein’s Cat: A Thought Experiment on the Universality of Time Dilation}

\author{V.G.~Rousseau}
\affiliation{Physics Department, Xavier University of Louisiana, 1 Drexel Dr., New Orleans, LA 70125, USA}

