\section{Appendix: Direct solution of the vector potential in any gauge by Fourier transforms}
\setcounter{equation}{0}
\renewcommand{\theequation}{A.\arabic{equation}}

In this Appendix, we show that the method of Fourier transforms offers a simpler way of obtaining the solution of the vector potential.
Define the Fourier component $\tilde{{\bf A}} ({\bf k}, \omega)$ of the vector potential ${\bf A}({\bf r}, t)$ by:

\begin{equation}
\tilde{{\bf A}} ({\bf k}, \omega) = \int e^{-i {\bf k} \cdot {\bf r} + i \omega t} {\bf A} ({\bf r}, t) d^3r dt,
 \label{eq-APA1}
\end{equation}
\begin{equation}
{\bf A} ({\bf r}, t)  = {1 \over (2 \pi)^4} \int e^{i {\bf k} \cdot {\bf r} - i \omega t} \tilde{{\bf A}} ({\bf k} , \omega) d^3k d\omega,
 \label{eq-APA2}
\end{equation}
and similarly for the scalar potential $\Phi$, {\it etc}.  Thus, equations eqs.~(\ref{eq-A2})-(\ref{eq-A3}) become
\begin{equation}
{\bf k}^2 \tilde{\Phi} 
- {\omega \over c} {\bf k} \cdot \tilde{ {\bf A} } 
= 4 \pi \tilde{ \rho },
\label{eq-APA3}
\end{equation}
\begin{equation}
\left( {\bf k}^2 - {\omega^2 \over c^2} \right) \tilde{ {\bf A} } 
= {4 \pi \over c} \tilde{ {\bf J} } + {\bf k} \left( {\bf k} \cdot \tilde{ {\bf A}} - {\omega \over c} \tilde{\Phi} \right).
\label{eq-APA4}
\end{equation}

Now, we first solve for ${\bf k} \cdot \tilde{{\bf A}}$ from eq.~(\ref{eq-APA3}):
\begin{equation}
{\bf k} \cdot \tilde{{\bf A}} = {c \over \omega} \left( {\bf k}^2 \tilde{\Phi} - 4 \pi \tilde{\rho} \right).
\label{eq-APA5}
\end{equation}
We then use eq.~(\ref{eq-APA5}) in eq.~(\ref{eq-APA4}) to have 
\begin{equation}
\left( {\bf k}^2 - {\omega^2 \over c^2} \right) \tilde{ {\bf A} }  
= {4 \pi \over c} \tilde{ {\bf J} } + {\bf k} \left[ {c \over \omega} \left( {\bf k}^2 \tilde{\Phi} - 4 \pi \tilde{\rho} \right) - {\omega \over c} \tilde{\Phi} \right]
= {4 \pi \over c} \tilde{ {\bf J} } - {4 \pi c \over \omega} {\bf k} \tilde{\rho}
+ {\bf k} {c \over \omega} \left( {\bf k}^2 - {\omega^2 \over c^2} \right) \tilde{\Phi}.
\label{eq-APA6}
\end{equation}
The solution for $\tilde{\bf A}$ is:
\begin{equation}
\tilde{ {\bf A} }  = {4 \pi \over {\bf k}^2 - {\omega^2 / c^2}} \left( {{\bf J} \over c} - c{{\bf k} \over \omega}\tilde{\rho} \right) + c{{\bf k} \over \omega}\tilde{\Phi}
= \tilde{{\bf A}}_{c} + c {i{\bf k} \over - i \omega} (\tilde{\Phi}_{c} - \tilde{\Phi}),
\label{eq-APA7}
\end{equation}
which is exactly eq.~(\ref{eq-A10}).


\section{Appendix: Direct solution of the vector potential from Maxwell's equations for potentials in the velocity gauge}
\setcounter{equation}{0}
\renewcommand{\theequation}{B.\arabic{equation}}

In this Appendix, we present one method for solving the vector potential {\em directly} from Maxwell's equations for potentials {\em in the velocity gauge}.  In the velocity gauge, the gauge condition is in eq.~(\ref{eq-B1}), the equation for the scalar potential is in eq.~(\ref{eq-B2}) and the equation for the vector potential is:
\begin{eqnarray}
\left( \grad^2 - {1 \over c^2} {\partial^2 \over \partial t^2}  \right) {\bf A} ^{(v)} 
= - { 4 \pi \over c } {\bf J} + c \grad \left( - {1 \over v^2} {\partial \over \partial t} + {1 \over c^2} {\partial  \over \partial t} \right) \Phi^{(v)} \ \ 
\nonumber
\\
= - { 4 \pi \over c } {\bf J} + c \grad \int \left( - {1 \over v^2} {\partial^2  \over \partial t^2} + {1 \over c^2} {\partial^2  \over \partial t^2} \right) \Phi^{(v)}  dt
\qquad \qquad \qquad \quad \ \ \,
\nonumber
\\
= - { 4 \pi \over c } {\bf J} + c \grad \int \left[ \left(\grad^2 - {1 \over v^2} {\partial^2 \over \partial t^2}\right) 
                           - \left(\grad^2 - {1 \over c^2} {\partial^2  \over \partial t^2} \right) \right] \Phi^{(v)} dt
\ \ \,
\nonumber
\\
= - { 4 \pi \over c } {\bf J} - 4 \pi \left( c \grad \int \rho dt \right)
                         - \left(\grad^2 - {1 \over c^2} {\partial^2  \over \partial t^2} \right) \left(c \grad \int \Phi^{(v)} dt \right).
\label{eq-APB1}
\end{eqnarray}
It is obvious that the solution for eq.~(\ref{eq-APB1}) is exactly the vector potential listed in eq.~(\ref{eq-B4}).
