\section{Preliminaries on numerical semigroup rings}

In this section we collect some basic notions and results on numerical semigroups and numerical semigroup rings that we will use in the sequel. For the proofs of the stated results we refer to \cite{A-D-GS}.

A \emph{numerical semigroup} $S$ is a submonoid of $(\mathbb N,+)$ such that $|\mathbb N\setminus S|$ is finite; the smallest integer $c$ such that $c+\mathbb N \subseteq S$ is called  the \emph{conductor} of $S$. It is well known that $S$ is finitely generated and has a unique minimal system of generators. Throughout the whole paper, $S=\left\langle n_1,\dots,n_\nu\right\rangle$ is a numerical semigroup minimally generated by $n_1<\cdots<n_\nu$; the ring $k[[S]]=k[[t^{n_1}, \dots, t^{n_\nu}]]$
is the corresponding numerical semigroup ring, with maximal ideal $\mathfrak{m}=(t^{n_1}, \dots, t^{n_\nu})$. The smallest nonzero element of
$S$, $n_1$, is called the \emph{multiplicity of} $S$ and is denoted by $m$; it is well known that $m=e(k[[S]])$, the multiplicity of $k[[S]]$. 

A 
\emph{relative ideal} of $S$ is a non-empty set $E$ of integers such that $E+S\subseteq E$ and $s+E\subseteq S$ for some $s\in S$; when it is contained in $S$, $E$ is simply called an \emph{ideal} of $S$. 
%We always assume that an ideal does not contain $0$, i.e.
%$E\ne S$. 
As for semigroups, we define the multiplicity of a relative ideal $E$ as the smallest element of $E$ and we denote it with $e(E)$. Note that for relative ideals $E_1$ and $E_2$ of $S$, the set $E_1+E_2=\{e_1+e_2\ |\ e_1\in E_1, e_2\in E_2\}$ is also a relative ideal. In particular, for $z\in\mathbb Z$, $z+S=\{z+s\ |\ s\in S\}$ is the principal relative ideal of $S$ generated by $z$. For any ideal $E$ of $S$, we can always express it as $E=(e_1+S)\cup\cdots\cup(e_h+S)$, for some $e_i\in E$; then, we write $E=\{e_1,\dots,e_h\}+S$ and we can always assume that the set $\{e_1,\dots,e_h\}$ is minimal, i.e., for all $i=1,\dots,h$, $e_i\notin \bigcup_{j\ne i}(e_j+S)$; it is straightforward to see that $E$ has a unique minimal set of generators. Moreover we always enumerate the generators in increasing order;
so, in particular, $e(E)=e_1$. By difference of two ideals $E_1$ and $E_2$, we mean the ideal $E_1-E_2=\{z\in\mathbb Z\ |\ z+E_2\subseteq E_1\}$. 

We denote by $M=S\setminus\{0\}$ the maximal ideal of $S$ and we set
$lM=M+\cdots+M$. The \emph{blow-up} of $S$ is defined as the numerical semigroup $B(S)=\bigcup_l(lM-lM)=\left\langle m, n_2-m,\dots, n_\nu-m\right\rangle$. It is well known that $B(S)=lM-lM=lM-lm$ for $l$ large enough.

Let $\omega_i=\min\{s\in S\ |\ s\equiv i\ (mod\ m)\}$. The \emph{Ap\'{e}ry set} of $S$ with respect to $m$ is the set $\Ap_m(S)=\{\omega_0=0, \omega_1,\dots, \omega_{m-1}\}$. In the same way we denote $\Ap_m(B(S))=\{\omega'_0=0, \omega'_1,\dots, \omega'_{m-1}\}$. It follows from the definition that $\omega_i\ge\omega'_i$ for all $i=0,\dots, m-1$ and we define the microinvariants of $S$ as the integers $a_i(S)$ such that $\omega'_i+ma_i(S)=\omega_i$. Moreover, we set $b_i(S)=\max\{l\ |\ \omega_i\in lM\}$. A criterion for the Cohen-Macaulayness of the associated graded ring, proved by Barucci and Fr\"oberg for analytically irreducible domains, implies the following result.

\begin{theorem} \cite[Theorem 2.6]{BF}
	The associated graded ring $\gr_{\mathfrak m}(k[[S]])$ is Cohen-Macaulay if and only if $a_i(S)=b_i(S)$ for each $i=0,\dots, m-1$.
\end{theorem}


Let $E=\left\{e_1,\dots,e_n\right\}+S$ be an ideal of a semigroup $S$. %(where, as said above, we assume that the generators are in increasing order, so that $e_1=e(E)$). 
The \emph{Ap\'{e}ry set} of $E$, with respect to the multiplicity  $m$ of $S$, is $\Ap_m(E)=\{\alpha_0,\alpha_1,\dots, \alpha_{m-1}\}$, where $\alpha_i$ is the smallest element in $E$ congruent to $i$ modulo $m$; we notice that $m$ may not be in $E$. In \cite{D'A-J-St}, the authors define the \emph{blow-up} of $E$ as 
$$
B(E)=\bigcup_{i\ge 1}\left(E+\left(i-1\right)M\right)-iM.
$$
and prove that $B(E)=\left(E+\left(i-1\right)M\right) -iM$ for $i$ large enough.

\begin{lemma}\label{B} \cite[Lemma 3.1]{D'A-J-St}
	Let $S$ be a numerical semigroup with maximal ideal $M$ and multiplicity $m$. Then $B(E)=\left\{e_1-m,\dots,e_n-m\right\}+B(S)$.
\end{lemma}

\begin{remark}
	If $m\in E$, then $0\in B(E)$ and so $B(E)=B(S)$.
\end{remark}

Let $\Ap_m(B(E))=\{\alpha'_0,\alpha'_1,\dots, \alpha'_{m-1}\}$. As for the semigroup case, we define the microinvariants of $E$ as the integers $a_i(E)$ such that $\alpha'_i+ma_i(E)=\alpha_i$. Moreover, we set $b_i(E)=\max\{l+1\ |\ \alpha_i\in lM+E\}$. It easy to see that $a_i(E)\ge b_i(E)$ \cite[Remark 3.2]{D'A-J-St}.

With these notations it is possible to generalize Theorem 1 for ideals.
\begin{proposition} \label{D-J-S}\cite[Proposition 3.6]{D'A-J-St}\label{ECM} Let $E=\{e_1, \dots, e_n\}+S$ and let $I=(t^{e_1},	\dots , t^{e_n})$.
	The following statements are equivalent:
	\begin{enumerate}
		\item  $\gr_{\mathfrak m}(I)$ is a one-dimensional  Cohen-Macaulay $\gr_{\mathfrak m}(k[[S]])$-module;
		%\item $(t^{m})^*$ is not a zero-divisor of $\gr_{\mathfrak m}(I)$;
		%\item $\ord_E(e+m)=\ord_E(e)+1$, for all $e\in E$;
		\item $a_i(E)=b_i(E)$ for all $i=0, \ldots, m-1$.
	\end{enumerate}
\end{proposition}



\section{The case $h(I)=1$}

Let $(R,\mathfrak m)$ be a one-dimensional, Noetherian, Cohen-Macaulay local ring, with residue field $k=R/\mathfrak m\subseteq R$. Let $I$ be a regular ideal of $R$ (i.e. $I$ contains a nonzero divisor) and let $x$ be a minimal reduction of $I$. Let us consider the 
subring $k+I$ of $R$,
that can be viewed as a pullback as shown 
by the following commutative square
(where $k+I=\pi^{-1}(k)$):

$$  \hskip1cm
\CD k+I  @>>> k \\
@VVV   @VVV \\
R  @>\pi>> R/I 
\endCD 
$$
Since $R/I$ is a finite $k$-vector space,
being an artinian ring, also the inclusion 
$k+I \subseteq R$ is finite and $k+I$ is Noetherian (see \cite[Proposition 1.8]{fo}); from this fact, it also follows immediately that $U=k+I$ is one-dimensional and local (with maximal ideal $\mathfrak n=I$). Moreover, being $I$ a regular ideal, $U$ is Cohen-Macaulay.

Multiplying $R$ by $x$ we obtain an ideal of $U$ that, from now on, we denote by $J:=xR$.

\begin{proposition} Under the hypotheses and notations introduced above,
	$\gr_I(R)$ is isomorphic to $\gr_{\mathfrak n}(J)$, both as a $\gr_{\mathfrak n}(U)$-module and as a $\gr_I(R)$-module.
\end{proposition}
\begin{proof}
	We note that $\gr_I(R)=\frac{R}{I}\oplus	\frac{I}{I^2}\oplus\cdots$ and, by $\mathfrak n=I$, we have that 
	$$
	\gr_{\mathfrak n}(J) \ = \ \frac{J}{\mathfrak nJ}\oplus\frac{\mathfrak nJ}{\mathfrak n^2J}\oplus\cdots \ = \ \frac{xR}{xI}\oplus\frac{xI}{xI^2}\oplus\cdots.
	$$ 
	%Let consider the following two short exact sequences of both $U$ and $R$ module:
	%
	%$$
	%0 \longrightarrow I^{j+1}\longrightarrow I^J\longrightarrow\dfrac{I^j}{I^{j+1}}\longrightarrow 0
	%$$
	%$$
	%0 \longrightarrow xI^{j+1}\longrightarrow xI^J\longrightarrow\dfrac{xI^j}{xI^{j+1}}\longrightarrow 0.
	%$$\\
	As $x$ is a regular element in both $R$ and $U$, we get that $I^{h}\cong xI^{h}$, for any $h \in \mathbb N$, as $U$- and $R$-module. Hence we get $\frac{I^j}{I^{j+1}}\cong\frac{xI^j}{xI^{j+1}}$ as $U$- and $R$-module. Thus $\gr_{\mathfrak n}(J)$ is isomorphic to $\gr_I(R)$, both as a $\gr_{\mathfrak n}(U)$-module and as a 
	$\gr_I(R)$-module.
\end{proof}

In light of the above isomorphism we immediately obtain
the following result.

\begin{corollary} Preserving the hypotheses and notations of the previous proposition,
	$\gr_I(R)$ is a Cohen-Macaulay ring if and only if $\gr_{\mathfrak n}(J)$ is a Cohen-Macaulay $\gr_{\mathfrak n}(U)$-module. %In particular, $\gr_I(R)$ is a CM ring if and only if the image of $x$ in $\gr_{\mathfrak n}(U)$ is a non zero divisor for $\gr_{\mathfrak n}(J)$.
\end{corollary}

%\begin{proof}
%	Let us suppose that $\gr_{\mathfrak n}(J)$ is a Cohen-Macaulay (from now on, CM for short) $\gr_{\mathfrak n}(U)$-module. Since $x$ is a non zero divisor in $\gr_{\mathfrak n}(J)$, then $x$ is a non zero divisor in $\gr_I(R)$, that is the one dimensional ring $\gr_I(R)$ is CM. Conversely, let us suppose that $\gr_I(R)$ is CM. By the previous proposition we get that $\gr_{\mathfrak n}(J)$ is a CM $\gr_{\mathfrak n}(U)$-module.
% The second part of the statement is now straightforward.
%\end{proof}

Remembering that in our setting the condition $\gr_I(R)$ Cohen-Macaulay is equivalent to say $h(I)=1$, we can rephrase the previous corollary.

\begin{corollary}\label{h=1} Under the standing hypotheses and notations, $h(I)=1$ if and only if $\gr_{\mathfrak n}(J)$ is a Cohen-Macaulay $\gr_{\mathfrak n}(U)$-module.
\end{corollary} 

If we restrict to the case of numerical semigroup rings, the previous corollary, together with Proposition \ref{D-J-S}, 
produces an effective computational method to
check when $h(I)=1$.

More precisely, let us fix the following notations through the rest of this section:
let $S$ be a numerical semigroup and let $E$ be an ideal of $S$ with multiplicity $e=e(E)$. Let us consider the numerical semigroup $T=\{0\}\cup E$ (hence the maximal ideal of $T$ coincides with $E$) and let $F=e+S\subseteq T$. Is easy to see that $F$ is an ideal of $T$ with $e(F)=e$.

Let $R=k[[S]]$ and $I=(t^a\ |\ a\in E)$. Set $x=t^{e}$, $U=k[[T]]$; clearly $U=k+I$ so we are in the setting of the beginning of this section. Finally, set $J=xR$, which is an ideal of $U$. Under these assumptions,
if $v$ is the usual discrete valuation on $k[[t]]$, we get: $v(R)=S$, $v(I)=E$, $v(U)=T$ and $v(J)=F$. 

Let $\left\{f_1,f_2,\dots,f_{n}\right\}$ be the generators of $F$ as ideal in $T$ (notice that $f_1=e$) and let $B(F)$ and $B(T)$ be the blow-up of $F$ and $T$, respectively.


\begin{remark} 
	Since $f_1=e$, Lemma \ref{B} implies that the blow-up of $F$ as ideal of the semigroup $T$ is 
	$$
	B(F)=\left\{ f_1-e,f_2-e,\dots, f_{n}-e\right\}+B(T)=B(T)
	$$
\end{remark}




The next result gives the promised computational method that allows to check when $h(I)=1$.


\begin{theorem}\label{comp} 
	Under the standing hypotheses and notations, $h(I)=1$ if and only if $a_i(F)=b_i(F)$, for every $i=0,\dots,e-1$.
\end{theorem}
\begin{proof} 
	By Proposition \ref{D-J-S}, we have that  $a_i(F)=b_i(F)$, for every $i=0,\dots,e-1$, if and only if $\gr_{\mathfrak n}(J)$ is a Cohen-Macaulay 
	$\gr_{\mathfrak n}(U)$-module. By Corollary
	\ref{h=1} we immediately obtain the thesis.
\end{proof}

\begin{example}\label{ex}
	Set $I=(t^9,t^{11}) \subset k[[S]]$ with $S=\left\langle 6,9,11\right\rangle$. Let us show that $h(I)=1$ using last theorem. 

	We have $v(I)=E=\{9,11\}+S=\{9,11,15,17,18,20, 21,22, 23,24,26,\rightarrow\}$ (where the arrow means that all the integer greater than $26$ belongs to $E$), and $3E=9+2E$; from this fact it follows immediately that $r(I)=2$. Moreover $T=\{0\}\cup E$
	and $$F=9+S=\{9,15,18,20,21,24,26,27,29,30,31,32,33,35,\rightarrow\};$$ thus $\Ap_9(F)=\{9,37,20,21,31,32,15,43,26\}$. 

	Furthermore, by $T=\left\langle 9,11,15,17,21,23\right\rangle$, we easily get  $B(F)=B(T)=\{0,2,4,6,8,\rightarrow\}$ and $\Ap_9(B(F))=\{0,10,2,12,4,14,6,16,8\}$; hence $a_0(F)=a_3(F)=a_6(F)=1$, $a_2(F)=a_5(F)=a_8(F)=2$ and $a_1(F)=a_4(F)=a_7(F)=3$. 

	The maximal ideal of $T$ is $E$ and so $$E+F=\{18,20,24,26,27,29,30,31,32,33,\rightarrow\}$$ and $lE+F=\{(l+1)\cdot 9, (l+1)\cdot 9+2, (l+1)\cdot 9+4,(l+1)\cdot 9+6,(l+1)\cdot 9+8,\rightarrow\}$ for every $l\ge 2$. This implies that $\alpha_i\notin E+F$ for $i\in\{0,3,6\}$, $\alpha_i\in (E+F)\setminus (2E+F)$ for $i=2,5,8$ and $\alpha_i\in (2E+F)\setminus (3E+F)$ for $i=1,4,7$. Therefore, we get $a_i(F)=b_i(F)$ for $i=0,\dots,8$.
\end{example}

In the previous example one could compute 
$h(I)$ directly checking that $I=\widetilde I$,
since $r(I)=2$ and so all the subsequent powers of $I$ have to be Ratliff-Rush closed.
Hence it is clear that the computational method given by Theorem \ref{comp} becomes convenient when the reduction number of $I$ increases. 

In the following example we consider a family of semigroups $S_n$ (with $n \geq 3$) and ideals $E_n \subset S_n$, introduced in
\cite[Example 2.3]{D'A-G-H2}, that have the following properties: $S_n$ is minimally generated by $n+1$ elements; $hE_n$ is minimally $n$-generated for every $h \geq 1$; the reduction number of $E_n$ is $n-1$. 
We will show that,  setting 
$I_n=(t^x: x \in E_n) \subset k[[S_n]]$ and using Theorem \ref{comp}, it is possible to prove that $h(I_n)=1$, for any $n \geq 3$.
Hence, as byproduct, we obtain that the asymptotic Ratliff-Rush number of an ideal,  with reduction number arbitrarily large, can be equal to $1$. Notice that in higher dimension such a situation has been proved in \cite[Example 3.2]{AA2}.

\begin{example}\label{ex}
	Fix $n\geq 3$ and set $S_n = \langle a,b,d,c_3,\dots , c_n\rangle$, where $a=2n$,
	$b=4n-1$, $d=n(2n-1)$ and $c_h=(n+h)(2n-1)+1$, for any $h=3,\dots n$. 

	Let $E_n=\{a,b,c_3,\dots, c_n\}+S_n$ and set
	$I_n=(t^x: x \in E_n) \subset k[[S_n]]$.
	We will show that 
	$h(I_n)=1$ using Theorem \ref{comp}. 

	We have: 
	$$
	T_n=\{0\}\cup E_n =\langle a,b,c_3,\dots, c_n,a+d,b+d, c_3+d, \dots, c_n+d\rangle
	$$
	but, since $c_h+d=(h-1)b+(2n+1-h)a$ for any $h=3,\dots n$, the last generators are superfluous. Hence 
	$T_n=\langle a,b,c_3,\dots, c_n,a+d,b+d\rangle$.
	Since $d$ is the only generator of $S_n$ not belonging to $E_n$, we easily obtain that  $F_n=S_n+a$ is generated, as ideal of $T_n$, by $\{a, a+d\}$. 

	As proved in \cite[Example 2.3]{D'A-G-H2}, $hE_n$ is minimally generated, as ideal of $S_n$, by $\{ha, (h-1)a+b, \dots, hb, (h-1)a+c_{h+2}, \dots, (h-1)a+c_n\}$, for any $h < n-1$, while $(n-1)E_n=\{(n-1)a, (n-2)a+b, \dots, (n-1)b\}+S_n$ and $nE_n=(n-1)E_n+a$.

	Using induction and the relations 
	between the generators proved in \cite[Example 2.3]{D'A-G-H2}, it is possible to show that $hb-a \notin S_n$ (and so $hb-a \notin T_n$) for every $h=1,\dots n-1$; therefore the Ap\'ery set of $T_n$ (ordering the elements by their residue modulo $a$) is the following:
	$$
	\Ap_a(T_n)=\{0,c_n, c_{n-1},\dots, c_3, d+b,d+a,(n-1)b, \dots, 2b,b\}.
	$$
	From this fact one can show that the Ap\'ery set of $F_n=a+S_n$ is 
	$$
	\Ap_a(F_n)=\{a,a+c_n, a+c_{n-1},\dots, a+c_3, a+d+b,d+a,a+(n-1)b, \dots, a+2b,a+b\}.
	$$
	Finally, since $d=n(b-a)$, we get $B(F_n)=B(T_n)=\langle a,b-a, c_3-a, \dots, c_n-a\rangle$, whose Ap\'ery set with respect to $a$ is 
	$$
	\Ap_a(B(F_n))=\{0,c_n-a, c_{n-1}-a,\dots, c_3-a,
	 d+b-a, d,$$
	 $$(n-1)(b-a), \dots, 2(b-a),b-a\}
	$$
	and, using the computation of the $hE_n$, that are the multiples of the maximal ideal of $T_n$,
	one can show that the orders $b_i$ of the elements of the Ap\'ery set of $F_n$ are
	$$
	b_0=0, b_1=\dots=b_{n-1}=2, b_n=1, b_{n+1}=n, b_{n+2}=n-1, \dots , b_{2n-1}=2,
	$$
	that, therefore, coincide with the $a_i$.
\end{example}

