%Let $a\in S\setminus E$, with $a\ne 0$. Then,
%remembering that $T=\{0\}\cup E$, we immediately get $a+e\in\Ap_e(T)$; hence $a+e$ is a minimal generator of $T$. This implies that $a+e\notin 2E$ and so $t^e$ is not a zero divisor in $\gr_{\mathfrak n}(U)$ ??. Since $T$ is a maximal embedding dimension numerical semigroup,  is a Cohen-Macaulay ring, hence $t^e$ is a non-zerodivisor in $\gr_{I}(R)$ ???? and so the depth of $\gr_I(R)$ is positive. This implies $h(I)=1$.
%\end{proof}



\section{The case $h(I)=r(I)$}

Let $R$ be a one-dimensional, local, reduced Noetherian ring having total ring of fractions $Q(R)$ and let assume that the integral closure $\overline {R}$ of $R$ in $Q(R)$ is a finitely generated $R$-module. Let $C=(R:_{Q(R)}\overline{R})$ denote the conductor of $\overline{R}$ into $R$.

Let $x$ be a principal reduction of $I$ and let $r=r(I)=\min\{n\in\mathbb N\ |\ I^{n+1}=xI^n\}$ be the reduction number of $I$. As noticed in \cite[Discussion 2.5]{D'A-G-H}, if $I$ is a regular ideal with a principal reduction $xR$, then, for every $s\ge r$,
$$
\widetilde{I}=(I^{s+1}:I^s)=(xI^s:_{Q(R)}I^s)\cap R=xR^I\cap R=I^sx^{-s+1}\cap R,
$$
where $R^I$ denotes the blow-up of $I$, i.e.,
in our setting, $R^I=\bigcup_{n\in \mathbb N}(I^n:I^n)$; it is well known that $R^I\subseteq \overline R$ and that $R^I=(I^s:I^s)$, for any $s \geq r(I)$ (see again \cite[Discussion 2.5]{D'A-G-H}).

From the equality $I^{r+1}=xI^r$ it follows immediately that
$I^{r+n}=I^rx^n$ for every $n\in\mathbb N$.
Moreover, it is straightforward to check that $x^m$ is a principal reduction of $I^m$ for every $m\in\mathbb N$.
Using this facts, we can 
obtain a bound on the reduction number of $I^m$.

%\begin{proof}
%By what it is written above, the lemma it is true for $n=0,1$. Suppose $I^{r+i}=I^rx^i$ for every $i\in\left\{0,1,\dots,n-1\right\}$, then $I^{n+r}=II^{r+n-1}=II^rx^{n-1}=I^{r+1}x^{n-1}=I^rxx^{n-1}=I^rx^n$.
%\end{proof}



\begin{lemma} 
	Fix and integer $m\in\mathbb N$, $m\geq 2$ and let $l\in\left\{0,\dots,m-1\right\}$ be such that $m$ divide $r+l$. Then $r(I^m)\le\frac{r+l}{m}$.
\end{lemma}
\begin{proof}
	The thesis follows by the following chain of equalities: 	
	$$ \left(I^{m}\right)^{\frac{r+l}{m}+1}=I^{r+l}I^{m}=I^mI^rx^{l}=I^{r+m}x^{l}=
	I^lI^{r+(m-l)}x^{l}= 
	$$
	$$
	\ \ \ =I^lI^rx^{m-l}x^l=I^{r+l}x^m=\left(I^{m}\right)^{\frac{r+l}{m}}x^m .
$$
\end{proof}

\begin{lemma}
	Let $m\in\mathbb N$, $m \geq 1$; then $I^rx^{-r+m}\cap R=\widetilde{I^m}$.
\end{lemma}
\begin{proof}
	If $m=1$ the thesis is given by the formula
	at the beginning of the section. If $m \geq 2$,
	let $l\in\left\{0,\dots,m-1\right\}$ such that $m$ divide $r+l$. Then, making use of the previous lemma, we get 
	$$ I^rx^{-r+m}\cap R=I^rx^lx^{-r+(m-l)}\cap R=I^{r+l}x^{-r+(m-l)}\cap R= $$
	$$=I^{r+l}x^{-(r+l)+m}\cap R=\left(I^{m}\right)^{\frac{r+l}{m}}\left(x^m\right)^{-\frac{r+l}{m}+1}\cap R=\widetilde{I^m} .$$
\end{proof}

Notice that if an ideal $J$ with principal reduction $yR$ is included in the conductor, by $R^J\subset \overline R$, it follows that $\widetilde J= yR^J\cap R=yR^J$, so the intersection with $R$ is superfluous. 
As observed also in \cite{D'A-G-H}, this means
that an ideal included in the conductor
is Ratliff-Rush closed if and only if it is stable (i.e. it has reduction number $1$).
If we apply this remark to $I^m$ we obtain the following result.

\begin{corollary}\label{l<r} Let $I$ be an ideal with reduction number $r$.
	If there exists $m<r$, such that $I^rx^{-r+m}\subseteq C$, then $I^m\ne \widetilde{I^m}$
\end{corollary}

\begin{proof}
	If $m<r$, then  $I^mx^{r-m}\subsetneq I^r$; therefore $I^m \subsetneq I^r x^{-r+m}$. By the previous lemma and by the hypothesis $I^rx^{-r+m}\subseteq C$, it follows that $I^r x^{-r+m}=\widetilde{I^m}$,
	that, in turn, implies the thesis.
\end{proof}

We can use the previous corollary to improve \cite[Proposition 3.10]{D'A-G-H}.

\begin{proposition}\label{1} Let $I$ be an ideal with reduction number $r$ and 
	set $l=\min\{m\in\mathbb N\ :\ I^rx^{-r+m}\subseteq C\}$. If $l<r$, then $h(I)=r$.
\end{proposition}
\begin{proof}
	By Corollary \ref{l<r}, for any $m \in \{l, \dots , r-1\}$, $I^m\neq \widetilde{I^m}$. The thesis follows immediately.
\end{proof}

\begin{example}\label{h=r}
	Set $I=(t^4,t^5,t^{11})\subset k[[S]]$, with $S=\langle 4,5,11\rangle=\{0,4,5,8,\rightarrow\}$. Clearly $I$ is the maximal ideal of $k[[S]]$, so $I= \widetilde I$.
	On the other hand, $I^2=(t^8,t^9,t^{10})$, $I^3=(t^{12},t^{13},t^{14},t^{15})$ and, for any $k\geq 1$,
	$I^{3+k}=x^{k}I^3$ (where $x=t^4$); thus $r(I)=3$. But 
	$I^2 \subseteq C$, hence $I^2\subsetneq \widetilde{I^2}$; in fact, arguing as in Corollary \ref{l<r}, $\widetilde{I^2}=I^3x^{-1}$, that contains $t^{11}$. 
\end{example}
%\begin{remark} 
%If $r=1$, then $I^2=xI$ and $h(I)=1$.
%\end{remark}
We conclude the paper applying the above proposition to the case of numerical semigroup rings. So
let $S$ be a numerical semigroup with conductor $c$ and let $R=k[[S]]$;
it is well known that $c=\min\left\{v(x)\ |\ x\in C\right\}$, where $C$ is the conductor of $R$.

\begin{proposition}\label{suff}
	Let $S$ be a numerical semigroup with conductor $c$ and let $E$ be an ideal of $S$ with multiplicity $e=e(E)$. Let $R=k[[S]]$ and let $I=(t^a\ |\ a\in E)$. Assume that $r(I)=r\ge 2$; if $(r-1)e\ge c$, then $h(I)=r$.
\end{proposition}
\begin{proof}
	By assumption, since $x=t^e$ is a principal reduction of $I$, we have $I^rx^{-r+(r-1)}\subseteq C$; therefore the integer $l$ defined in Proposition \ref{1} is such that $l\le r-1<r$. Again by Proposition \ref{1}, we get the thesis.
\end{proof}

\begin{example}
	Set $I=(t^7,t^8) \subset k[[S]]$ where $S=\left\langle 4,5,7\right\rangle=\left\{0,4,5,7,\stackrel{}{\rightarrow}\right\}$; in this case the conductor of $S$ is $c=7$.  Since $E=\{7,8\}+S=\left\{7,8,12,\stackrel{}{\rightarrow}\right\}$, we have $e=7$ and, by simple calculations, $r=4$. Finally, Proposition \ref{suff} implies that $h(I)=4$. 
\end{example} 



