\title[Segments of bounded power series]{Sharp bounds for some segments \\ of bounded power series}

\author{Leonid V. Kovalev}
\address{215 Carnegie, Department of Mathematics, Syracuse University, Syracuse, NY 13244, USA \\
ORCiD: 0000-0001-8002-7155}
\email{lvkovale@syr.edu}

