Our approach is based on the following verification theorem, which is a slight extension of Theorem 2.2.4 in \cite{bouchard2007introduction} to controlled stochastic jump intensities $\lambda(\cdot)$.
\begin{theorem}
	Let $v \in \mathcal{V} \cap C([0,T]\times D)$ be a solution of \eqref{HJB2}, and assume there exists a measurable mapping $\hat{\alpha}: [0,T) \times D \to A$  such that %\footnote{\hspace{-0.3mm}{\small or\hspace{-0.2mm} $\mathcal{H}(t,x,\hspace{-0.35mm}\widehat{V}, \nabla_x\widehat{V} (t,x),\hspace{-0.35mm}\nabla^2_x \widehat{V}(t,x), \hspace{-0.35mm} \hat{\alpha}(t,x)) \hspace{-0.1mm}+\hspace{-0.1mm} \partial_t\widehat{V} (t,x) = \hspace{-0.7mm}0$.}} 
	\begin{equation}
	\hat{\alpha}(t,x) \in \argmax_{a\in A} H(t,x,  v, a) \ \quad \text{for all } (t,x) \in [0,T) \times D, \label{theorem1} 
	\end{equation}
	and the jump-diffusion equation \eqref{sde}  admits a unique solution for each initial condition $x \in D$. Then $v = V$ and $\hat{\alpha}$ is an optimal control.
	\label{Th2}
\end{theorem}
