\subsection{GPI-PINN Algorithm \ref{Algo 2}}  \vspace{-1mm}
\label{sect3.2.1} 
GPI-PINN 1, described in Algorithm \ref{Algo 2}, uses a PINN approach and minimizes the 
residuals of the HJB equation \eqref{HJB2} to approximate the value function. It works well in the absence of jumps in the state dynamics \eqref{sde}, but becomes inefficient otherwise since it needs to compute the jump expectations $\E^{\mathcal{Z}} V(t, x + \gamma(t,x,Z_1,a))$ for each $(t,x)$ at every iteration. More precisely, we see in Algorithm \ref{Algo 2}  that we first minimize the loss function \eqref{squareloss} with respect to value weights $\theta$ so as to enforce the HJB equation\footnote{or equivalently  the Lyapunov equation \eqref{lyapun} for the reward $V^{\alpha_{\phi(k)}}$ if the control is not yet optimal at step $k$.} \eqref{HJB2}, while keeping the weights $\phi$ of the control NN fixed. \setlength{\textfloatsep}{5pt}
\begin{algorithm}[t]
	\caption{GPI-PINN 1 }
	\label{Algo 2}
	\begin{algorithmic}
		\STATE Initialize admissible weights $\theta^{(0)}$ for $V_{\theta^{(0)}}$ and $\phi^{(0)}$ for  $\alpha_{\phi^{(0)}}$. Set  tolerance $\varepsilon > 0$ and $k=0$. 
		\REPEAT \vspace{0.5mm}
		\STATE  \textbf{Step 1:} Update the value NN $V_{\theta^{(k+1)}}$ for given control  $ \alpha_{\phi^{(k)}}$ by minimizing the loss
		\vspace{-1mm}
	\begin{equation}
				\theta^{(k+1)} = \argmin_{\theta} \mathscr{L}_1(\theta, \phi^{(k)}) \, , \vspace{-3mm} \label{theta1}
		\end{equation}
		where \vspace{-2.5 mm}
	\begin{align}
				\hspace{-2mm}	\mathscr{L}_1( \theta,\phi ) &= \mathbb{E}_{(t,x)\sim \mu}\mathcal{H}^2(t,x,\theta,\phi)  +  \mathbb{E}_{x \sim \nu} \left(V_\theta(T,x) - F(x)\right)^2 \label{squareloss}%\nonumber
				%	&\hspace{-15mm}= \mathbb{E}_{(t,x) \sim \mu} 	\hspace{-0.6mm} \left[\mathcal{H}\big(t,x,\theta,\phi^{(k)}\big) ^2 \right] 	\hspace{-0.6mm}+	\hspace{-0.6mm}\mathbb{E}_{ x \sim \nu} 	\hspace{-0.6mm}\left[ \left(V(T,x; \theta) - F(x) \right)^2 \right] . \label{squareloss}
		\end{align}
		\vspace{-1.5mm}
		\STATE \textbf{Step 2:}   Update the control NN $\alpha_{\phi^{(k+1)}}$ for the known value NN $V_{\theta^{(k+1)}}$ by minimizing the loss
	\begin{equation}
				\phi^{(k+1)} = \argmin_{\phi} \mathscr{L}_2(\theta^{(k+1)}, \phi) \, ,\vspace{-3mm} \label{theta2b}
		\end{equation}
		where \vspace{-2.5mm}
	\begin{align}
				\mathscr{L}_2(\theta, \phi) & = - \mathbb{E}_{(t,x) \sim \mu} \mathcal{H}\big(t,x,\theta, \phi \big)  = -\int_{ [0,T) \times D} \hspace{-2mm}\mathcal{H}\big(t,x,\theta, \phi\big) \, d\mu(t,x). \label{squareloss2} 
		\end{align} \vspace{-2mm}
		\STATE $k \leftarrow k+1$
		\UNTIL{ $\max_{(t,x) \in [0,T] \times D} \Big| V_{\theta^{(k)}}\hspace{-0.4mm}(t,x)- V_{\theta^{(k-1)}}\hspace{-0.4mm}(t,x) \Big|  \leq \varepsilon $ .}
		\STATE  \textbf{return} \hspace{0.4mm}$V_{\theta^{(k)}}$ and $\alpha_{\phi^{(k)}}$, and set  $k_* \leftarrow k$.
	\end{algorithmic}  	
\end{algorithm}
%\footnote{Note that potential boundary conditions on the HJB equation inferred from the physics of the problem can also be easily considered by adding a third residual term $\big\| V(t,x; \theta) - F(t,x) \big\|^2_{\partial Q, \, \mu_3}$  in \eqref{squareloss}, defined on the boundary $\partial Q := [0,T) \times \partial D$.}
This first loss function \eqref{squareloss} consists of two terms  representing the PIDE  residual at selected points sampled in the interior of the space-time domain according to a suitable sampling measure $\mu$, as well as the violation of the terminal and boundary conditions along  points sampled from the boundary of the domain according to a second sampling measure $\nu$. The loss function $\mathscr{L}_1$ measures how well the function $V_\theta$  satisfies the HJB equation \eqref{HJB2} (or Lyapunov equation \eqref{lyapun} if the control is not yet optimal). Therefore, the goal is to find a set of parameters $\theta$ such that the NN $V_\theta$ minimizes the error $\mathscr{L}_1(\theta, \phi^{(k)})$ at step $k$, ultimately leading to a reduced-form model  which approximates $V(t,x)$ for all $(t,x) \in [0,T] \times D$. Estimating $\theta$ by minimizing directly $\mathscr{L}_1(\theta, \phi^{(k)})$ is infeasible when the dimension $d$ is large since integrating over the whole domain is intractable computationally.  However,  using stochastic gradient descent (SGD)  with machine learning approach limits the curse of dimensionality by drawing a sequence of time and space points  according to $\mu$ and $\nu$, while satisfying the dynamics \eqref{sde}. These sampling measures $\mu, \nu$ are chosen according to the Residual-based Adaptive Distribution (RAD) method of \cite{wu2023comprehensive}, as it is known to significantly improve the accuracy of PINNs. 
\\[0.31cm]
We then minimize the second loss function \eqref{squareloss2} with respect to $ \phi$ so as to minimize the extended Hamiltonian $\cal{H}$ (or equivalently, $H$) with respect to the control $\alpha_\phi$ in an average sense according to $\mu$, while keeping the weights $\theta$ of the value NN constant. %Alternatively,  we can impose instead of the loss \eqref{squareloss2} that the gradient of the Hamiltonian (or equivalently $\mathcal{H}$) with respect to $\alpha_\phi$ is equal to zero  (\textit{i.e.}\ first order condition) using the loss \vspace{-3mm}
%{\small$$\mathscr{L}_{2'}(\theta, \phi)= \int_Q \big\| \mathcal{H}_\alpha\big(t,x,\theta, \phi\big) \big\|^2_2 \, d\mu(t,x), \vspace{-0.99mm}$$}%	& + \Big\| u(T,x; \phi) - g_2(x) \Big\|^2_{D \cap S_2, \, \nu}  + \Big\| u(t,x ; \phi) - g_2(t,x) \Big\|^2_{\partial Q \cap S_3, \mu_3}  \label{How2}
%where
%{\small$	\mathcal{H}_\alpha(\cdot,\theta, \phi)  \hspace{-0.5mm} :=  \hspace{-0.6mm}\left. \nabla_a \mathcal{H}\big(\cdot, \hspace{-0.3mm}V_\theta, \hspace{-0.3mm}\nabla_x V_\theta(\cdot),\hspace{-0.3mm}\nabla^2_x V_\theta(\cdot),a\big) \right|_{a=\alpha_\phi(\cdot))}$}. This  does not guarantee finding a global minimum, but this  may speed up convergence in certain optimal control problems (though this was not observed in the experiments of Section \ref{Section4}). 
%We also see that we only need to train two NNs $V_\theta$ and $\alpha_\phi$ with    only two sets of parameters $\theta$ and $\phi$  so as to approximate both the value function $V(t,x)$  for all $(t,x) \in [0,T]\times D$ and the  optimal control  $\alpha^*(t,x)$ for all $(t,x) \in [0,T) \times D$. 
Therefore, GPI-PINN \ref{Algo 2} leads to a global approximation $V_{\theta^{(k_{*})}}$ of the  value function and $\alpha_{\phi^{(k_{*})}}$ of the  optimal control  on the whole space-time domain $[0,T] \times D$, where $k_{*}$ corresponds to the last epoch $k$ in  Algorithm \ref{Algo 2}.  This differs from the local approach of \citet{bachouch2022deep} and \citet{han2016deep},  where two sets of parameters $(\theta^{(n)}, \phi^{(n)})$  need to be estimated  at each discretized time $t_n\in [0,T]$. Moreover, once the NNs are trained, we can then rapidly evaluate the optimal control and the value function online, making it suitable for real-time applications.  Finally, in practice, the loss functions  \eqref{squareloss} and \eqref{squareloss2} are estimated by  the following sampling procedure. Generate a mini-batch of $M_1$ random points $\{(t_m, x_m) \}_{m=1}^{M_1}$ in $[0,T) \times D$ according to $\mu$ and $M_2$ random points $ \{(\tilde{x}_m)\}_{m=1}^{M_2}$ in $ D$ according to $\nu$.  Generate $M_3$ points $\{(z^{(m)}_j)\}_{j=1}^{M_3}$ in $E$ according to $\mathcal{Z}$ for each $m=1,\ldots, M_1$. The loss functions \eqref{squareloss} and \eqref{squareloss2} are then estimated using,\vspace{-0.5mm}
\begin{equation} 	\widehat{\mathscr{L}}_1(\theta,\phi^{(k)}) = \frac{1}{M_1} \sum_{m=1}^{M_1}  \Big( \widehat{\mathcal{H}}\big(t_m,x_m,\theta,\phi^{(k)}\big)\Big)^2 + \frac{1}{M_2}\sum_{m=1}^{M_2} \left( V_\theta(T, \tilde{x}_m) - F(\tilde{x}_m) \right)^2 , \label{How1} \vspace{-2mm} \end{equation}
and, \vspace{-1.7mm}
\begin{equation} 	\widehat{\mathscr{L}}_2(\theta^{(k+1)}, \phi)=   -\frac{1}{M_1} \sum_{m=1}^{M_1}  \widehat{\mathcal{H}}\hspace{-0.5mm}\left(t_m,x_m,\theta^{(k+1)},  \phi\right) , \quad \  \label{How2}  %	& + \Big\| u(T,x; \phi) - g_2(x) \Big\|^2_{D \cap S_2, \, \mu_2}  + \Big\| u(t,x ; \phi) - g_2(t,x) \Big\|^2_{\partial Q \cap S_3, \mu_3}  
\end{equation}  where\vspace{-0.3mm} $\widehat{\mathcal{H}}(t_m,x_m,\theta,  \phi)  := \frac{1}{M_3} \sum_{j=1}^{M_3}\mathcal{G}(t_m,x_m,z^{(m)}_j,\theta,  \phi)$ approximates $\mathcal{H}(t_m,x_m,\theta,  \phi)$ for each of the $M_1$ points $(t_m, x_m)$. The minimizations \eqref{theta1} and \eqref{theta2b} are then performed  using mini-batch gradient descent on the empirical losses \eqref{How1} and \eqref{How2}. Therefore, \vspace{0.2mm}in practice, we apply in Step 1 and 2 of  GPI-PINN \ref{Algo 2}   the following update rule $N_1$ times for the value NN \vspace{0.3mm}
\begin{equation}  \label{update1}
\begin{aligned}
		\theta^{(k+1)} &= \theta^{(k)} 
	-  \textstyle \frac{2 \eta_1}{M_1}\sum_{m=1}^{M_1}  \widehat{\mathcal{H}}\big(t_m,x_m,\theta^{(k)},\phi^{(k)}\big) \nabla_\theta \widehat{\mathcal{H}}\big(t_m,x_m,\theta^{(k)},\phi^{(k)}\big) 
	\\[0.05cm]
	& \hspace{29mm}- \textstyle \frac{2 \eta_1}{M_2} \sum_{m=1}^{M_2} \left(   V_{\theta^{(k)}}\hspace{-0.4mm}(T, \tilde{x}_m) - F(\tilde{x}_m) \right) \nabla_\theta V_{\theta^{(k)}}\hspace{-0.4mm}(T, \tilde{x}_m ) \, , 
\end{aligned} \end{equation}
and the following update rule $N_2$ times for the control network	\vspace{-0.5mm}
 \begin{equation}
	\phi^{(k+1)} = \phi^{(k)} +  \frac{\eta_2}{M_1} \sum_{m=1}^{M_1}  \nabla_\phi\widehat{\mathcal{H}}\hspace{-0.5mm}\left(t_m,x_m,\theta^{(k+1)},  \phi^{(k)}\right) , \label{update2}
\end{equation} with learning rates $\eta_1$, $\eta_2 > 0$. Importantly, in the numerical implementation of  GPI-PINN \ref{Algo 2}, Proposition \ref{Prop1} allows us to bypass the computation of the Hessian and gradients in  $\mathcal{H}$  by using  the univariate function $ \psi''(0)$ in \eqref{eqprop}. However, GPI-PINN \ref{Algo 2} has still two main drawbacks. First, it does not avoid  the costly computation of the expectations  $\mathbb{E}^{\mathcal{Z}}\big[V_\theta(t,x+\gamma(t,x,Z_1,\alpha(t,x)))\big]$ for each of the $M_1$ sample points $(t,x) \in \{(t_m, x_m) \}_{m=1}^{M_1}$, as we need to evaluate the empirical mean $\widehat{\mathcal{H}}$ in both updates rules \eqref{update1} and \eqref{update2}. % Indeed, Proposition \ref{Prop2} does not apply directly for \eqref{squareloss} as finding the weights $\theta$ minimizing the mean square error $\mathbb{E}_{(t,x,z)\sim \mu \otimes \mathcal{Z}} \big[\mathcal{G}^2(t,x,e,\theta,\phi)\big]$ does not imply that they minimize $\mathbb{E}_{(t,x) \sim \mu} \big[\mathcal{H}^2\big(t,x,\theta,\phi\big) \big]$. 
Secondly, the gradient steps $\nabla_\theta \widehat{\mathcal{H}}$ in the update rule \eqref{update1} imply to compute third order derivatives, which are numerically costly to evaluate. 
\subsection{GPI-PINN Algorithm \ref{Algo 3}}
\label{section3.2.2}
Using Proposition \ref{Prop2}, we now provide a second version of the GPI-PINN algorithm designed to overcome these two limitations of GPI-PINN \ref{Algo 2}. Therefore, as mentioned in Section \ref{Section2}, Eqs.\ \eqref{lsmc2} and \eqref{notyet} suggest the following recursive approach at step $k$: $\,	\theta^{(k+1)} = \argmin_\theta \mathscr{L}^{(k)}_1(\theta)$, where
	\begin{align*}
		\hspace{-3.1mm}	\mathscr{L}^{(k)}_1(\theta) \hspace{-0.4mm} &= \hspace{-0.4mm} \mathbb{E}_{(t,x,z)\sim \mu \otimes \mathcal{Z}}  \left(V_\theta(t,x) - G(t,x,z,\theta^{(k)},\phi^{(k)}) \right)^2  + \mathbb{E}_{ x \sim \nu}  \left(V_\theta(T,x) - F(x) \right)^2 . \hspace{-2mm} 
\end{align*} This indeed provides an approximation of the reward functional $V^{\alpha_{\phi(k)}}$ associated with the Markov control $\alpha_{\phi^{(k)}}$ from the previous iteration. It is crucial to note that {\small $\mathscr{L}^{(k)}_1(\theta)$}  now depends explicitly on both the value and control  weights $\theta^{(k)}$ and $\phi^{(k)}$ computed at the previous iteration.
 In practice, these expectations are  estimated using the following sampling procedure. Generate a mini-batch of $M_1$ random points $\{(t_m, x_m, z_m) \}_{m=1}^{M_1}$  in $[0,T) \times D \times E$ according to $\mu \otimes \mathcal{Z}$ and $M_2$ random points $ \{(\tilde{x}_m)\}_{m=1}^{M_2}$ in $ D$ according to $\nu$.  The loss function $\mathscr{L}_1$ at step $k$ is then estimated using
{\small\begin{equation}	\hspace{-2mm} \widehat{\mathscr{L}}^{(k)}_1\hspace{-0.4mm}(\theta) = \frac{1}{M_1} \hspace{-0.2mm} \sum_{m=1}^{M_1}  \hspace{-0.5mm}  \left( \hspace{-0.2mm}V_\theta(t_m, x_m) \hspace{-0.2mm}  - \hspace{-0.2mm} G\big(t_m,x_m,z_m,\theta^{(k)},\phi^{(k)}\big) \hspace{-0.3mm} \right)^2 \hspace{-0.3mm} + \hspace{-0.4mm}  \frac{1}{M_2} \hspace{-0.4mm} \sum_{m=1}^{M_2} \hspace{-0.6mm} \left( V_\theta(T, \tilde{x}_m) - F(\tilde{x}_m) \right)^2 \hspace{-1mm}. \hspace{-1mm} \label{How3}
\end{equation}}Taking one step along the gradient of $\widehat{\mathscr{L}}^{(k)}_1(\theta)$, evaluated at the starting point $\theta = \theta^{(k)}$, then leads to the following update rule for $\theta$, \vspace{0.2mm}
%{\small \begin{align}
%		\nabla_\theta \widehat{\mathscr{L}}^{(k)}_1(\theta^{(k)})  
%		&= \frac{-2}{M_1} \sum_{m=1}^{M_1}  \mathcal{G}\big(t_m,x_m,z_m,\theta^{(k)},\phi^{(k)}\big) \nabla_\theta V_{\theta^{(k)}}\hspace{-0.4mm}(t_m, x_m)   \label{22}
%		\\[-1.4mm]
%		&\hspace{12mm}+ \frac{2}{M_2}\sum_{m=1}^{M_2} \left( V_{\theta^{(k)}}\hspace{-0.4mm}(T, \tilde{x}_m) - F(\tilde{x}_m) \right) \nabla_\theta V_{\theta^{(k)}}\hspace{-0.4mm}(T, \tilde{x}_m) \, , \nonumber 
%\end{align}}
\begin{align}
	\theta^{(k+1)}  \hspace{-0.25mm}=  \hspace{-0.25mm}	\theta^{(k)} \hspace{-0.5mm}- \eta_1 \nabla_\theta \widehat{\mathscr{L}}^{(k)}_1\hspace{-0.3mm}(\theta^{(k)}) \hspace{-0.5mm} &=  	\hspace{-0.3mm} \textstyle \theta^{(k)}  \hspace{-0.5mm}+ \hspace{-0.5mm} \frac{2 \eta_1}{M_1} \sum_{m=1}^{M_1}  \mathcal{G}\big(t_m,x_m,z_m,\theta^{(k)},\phi^{(k)}\big) \nabla_\theta V_{\theta^{(k)}}\hspace{-0.4mm}(t_m, x_m) \nonumber
	\\[0.08cm]
 &\hspace{4mm}  \textstyle- \frac{2 \eta_1}{M_2}\sum_{m=1}^{M_2} \left( V_{\theta^{(k)}}\hspace{-0.4mm}(T, \tilde{x}_m) - F(\tilde{x}_m) \right) \nabla_\theta V_{\theta^{(k)}}\hspace{-0.4mm}(T, \tilde{x}_m) \, ,  \label{update3} 
 \\[-0.39cm] \nonumber
\end{align}
when using the notation \eqref{key2} for $\mathcal{G}$ and with learning rate $\eta_1$.
%\begin{align}
%	&\theta^{(k+1)}  =  	\theta^{(k)} - \eta_1 \nabla_\theta \widehat{\mathscr{L}}^{(k)}_1(\theta^{(k)}) .   \label{update3}
%\end{align}
In contrast to GPI-PINN  \ref{Algo 2} with update rule \eqref{update1}, the new  update rule \eqref{update3} for the value NN $V_\theta$ is now based on $\mathcal{G}$ as defined in \eqref{key2}, thereby avoiding \vspace{-0.5mm} the costly computation of the expectations  $\mathbb{E}^{\mathcal{Z}}\big[ V_\theta\big(t_m,x_m+\gamma(t_m,x_m,Z_1,\alpha_\phi(t_m,x_m))\big)\big]$ at each sample point $(t_m,x_m)$, $m=1, \ldots, M_1$. More precisely, the computation of {\small$\widehat{\mathcal{H}}$} in  GPI-PINN \ref{Algo 2} based on the $M_1 \times M_3$ points {\small $\{(z^{(m)}_j)\}_{j=1}^{M_3}$} in $E$  is avoided. Secondly, when updating the value NN using \eqref{update3}, it is no longer necessary to compute third-order derivatives, as in \eqref{update1}, since only  $\nabla_\theta V_\theta$ is needed. However, algorithms based on the HJB residuals such as  GPI-PINN \ref{Algo 2}  are known to be typically more stable for  nonlinear function approximation than the recursive approach of  GPI-PINN \ref{Algo 3}, see \citet{baird1995residual} and empirical Section \ref{Section4}.  Finally, in practice, we can introduce a proportionality factor $\xi \in \mathbb{R}^+$ between the first interior term and the second boundary term of loss \eqref{How3}, that can be fine-tuned for improving the numerical convergence of Algorithm \ref{Algo 3}, see \textit{e.g.}\ \cite{wang2022and}.
%and
%\begin{align}
%	\widehat{\mathscr{L}}_2(\theta^{(k)}, \phi)&=  \frac{1}{M_1} \sum_{m=1}^{M_1}  H\hspace{-0.5mm}\left(t_m,x_m,z_m,\theta^{(k)},  \phi\right) . \label{How2}  %	& + \Big\| u(T,x; \phi) - \phi_2(x) \Big\|^2_{D \cap S_2, \, \nu}  + \Big\| u(t,x ; \phi) - g_2(t,x) \Big\|^2_{\partial Q \cap S_3, \mu_3}  
%\end{align}
The next step of  the GPI-PINN \ref{Algo 3} again relies for the second loss function {\small ${\mathscr{L}}_2^{(k+1)}$} on the expectation-free map $\mathcal{G}$, instead of the extended Hamiltonian $\mathcal{H}$. Specifically, at step $k+1$: $\phi^{(k+1)} = \argmin_\phi \mathscr{L}^{(k+1)}_2(\phi)$, where 
\begin{align}
	\mathscr{L}^{(k+1)}_2(\phi) &= -\mathbb{E}_{(t,x,z)\sim \mu \otimes \mathcal{Z}}   \ \mathcal{G}(t,x,z,\theta^{(k+1)},\phi)  = -\mathbb{E}_{(t,x)\sim \mu}   \mathcal{H}(t,x,\theta^{(k+1)},\phi)  ,  \label{key3}
\end{align} from Fubini's theorem. Therefore, minimizing the sample estimate \vspace{-1.5mm}
\begin{equation} 
	\widehat{\mathscr{L}}^{(k+1)}_2(\phi) =  - \frac{1}{M_1} \sum_{m=1}^{M_1} \mathcal{G}(t_m,x_m, z_m,\theta^{(k+1)},\phi)  \label{How4}
\end{equation}
using the following mini-batch update rule, starting at $\phi^{(k)}$ with learning rate $\eta_2$, \vspace{-1.5mm}
\begin{equation} 
		\phi^{(k+1)} = \phi^{(k)} + \frac{\eta_2}{M_1} \sum_{m=1}^{M_1} \nabla_\phi \mathcal{G}(t_m,x_m, z_m,\theta^{(k+1)}, \phi^{(k)}) \, , \label{update44} 
\end{equation}allows us to maximize the average Hamiltonian $\mathcal{H}$ over the $M_1$ sample points in $[0,T) \times D$.% 
\begin{algorithm}[t]
	\caption{GPI-PINN 2}
	\label{Algo 3}
	\begin{algorithmic}
		\STATE Initialize admissible neural weights  $\theta^{(0)}$ for $V_{\theta^{(0)}}$ and $\phi^{(0)}$ for $\alpha_{\phi^{(0)}}$.  Set tolerance $\varepsilon > 0$, $k = 0$, learning rates $\eta_1, \eta_2$, proportionality factor $\xi$, and number of gradient steps $N_1, N_2$.

		\REPEAT

		\STATE 
		\textbf{Step 0:} Generate a mini-batch $B$ of $M_1$ sample points $\{(t_m, x_m, z_m) \}_{m=1}^{M_1}$  in $[0,T) \times D \times E$ according to $\mu \otimes \mathcal{Z}$ and of $M_2$ points $ \{(\tilde{x}_m)\}_{m=1}^{M_2}\hspace{-0.7mm}$ in $ D$ according to $\nu$. \vspace{0.5mm}
		\STATE \textbf{Step 1:} Update $V_{\theta^{(k+1)}}$ by minimizing the loss \eqref{How3}
		\begin{equation*}
			\	\	\theta^{(k+1)} = \argmin_{\theta}\widehat{\mathscr{L}}^{(k)}_1(\theta) \, , \vspace{-1mm} \label{theta1c}
		\end{equation*}
		using the update rule \eqref{update3} $N_1$ times.

		\STATE \textbf{Step 2:}  Update $\alpha_{\phi^{(k+1)}}$ by minimizing the loss \eqref{How4}
		\begin{equation*}
			\phi^{(k+1)} = \argmin_{\phi}\widehat{\mathscr{L}}^{(k+1)}_2(\phi) \, , \vspace{-1mm} \label{theta1cc}
		\end{equation*}
		using the update rule \eqref{update44} $N_2$ times.
		\vspace{0.75mm}
		\STATE $k \leftarrow k+1$
		\UNTIL{$\max_{(t,x) \in B} \Big| V_{\theta^{(k)}}\hspace{-0.4mm}(t,x)- V_{\theta^{(k-1)}}\hspace{-0.4mm}(t,x) \Big|  \leq \varepsilon$. }
		\STATE \textbf{return} $V_{\theta^{(k)}}$ and $\alpha_{\phi^{(k)}}$, and set $k_* \leftarrow k$.
	\end{algorithmic} 
\end{algorithm} In practice, to improve the performance of GPI-PINN \ref{Algo 3} (and \ref{Algo 2}), several techniques from RL  can be applied to obtain a better trade-off between exploration and exploitation \citep{fujimoto2018addressing}.  This includes experience replay buffer $B$, target networks for the control, policy smoothing via Gaussian noise, etc. The GPI-PINNs  indeed operate as a deterministic on-policy method and we can thus only accomplish smoothing by adding random noise to the obtained actions.\vspace{-1.5mm}%	First, \vspace{-0.1mm}instead of sampling in Step 1 a new mini-batch for each iteration $k$, one can draw these time-space points from an experience replay buffer $\mathcal{B}$ of some fixed size $B = b(M_1 +M_2)$ containing the most recent (previous) sample points, while the oldest $M_1 +M_2$ points are discarded at each iteration and replaced by a new set of points. The hyperparameter $b \in \mathbb{N}$ should be tuned to offer a good trade-off between exploration and exploitation. Secondly, at Step 2, instead of  using in the first loss function $\widehat{\mathscr{L}}^{(k)}_1$ \eqref{lossalgo2} the optimal weights $\theta^{(k)}$ and $\phi^{(k)}$ computed at the previous iteration, one can instead take a value target $\theta^{(targ)} = \rho \theta^{(targ)} + (1-\rho)\theta^{(k)}$ and a control target $\phi^{(targ)} = \rho \phi^{(targ)} + (1-\rho)\phi^{(k)}$ for $\rho \in [0,1)$.
% In particular, we apply target policy smoothing, which consists in replacing in the first loss $\widehat{\mathscr{L}}^{(k)}_1$ \eqref{lossalgo2}  the action $\alpha_{\phi^{(k)}}(t,x)$ at each sample point $(t,x)$ by
%\begin{equation*}
%\tilde{\alpha}(t,x) \hspace{-0.6mm}= \hspace{-0.6mm}\text{clip}(\alpha_{\phi^{(targ)}}\hspace{-0.4mm}(t,x) + \text{clip}(\varepsilon, -c, c), a_{Low}, a_{High}), 
%\end{equation*}
%where $\varepsilon \sim \mathcal{N}_m(0, \Sigma_\varepsilon)$, $c \in \mathbb{R}^m_+$ , $a_{Low}$, $a_{High} \in \mathbb{R}^m$ chosen such that $\tilde{\alpha}(t,x) \in A$, and  $\phi^{(targ)} = \rho \phi^{(targ)} + (1-\rho)\phi^{(k)}$, $\rho \in [0,1)$. This aims at making the policy explore better. The GPI-PINNs  indeed operate as a deterministic on-policy method and we can thus only accomplish smoothing by adding random noise to the obtained actions. Note that the parameters $a_{Low}$, $a_{High}$ make it easy to impose constraints  \vspace{-0.1mm}on the control given by general closed sets. \vspace{-1mm}%Finally, a useful heuristic  \vspace{-0.1mm}is to update the control NN in Step 3 after every two value  updates in Step 2. 
