\subsection{Proof of Proposition \ref{Prop1}}
\label{Proof1}
\begin{proof}   Letting $v(\cdot) = v\Big( t+\frac{h^2}{2k}, x + \frac{h}{\sqrt{2}}\sigma_i(t,x,a) + \frac{h^2}{2k} \beta(t,x,a)\Big)$, the second-order derivative of $	\psi(h) := \sum_{i=1}^{k} v (\cdot)$ is given by 
{\small	\begin{align}
		\psi''(h) =& \sum_{i=1}^k \Bigg( \partial^2_{tt}v(\cdot) \frac{h^2}{k^2} +  \frac{h}{k}[\nabla_{tx} v(\cdot)]^\top \left(\frac{\sigma_i(t,x,a)}{\sqrt{2}} + \frac{h}{k}\beta(t,x,a) \right)  + \frac{1}{k}\partial_t v(\cdot)  + \frac{1}{k} [\nabla_x v(\cdot)]^\top \beta(t,x,a) \nonumber
		\\
		& \hspace{9mm}+ \left(\frac{\sigma_i(t,x,a)}{\sqrt{2}} + \frac{h}{k}\beta(t,x,a) \right)^{\hspace{-0.7mm}\top} \hspace{-1mm} \nabla^2_x v(\cdot)\left(\frac{\sigma_i(t,x,a)}{\sqrt{2}} + \frac{h}{k}\beta(t,x,a) \right) \nonumber
		\\
		& \hspace{9mm}+ [\nabla_{tx}v(\cdot)]^\top \hspace{-0.8mm} \left(\frac{\sigma_i(t,x,a)}{\sqrt{2}} + \frac{h}{k}\beta(t,x,a) \right)  \frac{h}{k} \Bigg)  \, .\nonumber
	\end{align}}
	Evaluating it at $h=0$ gives
	\begin{equation}
		\psi''(0) =  \partial_t v(t,x) + \left[\nabla_xv(t, x)\right]^\top \hspace{-1mm}	\beta(t, x, a) + \frac{1}{2} \normalfont \text{Tr}  \left[ \sigma \sigma^\top\hspace{-0.5mm}(t,x,a)\nabla^2_xv(t,x) \right] , \nonumber
	\end{equation}
	which ends the proof.
\end{proof}
\subsection{Proof of Proposition \ref{Prop2}}
\label{Proof2}
\begin{proof}
	First, notice that the conditional expectation $\mathbb{E}[G(t,X^\alpha_{t-}, Z_1, V^\alpha, \alpha(t,X^\alpha_{t-})) \,  | \, X^\alpha_{t-}]$ is such that  for all $(t,x) \in [0,T) \times D$, 
	\begin{align}
	\mathbb{E}[	G(t,X^\alpha_{t-},  Z_1, V^\alpha, \alpha(t,X^\alpha_{t-})) |X^\alpha_{t-} = x] =	V^\alpha(t,x)   &+ f(t,x,\alpha(t,x))+ \partial_t V^\alpha(t,x)  \hspace{-0.5mm} \nonumber
		\\
		& \hspace{-42mm} +	\beta^\top \hspace{-0.5mm}(t, x, \alpha(t,x)) \, \nabla_x V^\alpha(t, x)  + \hspace{-0.5mm}\frac{1}{2} \normalfont \text{Tr} \left[ \sigma \sigma^\top\hspace{-0.5mm}(t,x,\alpha(t,x))\nabla^2_x V^\alpha(t,x) \right] \nonumber
		\\
		& \hspace{-42mm}  + \lambda(t,x,\alpha(t,x)) \, \mathbb{E}^{\mathcal{Z}} \left[V^\alpha(t,x+\gamma(t,x,Z_1,\alpha(t,x))) - V^\alpha(t,x) \right]   \nonumber%\label{test}
		\\[0.1cm]
		&\hspace{-17mm}= V^\alpha(t,x) + \mathcal{H}(t,x,V^\alpha, \alpha(t,x))  . \label{testest} 
	\end{align} 
	Then, using \textit{e.g}\ Proposition 2.1 of \citet{hainaut2023risk} with $\E \, G^2 (t,X^\alpha_{t-}, Z_1, V^{\alpha}, \alpha(t,X^{\alpha}_{t-})) < \infty$
	for all $t \in [0,T)$,  it can be shown that the conditional expectation $\mathbb{E}[G(t,X^\alpha_{t-}, Z_1, V^\alpha, \alpha(t,X^\alpha_{t-})) \,  | \, X^\alpha_{t-}]$ is such that 
	\begin{align}
		\mathbb{E}&[G(t,X^\alpha_{t-}, Z_1, V^\alpha, \alpha(t,X^\alpha_{t-})) \,  | \, X^\alpha_{t-}]  \label{lsmc}
		\\
		&\hspace{18mm}=\argmin_{\substack{g \colon [0,T] \times D \to \R\\g \mbox{ \scriptsize{Borel measurable}}}}  \mathbb{E} \edg{ \hspace{-0.4mm} \brak{g(t,X^\alpha_{t-}) - G(t,X^\alpha_{t-}, 
				\hspace{-0.4mm} Z_1, V^{\alpha}, \alpha(t,X^\alpha_{t-})) \hspace{-0.1mm}  }^2 \hspace{-0.2mm}}. \nonumber
	\end{align}
	Moreover, from the Dynamic Programming Principle and Ito's lemma, see  \citet{bouchard2007introduction} and \cite{oksendal2019stochastic}, the reward functional $V^\alpha \in C^{1,2}([0,T] \times D)$  is known to satisfy the following nonlinear Lyapunov equation for all $(t,x) \in [0,T)\times D$,
	\begin{equation}
		\mathcal{H}(t,x,V^\alpha, \alpha(t,x))  = 0 \, .
		\label{lyapun}
	\end{equation}
	Therefore,  $	\mathbb{E}[	G(t,X^\alpha_{t-},  Z_1, V^\alpha, \alpha(t,X^\alpha_{t-})) |X^\alpha_{t-} = x]  = V^\alpha(t,x)$, and we find 
	\begin{equation*}
	V^\alpha (t,X^\alpha_{t-}) 
	= \argmin_{\substack{g \colon [0,T] \times D \to \R\\g \mbox{ \scriptsize{Borel measurable}}}}  \mathbb{E} \edg{  \brak{g(t,X^\alpha_{t-}) - G(t,X^\alpha_{t-}, 
		Z_1, V^{\alpha}, \alpha(t,X^\alpha_{t-}))  }^2 }\vspace{-4mm}
	\end{equation*}
\end{proof}

\subsection{DGM Architecture}
\label{dgm}
\begin{figure}[H]
	\centering  
	\includegraphics[scale=0.153]{Figs/DGM_bird.png} 
	\caption{DGM architecture for the value neural network with $L=3$ (\textit{i.e.}\ 4 hidden layers).}
	\label{U_S process} \vspace{-2mm}
\end{figure}
Each DGM layer in Figure \ref{U_S process} for the value network $V_\theta$ is as follows
$$
\begin{aligned}
	S^1 & =\sigma_V\left(W^1 \cdot (t,x)+b^1\right), \\
	Z^{\ell} & =\sigma_V\left(U^{z, \ell} \cdot (t,x)+W^{z, \ell} \cdot S^{\ell}+b^{z, \ell}\right), \quad \ell=1, \ldots, L, \\
	G^{\ell} & =\sigma_V\left(U^{g, \ell} \cdot (t,x)+W^{g, \ell} \cdot S^1+b^{g, \ell}\right), \quad \ell=1, \ldots, L, \\
	R^{\ell} & =\sigma_V\left(U^{r, \ell} \cdot (t,x)+W^{r, \ell} \cdot S^{\ell}+b^{r, \ell}\right), \quad \ell=1, \ldots, L, \\
	H^{\ell} & =\sigma_V\left(U^{h, \ell} \cdot (t,x)+W^{h, \ell} \cdot \left(S^{\ell} \odot R^{\ell}\right)+b^{h, \ell}\right), \quad \ell=1, \ldots, L, \\
	S^{\ell+1} & =\left(1-G^{\ell}\right) \odot H^{\ell}+Z^{\ell} \odot S^{\ell}, \quad \ell=1, \ldots, L, \\
	V_\theta(t, x) & =\sigma_{{V}_{out}} \left(W \cdot S^{L+1}+b \right), 
\end{aligned}
$$
where the number of hidden layers is $L+1$, and $\odot$ denotes element-wise multiplication. The DGM parameters are
\begin{align*}
		\theta = \Big\{ \hspace{-0.5mm}W^1, b^1, \left(U^{z, \ell}, W^{z, \ell}, b^{z, \ell}\right)_{\ell=1}^L,&\left(U^{g, \ell}, W^{g, \ell}, b^{g, \ell}\right)_{\ell=1}^L
		\\
	&,\left(U^{r, \ell}, W^{r, \ell}, b^{r, \ell}\right)_{\ell=1}^L, \left(U^{h, \ell}, W^{h, \ell}, b^{h, \ell}\right)_{\ell=1}^L , W, b\Big\} .
\end{align*}The number of units in each layer is $N$.  $\sigma_V: \mathbb{R}^N \rightarrow \mathbb{R}^N$ is a twice-differentiable element-wise nonlinearity and $\sigma_{V_{out}}: \mathbb{R}^N \to \mathbb{V}$ is the output activation function, also twice-differentiable, where $\mathbb{V} \subseteq \R$ is chosen such as to satisfy possible restrictions on the value function's output, inferred from the form of the stochastic control problem (e.g.\ non-negative value function). The control NN is designed following the same DGM architecture with $\sigma_{\alpha_{out}} : \mathbb{R}^N \rightarrow A$.
\\ \\
Throughout the numerical examples of the paper, we consider $L=3$, each one with $N\hspace{-0.15mm} =\hspace{-0.15mm} 50$ neurons,  see Figure \ref{U_S process}. Unless otherwise stated, we take $M_1 = M_2 = 2^{16}$ samples and a maximum number of epochs $k_{*}=1500$. The network's parameters are updated using the Adaptive Moment Estimation  with  constant learning rates $\eta_1, \eta_2$ equal to $0.001$, $N_1, N_2$ equal to $512$, and a proportionality factor $\xi = 45$. Finally, we choose as value activation functions the $\tanh$ for  $\sigma_V$ and the softplus for $\sigma_{V_{out}}$, and as control activation functions the $\tanh$ for $\sigma_\alpha$ and a linear $\sigma_{\alpha_{out}}$. The  Algorithms \ref{Algo 2} and \ref{Algo 3} are implemented using TensorFlow and Keras, which are software libraries in Python with reverse mode automatic differentiation. GPU acceleration has been used on a NVIDIA RTX 4090.
