\subsection{Linear-Quadratic Regulator with jumps -- Detailed results}
\label{lqr2}
The value function for the jump-LQR control problem \eqref{vv} is given by \begin{equation}
V(t,x) = 	\inf_{\alpha} \mathbb{E}\left[ \int_0^T c_1\, \|\alpha_s\|^2_2 \, ds + c_2 \|X^\alpha_T \|^2_2  \  \Big| \, X^\alpha_t =x \right] , \label{vv2} \vspace{-0.1mm}
\end{equation}and the corresponding  HJB equation then solves
\begin{equation} \label{HJB3} 
\begin{aligned}
	&0= \partial_t V(t,x) + \frac{1}{2}\text{Tr} \left[\Sigma \Sigma^\top \hspace{-0.3mm}\nabla^2V_{x}(t,x)\right] \hspace{-0.4mm} +\inf_{a \in \mathbb{R}^d} \Big\{ c_1 \|a\|^2_2 
	\\[-0.6mm]
	& \hspace{30mm}+ ( \Lambda_1+ \Lambda_2 \|a\|^2_2) \, \mathbb{E}^{\mathcal{Z}}  \left[V(t, x +  Z_1)  -  V(t,x) \right] +  a^\top \hspace{-0.2mm} \nabla_x V(t,x) \Big\}  ,  
\end{aligned}
\end{equation}with terminal condition $V(T,x) = c_2 \|x\|^2_2$. It is  straightforward to show using the verification Theorem \ref{Th2} with HJB equation \eqref{HJB3} and the Ansatz 
\begin{equation} \label{analy}
	V(t,x) = \frac{1}{2} h(t) \|x\|^2_2 + f(t) \, ,
\end{equation} that $f$ satisfies
\begin{equation}
f(t) = \frac{1}{2} \big( \text{Tr}[\Sigma \Sigma^\top]  +\Lambda_1  \hspace{0.2mm} \zeta) \int_t^T h(s) ds \, , \label{ff}
\end{equation}
where $h$ satisfies the non-linear ordinary differential equation
\begin{equation}
h'(t) = \frac{h^2(t)}{2c_1 + h(t) \hspace{0.2mm} \zeta \hspace{0.2mm}\Lambda_2}, \quad h(T) = 2 c_2\, , \label{RK45}
\end{equation}
which can be computed efficiently using numerical methods, such as the Runge-Kutta method of order $5(4)$, \cite{dormand1980family}. The optimal control $\alpha^*$ is then given by
\begin{equation} \label{analy2}
\alpha^*(t,x) = - \frac{h(t)x}{2 c_1 + h(t) \hspace{0.2mm} \zeta \hspace{0.2mm}\Lambda_2} \, .
\end{equation}
In the constant intensity case $\Lambda_2 = 0, \Lambda_1 > 0$, \eqref{ff} and \eqref{RK45} simplify to $h(t) = \frac{2 c_1 c_2}{c_1+ c_2 (T-t)}$ and $f(t) = (\text{Tr} [\Sigma \Sigma^T ] + \Lambda_1 v)\,c_1( \ln(\frac{c_2}{c_1}(T-t)+1))$. \\ \\
