\section{Oplax colimits of stable, hermitian and Poincaré categories}
\subsection{Recollections and oplax colimits for stable categories}

\hspace{1.2em} Let us begin a short recollection of general oplax colimits. We formulate the definitions in the context of \cite[Definition 6.1]{GepnerHaugsengNikolaus} --- this is weaker than usually required for $(\infty, 2)$-category theory, but we will not need more.

\begin{defi}
    An \textit{enhanced mapping functor} $\FunInt$ for a category $\Ccal$ is a functor
    $$
        \begin{tikzcd}
            \FunInt:\Ccal^\op\times\Ccal\arrow[r] & \Cat 
        \end{tikzcd}
    $$
    with a given natural equivalence of its underlying space $\FunInt^\simeq\simeq\Map_\Ccal$.
\end{defi}

\begin{ex} \label{ExampleEnhancedMappingFunctors}
    We will be mainly interested in the following examples:
    \begin{itemize}
        \item The category of functors $\Fun(\Ccal, \Dcal)$ determines an enhancement of the mapping spaces of $\Cat$.
        \item The category of exact functors $\FunEx(\Ccal, \Dcal)$ determines an enhancement of the mapping spaces of $\CatEx$.
        \item The category of hermitian functors $\FunH((\Ccal,\Qoppa), (\Dcal,\Psi))$, the total space of the left fibration classifying $\FunEx(\Ccal, \Dcal)\to\Spaces$ sending $f$ to $\Nat(\Qoppa, \Psi\circ f)$, determines an enhancement of the mapping spaces of $\CatH$.
        \item The full subcategory $\FunP((\Ccal,\Qoppa), (\Dcal,\Psi))$ of $\FunH((\Ccal,\Qoppa), (\Dcal,\Psi))$ spanned by those hermitian functors $(f, \eta)$ which are Poincaré determines an enhancement of the mapping spaces of $\CatP$.
    \end{itemize}
    The last point is less well-behaved than the other three, see \cite[Section 6.5]{HermKI}.
\end{ex}

\begin{defi} \label{DefOplaxColimit}
    Let $(\Ccal, \FunInt)$ be a category with a choice of enhanced mapping functor. An oplax cocone of a functor $F:\Ical\to\Ccal$ is a point in the category 
    $$
        \Fun_{\Ical}(\Ical, \UnCart(\FunInt(F(-), X)))
    $$
    for some $X\in\Ccal$. By varying $X$, the above category determines a functor $\Ccal\to\CatInfty$ whose unstraightening is the category of oplax cocones of $F$. \\

    The \textit{oplax colimit} of a functor $F$, if it exists, is an oplax cocone which is initial in the enhanced sense, so that there is an equivalence
    $$
        \begin{tikzcd}
            \FunInt(\oplaxcolim(F), X)\arrow[r, "\simeq"] & \Fun_{\Ical}(\Ical, \UnCart(\FunInt(F(-), X)))
        \end{tikzcd}
    $$
    of categories, induced by post-composing the oplax cocone of $\oplaxcolim(F)$.
\end{defi}

We will be interested with the interaction of oplax colimits and restriction of the indexing diagrams. We have the following lemma:

\begin{lmm} \label{OplaxColimitsPreserveColimits}
    Let  $(\Ccal, \FunInt)$ be a category with a choice of enhanced mapping functor, such that $\Ccal$ is cocomplete and $(\Ccal, \FunInt)$ has all (small) oplax colimits. Then, given a functor $F:K\to\Ccal$, the association
    $$
        \alpha\in\CatInfty_{/K}\longmapsto \oplaxcolim(F\circ\alpha)\in\Ccal
    $$
    is functorial and preserves colimits.
\end{lmm}
\begin{proof}
    Since we have assumed the existence of both colimits and oplax colimits, it suffices to work with represented functors. In particular, the Yoneda lemma reduces both the functoriality and the preservation of colimits to checking that for a fixed functor $F:\Ccal\to\CatInfty$, the association
    $$
        (\alpha:\Dcal\to\Ccal)\mapsto \Fun_\Dcal(\Dcal, \Un(F\circ\alpha))\simeq\Fun_{/\Ccal}(\Dcal, \Un(F))
    $$
    is functorial and sends colimits to limits, which is straightforward from identifying the right hand side with the mapping category from $\alpha$ to $(\Un(F)\to\Ccal)$ in $\CatInfty_{/\Ccal}$. Here, note that we need only appeal to the 1-categorical Yoneda since we are only proving statements related to 1-colimits and 1-functoriality.
\end{proof}

 Given a functor $F:\Ical\to\CatInfty$, there are two fibrations associated to it via the unstraightening. We write $\Un(F)$ for the total space of its cocartesian unstraightening and $\UnCart(F)$ for the cartesian one.

\begin{prop} \label{FunctorsFromUn}
    Let $F:\Ical\to\CatInfty$ be a functor. For every category $\Ecal$, there are equivalences:
    $$
    \begin{tikzcd}[row sep=0.2em]
        \Fun(\Un(F), \Ecal)\arrow[r, "{\simeq}"] & \Fun_{\Ical}\left(\Ical, \UnCart(\Fun(F(-), \Ecal))\right) \\
        \Fun(\Un(F)^\op, \Ecal)\arrow[r, "{\simeq}"] & \Fun_{\catop{\Ical}}\left(\catop{\Ical}, \Un(\Fun(\catop{F(-)}, \Ecal))\right)
    \end{tikzcd}
    $$
    where on the right, $\Fun_{\Ical}(\Ical, -)$ denotes the category of sections of a given fibration over $\Ical$. 

    In particular, the collection of inclusions of the fibers $F(i)\to\Un(F)$ upgrades to an oplax cocone which realizes $\Un(F)$ as the oplax colimit of $F:\Ical\to\CatInfty$.
\end{prop}
\begin{proof}
    By \cite[Corollary 3.2.2.13]{HTT} and Proposition 7.3 of \cite{GepnerHaugsengNikolaus}, the functor $\Fun(F(-), \Ecal):\catop{\Ical}\to\CatInfty$ is classified by a cartesian fibration $\UnCart(\Fun(F(-), \Ecal))\to\Ical$ which satisfies the following equivalence
    $$
        \begin{tikzcd}
            \Fun(\Un(F), \Ecal)\arrow[r, "{\simeq}"]& \Fun_{\Ical}\left(\Ical, \UnCart(\Fun(F(-), \Ecal))\right)
        \end{tikzcd}
    $$
    which is induced by the inclusions of the fibers. Let us also explain a model-independent argument: by the equivalence of $(\infty,2)$-categories of straightening--unstraightening \cite[Theorem 3.2.0.1]{HTT}, we have
    $$
        \Fun_{\Ical}\left(\Ical, \UnCart(\Fun(F(-), \Ecal))\right)\simeq\Nat^{\oplax}(\cst_*, \Fun(F(-), \Ecal))
    $$
    where $\Nat^{\oplax}$ is the category of oplax natural transformations, i.e. the category of maps in the $(\infty, 2)$-category of oplax functors $\Ical\to\Cat$ or equivalently, in that of cartesian fibrations over $\Ical$, see section 5 of \cite{HaugsengHebestreitLinskensNuiten} for details. Of course 
    $$
        \Nat^{\oplax}(\mathrm{cst}_*, \Fun(F(-), \Ecal))\simeq\Nat^{\oplax}(F(-), \Ecal)
    $$ 
    and the covariant unstraightening gives
    $$
        \Nat^{\oplax}(F(-), \Ecal)\simeq\Fun_{\Ical}\left(\Un(F), \Ecal\times\Ical\right)\simeq\Fun(\Un(F), \Ecal)
    $$
    The second equivalence can be deduced from the first by using that the opposite of a cartesian fibration classifying $F$ is the cocartesian fibration classifying $\mathrm{op}\circ F$ (see for instance \cite{BarwickGlasmanNardin}), so that we have:
    $$
        \begin{tikzcd}
            \Fun(\Un(F)^\op, \Ecal)\arrow[r, "{\simeq}"] & \Fun_{\catop{\Ical}}\left(\catop{\Ical}, \Un(\Fun(\catop{F(-)}, \Ecal))\right)
        \end{tikzcd}
    $$
    which concludes.
\end{proof}

\begin{rmq} \label{ComparisonWithGHN}
    In \cite{GepnerHaugsengNikolaus}, a different definition of oplax colimits (as well other variants of (op)lax (co)limits) is given through weighted limits. It follows from the results of section 7 of \loccit but also from the above proposition that these agree with our definition.

    Note also that \cite[Proposition 7.1]{GepnerHaugsengNikolaus} identifies the oplax limit of a functor $F:\Ical\to\CatInfty$ with the category of sections $\Fun_{\Ical^\op}(\Ical^\op, \UnCart(F))$. Indeed, by a similar proof as in proposition \ref{FunctorsFromUn}, there is an equivalence
    $$
        \Fun(\Ecal, \Fun_{\Ical^\op}(\Ical^\op, \UnCart(F)))\simeq\Fun_{\Ical^\op}(\Ical^\op, \UnCart(\Fun(\Ecal, F(-)))
    $$
    Therefore, the first equivalence of Proposition \ref{FunctorsFromUn} can be restated as the following:
    $$
        \begin{tikzcd}
            \Fun(\oplaxcolim(F), \Ecal)\arrow[r, "{\simeq}"] & \oplaxlim(\Fun(F(-), \Ecal))
        \end{tikzcd}
    $$
    which is an oplax-colimit variant of the fact that the contravariant entry of mapping spaces sends colimits to limits.
\end{rmq}

Suppose now that our functor $F$ lands in $\CatEx$, the category of stable categories and exact functors between them. In general, $\Un(F)$ will not be a stable category itself --- this already fails if $F$ is constant and $\Ical$ not stable. We now seek to produce a stable category as close as possible to $\Un(F)$.

\begin{defi}
    Let $\Ecal$ be a stable category, and $F:\Ical\to\CatEx$ a functor. A functor $G:\Un(F)\to\Ecal$ is called \textit{fiberwise-exact} if its restriction along each fiber $G_i:F(i)\to\Un(F)\rightarrow\Ecal$ is an exact functor. We denote 
    $$
        \Fun^{\fbwex}(\Un(F), \Ecal)
    $$
    the full subcategory of $\Fun(\Un(F), \Ecal)$ of fiberwise-exact functors.
\end{defi}

\begin{thm} \label{StabUnDefThm}
    Let $\Ical$ be a category and $F:\Ical\to\CatEx$ a functor. There exists a stable category $\StabUn(F)$ equipped with a fiberwise-exact functor $\alpha:\Un(F)\to\StabUn(F)$ satisfying the following universal property: for every stable $\Ecal$, the functor
    $$
        \begin{tikzcd}
            \alpha^*:\FunEx(\StabUn(F), \Ecal)\arrow[r, "\simeq"] & \Fun^{\fbwex}(\Un(F), \Ecal)
        \end{tikzcd}
    $$
    is an equivalence.
\end{thm}
\begin{proof}
    This follows from the general framework of \cite[Proposition 5.3.6.2]{HTT} as we now explain. Let $\Pcal(\Un(F))$ be the category of space-valued presheaves on $\Un(F)$. Consider the full subcategory $\Pcal^{\fbwex}(\Un(F))$ of $\Pcal(\Un(F))$ spanned by those presheaves whose restriction to each fiber is right-exact; this is an accessible localization of $\Pcal(\Un(F))$ and we denote by $L$ the associated localization functor. 

    Let $j$ be the Yoneda embedding $\Un(F)\to\Pcal(\Un(F))$ and write $\Qcal$ for the smallest full subcategory of $\Pcal^{\fbwex}(\Un(F))$ stable under finite colimits and containing the image of $L\circ j$. It follows from \cite[Proposition 5.3.6.2]{HTT} that for every category with finite colimits $\Ecal$, the functor $L\circ j:\Un(F)\to\Qcal$ induces an equivalence
    $$
        \begin{tikzcd}
            (L\circ j)^*:\FunLEx(\Qcal, \Ecal)\arrow[r, "\simeq"]& \Fun^{\fbwex}(\Un(F), \Ecal)
        \end{tikzcd}
    $$
    with source the category of left-exact functors $\Qcal\to\Ecal$. Thus, to conclude we can simply let $\StabUn(F)$ be the Spanier-Whitehead stabilization of $\Qcal$, that is the image of $\Qcal$ under the left adjoint of the inclusion $\CatEx\subset\cat{Cat}^{\mathrm{fin-colim}}$.
\end{proof}

\begin{prop} \label{StabUnIsOplaxColimit}
    Let $F:\Ical\to\CatEx$ be a functor. Then, $\StabUn(F)$ is the oplax colimit of $F$ computed in $\CatEx$ with its enhanced mapping functor as in Example \ref{ExampleEnhancedMappingFunctors}.
\end{prop}
\begin{proof}
    This follows without difficulty from the previous results. Let $\Ecal$ be stable, then Theorem \ref{StabUnDefThm} shows that the map $\Un(F)\to\StabUn(F)$ induces 
    \[
        \begin{tikzcd}
            \FunEx(\StabUn(F), \Ecal)\arrow[r, "\simeq"]&  \Fun^{\fbwex}(\Un(F),\Ecal)
        \end{tikzcd}
    \]
    Since being fiberwise-exact is a fiberwise condition, as the name suggests, we deduce from Theorem \ref{FunctorsFromUn} that pulling along the oplax cocone of $\Un(F)$ induces
    \[
        \begin{tikzcd}
            \Fun^{\fbwex}(\Un(F),\Ecal) \arrow[r, "\simeq"] & \Fun_{\Ical}(\Ical, \UnCart(\Fun^{\Ex}(F(-), \Ecal)))
        \end{tikzcd}
    \]
    which concludes.
\end{proof}

\begin{ex}
    If $F:\Ical\to\CatEx$ is constant with value $\Ccal$, then $\Un(F)\simeq\Ical\times\Ccal$, $\StabUn(F)$ is $\Ical\otimes\Ccal$, the value of the left adjoint of the endofunctor of $\CatEx$ given by $\Fun(\Ical, -)$ --- this is often called the tensor of the stable category $\Ccal$ by $\Ical$ in the sense of $\CatEx$, and was described under the name \textit{semi-exact tensoring} in \cite[Definition 2.1]{SaunierFundamental}.
\end{ex}

\begin{ex}
    If $F:\Delta^1\to\CatEx$ is a functor corresponding to an exact functor $G:\Bcal\to\Acal$, then $\StabUn(F)$ is the total space of the semi-orthogonal decomposition classified by $G$, i.e. it fits in the pullback square:
    $$
        \begin{tikzcd}
            \StabUn(F)\arrow[d]\arrow[r] & \Acal^{\Delta^1}\arrow[d, "t"] \\
            \Bcal\arrow[r] & \Acal
        \end{tikzcd}
    $$
    Indeed, this follows from \cite[Remark 5.7]{ChristDycherhoffWaldeLaxAdd} and the identification of $\StabUn(F)$ with the oplax colimit of $F$.
\end{ex}

\begin{rmq} \label{InverseToUniversalPropEquivalence}
    In Lemma \ref{AlphaiasAdjoints} and Proposition \ref{ExplicitStabUnStronglyFinite}, we will show that if $\Ical$ is strongly finite (see Definition \ref{DefStronlyFinite}), the inverse to the first equivalence of Proposition \ref{FunctorsFromUn} is given by right Kan extension along $\alpha$. 
\end{rmq}
