\section{The twisted Shaneson splitting}
\subsection{The twisted Shaneson splitting for bordism-invariant functors}

\hspace{1.2em} In this section, we deduce the twisted Shaneson splitting for bordism-invariant functors by leveraging the results of the previous section and applying them to a specific simplicial complex. Namely, let $K=\partial \Delta^2$ be the simplicial complex
\[
\begin{tikzcd}
	& 2\arrow[rd, dash] \\
	0\arrow[ru, dash]\arrow[rr, dash] & {} & 1
\end{tikzcd}
\]
with no nondegenerate $n$-simplex for $n\geq 2$ and denote $\lambda: \catop{\Face(K)}\to |\catop{\Face(K)}|\simeq |K|\simeq S^1$ the localization at all arrows. We now show:

\begin{thm}\label{Kernel-S1-is-metabolic}
    Let $F:|K|\to \CatP$ be a functor. Then the kernel of the Poincaré functor 
    $$
        \begin{tikzcd}
            \UnH(F\circ \lambda)\arrow[r, "{\Phi^{\Ex}_{F,\lambda}}"] & \UnH(F)
        \end{tikzcd}
    $$ 
    admits a dense Poincaré subcategory which is metabolic.
\end{thm}
\begin{proof}
    Let us introduce the following notation for the poset $\catop{\Face(K)}$:
    \[\begin{tikzcd}
    	& {[0,2]} & {[2]} \\
    	{[0]} &&& {[1,2]} \\
    	& {[0,1]} & {[1]}
    	\arrow[from=1-2, to=1-3, "\gamma_2^+"]
    	\arrow[from=2-4, to=1-3, "\gamma_2^+"]
    	\arrow[from=1-2, to=2-1, "\gamma_0^-"]
    	\arrow[from=3-2, to=2-1, "\gamma_0^+"]
    	\arrow[from=2-4, to=3-3, "\gamma_1^+"]
    	\arrow[from=3-2, to=3-3, "\gamma_1^-"]
    \end{tikzcd}\]

    %In this proof, we will adopt the following, more convenient notation:
    %\[\begin{tikzcd}
    %	& {0^-=2^+} & 2 \\
    %	0 &&& {1^+=2^-} \\
    %	& {0^+=1^-} & 1
    %	\arrow["{\gamma_2^+}", from=1-2, to=1-3]
    %	\arrow["{\gamma_2^-}"', from=2-4, to=1-3]
    %	\arrow["{\gamma_0^-}"', from=1-2, to=2-1]
    %	\arrow["{\gamma_0^+}", from=3-2, to=2-1]
    %	\arrow["{\gamma_1^+}", from=2-4, to=3-3]
    %	\arrow["{\gamma_1^-}"', from=3-2, to=3-3]
    %\end{tikzcd}\]
    Given $i=0,1,2$, we will write $i+1$ for its value mod $3$, and the same for $i-1$. This means that arrows are of the form $\gamma_i^\pm:[i, i\pm 1]\to [i]$ (up to swapping $i,i\pm 1$ inside the square brackets to match the notation).

    We know by Lemma \ref{GeneratorsKernelOfVerdierProj} that the kernel is generated as a stable category closed under retracts by objects of the form 
    $$
        z_x^{\gamma^\pm_i}:=\fib(\overline{\gamma^\pm_i})
    $$ 
    where $x\in F([i, i+1])$ and $\overline{\gamma^\pm_i}$ is the image under $\alpha$ of the cocartesian lift of $\gamma$ to $\Un(F\circ\lambda)$ with source $x$. Let us now define 
    $$
        \Lcal^\pm=\langle z_{x}^{\gamma_i^\pm}\mid i=0,1,2, x\in F([i,i+1])\rangle
    $$ 
    It will suffice to check the conditions of Lemma \ref{EasierCriterionMetabolic} for the subcategory $\mathcal L^+\subset \ker(\Phi_{F,\lambda}^{\Ex})$ up to retracts since we only want to prove that there exists a dense subcategory which has a Lagrangian. \\

    From Remark \ref{FormulaForZGammaX} we have:
    $$
        z_x^{\gamma^+_i}(a)=
        \begin{cases*}
            0 & if $a=[i]$ \\
            x & if $a=[i,i+1]$ \\
            F(\lambda(\gamma_{i+1}^-))x & if $a=[i+1]$ \\
            0 & otherwise
        \end{cases*}
    $$
    and 
    $$
        z_x^{\gamma^-_i}(a)=
        \begin{cases*}
            F(\lambda(\gamma_{i-1}^+))x & if $a=[i-1]$\\
            x & if $a=[i-1,i]$\\
            0 & if $a=[i]$\\
            0 & otherwise.
        \end{cases*}
    $$

    %We are now ready to compute the value of the duality on the generators.
    %
    %$$D_\Qoppa(z^{\gamma^+_i}_x)(a)=\colim_{b\in \Face(K)^\op}\lim_{\delta:b\to a}F(\lambda(\delta))D_{\Qoppa_{F(b)}}z_x^{\gamma^+_i}(b).$$ 
    %  
    %  Now, the limit inside is
    %    $$\begin{cases*}\lim_{\delta:[i+1]\to a} F(\delta)F(\lambda(\gamma_{i+1}^-))D_{\Qoppa_{F(b)}}x & if $b=[i+1]$\\
    %    \lim_{\delta:[i,i+1]\to a} F(\delta)D_{\Qoppa_{F(b)}}x & if $b=[i,i+1]$\\
    %    0 & otherwise.
    %  \end{cases*}$$
    %
    By a direct computation, we find
    $$
        D_{\Qoppa}(z^{\gamma^+_i}_x)(a)=
        \begin{cases*}
            \Sigma F(\lambda(\gamma^+_i))D_{\Qoppa_{F([i, i+1])}}x & if $a=[i]$\\
            \Sigma D_{\Qoppa_{F([i,i+1])}}x & if $a=[i,i+1]$\\
            0 & if $a=[i+1]$\\
            0 & otherwise.
        \end{cases*}
    $$
    Symmetrically, 
    $$ 
        D_{\Qoppa}(z^{\gamma^-_i}_x)(a)=
        \begin{cases*}
            0& if $a=[i-1]$\\
            \Sigma D_{\Qoppa_{F([i-1,i])}}x & if $a=[i-1,i]$\\
            \Sigma F(\lambda(\gamma_i^-))D_{\Qoppa_{F([i-1,i])}}x & if $a=[i]$\\
            0 & otherwise.
        \end{cases*}
    $$
    Hence, 
    \begin{equation}\label{duality-of-z+}
        D_\Qoppa(z^{\gamma_i^+}_x)\simeq \Sigma z^{\gamma_{i+1}^-}_{D_{\Qoppa_{F([i,i+1])}}x}
    \end{equation} 
    and symmetrically 
    $$
        D_\Qoppa(z^{\gamma_i^-}_x)\simeq \Sigma z^{\gamma^+_{i-1}}_{D_{\Qoppa_{F([i-1,i])}}x}
    $$
    This shows that the thick subcategory $\langle \mathcal L^+, D_{\Qoppa}\mathcal L^+\rangle=\ker(\Phi^{\Ex}_{F, \lambda})$ so that we have the second part of the hypotheses of Lemma \ref{EasierCriterionMetabolic}.

    We now show that $\Qoppa(z_x^{\gamma_i^+})$ vanishes for $i=0$, the others case are totally symmetric; the formula is as follows:
    $$
    \Qoppa(z_x^{\gamma_0^+})\simeq\colim\left(
    \begin{tikzcd}[column sep="0.5cm"]
    	& 0 & 0 \\
    	0 &&& 0 \\
    	& \Qoppa_{F([0,1])}(x) & \Qoppa_{F([1])}(F(\lambda(\gamma_1^-))(x))
    	\arrow[from=1-2, to=1-3]
    	\arrow[from=2-4, to=1-3]
    	\arrow[from=1-2, to=2-1]
    	\arrow[from=3-2, to=2-1]
    	\arrow[from=2-4, to=3-3]
    	\arrow[from=3-2, to=3-3]
    \end{tikzcd}\right)
    $$
    Since $F$ factors through the localization at all arrows, the associated natural transformation $\Qoppa_{F(k)}\to f^*\Qoppa_{F(k')}$ is an equivalence. Therefore, the above colimit is $0$.

    Let us now show that $B_\Qoppa(z^{\gamma_i^+}_x, z^{\gamma_j^+}_y)\simeq 0$ for every $i,j=0,1,2, x\in F([i,i+1]), y\in F([j,j+1])$. If $i=j$, then $z^{\gamma_i^+}_x\oplus z^{\gamma_i^+}_y\simeq  z^{\gamma_i^+}_{x\oplus y}$ therefore $B_\Qoppa(z^{\gamma_i^+}_x, z^{\gamma_i^+}_y)$ is a retract of $\Qoppa(z^{\gamma_i^+}_{x\oplus y})\simeq 0$, hence zero itself.

    Let us now deal with the case $i\neq j$, say $i=0,j=1$; again, any other case is totally symmetric. Note that $$B_\Qoppa(z^{\gamma_0^+}_x, z^{\gamma_1^+}_y)\simeq \map(z_x^{\gamma_0^+}, D_\Qoppa(z^{\gamma_{i}^+}_y)).$$ An object of this mapping spectra is a map of diagrams in $\UnCart(F\circ \lambda)$ of the following form:

    \[\begin{tikzcd}
    	& \ 0 & \ 0 \\
    	0 &&& 0 \\
    	& x \ & {F(\lambda(\gamma_{1}^+))x} \\
    	& \ 0 & \ 0 \\
    	0 &&& {\Sigma D_{\Qoppa_{F([1,2])}}y} \\
    	& 0 \ & {\Sigma F(\lambda(\gamma_1^+))D_{\Qoppa_{F([1,2])}}y}
    	\arrow[from=1-2, to=1-3]
    	\arrow[from=1-2, to=2-1]
    	\arrow[shift left=2, from=1-2, to=3-2, dash]
    	\arrow[shift left=2, from=1-3, to=3-3, dash]
    	\arrow[from=2-1, to=5-1]
    	\arrow[from=2-4, to=1-3]
    	\arrow[from=2-4, to=3-3]
    	\arrow[from=2-4, to=5-4]
    	\arrow[from=3-2, to=2-1]
    	\arrow[from=3-2, to=3-3]
    	\arrow[shift right=2, from=3-2, to=6-2, crossing over]
    	\arrow[shift left=2, from=3-2, to=4-2]
    	\arrow[shift right=2, from=3-3, to=6-3, crossing over]
    	\arrow[shift left=2, from=3-3, to=4-3]
    	\arrow[from=4-2, to=4-3]
    	\arrow[from=4-2, to=5-1]
    	\arrow[from=5-4, to=4-3]
    	\arrow[from=5-4, to=6-3]
    	\arrow[from=6-2, to=5-1]
    	\arrow[from=6-2, to=6-3]
    \end{tikzcd}\]
    The commutativity of the front square induces a factorization of the map 
    $$
        \begin{tikzcd}
            F(\lambda(\gamma_{1}^+))x\arrow[r] & \Sigma F(\lambda(\gamma_1^+))D_{\Qoppa_{F([1,2])}}y
        \end{tikzcd}
    $$
    through the cokernel of the top map $x\to F(\lambda(\gamma_{1}^+))x$, which is an equivalence hence has vanishing cokernel. Therefore the wanted mapping spectrum is null.

    This shows that $\Qoppa$ is exact on $\mathcal L^+$, and since it vanishes on the generators $z_x^{\gamma_i^+}$ it is zero on $\mathcal L$. In particular, we have verified the hypotheses of Lemma \ref{EasierCriterionMetabolic} and hence the theorem follows.
\end{proof}

\begin{cor} \label{AssemblyBZofBIPVisEquivalence}
    Let $F:B\Z\to\CatP$ be a functor such that $F(*)$ is idempotent-complete, and $E:\CatP\to\Ecal$ be a bordism-invariant Poincaré--Verdier localizing functor. Then, the assembly map
    $$
        \begin{tikzcd}
            \colim\limits_{B\Z}E\circ F\arrow[r] &  E(\colim\limits_{B\Z}F)
        \end{tikzcd}
    $$ 
    is an equivalence in $\Ecal$.
\end{cor}

\begin{proof}
    This follows from combining Theorem \ref{AssemblyMapOfBIPV} and Theorem \ref{Kernel-S1-is-metabolic}.
\end{proof}

We can recover Ranicki's original result for the L-theory of rings of twisted Laurent polynomials from the above statement.


\begin{cor}[{\cite[Theorem 5.1 with $T=\widetilde K_0(R)$]{Ranicki-ALTIII}}]
    Let $(R, \tau)$ be a ring with involution, equipped with an automorphism $\alpha$. Let $(R_\alpha[t^\pm], \tau^-)$ be the ring of $\alpha$-twisted Laurent polynomials equipped with the involution sending $t\mapsto t^{-1}$. Then there exists a long exact sequence of abelian groups
    $$
        \begin{tikzcd}
            \dots\arrow[r] & \tL^{\tq,\proj}_n(R)\arrow[r, "{(1-\alpha)}"] & \tL^{\tq,\proj}_n(R)\arrow[r] & \tL^{\tq, \proj}_n(R_\alpha[t^{\pm 1}])\arrow[r] & \dots
        \end{tikzcd}
    $$
\end{cor}

\begin{proof}
    It suffices to prove that 
    $$
        \tL^{\tq,\proj}(R_\alpha[t^{\pm 1}], \tau^-)\simeq \cofib\left(\begin{tikzcd}\tL^{\tq,\proj}(R, \tau)\arrow[r, "{1-\alpha}"] & \tL^{\tq,\proj}(R, \tau)\end{tikzcd}\right)
    $$
    Let $F:B\Z\to \CatP$ be the functor parametrizing $(\Perf(R), \Qoppa_\tau^\tq)$ and let us denote again by $\alpha$ the functor $\alpha:\Perf(R)\to \Perf(R)$ induced y $\alpha:R\to R$. One can prove, by means of \ref{quadratic-L-theory} and \cite[§4.3]{HermKI}, that $$\colim_{B\Z} F\simeq (\Perf_{R_\alpha[t^{\pm 1}]}, \Qoppa_{\tau^-}^\tq).$$

    By abstract nonsense, 
    \begin{align*}
        \colim_{B\Z}\tL\circ F & =
            \colim \left(\begin{tikzcd}[ampersand replacement=\&]\tL(R, \tau) \& \arrow[l, "{\textup{pr}_1}"']\tL(R, \tau)\oplus\tL(R, \tau)\arrow[r, "{\alpha\circ \textup{pr}_2}"] \& \tL(R, \tau)\end{tikzcd}\right) \\ 
            & \simeq\cofib \left(\begin{tikzcd}[ampersand replacement=\&]\tL(R,\tau)\arrow[r, "{\id-\alpha}"] \& \tL(R,\tau)\end{tikzcd}\right)
    \end{align*}
    The statement then follows from Corollary \ref{AssemblyBZofBIPVisEquivalence}.
\end{proof}

\subsection{Towards the general twisted Shaneson splitting}

\hspace{1.2em} Let $\Ical$ the following category
\begin{equation}\label{DiagramIcal}
    \begin{tikzcd}
        \bullet\arrow[loop left, "(-1)", phantom]\arrow[r, bend left=30, "\alpha_+"]\arrow[r, bend right=30, "\alpha_-"'] & \bullet \arrow[loop right, "(+1)", phantom]
    \end{tikzcd}
\end{equation}

Recall that in our convention, $\TwAr(\Delta^1)$ is the category pictorially depicted as follows:
$$
    \begin{tikzcd}
        (0\to 0) & (0\to 1)\arrow[l]\arrow[r]& (1\to 1)
    \end{tikzcd}
$$
Hence, there is a pushout square of categories
$$
    \begin{tikzcd}
        \Delta^0\coprod\Delta^0\arrow[r]\arrow[d] & \TwAr(\Delta^1)\arrow[d] \\
        \Delta^0\arrow[r] & \Ical
    \end{tikzcd}
$$  
where the bottom map is the inclusion of $(+1)$ in the description (\ref{DiagramIcal}). We deduce the following:

\begin{prop} \label{PoincareSquareUnPIcal}
    Let $F:\Ical\to\CatP$ be a functor. There is a pushout square in $\CatP$:
    $$
        \begin{tikzcd}
            F(1)\oplus F(1)\arrow[r]\arrow[d] & \UnP(F\mid_{\TwAr(\Delta^1)})\arrow[d, "p"] \\
            F(1)\arrow[r, "i_{1}"] & \UnP(F)
        \end{tikzcd}
    $$
    whose horizontal arrows are split Poincaré--Verdier inclusions. In particular, $\UnP(F)$ is Poincaré.
\end{prop}
\begin{proof}
    The existence of the above square and it being a pushout of hermitian categories follows from Lemma \ref{OplaxColimitsPreserveColimits}.

    Since we already know the square is a pushout in $\CatH$, the closure of $\CatP$ under colimits in $\CatH$ reduces the problem to check whether the left vertical map and the top horizontal map are Poincaré functors between Poincaré categories. The hermitian categories $F(1)$ and $F(1)\oplus F(1)$ are obviously Poincaré and Lemma \ref{UnPPoincaréCubePunctN} guarantees this also holds for $\UnP(F\mid_{\TwAr(\Delta^1)})$ since $\TwAr(\Delta^1)\simeq\CubePunct{1}$.
    \begin{itemize}
        \item[(i)] The map $F(1)\oplus F(1)\to F(1)$ is the fold map, hence Poincaré for reasons unrelated to $F$.
        \item[(ii)] The functor $\Delta^0\coprod\Delta^0\to\TwAr(\Delta^1)$ satisfies the hypotheses of Proposition \ref{FibreCofinalInducesCartesianLift}, hence $F(1)\oplus F(1)\to\UnP(F\mid_{\TwAr(\Delta^1)})$ is a duality-preserving cartesian lift of the underlying functor of exact categories. To show that it is a split-Poincaré--Verdier inclusion, it suffices to show that
        $$
            F(1)\oplus F(1)\to\StabUn(F\mid_{\TwAr(\Delta^1)})
        $$
        is fully-faithful with a right adjoint. We already have the adjunction statement by Lemma \ref{AlphaiasAdjoints} and the fully-faithfulness can be checked on the formula using $\Map_{\TwAr(\Delta^1)}(i, i)\simeq *$ for every $i\in\TwAr(\Delta^1)$.
    \end{itemize}
    Since $\CatP\to\CatH$ reflects colimits, the square is a pushout square in $\CatP$. This implies that the bottom horizontal functor is a Poincaré--Verdier inclusion, which concludes.
\end{proof}

\begin{prop} \label{CommonValueKernelUnPIcal}
    Let $F:\Ical\to\CatP$ be a functor. The common value of the cokernel of the Poincaré--Verdier inclusions of Proposition \ref{PoincareSquareUnPIcal} is $(F(-1), \Sigma\Qoppa_{F(-1)})$. Differently stated, the Poincaré--Verdier inclusion $i_1:F(1)\to\UnP(F)$ fits into a split Poincaré--Verdier sequence
    $$
        \begin{tikzcd}
            F(1)\arrow[r, "i_{1}"] & \UnP(F)\arrow[r, "\ev_{-1}"] & (F(-1), \Sigma\Qoppa_{F(-1)})
        \end{tikzcd}
    $$
\end{prop}
\begin{proof}
    By Proposition \ref{PoincareSquareUnPIcal}, we know that $i_1$ is a split Poincaré--Verdier inclusion whose cokernel is the same as $F(1)\oplus F(1)\to\UnP(F\mid_{\TwAr(\Delta^1)})$. We are thus left to identify the latter. We claim that
    $$
        \ev_{-1}:\UnP(F\mid_{\TwAr(\Delta^1)})\longrightarrow(F(-1), \Sigma\Qoppa_{F(-1)})
    $$
    is the quotient functor (of the latter map, but consequently also of the former). First let us remark that $\ev_{-1}$ is indeed a Poincaré functor thanks to Remark \ref{AlphaNotPoincareButEvYes}.

    Using that $\TwAr(\Delta^1)$ is obtained by gluing two copies of $\Delta^1$ along three copies of $\Delta^0$, the explicit description of \ref{ExplicitStabUnStronglyFinite} implies that $\StabUn(F\mid_{\TwAr(\Delta^1)})$ fits in the following pullback square
    $$
        \begin{tikzcd}[column sep=huge]
            \StabUn(F\mid_{\TwAr(\Delta^1)})\arrow[d, "{(\ev_{1}, \ev_{1}, \ev_{-1})}"]\arrow[rr] && \Ar(F(1))^2\arrow[d, "{(s, t, s, t)}"] \\
            F(1)\oplus F(1)\oplus F(-1)\arrow[rr, "{(\id, \id, f(\alpha^+), f(\alpha^-))}"]& & F(1)^4
        \end{tikzcd}
    $$
    In particular, the underlying functor of stable categories of $\ev_{-1}$ is indeed the cokernel of $F(1)\oplus F(1)\to \StabUn(F\mid_{\TwAr(\Delta^1)})$. %\personalJ{We should just compute this directly. The map $F(1) \oplus F(1) \to \StabUn(F|_{\TwAr(\Delta^1)})$ takes the pair $(X,Y)$ to the section 
    % \begin{align*}
    % (-1) &\mapsto 0 \text{ since there are no maps from either copy of +1 to -1}\\
    % (+1) &\mapsto X \text{ this is the first copy of +1}\\
    % (+1) &\mapsto Y \text{ this is the second copy of +1}
    %    \end{align*}
    % which all follows from the formulae for the $\alpha_i$ in the Lemma. Since this is split, the cokernel is given by the $F(-1)$ and the map is the $ev_{-1}$. I wrote this because I don't really understand how the pullback you wrote is relevant. }

    To conclude, we have to check that
    $$
        (\ev_{-1}^\op)_!\Qoppa_F\longrightarrow\Sigma\Qoppa_{F(-1)}
    $$
    is an equivalence. Since the formula for $(\ev_{-1}^\op)_!\Qoppa_F$ is the colimit over $\TwAr(\Delta^1)$ --- i.e. the pushout --- of the following diagram:
    $$
        \begin{tikzcd}
            & (\ev_{-1}^\op)_!(\ev_{1}^\op)^*\Qoppa_{F(1)} \\
            (\ev_{-1}^\op)_!(\ev_{-1}^\op)^*\Qoppa_{F(-1)}\arrow[ru]\arrow[rd] \\
            & (\ev_{-1}^\op)_!(\ev_{1}^\op)^*\Qoppa_{F(1)}
        \end{tikzcd}
    $$
    it suffices to check that $(\ev_{-1}^\op)_!(\ev_{-1}^\op)^*\simeq\id$ and $(\ev_{-1}^\op)_!(\ev_{1}^\op)^*\simeq 0$. The first statement follows from the fully-faithfulness of the right adjoint of $\ev_{-1}$, itself a consequence of the formula of Lemma \ref{AlphaiasAdjoints} and the fact that every point of $\TwAr(\Delta^1)$ has no non-trivial endomorphisms. Since $(\ev_{1}^\op)^* \simeq(\alpha_1^\op)_!$, the second statement follows from checking that $\ev_{-1}\circ\;\alpha_{1}\simeq0$ which we can also see in the formula of Lemma \ref{AlphaiasAdjoints}, as $\Map_{\TwAr(\Delta^1)}(1, -1)=\emptyset$. This concludes.
\end{proof}

Remark that $\TwAr(\Delta^1)$ is contractible and the map $\TwAr(\Delta^1)\to\Ical\to B\Z$ therefore factorizes through $*\to B \Z$. Hence, given a functor $F:B\Z\to\CatP$, we can form the comparison functor between the oplax colimit and the colimit of two different functors which gives rises to:

\begin{lmm}
    Let $F:B\Z\to\CatP$ be a functor. There is a diagram with Poincaré--Verdier sequences as rows as follows:
    $$
        \begin{tikzcd}
            \ker(\Phi^{\mathrm{P}}_{F\mid_{\TwAr(\Delta^1)}})\arrow[r]\arrow[d] & \UnP(F\mid_{\TwAr(\Delta^1)})\arrow[r]\arrow[d] & F(*)\arrow[d] \\
            \ker(\Phi^{\mathrm{P}}_{F})\arrow[r]& \UnP(F\mid_{\Ical})\arrow[r] & \colim\limits_{B\Z} F
        \end{tikzcd}
    $$
    Moreover, the first kernel $\ker(\Phi^{\mathrm{P}}_{F\mid_{\TwAr(\Delta^1)}})$ is a metabolic category.
\end{lmm}
\begin{proof}
    The functor $\TwAr(\Delta^1)\to\Delta^0\simeq *$ is the localisation at all the arrows of a poset of faces of a simplicial complex, hence the top sequence is a Poincaré--Verdier sequence by an instance of Proposition \ref{KernelStableUnderDualityFiniteCpx}. We delay the computation that shows the stability of the kernel $\ker(\Phi^{\mathrm{P}}_{F})$ to a latter section (see Lemma \ref{KernelStableUnderDuality}), for the only reason to gather all of the computations about it in a single place (this will imply that the bottom sequence is a Poincaré--Verdier sequence as well). 

    The compatibility of the sequences is ensured by the functoriality of oplax colimits, see Proposition \ref{OplaxColimitsPreserveColimits}. Finally, the metabolicity of the top kernel is a direct consequence of Lemma \ref{KernelMetabolicCubes}, since $\TwAr(\Delta^1)$ is the opposite of the poset of faces of the simplicial complex $\begin{tikzcd}\bullet_0\arrow[r, dash] &\bullet_1\end{tikzcd}$.
\end{proof}

We can combine the square of Proposition \ref{PoincareSquareUnPIcal} and the cokernel of \ref{CommonValueKernelUnPIcal} with the rectangle of the above lemma to get the following:
$$
    \begin{tikzcd}[row sep=small, column sep=small]
        0\arrow[rr]\arrow[dd]\arrow[rd] && F(*)\oplus F(*)\arrow[rr]\arrow[dd]\arrow[rd] && F(*)\oplus F(*)\arrow[dd]\arrow[rd] \\
        &\ker(\Phi^{\mathrm{P}}_{F\mid_{\TwAr(\Delta^1)}})\arrow[rr, crossing over] && \UnP(F\mid_{\TwAr(\Delta^1)})\arrow[rr, crossing over]&& F(*)\arrow[dd] \\
        0\arrow[rr]\arrow[rd] && F(*)\arrow[rr]\arrow[rd] && F(*)\arrow[rd] \\
        &\ker(\Phi^{\mathrm{P}}_{F})\arrow[rr]\arrow[from=uu, crossing over] && \UnP(F\mid_{\Ical})\arrow[rr]\arrow[from=uu, crossing over] && \colim\limits_{B\Z} F
    \end{tikzcd}
$$
The rightmost face is cocartesian by abstract nonsense, and every horizontal sequence is a Poincaré--Verdier sequence. Recall from Lemma \ref{PoincareSquareUnPIcal} that the middle slanted square is a pushout in $\CatP$, whose horizontal arrows are Poincaré--Verdier inclusions.

Thanks to these observations, for any Poincaré--Verdier localizing $E$ there is a diagram of short-exact sequences
\begin{equation}\label{eq-ComparisonReducesToKernels}
    \begin{tikzcd}
        E(\ker(\Phi^{\mathrm{P}}_{F\mid_{\TwAr(\Delta^1)}}))\arrow[r]\arrow[d] & E(\UnP(F\mid_{\Ical}))\arrow[r]\arrow[d, equal]& \colim_{B\Z}E\circ F\arrow[d]\\
        E(\ker(\Phi^{\mathrm{P}}_{F}))\arrow[r] & E(\UnP(F\mid_{\Ical}))\arrow[r] & E(\colim_{B\Z}F)
    \end{tikzcd}
\end{equation}
where the rightmost map is the colimit-comparison map, that is the assembly map for $B\Z$. In other words, the failure for the $B\Z$-assembly map to be an equivalence is completely controlled by the failure of the map between the kernels to be an equivalence.

The goal of the next section is to study the Poincaré functor:
$$
    \begin{tikzcd}
        \ker(\Phi^{\mathrm{P}}_{F\mid_{\TwAr(\Delta^1)}})\arrow[r, "{\Psi}"] & \ker(\Phi^{\mathrm{P}}_{F})
    \end{tikzcd}
$$ 
We already know that $\ker(\Phi^{\mathrm{P}}_{F\mid_{\TwAr(\Delta^1)}})$ is hyperbolic, and we will show that the whole map is in fact in the image of $\Hyp$, and that it admits a retraction which becomes compatible with the previous diagram after applying a Poincaré--Verdier localizing invariant.

\subsection{The nil-term(s) and the twisted Shaneson splitting}

\hspace{1.2em} We want to show that $\ker(\Phi^{\mathrm{P}}_{F})$ is metabolic (with the same notation as in the previous section). From Lemma \ref{UnPNonDegenerateAndFormula}, we have that for $x\in F(-1)$:
\begin{align*}
    \alpha_{-1}(x) & \simeq \begin{tikzcd}[ampersand replacement = \&]\Big[(-1,\lim_{\alpha\in \Ical_{-1//-1}}^{F(-1)}x) \& (1,\lim_{\alpha\in \Ical_{-1//1}}^{F(1)}F(\alpha)x)\arrow[l,shift right]\arrow[l,shift left] \Big]\end{tikzcd} \\
                   & \simeq \begin{tikzcd}[ampersand replacement = \&]\Big[(-1,x) \& (1,F(\alpha^+)x\oplus F(\alpha^-)x)\arrow[l,shift right]\arrow[l,shift left] \Big]\end{tikzcd}
\end{align*}
with the first map (resp. the second map) given by the first (resp. second) projection of the direct sum followed by the cartesian lift of $\alpha^+$ (resp. $\alpha^-$) at $x\in F(-1)\subset\UnCart(F)$. Here, for simplicity, we chose to write a section $\Ical^\op\to\UnCart(F)$ by the diagram it represents. Analogously, one can compute:
$$
    \alpha_1(F(\alpha^+)x)\simeq\begin{tikzcd}\Big[(-1,0) & (1,F(\alpha^+)x)\arrow[l,shift right]\arrow[l,shift left] \Big]\end{tikzcd} $$
and
$$
    \alpha_1(F(\alpha^-)x)\simeq\begin{tikzcd}\Big[(-1,0) & (1,F(\alpha^-)x)\arrow[l,shift right]\arrow[l,shift left] \Big]\end{tikzcd}
$$
where the two maps are the unique such maps over either $\alpha^+$ or $\alpha^-$. The oplax structure of $\StabUn(F)$ means there are natural maps
$$
    \begin{tikzcd}
        \alpha_{-1}(x)\arrow[r] & \alpha_1(F(\alpha^\pm)x)
    \end{tikzcd}
$$
whose fiber is given by:
$$
    z^{\pm}_x\coloneqq\fib(\begin{tikzcd}\alpha_{-1}(x)\arrow[r] &  \alpha_1(F(\alpha^\pm)x)\end{tikzcd})=\begin{tikzcd}\Big [(-1,x)& (1,F(\alpha^\mp)x)\arrow[l,shift right]\arrow[l,shift left]\Big ],\end{tikzcd}
$$
Here, in the case of $z^+_x$, the first map is the cartesian lift of $\alpha^-$ and the second is zero. In the case of $z^-_x$, the first map is zero and the second is the identity. 

\begin{lmm} \label{KernelStableUnderDuality}
    The kernel $\ker(\Phi^{\Ex}_{F})$ is generated under finite colimits and retracts by the $z^{\pm}_x$ for $x\in F(-1)$. Moreover, we have 
    $$
        D_{\Qoppa_F}(z^\pm_x)\simeq \Sigma z^{\mp}_{D_{F(-1)}x}
    $$
    In particular, the kernel is stable under the duality of $\StabUn(F)$. 
\end{lmm}
\begin{proof}
    The generation statement follows directly from Lemma \ref{GeneratorsKernelOfVerdierProj}. Using Proposition \ref{UnPNonDegenerateAndFormula}, we can compute
    $$
        D_{\Qoppa_F}(z^\pm_x)(-1)\simeq\colim^{F(-1)}\Big[\begin{tikzcd} D_{F(-1)}x \arrow[r,shift left]\arrow[r, shift right] & 0\Big]\end{tikzcd})\simeq\Sigma D_{F(-1)}x
    $$
    where the superscript $F(-1)$ indicates we take the colimit in the stable category $F(-1)$, and 
    \begin{align*}
        D_{\Qoppa_F}(z^\pm_x)(1) & \simeq \colim^{F(1)}\Big[\begin{tikzcd}[ampersand replacement = \&] D_{F(1)}(F(\alpha^+)x\oplus F(\alpha^-)x) \arrow[r,shift left]\arrow[r, shift right] \& D_{F(1)}F(\alpha^\mp)x\Big]\end{tikzcd} \\
        &\simeq\Sigma D_{F(1)}(F(\alpha^\pm)x) \\
        &\simeq\Sigma F(\alpha^\pm)(D_{F(-1)}x)
    \end{align*}
    where the last equality follows from the fact that $F(\alpha^{\pm})$ is duality-preserving. Comparing with the formula, we get the wanted formula on the duality, and the last statement is straightforward.
\end{proof}

From the above lemma, it appears that there are two flavours of objects in the kernel, which warrants the following definition:

\begin{defi}
    Let $\Ncal^+$ denote the full stable subcategory of $\StabUn(F)$ which is closed under retracts generated by the $z^{+}_x$ for $x\in F(-1)$ (respectively $\Ncal^-$ for $z^{-}_x$ still with $x\in F(-1)$).
\end{defi}

\begin{lmm} \label{QuadraticVanishing}
    The quadratic functor on $\ker\Phi^{\mathrm{p}}_{F}$ vanishes on both $\Ncal^+$ and $\Ncal^-$. Moreover, the duality induces an equivalence $\catop{(\Ncal^+)}\simeq\Ncal^-$.
\end{lmm}
\begin{proof}
    The second statement follows from \ref{KernelStableUnderDuality} since the duality is an anti-involution of the kernel. To check the first, first recall from \ref{UnPNonDegenerateAndFormula}:
    $$
    \Qoppa_{F}(z^\pm_x)\simeq\colim\begin{tikzcd}\Big[\Qoppa_{F(-1)}(x)\arrow[r,shift left, "\eta_x"]\arrow[r,shift right, "0"']&\Qoppa_{F(1)}(F(\alpha^\mp)x)\Big]\end{tikzcd}
    $$
    where $\eta^\mp_x$ is the value at $x$ of the natural transformation $\eta^\mp:\Qoppa_{F(-1)}\to \Qoppa_{F(1)}\circ \catop{F(\alpha^\mp)}$ provided by Lemma \ref{DatumOfLift}. Since it factors through $B\Z$, $F$ sends all arrows of $\Ical$ to equivalences (this is actually the only moment we use this) hence, in particular, the two possible natural transformations $$\Qoppa_{F(-1)}\to \Qoppa_{F(1)}\circ \catop{F(\alpha^\mp)}$$ are equivalences.
    Therefore, the top arrow in the diagram is an equivalence, and hence the coequalizer is zero. 

    We have checked that $\Qoppa$ vanishes on the generators of $\Ncal^+, \Ncal^-$ but $\Qoppa$ is only quadratic and not exact so this does not suffices. However, the only obstruction to $\Qoppa$ being exact is $B_\Qoppa$, which is linear in each variable and thus to conclude, it suffices to check that $B_\Qoppa(z^+_x, z^+_y)\simeq 0$. Now, $B_\Qoppa(z^+_x, z^+_y)$ is a retract of $\Qoppa(z^+_x\oplus z^+_y)$; but since $z^+_x\oplus z^+_y\simeq z^+_{x\oplus y}$, the previous computation shows that $\Qoppa(z^+_x\oplus z^+_y)\simeq 0$, which concludes.
\end{proof}

\begin{lmm} \label{OrthogonalComplement}
    The two subcategories $\Ncal^+$ and $\Ncal^-$ are in orthogonal complement inside $\ker\Phi^{\Ex}_{F}$.
\end{lmm}
\begin{proof}
    Let us simply write $\Qoppa$ for the quadratic functor on $\ker\Phi^{\mathrm{p}}_{F}$. Remark that
    $$
        \map(z^+_x, z^-y)\simeq\map(z^+_x, D_\Qoppa(z^+_y))\simeq B_\Qoppa(z^+_x, z^+_y)
    $$
    As previously, $B_\Qoppa(z^+_x, z^+_y)$ is a retract of $\Qoppa(z^+_{x\oplus y})$, which we have shown to vanish in the previous lemma, hence
    $$
        \map(z^+_x, z^-_y)\simeq 0
    $$
    Since the duality is its own adjoint, the above computation also shows that
    $$
        \map(z^-_x, z^+_y)\simeq 0
    $$
    which concludes.
\end{proof}

We have now all that we need to show the following:

\begin{prop} \label{KernelHyperbolic}
    Let $F:B\Z\to\CatP$. There is a Poincaré--Verdier functor, whose underlying exact functor is a dense inclusion:
    $$
        \begin{tikzcd}
            \Hyp(\Ncal^+)\arrow[r] & \ker(\Phi^{\mathrm{p}}_{F})
        \end{tikzcd}
    $$
    which is an equivalence if the composite $F:B\Z\to\CatEx$ has values in idempotent-complete stable categories.
\end{prop}
\begin{proof}
    By Lemma \ref{OrthogonalComplement}, the functor $\Ncal^+\oplus\Ncal^-\to\ker\Phi^{\Ex}_{F, i}$ is fully-faithful. Moreover, by Lemma \ref{QuadraticVanishing}, the quadratic functor on $\ker(\Phi^{\mathrm{p}}_{F, i})$ vanishes on both summands so its restriction to the direct sum must be hyperbolic. Lemma \ref{GeneratorsKernelOfVerdierProj} guarantees that the inclusion $\Ncal^+\oplus\Ncal^-\to\ker\Phi^{\Ex}_{F, i}$ has dense image, which gives the first part. \\

    Suppose now that the underlying stable categories in which $F$ takes values are idempotent-complete, then so is $\StabUn(F)$ by Proposition \ref{IdempotentCompleteStabUn}; note that this applies both to $F$ and $F\circ i$ so that the kernel $\ker(\Phi^{\Ex}_{F, i})$ is also idempotent-complete, as such categories are closed under limits in $\CatEx$. Since they are closed under retracts in the kernel, $\Ncal^+$ and $\Ncal^-$ are idempotent-complete as well and thus so is their sum $\Ncal^+\oplus\Ncal^-$. Consequently, the above map is an equivalence as wanted.
\end{proof}

Finally, to complete our understanding of the Shaneson splitting, we have to understand the map $\Psi$ itself. As a preliminary, we will need the following folklore result, related to results of Schwede--Shipley:

\begin{lmm} \label{MapsFromStableCatGeneratedByOneElement}
    Let $\Ccal$ be a small stable category generated under finite colimits and retracts by a single object $G\in\Ccal$, and denote $B\End_\Ccal(G)$ the one-point category with $\End_\Ccal(G)$ as endomorphisms. The functor $\alpha:B\End_\Ccal(G)\to\Ccal$ induces an equivalence
    $$
        \begin{tikzcd}
            \alpha^*:\FunEx(\Ccal, \Dcal)\arrow[r, "\simeq"] & \Fun(B\End_\Ccal(G), \Dcal)
        \end{tikzcd}
    $$
    for every idempotent-complete $\Dcal$.
\end{lmm} 
\begin{proof}
    Under these hypotheses, $\Ind(\Ccal)$ is generated under colimits by $G$ and therefore
    $$
        \begin{tikzcd}
            \alpha^*:\FunL(\Ind(\Ccal), \Dcal)\arrow[r] & \Fun(B\End_\Ccal(G), \Dcal)
        \end{tikzcd}
    $$
    is conservative for any presentable stable $\Dcal$. A priori, this functor has a left adjoint given by left Kan extension followed by forcing the functor to commute with small colimits.

    We now show that the left Kan extension $\alpha_!$ already lands in $\FunL(\Ind(\Ccal), \Dcal)$ so that this second operation is not necessary; for this we adapt a criterion of Rezk, see \href{https://mathoverflow.net/q/450214}{this MO answer}, to the stable world. Write $\Pcal^{st}$ for the left adjoint $\Cat\to\CatEx$ to the inclusion and let us shorten $\Ccal_0:=B\End_\Ccal(G)$. Then, there is a unique colimit-preserving $\overline{\alpha}:\Ind(\Pcal^{st}(\Ccal_0))\to\Ccal$ whose restriction to $\Ccal_0$ is $\alpha$. in particular, there is a commutative diagram
    $$
        \begin{tikzcd}
            \FunL(\Ind(\Ccal), \Dcal)\arrow[r, "{\alpha^*}"]\arrow[rd, "{\overline{\alpha}^*}"] & \Fun(\Ccal_0, \Dcal) \\
            & \FunL(\Ind(\Pcal^{st}(\Ccal_0)), \Dcal)\arrow[u, "\simeq"]
        \end{tikzcd}
    $$
    Hence, passing to left adjoints, for any $g:B\End_\Ccal(G)\to\Dcal$, we see that $\alpha_!g$ is equivalently given as the composite $\Ind(\Pcal^{st}(g))\circ R_\alpha$ where $\Ind(\Pcal^{st}(g))$ is the unique colimit-extension of $g$ to $\Ind(\Pcal^{st}(\Ccal_0))$ and $R_\alpha$ is the following functor:
    \begin{align*}
        \Ind(\Ccal)\longrightarrow & \Ind(\Pcal^{st}(\Ccal_0))\simeq\FunEx(\Pcal^{st}(\Ccal_0)^\op, \Sp) \\
        X\longmapsto & \map_{\Ind(\Ccal)}(\alpha(-), X)
    \end{align*}
    formally induced by taking the right adjoint of the colimit-preserving extension of $\alpha$ to $\Ind(\Pcal^{st}(\Ccal_0))$. In particular, it suffices to check that $R_\alpha$ is colimit-preserving for all of the $\alpha_!g$ to be, and this follows directly from the fact that $\map_{\Ind(\Ccal)}(\alpha(C), -)$ commutes with colimits for every $C\in\Pcal^{st}(\Ccal_0)$ because they are compact in $\Ind(\Ccal)$ since our original $\alpha:B\End_\Ccal(G)\to\Ccal$ lands in $\Ccal\subset\Ind(\Ccal)^\omega$. \\

    In particular, the above showed that for every presentable stable $\Ecal$, there is an equivalence
    $$
        \begin{tikzcd}
            \alpha^*:\FunEx(\Ccal, \Ecal)\arrow[r, "\simeq"] & \Fun(B\End_\Ccal(G), \Ecal)
        \end{tikzcd}
    $$
    Now given a small stable $\Dcal$, instantiating the above statement with $\Ecal=\Ind(\Dcal)$, we get that
    $$
        \begin{tikzcd}
            \alpha^*:\FunEx(\Ccal, \Dcal)\arrow[r] & \Fun(B\End_\Ccal(G), \Dcal)
        \end{tikzcd}
    $$
    is fully-faithful. But note that given $f:B\End_\Ccal(G)\to\Dcal$, for every $X\in\Ccal$ such that $X\simeq\colim_I G$ with $I$ finite, the unique extension $\overline{f}:B\End_\Ccal(G)\to\Ind(\Dcal)$ must satisfy
    $$
        \overline{f}(X)\simeq\colim_{I}f(G)
    $$
    hence $\overline{f}(X)\in\Ccal$. Since every object of $\Ccal$ is a retract of such an $X$ and $\Dcal$ is idempotent-complete, we get that $\overline{f}:\Ccal\to\Dcal$, which concludes.
\end{proof}

\begin{rmq}
    Note that the above proof also shows that if $\Ccal$ is generated by finite colimits by $G$ without needing retracts, then the idempotent-completeness is not necessary for $\Dcal$.
\end{rmq}

\begin{prop} \label{MapOfKernelsIsSplit}
    Let $F:B\Z\to\CatP$ be a functor valued in idempotent-complete categories. Then, the functor
    $$
        \begin{tikzcd}
            \Psi:\ker(\Phi^{\mathrm{p}}_{F\mid_{\TwAr(\Delta^1)}})\arrow[r] & \ker(\Phi^{\mathrm{p}}_{F})
        \end{tikzcd}
    $$ 
    is in the image of the functor $\Hyp:\CatEx\to\CatP$. Moreover, it admits a retraction $\Psi_r$ which is also in the image of $\Hyp$.
\end{prop}
\begin{proof}
    Both the source and the target of $\Psi$ are hyperbolic by respectively Proposition \ref{KernelHyperbolic} and Lemma \ref{KernelMetabolicCubes} for $n=1$. For the latter, we note the Lemma only proves metabolicity but it is clear that $\Lcal$ and $D_\Qoppa(\Lcal)$ are fully orthogonal so that the category is in fact hyperbolic.

    To check that the functor is in the image of $\Hyp$, it suffices to show that it sends the canonical Lagrangian of the hyperbolic category to the Lagrangian of the target (here, the canonical Lagrangian of $\Hyp(\Ccal)$ is none other $\Ccal$ and we are simply saying that $\Hyp(\Ccal)\to\Hyp(\Dcal)$ is of the form $\Hyp(f)$ if and only if it sends $\Ccal$ to $\Dcal$). 

    Write $\gamma_+$ and $\gamma_-$ for the two arrows of $\TwAr(\Delta^1)$ such that the former is mapped to $\alpha^+$ and the latter to $\alpha_-$ by $\TwAr(\Delta^1)\to\Ical$. We claim that is that $z^{\gamma^+}_x$ in the notation of Lemma \ref{KernelMetabolicCubes} is sent to $z^+_x$ in the notation of Proposition \ref{KernelHyperbolic}; this can be checked directly by inspecting the respective formulas for both sections. \\

    Furthermore, the induced functor
    $$
        \Psi(-):\Map(z^{\alpha^+}_x, z^{\alpha^+}_x)\longrightarrow\Map(z^+_x, z^+_x)
    $$
    has a retraction. This is because the right hand side is the space of squares
    $$
        \begin{tikzcd}
            X\arrow[d, "f"] &\arrow[l, "\can"] F(\alpha^-)(X)\arrow[d, "g"] && X\arrow[d, "f"] &\arrow[l, "0"] F(\alpha^-)(X)\arrow[d, "g"]\\
            X &\arrow[l, "\can"] F(\alpha^-)(X) && X &\arrow[l, "0"] F(\alpha^-)(X)
        \end{tikzcd}
    $$
    whereas the left hand side only has the left square as part of the datum. 

    The datum of a right hand square can equivalently be described as the datum of a map $\Sigma F(\alpha^-)(X)\to X$. Under this description, the functor $\Psi(-)$ sends the zero map $0:\Sigma F(\alpha^-)(X)\to X$ and consequently, it has a retraction given by forgetting this extra map. Since each Lagrangian is generated by one object, namely $z^{\alpha^+}_x$ and $z^+_x$, it follows from Lemma \ref{MapsFromStableCatGeneratedByOneElement} that this restriction extends to the whole Lagrangians, since both kernels are idempotent-complete by hypothesis on $F$ and Lemma \ref{IdempotentCompleteStabUn} After applying $\Hyp$, this provides the wanted retraction $\Psi_r$ to $\Psi$. 
\end{proof}

\begin{rmq}
    Note that this retraction is not compatible with the exact sequence of diagram \eqref{eq-ComparisonReducesToKernels}: it is clear that the composite
    $$
        \begin{tikzcd}
            \ker(\Phi^{\mathrm{p}}_{F})\arrow[r, "\Psi_r"] & \ker(\Phi^{\mathrm{p}}_{F\mid_{\TwAr(\Delta^1)}})\arrow[r] & \UnH(F\mid_{\Ical}) 
        \end{tikzcd}
    $$ 
    is not fully-faithful and therefore cannot coincide with the inclusion of the kernel of $\Phi^{\mathrm{p}}_{F}$.
\end{rmq}

\begin{defi}
    Let $F:B\Z\to\CatP$ be a functor. We let $NE^{\hyp}(F)$ be the following (split)-cofiber:
    $$
        NE^{\hyp}(F):=\Sigma \cofib(E(\Psi))
    $$ 
    The shift appears for cosmetic reasons.
\end{defi}

Since $\Psi$ is a map in the image of $\Hyp$, $NE^{\hyp}(F)$ only depends on $E^{\hyp}$, the hyperbolisation of $E$. In particular, it vanishes for all bordism-invariant $E$. Note also that $NE^{\hyp}(F)$ does not coincide with $\Sigma E(\coker(\Psi))$; in fact, it is straightforward to check that $\coker(\Psi)\simeq 0$ as this holds before applying $\Hyp$.

Finally, we check that notwithstanding the previous remark, the retraction $\Psi_r$ does becomes compatible with diagram \eqref{eq-ComparisonReducesToKernels} after applying any Poincaré-Verdier localizing invariant. Because figuring carefully what happens in the general is painful, we reduce the problem the stable case, where it has already been treated by Kirstein--Kremer in \cite{KirsteinKremer}.

\begin{lmm}
    Let $E:\CatP\to\Ecal$ be a Poincaré-Verdier localizing invariant and $F:B\Z\to\CatP$. Then, the composite
    $$
        \begin{tikzcd}
            \Omega NE^{\hyp}(F)\arrow[r] & E(\ker(\Phi^{\mathrm{p}}_{F}))\arrow[r] & E(\UnP(F\mid_{\Ical}))
        \end{tikzcd}
    $$
    is null. In consequence, the splitting of Proposition \ref{MapOfKernelsIsSplit} is compatible with the maps in diagram \eqref{eq-ComparisonReducesToKernels}.
\end{lmm}
\begin{proof}
    Since $\ker(\Phi^{\mathrm{p}}_{F})$ is hyperbolic, the second map factors through $E^{\hyp}(\StabUn(F\mid_{\Ical}))$ and it is sufficient to check that this composite vanishes. But now, we are in a purely stable situation and it suffices to prove the vanishing of
    $$
        \begin{tikzcd}
            \Omega NG(F)\arrow[r] & G(\Lcal)\arrow[r] & G(\StabUn(F\mid_{\Ical}))
        \end{tikzcd}
    $$
    where $\Lcal$ is such that $\Hyp(\Lcal)\simeq\ker(\Phi^{\mathrm{p}}_{F})$ and $\Omega NG$ is now the split-cokernel of the map which gives the map of Proposition \ref{MapOfKernelsIsSplit} after applying $\Hyp$. This second vanishing holds more generally than for $G:=E^{\hyp}$. Indeed, in Theorem 3.15 of \cite{KirsteinKremer} and more precisely in its proof, this map is identified with
    $$
        \begin{tikzcd}[cramped]
            \Omega NG_{\alpha}(\Ccal)\oplus \Omega NG_{\alpha}(\Ccal)\arrow[r] &[-1em] \Omega NG_{\alpha}(\Ccal)\oplus \Omega NG_{\alpha}(\Ccal)\oplus G(\Ccal)\oplus G(\Ccal)\arrow[r, "{0\oplus 0\oplus(\id,\id)\oplus(\alpha,\id)}"] &[5em] G(\Ccal)\oplus G(\Ccal)
        \end{tikzcd}
    $$
    where $NG_{\alpha}(\Ccal)$ is the nilterm of $\Ccal:=F(*)$ under $G$ twisted by the action of $\alpha:=F(1)$. In particular, this map is $\cyclicGrp{2}$-equivariant under the action that flips the copies of the nilterms and flips the copies of $(E^{\hyp})(F(*))$, which is precisely the action induced from the duality. Therefore, the map is still null after taking homotopy orbits.
\end{proof}

Assembling all of our results, we have therefore proven the following result:

\begin{thm}[Twisted Shaneson splitting --- Verdier-localizing case] \label{TSSVerdierLoc}
    Let $F:B\Z\to\CatP$ be an idempotent-complete Poincaré category with $\Z$-action, and $E:\CatP\to\Ecal$ a Poincaré--Verdier localizing invariant. Then, the the assembly map of $E$ fits in a split-exact sequence
    $$
        \begin{tikzcd}[cramped]
            \colim\limits_{B\Z}E\circ F\arrow[r] & E(\colim\limits_{B\Z} F)\arrow[l, bend right=25, dotted]\arrow[r] & NE^{\hyp}(F)
        \end{tikzcd}
    $$
    Moreover, $NE^{\hyp}(F)$ vanishes if $E$ is bordism-invariant.
\end{thm}
\begin{proof}
    Using diagram \eqref{eq-ComparisonReducesToKernels}, we see that the cokernel of the assembly map for $E$ is exactly the once-shifted of the cokernel of $E(\Psi)$, which we have denote $NE^{\hyp}(F)$. Moreover, the assembly itself is the cokernel of maps with compatible retractions, therefore admits a retraction itself.
\end{proof}

Since Poincaré-Karoubi localizing invariants are invariant under idempotent-completion, we also have:

\begin{cor}[Twisted Shaneson splitting] \label{TSSKaroubiLoc}
    Let $F:B\Z\to\CatP$ be a Poincaré category with $\Z$-action and $E:\CatP\to\Ecal$ a Poincaré-Karoubi localizing invariant. Then, the the assembly map of $E$ fits in a split-exact sequence
    $$
        \begin{tikzcd}
            \colim\limits_{B\Z}E\circ F\arrow[r] & E(\colim\limits_{B\Z} F)\arrow[l, bend right=25, dotted]\arrow[r] & NE^{\hyp}(F)
        \end{tikzcd}
    $$
    Moreover, $NE^{\hyp}(F)$ vanishes if $E$ is bordism-invariant.
\end{cor}

