\section{Code for ODEs Methods and Monte-Carlo Simulation}

This appendix provides the full Python source code used in the project for deterministic and stochastic enzyme kinetics modeling.

\subsection{Deterministic vs. Stochastic Enzyme Kinetics}

\begin{lstlisting}[language=Python, caption={Deterministic vs. Stochastic Enzyme Kinetics Code}]
import numpy as np
import matplotlib.pyplot as plt
from scipy.integrate import odeint

# Deterministic ODE method
def enzyme_odes(y, t, k1, k_1, k2, E0):
    E, S, ES, P = y
    dEdt  = -k1*E*S + k_1*ES + k2*ES
    dSdt  = -k1*E*S + k_1*ES
    dESdt =  k1*E*S - (k_1 + k2)*ES
    dPdt  =  k2*ES
    return [dEdt, dSdt, dESdt, dPdt]

def gillespie_enzyme(k1, k_1, k2, E0, S0, tmax):
    t = 0.0
    nE  = E0
    nS  = S0
    nES = 0
    nP  = 0
    times, E_vals, S_vals, ES_vals, P_vals = [t], [nE], [nS], [nES], [nP]

    while t < tmax:
        a1 = k1 * nE * nS   
        a2 = k_1 * nES      
        a3 = k2 * nES       
        a0 = a1 + a2 + a3
        if a0 <= 0: break

        tau = -np.log(np.random.rand()) / a0
        t += tau
        r = np.random.rand()
        if r < a1/a0:
            nE, nS, nES = nE - 1, nS - 1, nES + 1
        elif r < (a1 + a2)/a0:
            nE, nS, nES = nE + 1, nS + 1, nES - 1
        else:
            nE, nP, nES = nE + 1, nP + 1, nES - 1

        times.append(t)
        E_vals.append(nE)
        S_vals.append(nS)
        ES_vals.append(nES)
        P_vals.append(nP)
        if nS == 0 and nES == 0: break

    return np.array(times), np.array(E_vals), np.array(S_vals), np.array(ES_vals), np.array(P_vals)

# Parameters
k1, k_1, k2 = 0.1, 0.05, 0.05
E0, S0 = 10, 100
y0 = [E0, S0, 0, 0]
tmax = 200
t_points = np.linspace(0, tmax, 2001)
sol = odeint(enzyme_odes, y0, t_points, args=(k1, k_1, k2, E0))
E_det, S_det, ES_det, P_det = sol[:,0], sol[:,1], sol[:,2], sol[:,3]

# Stochastic Simulations
N_runs = 500  
t_grid = np.linspace(0, tmax, 2001)
S_runs, P_runs = np.zeros((N_runs, len(t_grid))), np.zeros((N_runs, len(t_grid)))

for i in range(N_runs):
    t_arr, E_arr, S_arr, ES_arr, P_arr = gillespie_enzyme(k1, k_1, k2, E0, S0, tmax)
    S_runs[i, :] = np.interp(t_grid, t_arr, S_arr)
    P_runs[i, :] = np.interp(t_grid, t_arr, P_arr)

S_mean, P_mean = np.mean(S_runs, axis=0), np.mean(P_runs, axis=0)
S_std, P_std = np.std(S_runs, axis=0), np.std(P_runs, axis=0)

# Plot
fig, ax = plt.subplots(figsize=(7,5))
ax.set_title("Deterministic vs. Stochastic Enzyme Kinetics")
ax.plot(t_points, S_det, label="Deterministic [S]", lw=2)
ax.plot(t_points, P_det, label="Deterministic [P]", lw=2)
ax.plot(t_grid, S_mean, '--', label="Stochastic avg S", lw=2)
ax.plot(t_grid, P_mean, '--', label="Stochastic avg P", lw=2)
ax.fill_between(t_grid, S_mean-S_std, S_mean+S_std, alpha=0.2)
ax.fill_between(t_grid, P_mean-P_std, P_mean+P_std, alpha=0.2)
ax.set_xlabel("Time")
ax.set_ylabel("Molecule Count")
ax.set_xlim(0, tmax)
ax.legend(loc="best")
plt.tight_layout()
plt.show()
\end{lstlisting}

\subsection{Positive Feedback Model}

\begin{lstlisting}[language=Python, caption={Stochastic Positive Feedback Model}]
def gillespie_positive_feedback(alpha0, alpha, K, n, gamma, X0=10, tmax=2000):
    t, X = 0.0, X0
    t_arr, X_arr = [t], [X]

    while t < tmax:
        prod_rate = alpha0 + alpha * (X**n / (K**n + X**n))  
        degr_rate = gamma * X                                
        a0 = prod_rate + degr_rate
        if a0 <= 0: break

        tau = -np.log(np.random.rand()) / a0
        t += tau
        r = np.random.rand()
        X += 1 if r < prod_rate / a0 else -1 if X > 0 else 0

        t_arr.append(t)
        X_arr.append(X)

    return np.array(t_arr), np.array(X_arr)

# Example Parameters
alpha0, alpha, K, n, gamma, X0, tmax = 5.0, 150.0, 20.0, 4, 1.0, 10, 2000
t_arr, X_arr = gillespie_positive_feedback(alpha0, alpha, K, n, gamma, X0, tmax)

# Plot
plt.figure(figsize=(8,4))
plt.plot(t_arr, X_arr, lw=1.5, color='blue')
plt.title("Stochastic Positive-Feedback Model: Random Switching")
plt.xlabel("Time")
plt.ylabel("X (copy number)")
plt.grid(True)
plt.tight_layout()
plt.show()
\end{lstlisting}

