	\title[Approximation of Dirac operators with $\delta$-shell potentials]{Approximation of Dirac operators with $\boldsymbol{\delta}$-shell potentials in the norm resolvent sense, II.~Quantitative results}



	\author[J. Behrndt]{Jussi Behrndt}
