	\begin{abstract}
		This paper is devoted to the approximation of two and three-dimensional Dirac operators $H_{\widetilde{V} \delta_\Sigma}$ with combinations of electrostatic and Lorentz scalar $\delta$-shell interactions in the norm resolvent sense. Relying on results from \cite{BHS23} an explicit smallness condition on the coupling parameters is derived so that $H_{\widetilde{V} \delta_\Sigma}$ is the limit of Dirac operators with scaled electrostatic and Lorentz scalar potentials. Via counterexamples it is shown that this condition is sharp. The approximation of $H_{\widetilde{V} \delta_\Sigma}$ for larger coupling constants is achieved by adding an additional scaled magnetic term.
	\end{abstract}

	\section{Introduction}
	Dirac operators  describe relativistic spin 1/2 particles in a quantum mechanical framework \cite{T92} and they play an important role in the mathematical description of graphene \cite{AB08, NGM04}. In order to model interactions  that are supported in a small neighbourhood of a curve in $\R^2$ or a surface in $\R^3$ Dirac operators with $\delta$-shell potentials are used. These operators  have been studied  intensively in the recent years, see for instance \cite{AMV14, AMV15, BEHL18, BEHL19, BHOP20, BHSS22, BHT23, Ben21, BP24, CLMT21,R22a}, and  are formally given by 
	\begin{equation}\label{eq_H_V_tilde_formal}
			H_{\widetilde{V} \delta_\Sigma} =
			-i(\alpha \cdot \nabla) 
			+ m \beta + \widetilde{V} \delta_\Sigma,
	\end{equation}
	where  $\alpha \cdot \nabla ,\beta$ are as in Section~\ref{sec_not}~\eqref{it_Dirac_matrices},
	$m \in \R$ is the mass of the underlying particle,  $\delta_\Sigma$ is the $\delta$-distribution supported on a $C^2$-smooth curve $\Sigma$ in $\R^2$ or surface in $\R^3$, and $\widetilde{V}$ is a symmetric matrix-valued function which models the  interaction on $\Sigma$. 

	The main objective of the present paper -- which is a continuation of our investigations in \cite{BHS23} -- is the approximation  of $H_{\widetilde{V} \delta_\Sigma}$ by Dirac operators with strongly localized potentials;
    here we complement the qualitative analysis in \cite{BHS23} with sharp quantitative results.
	We also refer the reader to \cite{BHS23} for a detailed introduction, overview and references on the topic.  The approximation of $H_{\widetilde{V} \delta_\Sigma}$ serves to justify the viewpoint that the expression in \eqref{eq_H_V_tilde_formal} is an idealized replacement for more realistic Dirac operators describing strongly localized interactions and was first considered in one dimension in \cite{S89}, see also \cite{HT22,HT23,Hu95,H97,H99,T20}. Furthermore, in the multidimensional setting strong resolvent convergence was shown in \cite{BHT23,CLMT21,MP18,Z23} under various assumptions on $\widetilde{V}$ and $\Sigma$. Finally, in our recent paper \cite{BHS23} it was shown that $H_{\widetilde{V} \delta_\Sigma}$ can be approximated in the norm resolvent sense, if the matrix 
	function $\widetilde{V}$ 
	satisfies an implicit smallness condition. In the present paper we replace this implicit condition by an  explicit and sharp condition for a specific class of interaction matrices, namely those that model electrostatic and Lorentz scalar interactions, see~\eqref{eq_V} and~\eqref{eq_scaling} below. 


	Let us recall the problem setting and the main result from \cite{BHS23}. The space dimension is denoted by $\theta \in \{ 2, 3 \}$ and we set $N=2$ for $\theta = 2$ and $N=4$ for $\theta = 3$. Assume that $\Sigma$ is the boundary of a $C^2$-domain  $\Omega_+ \subset \R^{\theta}$ as in Section~\ref{sec_not}~\eqref{it_def_Sigma} and that $\nu$ is the unit normal vector field on $\Sigma$ which points outwards of $\Omega_+$. Note that $\Omega_+$ can be any bounded $C^2$-domain, but also a wide class of unbounded domains is allowed in our assumptions. Then, define 
	\begin{equation}\label{eq_iota}
		\iota: \Sigma \times \R \to \R^\theta, \quad \iota(x_\Sigma,t):= x_\Sigma + t \nu(x_\Sigma), \quad (x_\Sigma,t) \in \Sigma \times \R,
	\end{equation}
	 and for  $\varepsilon \in (0,\infty)$  set $\Omega_\varepsilon := \iota(\Sigma \times (-\varepsilon,\varepsilon))$, which is the so-called \textit{tubular neighbourhood} of $\Sigma$. It follows from the assumptions on $\Sigma$ that one can fix an $\varepsilon_1>0$  such that   $\iota|_{ \Sigma \times (-\varepsilon_1,\varepsilon_1)}$ is injective; cf.  \cite[Proposition~2.4]{BHS23}. Next, we fix a
	 symmetric matrix-valued function
	\begin{equation}\label{eq_q1}
		V = V^*\in W^1_\infty(\Sigma;\C^{N \times N}),
		\end{equation}
		where $W^1_\infty$ is the $L^\infty$-based Sobolev space of once weakly differentiable functions, and 
		\begin{equation}\label{eq_q2}
	q \in L^{\infty}((-1,1);[0,\infty))  \,\,\text{ such that }\,\,   \int_{-1}^{1} q(s)  \, ds = 1,
	\end{equation}
	and we introduce for $\varepsilon \in (0,\varepsilon_1)$ the strongly localized potentials
	\begin{equation}\label{eq_V_eps}
		V_\varepsilon(x) := 
		\begin{cases}
			\frac{1}{\varepsilon}V(x_\Sigma)q\left(\frac{t}{\varepsilon}\right),& \text{if } x = \iota(x_\Sigma,t) \in \Omega_\varepsilon,\\
			0,& \text{if } x \notin \Omega_\varepsilon.
		\end{cases}
	\end{equation} 
	For $m \in \R$ and $\varepsilon \in (0, \varepsilon_1)$ consider the operator
	\begin{equation}\label{eq_H_V_eps}
		\begin{split}\
			H_{V_\varepsilon} u &:= -i(\alpha \cdot \nabla) u + m \beta u + V_\varepsilon  u, \quad  \dom H_{V_\varepsilon} :=  H^1(\R^\theta;\C^N),
		\end{split}
	\end{equation}
	where $H^k$ denotes the $L^2$-based Sobolev space of $k$-times weakly differentiable functions.
	Note that $ H_{V_\varepsilon} = H + V_\varepsilon$ is self-adjoint in $L^2(\mathbb{R}^\theta; \mathbb{C}^N)$ as $V_\varepsilon \in L^\infty(\mathbb{R}^\theta; \mathbb{C}^{N \times N})$ is symmetric and bounded, and the free Dirac operator $H=-i(\alpha \cdot \nabla)  + m \beta $ is self-adjoint 
	in $L^2(\mathbb{R}^\theta; \mathbb{C}^N)$; cf. Section~\ref{sec_free_Dirac}.	

	Next, the rigorous mathematical definition of $H_{\widetilde{V}\delta_\Sigma}$ as an operator in $L^2(\mathbb{R}^\theta; \mathbb{C}^N)$ is recalled. We
	set $\Omega_- = \R^{\theta} \setminus \overline{\Omega_+}$, write $u_\pm := u|_{\Omega_\pm}$ 
	for
	$u: \mathbb{R}^\theta \rightarrow \mathbb{C}^N$, and the Dirichlet trace operator is denoted by $\mathbf{t}_\Sigma^\pm: H^1(\Omega_\pm; \mathbb{C}^N) \rightarrow H^{1/2}(\Sigma; \mathbb{C}^N)$.
Then, for $\widetilde{V} = \widetilde{V}^* \in L^\infty(\Sigma;\C^{N \times N})$ the differential operator $H_{\widetilde{V} \delta_\Sigma}$  in $L^2(\mathbb{R}^\theta; \mathbb{C}^N)$  is defined by 
\begin{equation}\label{eq_def_H_V_tilde}
	\begin{split}
		H_{\widetilde{V}\delta_\Sigma}u & := (-i(\alpha \cdot \nabla) + m \beta) u_+ \oplus (-i(\alpha \cdot \nabla ) + m \beta) u_-, \\
		\dom H_{\widetilde{V}\delta_\Sigma}&:= \biggl\{ u \in H^1 (\Omega_+;\C^N) \oplus H^1(\Omega_-; \mathbb{C}^N): \\
		& \quad \qquad i(\alpha \cdot \nu )(\tr^+ u_+  - \tr^- u_-) +  \frac{\widetilde{V}}{2}(\tr^+ u_+  + \tr^- u_-) =0 \biggr\}.
	\end{split}
\end{equation}
	Eventually, the application of $\cos(x)$ and $\textup{sinc}(x) = \frac{1}{x} \sin(x)$ to matrices is understood via power series.
	Now, we are ready to recall the main result from \cite{BHS23} in a compressed  form; note that $H_{V_\varepsilon}$ and $H_{\widetilde{V} \delta_\Sigma}$ are denoted  in  \cite{BHS23} by $H_\varepsilon$ and $H_{\widetilde{V}}$, respectively.


	\begin{theo}[{\cite[Theorem~1.1]{BHS23}}]\label{THEO_MAIN}
		Let  $V$ and $q$ be as in \eqref{eq_q1}--\eqref{eq_q2}. Furthermore, assume that
		\begin{equation}\label{cond234}
			\cos\bigl(\tfrac{1}{2}(\alpha \cdot \nu)V\bigr)^{-1} \in W^1_\infty(\Sigma;\C^{N\times N})
		\end{equation}
		and set $\widetilde V =  V \textup{sinc}\bigl(\tfrac{1}{2}(\alpha \cdot \nu)V\bigr)	\cos\bigl(\tfrac{1}{2}(\alpha \cdot \nu)V\bigr)^{-1}$. If
		 \begin{equation*}
			\norm{V}_{W^1_\infty(\Sigma;\C^{N\times N})}   \norm{q}_{L^\infty(\R)} 
		\end{equation*}
		is sufficiently small, 	then 	$H_{\widetilde{V}\delta_\Sigma}$  is self-adjoint in $L^2(\R^{\theta};\C^N)$ and $H_{V_\varepsilon}$ converges to $H_{\widetilde{V}\delta_\Sigma}$ in the norm resolvent sense as $\varepsilon \to 0$. 
	\end{theo}

	Similar to previous approximation results a nonlinear rescaling of $V$ to $\widetilde{V}$ is observed in the limit, which is often related to Klein's paradox; cf. \cite{CLMT21,MP18,S89}.

	A direct application of Theorem~\ref{THEO_MAIN} to check the convergence of $H_{V_\varepsilon}$ is difficult, since it contains a nonexplicit smallness assumption on $V$. 
	The main motivation  in the present paper is to make this smallness condition explicit, if $V$ is of the specific form
	\begin{equation}\label{eq_V}
			V = \eta I_N + \tau \beta,\qquad \eta,\tau \in C^1_b(\Sigma;\R);
	\end{equation}
	here $C^1_b(\Sigma;\R)$ is the space of continuously differentiable functions with bounded derivatives 
	(see Section~\ref{sec_not}~\eqref{gehtdas}).
	In fact, such potentials are of particular physical interest since  $\eta I_N$ and $\tau \beta$ model electrostatic and Lorentz scalar interactions, respectively, and they are, in the context of $\delta$-shell potentials, studied in \cite{AMV14, AMV15,BEHL19,BHOP20,BHSS22,Ben21, BP24, R22a}. 
	Moreover, for $V$ as in~\eqref{eq_V} the condition \eqref{cond234} and the rescaling $V \mapsto \widetilde{V}$ simplify substantially, as then the anti-commutation rules for the Dirac matrices yield $((\alpha \cdot \nu) V)^2 = d I_N$, with $d = \eta^2 - \tau^2$, and thus,  the power series representations of $\cos$ and $\textup{sinc}$ lead
	to
	\begin{equation*}
		\cos\bigl(\tfrac{1}{2}(\alpha \cdot \nu)V\bigr) = \cos\bigl(\tfrac{\sqrt{d}}{2}\bigr) I_N \quad \textup{and} \quad \textup{sinc}\bigl(\tfrac{1}{2}(\alpha \cdot \nu)V\bigr) = \textup{sinc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) I_N.
	\end{equation*}
	Hence, \eqref{cond234} simplifies to
	\begin{equation}\label{eq_scaling_cond}
		\inf_{x_\Sigma \in \Sigma, k \in \N_0} \abs{d(x_\Sigma)- (2k+1)^2 \pi^2} >0
	\end{equation}
	and we have
	\begin{equation}\label{eq_scaling}
		\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta, \qquad (\widetilde{\eta},\widetilde{\tau}) = \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr)(\eta,\tau),
	\end{equation}
	where $\textup{tanc}(x) = \frac{\textup{tan}(x)}{x}$, see also Section~\ref{sec_not}~\eqref{it_tanc}.  Moreover, in the present situation $H_{\widetilde{V}\delta_\Sigma}$ is self-adjoint in $L^2(\R^\theta;\C^N)$ if 
	\begin{equation}\label{eq_d_tilde_non_crit}
		\inf_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)-4| > 0, \qquad  \widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2,
	\end{equation}
	see  \cite[Section~6]{R22a}, which is called the \textit{noncritical} case. 


In the main result of this paper, Theorem~\ref{theo_main_1}, we prove that if $V$ is chosen as in \eqref{eq_V}, then the  explicit smallness condition 
\begin{equation}\label{eq_d_cond_int}
	\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4}, \qquad d = \eta^2 - \tau^2,
\end{equation}
already guarantees norm resolvent convergence of $H_{V_\varepsilon}$ to $H_{\widetilde{V} \delta_\Sigma}$. 
Note that~\eqref{eq_d_cond_int} via \eqref{eq_scaling} implies 
\begin{equation}\label{supjussi}
\sup_{x_\Sigma \in \Sigma}\vert \widetilde{d}(x_\Sigma)\vert <4
\end{equation}
and hence
\eqref{eq_d_tilde_non_crit} is satisfied. This is already a first indication that it is not possible to relax the condition~\eqref{eq_d_cond_int}, as otherwise Dirac operators with critical $\delta$-shell potentials could be approximated, which have very different spectral properties as in the noncritical case.
However, to approximate $H_{\widetilde{V}\delta_\Sigma}$ also for $\widetilde{V}$ with 
\begin{equation}\label{infjussi}
\inf_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| > 4
\end{equation}
we make use of a well-known unitary transformation.
Its approximation  
results, in a similar way as it was also described in \cite[Section~8]{CLMT21}, in an additional strongly localized magnetic potential $V_{m,\varepsilon}$ that is added to  $H_{V_\varepsilon}$. In Theorem~\ref{theo_main_2} we then show that $H_{V_\varepsilon} + V_{m,\varepsilon}$  also converges in the norm resolvent sense to a Dirac operator with a combination of electrostatic and Lorentz scalar $\delta$-shell potentials, where the rescaling of $\eta$ and $\tau$ is different.
In fact, as a consequence of this result and Theorem~\ref{theo_main_1} we obtain Corollary~\ref{cor_main_1}, which states that every Dirac operator with a given $\delta$-shell potential $\widetilde{V} \delta_\Sigma$, $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta$, $\widetilde{\eta},\widetilde{\tau} \in C_b^1(\Sigma;\R)$, and $\widetilde{d} = \widetilde{\eta}^2 -\widetilde{\tau}^2$ fulfilling \eqref{supjussi} or \eqref{infjussi}
can  be approximated by a sequence of Dirac operators with strongly localized potentials in the norm resolvent sense.

In Section~\ref{sec_counter} we show that the condition \eqref{eq_d_cond_int} is sharp, i.e. that $H_{V_\varepsilon}$ does, in general, not converge to $H_{\widetilde{V} \delta_\Sigma}$, if \eqref{eq_d_cond_int} is not satisfied. To do so, we provide suitable counterexamples under the assumption $\eta,\tau \in \R$. In Theorem~\ref{theo_main_counter_critical} we consider the case $\widetilde{d} =4 $ for a compact surface $\Sigma \subset \R^\theta$ and in Theorem~\ref{theo_main_3} the situation $\widetilde{d} > 4$ for $\Sigma = \{0\} \times \R$. In both cases we are able to show that if \eqref{eq_d_cond_int} is not fulfilled, then norm resolvent convergence would yield contradictory spectral implications for the limit operator $H_{\widetilde{V}\delta_\Sigma}$.

Finally, let us describe the structure of the paper. We start by introducing various notations and conventions in Section~\ref{sec_not}. Then, in Section~\ref{sec_expl_cond} we prove the main results of this paper on the approximation of $H_{\widetilde{V} \delta_\Sigma}$ by Dirac operators with squeezed potentials in the norm resolvent sense, and we provide explicit conditions on the coefficients such that the associated convergence results hold. The proof of Theorem~\ref{theo_main_1}  relies on the same statement for the special case where $\Sigma$ is a rotated graph and the technically complicated long proof of this special case is outsourced to Section~\ref{sec_C^2_b_graphs}.   After Section~\ref{sec_expl_cond}, we complement in  Section~\ref{sec_counter} the results of Section~\ref{sec_expl_cond} by providing counterexamples which show that \eqref{eq_d_cond_int} is sharp.


\subsection{Notations and assumptions}\label{sec_not}
	\newcounter{not_list}
	In this section we introduce frequently used notations and assumptions.
	Let us start with a few general conventions.
	\begin{enumerate}[(i)]
		\item The letter $C>0$ always denotes a generic constant which may change in-between lines.
		\item The branch of the square root is fixed by $\text{Im}\, \sqrt{w} > 0$ for $w \in \C \setminus [0, \infty)$.
		\item \label{it_tanc} For $w\in \C \setminus \{k\pi + \tfrac{\pi}{2} : k \in \Z \}$ we define the function 	
		\begin{equation*}
			\textup{tanc}(w) :=
			\begin{cases}
				\tfrac{\tan(w)}{w}, &  w \in \C \setminus \big(\{0\} \cup \{ k\pi + \tfrac{\pi}{2} : k \in \Z \}\big),\\
				1, & w = 0.
			\end{cases}
		\end{equation*}
		For $ x \in \R \setminus \{ 0 \}$ the equation $\textup{tanc}(i x) = \frac{\tanh(x)}{x}$ is valid, which can be extended by continuity to $x=0$.
		\item The symbol $| \cdot|$ is used for the absolute value, the Euclidean vector norm, or the Frobenius norm of a number, vector, or matrix, respectively.
		We write $\langle \cdot, \cdot \rangle$ for the Euclidean scalar product  in $\C^n$, $n \in \N$, which is anti-linear in the second argument. 
		\item  Let $\mathcal{H}$ and $\mathcal{G}$ be Hilbert spaces and  $A$ be a linear operator from $\mathcal{H}$ to $\mathcal{G}$. The domain, kernel, and range of $A$ are denoted by $\dom A$, $\ker A$, and $\ran A$, respectively. If $A$ is bounded and everywhere defined, then we write $\| A \|_{\mathcal{H} \rightarrow \mathcal{G}}$ for its operator norm.  The expression $[\cdot,\cdot]$ denotes the commutator of two operators. If $\mathcal{H} = \mathcal{G}$ and $A$ is a closed operator, then the resolvent set,  the spectrum, and the point spectrum of $A$ are denoted by $\rho(A)$, $\sigma(A)$, and $\sigma_{\textup{p}}(A)$, respectively. In the case that $A$ is self-adjoint, we denote the essential and discrete spectrum of $A$ by $\sigma_{\textup{ess}}(A)$ and $\sigma_{\textup{disc}}(A)$, respectively.
		\setcounter{not_list}{\value{enumi}}
	\end{enumerate}
	Next, we fix the space dimension, introduce Dirac matrices and define related notations.
	\begin{enumerate}[(i)]
		\setcounter{enumi}{\value{not_list}}
		\item\label{it_Dirac_matrices} By $\theta \in \{ 2, 3 \}$ we denote the space dimension and we set $N=2$ for $\theta=2$ and $N=4$ for $\theta = 3$. 
		With the help of the  Pauli spin matrices
		\begin{equation*}
			\sigma_1 = \begin{pmatrix} 0 & 1\\ 1 & 0 \end{pmatrix}, \quad\sigma_2 = \begin{pmatrix} 0 & -i\\ i & 0 \end{pmatrix}, \quad \text{and} \quad \sigma_3 =\begin{pmatrix} 1 & 0\\ 0 & -1 \end{pmatrix}
		\end{equation*} 
		we define the Dirac matrices $\alpha_1, \dots, \alpha_\theta, \beta \in \mathbb{C}^{N \times N}$  for $\theta=2$ by
		\begin{equation} \label{def_Dirac_matrices_2d}
			\alpha_1 := \sigma_1, \quad \alpha_2 := \sigma_2, \quad \text{and} \quad \beta := \sigma_3,
		\end{equation}
		and  for $\theta = 3$ by
		\begin{equation} \label{def_Dirac_matrices_3d}
			\alpha_j := \begin{pmatrix} 0 &
				\sigma_j \\ \sigma_j & 0
			\end{pmatrix}\text{ for } j=1,2,3  \quad \text{and} \quad \beta := \begin{pmatrix}
				I_2 & 0 \\ 0 & -I_2
			\end{pmatrix},
		\end{equation}
		where $I_n$ is the $n \times n$-identity matrix, $n \in \mathbb{N}$. The Dirac matrices satisfy
		\begin{equation}\label{eq_dirac_matrices}
			\alpha_j \alpha_k + \alpha_k \alpha_j = 2 I_N \delta_{jk} \quad \text {and} \quad \alpha_j \beta + \beta \alpha_j=0 \quad j,k \in \{1,\dots,\theta\},
		\end{equation}
		where $\delta_{jk}$ denotes the Kronecker delta.
		Vectors in $\C^\theta$ are denoted by  $x = (x_1,\dots,x_\theta)$ and	we will often make use of the notations
		\begin{equation*}
			\alpha \cdot \nabla := \sum_{j = 1}^\theta \alpha_j \partial_j \quad \text{and} \quad \alpha \cdot x := \sum_{j = 1}^\theta \alpha_j x_j, \quad x = (x_1, \dots, x_\theta) \in \C^\theta.
		\end{equation*}
		Finally, we use the notation $x = (x',x_\theta)$ with $x' \in \C^{\theta-1}$ and $x_\theta \in \C$.
		\setcounter{not_list}{\value{enumi}}
	\end{enumerate}
	In the upcoming item we introduce a class of $C^2$-hypersurfaces which is convenient for the definition of trace and extension operators, as well as tubular neighbourhoods.
	\begin{enumerate}[(i)]
		\setcounter{enumi}{\value{not_list}}
		\item  \label{it_def_Sigma} We assume that $\Sigma$ is  the boundary of an open set $\Omega_+ \subset \R^{\theta}$ which satisfies the following: There exist open sets  $W_1, \dots ,W_p \subset \mathbb{R}^\theta$, mappings $\zeta_1,\dots,\zeta_p \in C^{2}_b(\R^{\theta-1}; \mathbb{R})$ (see \eqref{gehtdas} below), rotation matrices $\kappa_1, \dots ,\kappa_p \in \R^{\theta \times \theta}$, and $\varepsilon_0 >0$ such that
		\begin{itemize}
			\item[(i)] $\Sigma \subset \bigcup_{l=1}^p W_l$;
			\item[(ii)] if $x \in \partial \Omega_+ = \Sigma$, then there exists $l \in \{1, \dots ,p\}$ such that $B(x,\varepsilon_0) \subset W_l$;
			\item[(iii)] $W_l \cap \Omega_+
			= W_l \cap \Omega_l$, where $\Omega_l = \{ \kappa_l (x', x_\theta): x_\theta < \zeta_l(x'), \, (x',x_\theta) \in \R^\theta \}$, for $l \in \{1,\dots ,p\}$.
		\end{itemize}
		Furthermore, we set $\Sigma_l := \partial \Omega_l = \{ \kappa_l (x', \zeta_l(x')): x' \in \mathbb{R}^{\theta-1} \}$,  $\Omega_- := \R^\theta \setminus \overline{\Omega_+}$, and denote the unit normal vector field at $\Sigma$ that is pointing outwards of $\Omega_+$ by $\nu$. Moreover, for $u: \mathbb{R}^\theta \rightarrow \mathbb{C}^N$ we define $u_\pm := u|_{\Omega_\pm}$.
		\setcounter{not_list}{\value{enumi}}
	\end{enumerate}
	Now, we turn to the introduction of various function spaces.
	\begin{enumerate}[(i)]
		\setcounter{enumi}{\value{not_list}}
		\item\label{gehtdas} If $n \in \N$ and $U \subset \R^n$ is open, then  $H^r(U)$ and $W^r_\infty(U)$ denote the $L^2$ and $L^\infty$ based Sobolev spaces of order $r$, respectively; cf. \cite[Chaper~3]{M00}. Moreover, if $k \in \N \cup \{\infty\}$, then we write $C_b^k(U)$ for the space which contains all $f \in C^k(U)$ such that $f$ and all partial derivatives of $f$ up to order $k$ are bounded. Vector or matrix valued function spaces are defined in the natural way, i.e.  component-wise. Moreover, for function spaces with $\C^{n \times l}$-valued functions, $n,l \in \N$, we use the notations $H^r(U;\C^{n\times l})$, $W^r_\infty(U;\C^{n\times l})$, and $C_b^k(U;\C^{n \times l}).$


		\item The trace spaces $H^r(\Sigma)$, $r \in [-2,2]$,  $W^1_\infty(\Sigma)$, and $C^k_b(\Sigma)$, $k \in \{1,2\}$, are defined via local coordinates, a partition of unity and the corresponding function spaces on open sets; cf. \cite[Section~2]{BHS23}.
		Moreover, the well-defined and bounded Dirichlet trace operator is denoted by
		\begin{equation*}
			\tr^{\pm}:  H^r(\Omega_\pm) \to H^{r-1/2}(\Sigma)  \quad \textup{and} \quad  \tr : H^{r}(\R^{\theta}) \to H^{r-1/2}(\Sigma),
		\end{equation*}
		$r \in (\tfrac{1}{2},\tfrac{5}{2})$; cf. \cite[Theorem~2]{M87}, where we use for 
		$$u=u_+\oplus u_- \in H^r(\R^{\theta} \setminus \Sigma) = H^r(\Omega_+;\C^N) \oplus H^r(\Omega_-;\C^N)$$ 
		the shortened notation $\tr^\pm u$ for $\tr^\pm u_\pm$. Vector or matrix valued trace spaces and trace operators are defined  component-wise.


		\item\label{it_Bochner} For a Hilbert space $\mathcal{H}$ the usual $L^2((-1,1))$ based Bochner Lebesgue space of $\mathcal{H}$-valued
		functions is denoted by $L^2((-1,1);\mathcal{H})$; cf. \cite[Section~2.2]{BHS23}. In the case $\mathcal{H}=H^r(S;\C^N)$ with $S \in \{\Sigma,\R^{\theta-1}\}$, we write $\mathcal{B}^r(S)$  instead of $L^2((-1,1);H^r(S;\C^N))$, respectively. We also write
		$\norm{\cdot}_r$ for the norm in $\mathcal{B}^r(S)$. In a similar way, we define
		\begin{equation*}\begin{aligned} 
				\norm{\cdot}_{r \to r'} &:=\norm{\cdot}_{\mathcal{B}^r(S) \to \mathcal{B}^{r'}(S)},\\
				\norm{\cdot}_{r \to \mathcal{H}} &:= \norm{\cdot}_{\mathcal{B}^r(S) \to \mathcal{H}},\\
				\norm{\cdot}_{\mathcal{H} \to r'} &:= \norm{\cdot}_{\mathcal{H} \to \mathcal{B}^{r'}(S) }.
			\end{aligned}
		\end{equation*}
		We  will  use  the bounded embedding
		\begin{equation*}%\label{eq_def_embedding_op}
			\mathfrak{J}:H^r(S;\C^N) \to \mathcal{B}^{r}(S),\quad
			\mathfrak{J}\varphi(t) := \varphi,
		\end{equation*}
		and its adjoint
		\begin{equation*}
			\mathfrak{J}^* :\mathcal{B}^{r}(S) \to H^r(S;\C^N),\quad
			\mathfrak{J}^*f = \int_{-1}^1 f(t) \,dt.
		\end{equation*} 

		We also use the following convenient identification: Let
		$\mathcal{Q} \in L^\infty((-1,1))$ and  $\mathcal{A}$ be bounded operator in $H^r(S;\C^N)$, $r \in [-2,2]$. Then, we identify 
		\begin{equation*}
			\mathcal{M}_{\mathcal{Q}}: \mathcal{B}^r(S)\to \mathcal{B}^r(S),\quad \!\!
			(\mathcal{M}_{\mathcal{Q}}f)(t) := \mathcal{Q}(t) f(t), 
		\end{equation*}
		and 
		\begin{equation*}
			\mathcal{M}_{\mathcal{A}} : \mathcal{B}^r(S)\to \mathcal{B}^r(S) ,\quad
			(\mathcal{M}_{\mathcal{A}}f)(t) :=  \mathcal{A}(f(t)), 
		\end{equation*}
		with $\mathcal{Q}$ and $\mathcal{A}$, respectively. Note  that the norms  $\norm{\mathcal{M}_{\mathcal{Q}}}_{r \to r}$ and $\norm{\mathcal{M}_{\mathcal{A}}}_{r \to r}$ are equal  to $\norm{\mathcal{Q}}_{L^\infty((-1,1))}$ and $\norm{\mathcal{A}}_{H^r(S;\C^N)\to H^r(S;\C^N)}$, respectively. 
		\setcounter{not_list}{\value{enumi}}
	\end{enumerate}
	Finally, we fix notations and state simple properties regarding Fourier transforms.
	\begin{enumerate}[(i)]
		\setcounter{enumi}{\value{not_list}}
		\item \label{it_Fourier}  The expression $\mathcal{F}$ denotes the Fourier transform in $\R^{\theta-1}$. Moreover, $\mathcal{F}_1$ and $\mathcal{F}_2$ denote the partial Fourier transforms in $\R^{\theta}$  with respect to the first $\theta-1$ variables and the $\theta$-th variable, respectively. These transforms are given for $\psi \in \mathcal{S}(\R^{\theta-1})$ and $u \in  \mathcal{S}(\R^\theta)$ by
		\begin{equation*}%\label{def_fourier_trans}
			\begin{aligned}
				\hspace{23 pt}\mathcal{F}\psi(\xi') &= \frac{1}{\sqrt{(2\pi)^{\theta-1}}}\int_{\R^{\theta-1}} \psi(x') e^{-i\langle x',\xi'\rangle}dx',&& \xi' \in \R^{\theta-1},\\
				\mathcal{F}_1u(\xi) &= \frac{1}{\sqrt{(2\pi)^{\theta-1}}}\int_{\R^{\theta-1}} u(x',\xi_\theta) e^{-i\langle x',\xi'\rangle}dx',   && \xi=(\xi',\xi_{\theta}) \in \R^{\theta},\\
				\mathcal{F}_2u(\xi) &= \frac{1}{\sqrt{2\pi}}\int_{\R} u(\xi',x_\theta) e^{-i x_\theta \xi_\theta}dx_\theta, && \xi=(\xi',\xi_{\theta}) \in \R^{\theta},
			\end{aligned}
		\end{equation*}
		and can be uniquely extended 
		to bounded operators in $\mathcal{S}'(\R^{\theta-1})$  and $\mathcal{S}'(\R^{\theta})$, where $\mathcal{S}'$ denotes the space of tempered distributions; cf. \cite[Chapter IX]{RS75}. Moreover, the application of the Fourier transform to vector and matrix-valued functions or distributions  is defined component-wise. The (usual) Fourier transform in $\R^\theta$ with respect to all variables is given by $\mathcal{F}_{1,2} := \mathcal{F}_1 \mathcal{F}_2 = \mathcal{F}_2 \mathcal{F}_1$.
	\end{enumerate}



