	\section{Explicit conditions for the approximation of Dirac operators with $\delta$-shell potentials in the norm resolvent sense}\label{sec_expl_cond}


	 In the first main theorem of this paper we replace the nonexplicit smallness condition from Theorem~\ref{THEO_MAIN} by the simple and explicit condition \eqref{eq_d_cond} below. This condition will also turn out to be optimal later.

		\begin{theo}\label{theo_main_1}
		Let $q\in L^\infty((-1,1);[0,\infty))$ with $\int_{-1}^1 q(s) \,ds =1$ and assume that
		$\eta, \tau \in  C^1_b(\Sigma;\R)$ satisfy the condition 
		\begin{equation}\label{eq_d_cond}
		\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4}, \qquad d = \eta^2 - \tau^2.
	\end{equation}
		 Let $V$ and $V_\varepsilon$ be  as in \eqref{eq_V} and  \eqref{eq_V_eps}, and define $\widetilde V$ by \eqref{eq_scaling}.
			Then, for all $z \in \C\setminus\R$  and $r \in (0,\tfrac{1}{2} )$ there exist $C>0$ and $\varepsilon' \in (0,\varepsilon_1)$ such that 
		\begin{equation*} 
			\norm{(H_{V_\varepsilon}-z)^{-1} - (H_{\widetilde{V}\delta_\Sigma}-z)^{-1}}_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N)} \leq C \varepsilon^{1/2-r}, \quad  \varepsilon \in (0, \varepsilon').
		\end{equation*} 
		In particular, $H_{V_\varepsilon}$ converges to $H_{\widetilde{V}\delta_\Sigma}$ in the norm resolvent sense as $\varepsilon \to 0$. 
	\end{theo}


	The strategy to prove Theorem~\ref{theo_main_1} is to reduce it to the case where $\Sigma$ is a rotated $C^2_b$-graph, which is shown as a separate result in Section~\ref{sec_C^2_b_graphs}. The actual proof of Theorem~\ref{theo_main_1} makes use of three preparatory results, which relate the resolvents of $H_{\widetilde{V}\delta_\Sigma}$ and $H_{V_\varepsilon}$ to similar operators with potentials supported on the $C^2_b$-graphs $\Sigma_l$ and tubular neighbourhoods of $\Sigma_l$ (see \eqref{it_def_Sigma} in Section~\ref{sec_not}), respectively, via a suitable partition of unity.
	We also remark that the condition \eqref{eq_d_cond} implies 
	\begin{equation*}
		\sup_{x_\Sigma \in \Sigma} \widetilde d(x_\Sigma)= \sup_{x_\Sigma \in \Sigma} (\widetilde\eta^{\,2}(x_\Sigma) - \widetilde\tau^{\,2}(x_\Sigma))= \sup_{x_\Sigma \in \Sigma}4 \tan^2\biggl(\frac{\sqrt{d(x_\Sigma)}}{2}\biggr) < 4,
	\end{equation*} 
	so that $\widetilde V$ in \eqref{eq_scaling}
	is noncritical; cf. \eqref{eq_d_tilde_non_crit}.


    The first preparatory lemma  is a slight variation of \cite[Lemma~B.2]{BHS23} and allows us to construct a suitable partition of unity for $\Sigma$. 

	\begin{lemma}\label{lem_part_unity_phi_l} 
		Let $\Sigma \subset \mathbb{R}^\theta$, $\theta  \in \{ 2,3  \}$, be a set as described in Section~\ref{sec_not}~\eqref{it_def_Sigma}. Then, there exists a partition of unity $\varphi_1,\dots,\varphi_p \in C^\infty_b(\R^{\theta};\R)$  for $\Sigma$ subordinate to the open cover $W_1,\dots,W_p$ of $\Sigma$. This partition of unity can be chosen such that $\varphi_1,\dots,\varphi_{p}$ is also a partition of unity for $\Sigma + B(0,\delta)$ for some $\delta>0$ and $\supp \varphi_l + B(0,\delta) \subset W_l$ for all $l \in \{1,\dots,p\}$.
	\end{lemma}
	\begin{proof}
	According to \cite[Appendix A, Lemmas~1.2 and~1.3]{S92} there exists a sequence $(x_n)_{n \in \N} \subset \mathbb{R}^\theta$, $M \in \N$, $0<\delta < \frac{\varepsilon_0}{4}$, with $\varepsilon_0$ from Section~\ref{sec_not}~\eqref{it_def_Sigma}, and a sequence of real-valued $C^\infty$-functions $(\phi_n)_{n \in \N}$  such that  $(B(x_n,\delta))_{n \in \N}$ is an open cover of $\R^\theta$, $(\phi_n)_{n \in \N}$  is a partition of unity for $\mathbb{R}^\theta$, $\supp \phi_n \subset B(x_n,\delta)$ for all $n \in \N$, every point $x \in \R^\theta$ is contained in at most $M$ of the sets $B(x_n,\delta)$, and the derivatives (of any order) of the functions $\phi_n$ are uniformly bounded.  Next, we define the set 
	$$Y := \{ x_n: B(x_n,2\delta) \cap \Sigma \neq \emptyset \}.$$ 
	By construction, for all $x_n \notin Y$ one has $B(x_n,\delta) \cap (\Sigma + B(0,\delta)) = \emptyset$.
	Moreover, note that for all $x_n \in Y$ there exists an $l \in \{1,\dots, p\}$ such that $B(x_n,2\delta) \subset W_l $. In fact, as $B(x_n,2\delta) \cap \Sigma \neq \emptyset$, there exists  a $y_\Sigma \in B(x_n,2\delta) \cap \Sigma$ and thus item~\eqref{it_def_Sigma} in Section~\ref{sec_not} implies $B(y_\Sigma,\varepsilon_0) \subset W_l$ for an $l \in \{1,\dots,p\}$. Hence, for any $ y \in B(x_n,2\delta)$ one has
	\begin{equation*}
		\abs{y-y_\Sigma} \leq \abs{y -x_n} + \abs{x_n - y_\Sigma} < 4\delta < \varepsilon_0, 
	\end{equation*}
	which shows $B(x_n,2\delta) \subset W_l$. Define the sets 
	$$I_1 := \{ n: x_n \in Y, B(x_n, 2\delta) \subset W_1 \}$$ 
	and for $l \in \{ 2, \dots, p \}$
	$$I_l := \{ n: x_n \in Y, B(x_n, 2\delta) \subset W_l, B(x_n,2\delta) \not\subset  W_k, k \in \{1,\dots, l-1\} \}.$$ 
	Then, it is not difficult to see that
	\begin{equation*}
		\varphi_l = 
		\sum_{n \in I_l}\phi_n 
	\end{equation*}
	is a partition of unity having the claimed properties. Moreover, the construction of $\varphi_l$, $l \in \{1,\dots,p\}$, also implies $\supp \varphi_l + B(0,\delta) \subset W_l$.
	\end{proof}

In the following we use a partition of unity as in Lemma~\ref{lem_part_unity_phi_l} to connect Dirac operators with strongly localized potentials 
supported in $\Omega_\varepsilon$ with Dirac operators with strongly localized potentials supported in
the tubular neighbourhoods $\Omega_{\varepsilon,l}$ of the rotated $C^2_b$-graphs
\begin{equation*}
	\Sigma_l =  \{\kappa (x',\zeta_l(x')) : x'\in\R^{\theta-1} \},\qquad l \in \{1,\dots,p\};
\end{equation*}
cf. Section~\ref{sec_not}~\eqref{it_def_Sigma}. Note that  $V$ is only defined on $\Sigma$ and hence $V$ is a priori only defined on a subset of $\Sigma_l$. Thus, to be able to define a strongly localized potential $V_{\varepsilon,l}$ in $\Omega_{\varepsilon,l}$ in the same way as $V_\varepsilon$ in \eqref{eq_V_eps}, we first construct suitable extensions $V_l$ of $V$ to $\Sigma_l$. To do so, we choose  $\rho_\nu \in C^1(\R;\R)$ with $0\leq \rho_\nu \leq 1 $, $\rho_\nu(0) = 1$ and compact support in $(-\varepsilon_1, \varepsilon_1)$, where $\varepsilon_1$ is the number specified below \eqref{eq_iota}. Since $\Sigma$ is assumed to satisfy \eqref{it_def_Sigma} in Section~\ref{sec_not}, it is not difficult to show that for $ \omega \in \{V,\eta,\tau\}$ the function
\begin{equation}\label{eq_interaction_extensions}
	\omega_{\rm ext}(x) =
	\begin{cases}
		\omega(x_\Sigma)\rho_\nu(t), & \text{if } x = x_\Sigma + t \nu(x_\Sigma) \in \Omega_{\varepsilon_1} ,\\
		0,& \text{if } x \notin \Omega_{\varepsilon_1},
	\end{cases}
\end{equation}
is a  $C_b^1$-extension of $\omega$ to $\R^\theta$ which is supported in $\Omega_{\varepsilon_1}$. 
We then define the functions 
\begin{equation} \label{def_V_l}
  V_l:=V_{\rm ext}|_{\Sigma_l} \in C^1_b(\Sigma;\C^{N \times N}),\,\,\, \eta_l :=  \eta_{\rm ext} |_{\Sigma_l},\,\,\, \tau_l :=  \tau_{\rm ext}|_{\Sigma_l} \in C^1_b(\Sigma_l;\R),
\end{equation}
and note that $V_l=\eta_l I_N+\tau_l\beta$ for $l \in \{1,\dots,p\}$; cf. \eqref{eq_V}. Clearly, 
\begin{equation*}
	V_l|_{\Sigma_l \cap \Sigma} = V|_{\Sigma_l \cap \Sigma}.
\end{equation*}
Moreover, we mention  that  $d_l = \eta_l^2 - \tau_l^2$ satisfies by construction
\begin{equation}\label{eq_cond_d_l}
	\sup_{x_{\Sigma_l} \in \Sigma_l} d_l(x_{\Sigma_l}) < \frac{\pi^2}{4}, \qquad  l \in \{1,\dots,p\},
\end{equation}
as $d = \eta^2-\tau^2$ satisfies \eqref{eq_d_cond}.
With this extension at hand, we define $V_{\varepsilon,l}$ as $V_\varepsilon$ in \eqref{eq_V_eps} (with $\Sigma$ and $V$ replaced by $\Sigma_l$ and $V_l$)
and in the same way as $H_{V_\varepsilon} = H + V_\varepsilon$ in \eqref{eq_H_V_eps} we define
$$
H_{V_{\varepsilon,l}} = H+ V_{\varepsilon,l}, \quad  \dom H_{V_{\varepsilon,l}} :=  H^1(\R^\theta;\C^N),\qquad  l \in \{1,\dots,p\},
$$
where $H$ is the free Dirac operator (see \eqref{eq_def_free_Dirac}). Note that the operators $H_{V_{\varepsilon,l}}$ are self-adjoint in $L^2(\R^\theta;\C^N)$.

In the next lemma we express the resolvent of $H_{V_\varepsilon}$ in terms of the resolvents of $H_{V_{\varepsilon,l}}$. Here we fix  
the partition of unity $\varphi_1,\dots,\varphi_{p} \in C^\infty_b(\R^{\theta};\R)$ from Lemma~\ref{lem_part_unity_phi_l} and  we set $\varphi_{p+1} := 1-\sum_{l=1}^p \varphi_l$.



	\begin{lemma}\label{lem_H_V_eps_formula}
		Let the functions $V_\varepsilon, V_{\varepsilon,l}$ and the self-adjoint operators $H_{V_\varepsilon} = H + V_\varepsilon$, $H_{V_{\varepsilon,l}} = H+ V_{\varepsilon,l}$ for $l \in \{1,\dots,p\}$
		be as above, and set $H_{V_{\varepsilon,p+1}} := H$. Then, for $z \in \C$ such that $\abs{\textup{Im } z} > \sum_{l=1}^{p+1} \|\alpha \cdot\nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}$
		the operator  $$I +\sum_{l=1}^{p+1}  i(H_{V_{\varepsilon,l}}-z)^{-1} (\alpha \cdot \nabla \varphi_l) $$ is continuously invertible in $L^2(\R^{\theta};\C^N)$ and the resolvent formula
		\begin{equation*}%\label{eq_resolvent_formula_V_eps_l}
			(H_{V_\varepsilon}-z)^{-1} = \Bigg(I +\sum_{l=1}^{p+1}  i(H_{V_{\varepsilon,l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l)  \Bigg)^{-1}\Bigg(\sum_{l=1}^{p+1} (H_{V_{\varepsilon,l}}-z)^{-1}\varphi_l \Bigg)
		\end{equation*}
		is valid for all $\varepsilon \in (0,\min\{\varepsilon_1,\delta\})$, where $\varepsilon_1>0$ and $\delta>0$ are chosen as below \eqref{eq_iota} and  as in Lemma~\ref{lem_part_unity_phi_l}, respectively.
	\end{lemma}

	\begin{proof}
	Our first goal is to verify that for $\varphi_l \in C^\infty_b(\R^{\theta};\R)$ from the fixed partition of unity the identity 
	\begin{equation}\label{jadochbitte}
	 H_{V_\varepsilon} \varphi_l u=H_{V_{\varepsilon,l}} \varphi_l u,\qquad l \in \{1,\dots,p\},
	\end{equation}
holds for $u \in \dom H_{V_\varepsilon} = \dom H_{V_{\varepsilon,l}} = H^1(\R^{\theta};\C^N)$ and $\varepsilon \in (0,\min\{\delta,\varepsilon_1\})$. For this it suffices to show 
		 \begin{equation}\label{eq_V_eps_phi_l}
		 	V_\varepsilon(x)\varphi_l(x) = V_{\varepsilon,l}(x) \varphi_l(x), \qquad  x \in \R^{\theta}.
		 \end{equation}
	 	 In fact, it is obvious that $V_\varepsilon(x) \varphi_l(x) = V_{\varepsilon,l}(x) \varphi_l(x)$ for $x \notin \supp \varphi_l$. Next, consider $x \in \Omega_\varepsilon \cap \supp \varphi_l$. Then, there exists $(x_{\Sigma},t) \in  \Sigma\times(-\varepsilon,\varepsilon)$ such that $x = x_{\Sigma} + t \nu(x_{\Sigma})$. The inclusion $\supp \varphi_l + B(0,\delta) \subset W_l $ implies $x_\Sigma \in W_l \cap \Sigma$. Hence, by Section~\ref{sec_not}~\eqref{it_def_Sigma} $x_{\Sigma} \in \Sigma_l$ and therefore $x = x_\Sigma + \nu_l(x_\Sigma) \in \Omega_{\varepsilon,l}$, where $\nu_l$ is the unit normal vector field at $\Sigma_l$ which has the same orientation on $\Sigma_l \cap \Sigma$ as $\nu$. In turn, we have
		 \begin{equation*}
		 	V_{\varepsilon}(x) \varphi_l(x) = V(x_\Sigma) \frac{q\bigl(\tfrac{t}{\varepsilon})}{\varepsilon} \varphi_l(x) = V_l(x_\Sigma) \frac{q\bigl(\tfrac{t}{\varepsilon})}{\varepsilon} \varphi_l(x) = V_{\varepsilon,l}(x) \varphi_l(x).
		 \end{equation*}
	 	If $x \in \Omega_{\varepsilon,l} \cap \supp \varphi_l$ one shows \eqref{eq_V_eps_phi_l} in the same way. It remains to treat the case $ x \in \Omega_{\varepsilon}^c \cap \Omega_{\varepsilon,l}^c \cap \supp \varphi_l$. However, then both sides of \eqref{eq_V_eps_phi_l} are zero. Therefore, \eqref{eq_V_eps_phi_l}
	 	and hence  \eqref{jadochbitte} are true.



	Applying the product rule and using \eqref{jadochbitte} yields for $u \in \dom H_{V_\varepsilon} = \dom H_{V_{\varepsilon,l}}$, $l \in \{1,\dots,p\}$, and $\varepsilon \in (0,\min\{\delta,\varepsilon_1\})$
			\begin{equation}\label{eq_H_V_eps_2_H_V_eps_l}
			\varphi_l H_{V_\varepsilon}u = H_{V_\varepsilon} \varphi_l u+ i(\alpha \cdot\nabla \varphi_l) u = H_{V_{\varepsilon,l}}\varphi_l  u + i(\alpha \cdot\nabla \varphi_l)u.
		\end{equation}
		As $\varphi_1,\dots,\varphi_p$ also form a partition of unity for $\Sigma + B(0,\delta) \supset \Omega_\varepsilon$, $\varepsilon \in (0,\delta)$, we have $V_\varepsilon \varphi_{p+1} =0$ for all $\varepsilon \in (0,\min\{\varepsilon_1,\delta\})$. Hence, the product rule and the convention  $H = H_{V_{\varepsilon,p+1}}$ show that \eqref{eq_H_V_eps_2_H_V_eps_l} remains valid for $l = p+1$ and $\varepsilon \in (0,\min\{\varepsilon_1,\delta\})$. 
		For $z \in \C \setminus \R$ and $u \in \dom H_{V_\varepsilon} = H^1(\R^{\theta};\C^N)$ it follows from \eqref{eq_H_V_eps_2_H_V_eps_l} that
			\begin{equation}\label{eq_res_formular_V_eps_0}
			\begin{aligned}
				\Bigg(\sum_{l=1}^{p+1} &(H_{V_{\varepsilon,l}}-z)^{-1}\varphi_l\Bigg)(H_{V_\varepsilon}-z) u \\
				&= \sum_{l=1}^{p+1} \Big((H_{V_{\varepsilon,l}}-z)^{-1}(H_{V_{\varepsilon,l}}-z) \varphi_lu + i(H_{V_{\varepsilon,l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l)u \Big)\\
				&=\sum_{l=1}^{p+1} \Big(\varphi_l u + i(H_{V_{\varepsilon,l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l) u \Big)\\
				&= \left(I +\sum_{l=1}^{p+1}  i(H_{V_{\varepsilon,l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l) \right) u.
			\end{aligned}
		\end{equation}
		In particular, if $|\textup{Im }z| > \sum_{l=1}^{p+1} \|\alpha \cdot\nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}$ holds, then it is clear that the operator $I +\sum_{l=1}^{p+1}  i(H_{V_{\varepsilon,l}}-z)^{-1} (\alpha \cdot \nabla \varphi_l) $ is continuously invertible in $L^2(\R^{\theta};\C^N)$ and therefore
		\begin{equation*}
			(H_{V_\varepsilon}-z)^{-1} = \Bigg(I +\sum_{l=1}^{p+1}  i(H_{V_{\varepsilon,l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l)  \Bigg)^{-1}\Bigg(\sum_{l=1}^{p+1} (H_{V_{\varepsilon,l}}-z)^{-1}\varphi_l \Bigg).
		\end{equation*}
	\end{proof}

	Next, we provide an analogous formula as in the previous lemma for the resolvents of Dirac operators with $\delta$-shell potentials. For this, recall first from 
	\eqref{eq_V} that 
	$V = \eta I_N + \tau \beta$ with $\eta,\tau \in C^1_b(\Sigma;\R)$, assume that $d = \eta^2-\tau^2$ satisfies \eqref{eq_d_cond}, and let $\widetilde{V} = \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr)V$
	be as in \eqref{eq_scaling}. Furthermore, with $V_l= \eta_l I_N + \tau_l \beta$ and $ \eta_l,\tau_l \in C^1_b(\Sigma;\R)$, $l \in \{1,\dots,p\}$, as described below \eqref{eq_interaction_extensions} we set (as in \eqref{eq_scaling})
	\begin{equation*}
		\widetilde{V}_l = \widetilde{\eta}_l I_N + \widetilde{\tau}_l \beta, \qquad (\widetilde{\eta}_l,\widetilde{\tau}_l) = \textup{tanc}\bigl(\tfrac{\sqrt{d_l}}{2}\bigr) (\eta_l,\tau_l), \qquad d_l = \eta^2_l -\tau^2_l.
	\end{equation*} 
	In the third preparatory lemma we shall again make use of 
	the partition of unity $\varphi_1,\dots,\varphi_{p} \in C^\infty_b(\R^{\theta};\R)$ from Lemma~\ref{lem_part_unity_phi_l} and as before we set 
	$\varphi_{p+1} = 1-\sum_{l=1}^p \varphi_l$.




	\begin{lemma}\label{lem_H_Vtilde}
	Let the functions $\widetilde{V}$ and $\widetilde V_l$ be as above, let the self-adjoint operator $H_{\widetilde{V} \delta_\Sigma}$ be defined as in \eqref{eq_def_H_V_tilde} and define
	in the same way (with $\widetilde{V}$ and $\Sigma$ replaced by $\widetilde{V}_l$ and $\Sigma_l$) the self-adjoint operators 
	$$H_{\widetilde{V}_l \delta_{\Sigma_l}},\,\,\, l \in \{1,\dots,p\},\qquad\text{and}\qquad H_{\widetilde{V}_{p+1} \delta_{\Sigma_{p+1}}} :=H.$$ 
	Then, for $z \in \C$ such that $\abs{\textup{Im } z} > \sum_{l=1}^{p+1} \|\alpha \cdot\nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}$ the operator  $$I +\sum_{l=1}^{p+1}  i(H_{\widetilde{V}_{l} \delta_{\Sigma_l}}-z)^{-1} (\alpha \cdot \nabla \varphi_l) $$ is continuously invertible in $L^2(\R^{\theta};\C^N)$ and the resolvent formula 
	\begin{equation*}
		(H_{\widetilde{V}\delta_\Sigma}-z)^{-1} = \Bigg(I +\sum_{l=1}^{p+1}  i(H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l)  \Bigg)^{-1}\Bigg(\sum_{l=1}^{p+1} (H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}\varphi_l \Bigg)
	\end{equation*}
	is valid.
	\end{lemma}

	\begin{proof}
		Similar as in the proof of the previous lemma we start by showing for $u \in \dom H_{\widetilde{V} \delta_\Sigma}$ and $l \in \{1,\dots,p\}$ that
		\begin{equation}\label{zuerstdas}
		 H_{\widetilde{V}\delta_\Sigma}\varphi_l u = H_{\widetilde{V}_l \delta_{\Sigma_l}} \varphi_l u.
		\end{equation}
		First we argue that for $u \in \dom H_{\widetilde{V} \delta_\Sigma}$ we 
		have 
		\begin{equation}\label{bittedas}
		\varphi_l u \in \dom H_{\widetilde{V} \delta_\Sigma} \cap \dom H_{\widetilde{V}_l \delta_{\Sigma_l}}.\end{equation}
		In fact, since 
		$ \dom H_{\widetilde{V} \delta_\Sigma}\subset H^1(\R^\theta \setminus \Sigma;\C^N)$ and $\varphi_l \in C^\infty_b(\R^\theta;\R)$, we have $\varphi_l u \in H^1(\R^{\theta}\setminus \Sigma;\C^N)$ for $u \in \dom H_{\widetilde{V} \delta_\Sigma}$ as well as  
		\begin{equation*}
			\begin{aligned}
			&\Bigg(i(\alpha\cdot\nu)(\boldsymbol{t}_{\Sigma}^+ - \boldsymbol{t}_{\Sigma}^-) + \frac{\widetilde{V}}{2}(\boldsymbol{t}_{\Sigma}^+ + \boldsymbol{t}_{\Sigma}^-)\Bigg) \varphi_l u \\
			&\hspace{100 pt}= (\varphi_l|_\Sigma)\Big(i(\alpha\cdot\nu)(\boldsymbol{t}_{\Sigma}^+ - \boldsymbol{t}_{\Sigma}^-) + \frac{\widetilde{V}}{2}(\boldsymbol{t}_{\Sigma}^+ + \boldsymbol{t}_{\Sigma}^-)\Big)  u = 0,
			\end{aligned}
		\end{equation*}
		that is, $\varphi_l u \in \dom H_{\widetilde{V} \delta_\Sigma}$. For \eqref{bittedas} it remains to verify $\varphi_l u\in \dom H_{\widetilde{V}_l \delta_{\Sigma_l}}$. Here it is convenient to introduce $(\Omega_l)_+ := \Omega_l$ and $(\Omega_l)_- := \R^\theta \setminus \overline{\Omega_l}$. Since we already have $ \varphi_l u \in \dom H_{\widetilde{V}\delta_\Sigma} \subset H^1(\R^{\theta}\setminus \Sigma)$ it is clear that $( \varphi_l u)|_{\Omega_\pm} \in H^1(\Omega_\pm;\C^N)$. Furthermore, as $\supp \varphi_l \subset W_l $ and $\Omega_\pm \cap W_l = (\Omega_l)_\pm \cap W_l$, see Section~\ref{sec_not}~\eqref{it_def_Sigma}, it follows that $(\varphi_l u)|_{(\Omega_l)_\pm} \in  H^1((\Omega_l)_{\pm};\C^N)$.   Thus, we can apply the trace operator to $(\varphi_l u)|_{(\Omega_l)_\pm}$ and obtain 
		\begin{equation*}
			\begin{aligned}
				\Bigg(i&(\alpha\cdot\nu)(\boldsymbol{t}_{\Sigma_l}^+ - \boldsymbol{t}_{\Sigma_l}^-) + \frac{\widetilde{V}_l}{2}(\boldsymbol{t}_{\Sigma_l}^+ + \boldsymbol{t}_{\Sigma_l}^-)\Bigg) \varphi_l u  \\
				&= \begin{cases} \Big(i(\alpha\cdot\nu)(\boldsymbol{t}_{\Sigma_l}^+ - \boldsymbol{t}_{\Sigma_l}^-) + \frac{\widetilde{V}_l}{2}(\boldsymbol{t}_{\Sigma_l}^+ + \boldsymbol{t}_{\Sigma_l}^-)\Big)  \varphi_l u  & \textup{ on } \Sigma_l \cap W_l \\ 0 & \textup{ on } \Sigma_l \setminus W_l
				\end{cases}\\
				&= \begin{cases} \Big(i(\alpha\cdot\nu)(\tr^+ - \tr^-) + \frac{\widetilde{V}}{2}(\tr^+ + \tr^-)\Big)  \varphi_l u & \textup{ on } \Sigma \cap W_l \\ 0 & \textup{ on } \Sigma \setminus W_l
				\end{cases}\\
				&=0,
			\end{aligned}
		\end{equation*} 
		where we used $ \varphi_l u \in \dom H_{\widetilde{V}\delta_\Sigma}$, $\supp \varphi_l \subset W_l$, and $\widetilde{V}_l = \widetilde{V}$ on $\Sigma_l \cap W_l = \Sigma \cap W_l$. Hence, $\varphi_l u \in H^1(\R^{\theta}\setminus \Sigma_l)$ and $\varphi_l u$ fulfils the boundary condition
		\begin{equation*}
			\Bigg(i(\alpha\cdot\nu)(\boldsymbol{t}_{\Sigma_l}^+ - \boldsymbol{t}_{\Sigma_l}^-) + \frac{\widetilde{V}_l}{2}(\boldsymbol{t}_{\Sigma_l}^+ + \boldsymbol{t}_{\Sigma_l}^-)\Bigg) \varphi_l u  = 0,
		\end{equation*}
		that is, $\varphi_l u  \in \dom H_{\widetilde{V}_l \delta_{\Sigma_l}}$ and hence we have 
		\eqref{bittedas}. Moreover, 
		\begin{equation*}
			\begin{aligned}
				H_{\widetilde{V}\delta_\Sigma} \varphi_l u &= \begin{cases} (-i(\alpha \cdot\nabla) + m \beta)(\varphi_l u )|_{\Omega_\pm \cap W_l} & \textup{in } \Omega_\pm \cap W_l\\
					0 & \textup{else}
				\end{cases}\\
				&= \begin{cases} (-i(\alpha \cdot\nabla) + m \beta)(\varphi_l u)|_{(\Omega_l)_\pm \cap W_l} & \textup{in } (\Omega_l)_\pm \cap W_l\\
					0 & \textup{else}\\
				\end{cases}\\
				&= H_{\widetilde{V}_l  \delta_{\Sigma_l}} \varphi_l u,
			\end{aligned}
		\end{equation*} 
		and hence also \eqref{zuerstdas} is valid.

	Applying the product rule and using \eqref{zuerstdas} yields for $u \in \dom H_{\widetilde{V}\delta_\Sigma }$ and any $l \in \{1,\dots,p\}$
		\begin{equation}\label{eq_res_formula_V_tilde_0}
			\varphi_l H_{\widetilde{V}\delta_\Sigma}u  =H_{\widetilde{V}\delta_\Sigma} \varphi_l u +  i 	(\alpha \cdot \nabla \varphi_l) u = H_{\widetilde{V}_l \delta_{\Sigma_l}} \varphi_l u  + i (\alpha \cdot \nabla \varphi_l) u.
		\end{equation}
		Since $\varphi_{p+1} = 0$ on $\Sigma + B(0,\delta)$, we get for $u \in \dom H_{\widetilde{V} \delta_\Sigma} \subset H^1(\R^{\theta}\setminus \Sigma;\C^N)$ that 
		 $\varphi_{p+1}  u \in H^1(\R^{\theta};\C^N)$ and 
		 $$H_{\widetilde{V} \delta_\Sigma} \varphi_{p+1} u= H \varphi_{p+1} u =H_{\widetilde{V}_{p+1} \delta_{\Sigma_{p+1}}} \varphi_{p+1} u.$$  
		 Thus,  the product rule implies that \eqref{eq_res_formula_V_tilde_0} is also valid for $ l= p+1$.  Next, let us mention that  since $d = \eta^2-\tau^2$ and $d_l = \eta_l^2 - \tau_l^2$, $l \in \{1,\dots,p\}$,  satisfy \eqref{eq_d_cond} and \eqref{eq_cond_d_l},  respectively, $\widetilde{d}  = 4\tan^2\bigl(\tfrac{\sqrt{d}}{2}\bigr)$ and $\widetilde d_l=4\tan^2\bigl(\tfrac{\sqrt{d_l}}{2}\bigr) $, $l \in \{1,\dots,p\}$, fulfil \eqref{eq_d_tilde_non_crit}. Hence, $H_{\widetilde{V}\delta_\Sigma}$ and $H_{\widetilde{V}_l \delta_{\Sigma_l}}$ are self-adjoint operators in $L^2(\R^{\theta};\C^N)$. Now, one can show in the same way as in \eqref{eq_res_formular_V_eps_0} 
		for $z \in \C \setminus \R$  and $u \in \dom H_{\widetilde{V}\delta_\Sigma}$ that
			\begin{equation*}
				\Bigg( \sum_{l=1}^{p+1} (H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}\varphi_l \Bigg) (H_{\widetilde{V}\delta_\Sigma}-z)u = \Bigg(I +\sum_{l=1}^{p+1}  i(H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l) \Bigg) u.
			\end{equation*}
			In particular, if $|\textup{Im }z| > \sum_{l=1}^{p+1} \|\alpha \cdot\nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}$, then it is clear that the operator $I +\sum_{l=1}^{p+1}  i(H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l)$ is continuously invertible in $L^2(\R^{\theta};\C^N)$ and therefore
		\begin{equation*}
			(H_{\widetilde{V}\delta_\Sigma}-z)^{-1} = \Bigg(I +\sum_{l=1}^{p+1}  i(H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l)  \Bigg)^{-1}\Bigg(\sum_{l=1}^{p+1} (H_{\widetilde{V}_l 	\delta_{\Sigma_l}}-z)^{-1}\varphi_l \Bigg).
		\end{equation*}
	\end{proof}

	With the help of the previous lemmas we are now in the  position to prove Theorem~\ref{theo_main_1}.
	\begin{proof}[Proof of Theorem~\ref{theo_main_1}]
	Let $V_l= \eta_l I_N + \tau_l \beta$, $l \in \{1,\dots,p\}$, be defined by~\eqref{def_V_l} and consider $z \in \C$ such that 
	$\abs{\textup{Im } z} > \sum_{l=1}^{p+1} \|\alpha \cdot\nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}$ and $r \in (0,\tfrac{1}{2})$.
		Since  $d_l = \eta_l^2 - \tau_l^2$ satisfies \eqref{eq_cond_d_l} we can apply Theorem~\ref{theo_rotated_graph}, which implies 
		that there exists an $\varepsilon' \in (0,\min\{\varepsilon_1,\delta,\varepsilon_{3,1},\dots,\varepsilon_{3,p}\})$, where $\varepsilon_{3,l}$, $l \in \{1,\dots,p\}$, corresponds to $\varepsilon_3$ from Theorem~\ref{theo_rotated_graph} for $\Sigma_l$, such that 
		\begin{equation}\label{eq_conv_H_V_l}
			\norm{(H_{V_{\varepsilon,l}}-z)^{-1} - (H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}}_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N)} \leq C \varepsilon^{1/2-r}
		\end{equation} 
		for $l \in \{1,\dots,p\}$ and $\varepsilon \in (0, \varepsilon')$. Our conventions from Lemma~\ref{lem_H_V_eps_formula} and  Lemma~\ref{lem_H_Vtilde} ensure that  \eqref{eq_conv_H_V_l} is also true for $l = p+1$.

	Now, we define  for $\varepsilon \in (0,\varepsilon')$
	\begin{equation*}
		\begin{aligned}
		\mathfrak{R}_{\varepsilon} &= \sum_{l=1}^{p+1}  (H_{V_{\varepsilon,l}}-z)^{-1} \varphi_l , &\mathfrak{S}_\varepsilon &= \sum_{l=1}^{p+1}  i(H_{V_{\varepsilon,l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l),  \\
		\mathfrak{R}_{0} &= \sum_{l=1}^{p+1}  (H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1} \varphi_l ,&\mathfrak{S}_0 &= \sum_{l=1}^{p+1}  i(H_{\widetilde{V}_l \delta_{\Sigma_l}}-z)^{-1}(\alpha \cdot \nabla \varphi_l).
		\end{aligned}
	\end{equation*}
 Thus, \eqref{eq_conv_H_V_l} and $\varphi_l \in C^{\infty}_b(\R^{\theta};\R)$, $l \in \{1,\dots,p+1\}$, imply 
	\begin{equation*}
	\lVert \mathfrak{S}_\varepsilon - \mathfrak{S}_0\rVert_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}, \, 	\lVert \mathfrak{R}_\varepsilon - \mathfrak{R}_0\rVert_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \leq C \varepsilon^{1/2-r}.
	\end{equation*} 
	Furthermore,  since
	\begin{equation*} 
		\begin{aligned}
		&\max\Big\{ \sup_{\varepsilon \in (0,\varepsilon')}	\lVert \mathfrak{S}_\varepsilon \rVert_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)},  	\lVert \mathfrak{S}_0\rVert_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \Big\} \\
		&\hspace{180 pt}\leq \frac{\sum_{l=1}^{p+1} \|\alpha \cdot\nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}}{\abs{\textup{Im }z}} <1,
		\end{aligned}
	\end{equation*}
	we conclude with the help of Lemma~\ref{lem_H_V_eps_formula} and Lemma~\ref{lem_H_Vtilde} 
	\begin{equation*}
		\begin{aligned}
		&\lVert (H_{V_\varepsilon} -z)^{-1} - (H_{\widetilde{V}\delta_\Sigma} -z)^{-1} \rVert_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \\
		&\hspace{50 pt}= \lVert (I+\mathfrak{S}_\varepsilon)^{-1}\mathfrak{R}_\varepsilon - (1+\mathfrak{S}_0)^{-1}\mathfrak{R}_0\rVert_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \leq C \varepsilon^{1/2-r},
		\end{aligned}
	\end{equation*}
	which proves the claim if $|\textup{Im }z| > \sum_{l=1}^{p+1} \|\alpha \cdot \nabla \varphi_l\|_{L^\infty(\R^{\theta};\C^{N \times N})}$. 
	Using the identity 
	\begin{equation*}
		\begin{aligned}
			(H_{\widetilde{V}\delta_\Sigma} -w)^{-1} -(H_{V_\varepsilon} -w)^{-1} 
			= (I+(w-z)(H_{\widetilde{V}\delta_\Sigma} -w)^{-1})&\\
			\cdot\big((H_{\widetilde{V}\delta_\Sigma} -z)^{-1} - (H_{V_\varepsilon} -z)^{-1}\big)(I + (w-z)(H_{V_\varepsilon} -w)^{-1})&, \quad  w \in \C\setminus\R,
		\end{aligned}
	\end{equation*}
	it follows that the claim is true for all $w \in \C\setminus\R$.
	This completes the proof of Theorem~\ref{theo_main_1}.
	\end{proof}


	In order to obtain the operator $H_{\widetilde{V}\delta_\Sigma}$ as a limit operator of Dirac operators with squeezed potentials also in the case 
	\begin{equation*}   
\inf_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| > 4
	\end{equation*}
	we use an approach that is inspired by the last paragraph of  \cite[Section~8]{CLMT21} and now  add  a strongly localized magnetic potential 
	$V_{m,\varepsilon}$ to $H_{V_\varepsilon}$ with the interaction strength $\pi$. It turns out that in this case $H_{V_\varepsilon}+V_{m,\varepsilon}$  also converges in the norm resolvent sense,  see the following Theorem~\ref{theo_main_2}. 
	However, by the specific choice of $\pi$ as the magnetic interaction strength,  the magnetic term disappears 
	in the limit. Hence, we end up with a limit operator $H_{\widetilde{V}\delta_\Sigma}$ which is again a Dirac operator with $\delta$-shell potential and only electrostatic and Lorentz-scalar interactions; however, we emphasize that here a
	different rescaling than \eqref{eq_scaling} in Theorem~\ref{theo_main_1} appears. %as in the case $V=\eta I_N + \tau \beta$. 

	\begin{theo}\label{theo_main_2}
		Let $q\in L^\infty((-1,1);[0,\infty))$ with $\int_{-1}^1 q(s) \,ds =1$, let $\eta, \tau \in  C^1_b(\Sigma;\R)$  and assume that $d = \eta^2-\tau^2$
		satisfies the condition \eqref{eq_d_cond} and  $\inf_{x_\Sigma \in \Sigma} |d(x_\Sigma)| >0$.
		 Let $V$ and $V_\varepsilon$ be  as in \eqref{eq_V} and  \eqref{eq_V_eps},
        let the strongly localized magnetic potential $V_{m,\varepsilon} \in L^\infty(\R^{\theta};\C^{N\times N})$, ${\varepsilon \in (0,\varepsilon_1)}$, be defined by
		\begin{equation}\label{eq_V^m_eps}
			V_{m,\varepsilon}(x) := \begin{cases} \pi (\alpha \cdot \nu(x_\Sigma)) \frac{1}{\varepsilon} q\bigl(\tfrac{t}{\varepsilon}\bigr)& \textup{for } x= \iota(x_\Sigma,t)\in \Omega_\varepsilon, \\
				0&  \textup{else},
			\end{cases}
		\end{equation}
		and set 
		\begin{equation}\label{eq_magnetic_scaling}
			\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta,\qquad (\widetilde{\eta},\widetilde{\tau}) = \frac{-2 }{\sqrt{d}\tan\bigl(\tfrac{\sqrt{d}}{2}\bigr)}(\eta,\tau),\qquad d = \eta^2-\tau^2.
		\end{equation} 
		Then, for all $z \in \C\setminus\R$  and $r \in (0,\tfrac{1}{2} )$ there exist $C>0$ and $\varepsilon' \in (0,\varepsilon_1)$ such that 
		\begin{equation*}
			\norm{(H_{V_\varepsilon} + V_{m,\varepsilon} -z)^{-1} - (H_{\widetilde{V}\delta_\Sigma}-z)^{-1}}_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N)} \leq C \varepsilon^{1/2-r}, \,\,  \varepsilon \in (0, \varepsilon').
		\end{equation*} 
		In particular, $H_{V_\varepsilon} + V_{m,\varepsilon}$ converges to $H_{\widetilde{V} \delta_\Sigma}$ in the norm resolvent sense as $\varepsilon \to 0$. 
	\end{theo}


	We note that the function
	\begin{equation*}
		(-\infty,\tfrac{\pi^2}{4}) \ni w \mapsto 4\tan^2\bigl(\tfrac{\sqrt{w}}{2}\bigr)  = \begin{cases}
			\tan^2\bigl(\tfrac{\sqrt{w}}{2}\bigr) \in [0,1),& w \in [0,\tfrac{\pi^2}{4}), \\\
			-\tanh^2\bigl(\tfrac{\sqrt{-w}}{2}\bigr) \in (-1,0), & w \in (-\infty,0),
		\end{cases}
	\end{equation*}
	is continuous, monotonically increasing and has its only root in zero. Hence, the assumption $\inf_{x_\Sigma \in \Sigma} \abs{d(x_\Sigma)} >0$, \eqref{eq_d_cond}, and the boundedness of $\eta$ and $\tau$ imply 
	\begin{equation*}
		\inf_{x_\Sigma \in \Sigma}  \Bigl|\tan^2\Bigr(\tfrac{\sqrt{d(x_\Sigma)}}{2}\Bigl)\Bigr| >0 \quad \textup{and} \quad\sup_{x_\Sigma \in \Sigma}  \Bigl|\tan^2\Bigr(\tfrac{\sqrt{d(x_\Sigma)}}{2}\Bigr)\Bigr|  <1.
	\end{equation*}
	 In particular,  $\widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2 = 4/\tan^2\bigl(\tfrac{\sqrt{d}}{2}\bigr)$ is well-defined and
	\begin{equation*}
		\inf_{x_\Sigma \in \Sigma} \abs{\widetilde{d}(x_\Sigma)} = \frac{4}{\sup_{x_\Sigma \in \Sigma}  \Bigl|\tan^2\Bigl(\tfrac{\sqrt{d(x_\Sigma)}}{2}\Bigr)\Bigr| } > 4.
	\end{equation*}
	 Thus, 
	$\widetilde V$ in \eqref{eq_magnetic_scaling}
	is noncritical; cf. \eqref{eq_d_tilde_non_crit}. 
	We point out again that the rescaling \eqref{eq_magnetic_scaling} in Theorem~\ref{theo_main_2} differs 
	from the rescaling \eqref{eq_scaling} in Theorem~\ref{theo_main_1}.



	The following preparatory lemma is an essential ingredient in the proof of Theorem~\ref{theo_main_2} and also of independent interest.

	\begin{lemma}\label{lem_int_u^2_estimate}
		Let $\varepsilon_1$ be chosen as below \eqref{eq_iota}, $\varepsilon \in (0, \varepsilon_1)$, and let $\Omega_\varepsilon$ be the tubular neighbourhood of $\Sigma$. Then, for all
		$s \in (\tfrac{1}{2},\infty)$ there exists $C>0$ such that  
		\begin{equation*}
			\int_{\Omega_\varepsilon} \lvert u(x) \rvert^2 \,dx \leq C \varepsilon \lVert  u \rVert_{ H^s(\R^{\theta}\setminus \Sigma;\C^N)}^2,\qquad 
			u \in H^s(\R^{\theta} \setminus \Sigma;\C^N).
		\end{equation*}
	\end{lemma} 
	\begin{proof}
		Since $H^{s'}(\R^{\theta}\setminus \Sigma;\C^N)$ is continuously embedded in $H^{s}(\R^{\theta}\setminus \Sigma;\C^N)$ for $s < s'$, it is no restriction to assume $ s \in (\tfrac{1}{2},1]$. We start by considering $u = u_+ \oplus u_-$ with $u_\pm \in \mathcal{D}(\overline{\Omega_\pm};\C^N)$, where 
		$$\mathcal{D}(\overline{\Omega_\pm};\C^N) := \{ u|_{\Omega_\pm}: u \in \mathcal{D}(\mathbb{R}^\theta; \mathbb{C}^N) \}.$$
		Moreover, by \cite[Proposition~2.4 and Corollary~A.3]{BHS23} and  our choice of $\varepsilon_1>0$, see the lines below \eqref{eq_iota},  we obtain
		\begin{equation*}
			\begin{aligned}
				\int_{\Omega_\varepsilon} |u(x)|^2 \,dx & \leq C  \int_{-\varepsilon}^\varepsilon \int_{\Sigma} |u(x_\Sigma + t \nu(x_\Sigma))|^2 \, d\sigma(x_\Sigma)  \,dt \\
				&=  {C}{\varepsilon} \bigg(\int_{-1}^0 \int_{\Sigma} |u_+(x_\Sigma + t\varepsilon  \nu(x_\Sigma))|^2 \, d\sigma(x_\Sigma)  \,dt   \\
				&\quad \quad +\int_{0}^1 \int_{\Sigma} |u_-(x_\Sigma +  t\varepsilon \nu(x_\Sigma))|^2 \, d\sigma(x_\Sigma)\,dt \bigg).
			\end{aligned}
		\end{equation*}
		Next, we estimate the term $\int_{-1}^0 \int_{\Sigma} |u_+(x_\Sigma + t \varepsilon\nu(x_\Sigma))|^2 \,d\sigma(x_\Sigma) \,dt$. Note that the smoothness of $u$ implies that for  $t \in (-1,0)$ the function 
		\begin{equation*}
			\Sigma \ni x_\Sigma \mapsto u_+(x_\Sigma + t\varepsilon \nu(x_\Sigma))
		\end{equation*}
		coincides with  the trace of the function
		\begin{equation*}
			\R^\theta \ni x  \mapsto \widetilde{u}_+(x + t\varepsilon \nu_{\rm ext}(x)),
		\end{equation*}
		where $\nu_{\rm ext}$ is a $C^1_b$-extension of the unit normal vector $\nu$ to $\R^{\theta}$, which can be constructed in the same way as the extensions of $\eta$, $\tau$, and $V$ in \eqref{eq_interaction_extensions}, and $\widetilde{u}_+ = E u_+ \in H^1(\R^{\theta};\C^N)$ is the extension of $u_+$ to $\R^{\theta}$ defined by Stein's continuous extension operator
		\begin{equation*}
			E:H^s(\Omega_+;\C^N) \mapsto H^s(\R^{\theta};\C^N);
		\end{equation*}
		cf. \cite[Chapter~6,~Section~3,~Theorem~5]{S70}. Then,
		\begin{equation*}
			\int_{-1}^0 \int_{\Sigma} |u_+(x_\Sigma + t\varepsilon \nu(x_\Sigma))|^2 \,d\sigma(x_\Sigma)\,dt = \int_{-1}^0 \int_{\Sigma} \big|\tr \big(\widetilde{u}_+( (\cdot) + t \varepsilon\nu_{\rm ext})\big)(x_\Sigma)\big|^2 \,d\sigma(x_\Sigma)\,dt
		\end{equation*}
		and we can  estimate this term  by
		\begin{equation*}
			\begin{aligned}
				\int_{-1}^0 \int_{\Sigma} |\tr \big(\widetilde{u}_+( (\cdot) + &t \varepsilon\nu_{\rm ext})\big)(x_\Sigma)|^2 \,d\sigma(x_\Sigma)\,dt \\
				&=\int_{-1}^0 \norm{\tr (E u_+)((\cdot) + t\varepsilon \nu_{\rm ext})}_{L^2(\Sigma;\C^N)}^2   \,dt \\
				&\leq \int_{-1}^{0} \norm{\tr (E u_+)((\cdot) + t\varepsilon \nu_{\rm ext})}_{H^{s-1/2}(\Sigma;\C^N)}^2 \,dt\\
				&\leq C\int_{-1}^{0}\norm{ (E u_+)((\cdot) + t\varepsilon \nu_{\rm ext})}_{H^s(\R^{\theta};\C^N)}^2 \,dt.
			\end{aligned}
		\end{equation*}
		According to \cite[Proposition~3.3]{BHS23} the term $\norm{ (E u_+)((\cdot) + t\varepsilon\nu_{\rm ext})}_{H^s(\R^{\theta};\C^N)}$ is uniformly bounded with respect to $t\in(0,1)$ and $\varepsilon \in (0,\varepsilon_1)$ by $C \norm{ E u_+}_{H^s(\R^{\theta};\C^N)}$, which is in turn bounded by $C \norm{u_+}_{H^s(\Omega_+;\C^N)}$. Therefore,
		\begin{equation*}
			\int_{-1}^0 \int_{\Sigma} |u_+(x_\Sigma + t \nu(x_\Sigma))|^2 \,d\sigma(x_\Sigma)\,dt \leq C \norm{u_+}_{H^s(\Omega_+;\C^N)}^2;
		\end{equation*}
		in the same way one gets
		\begin{equation*}
			\int_{0}^1 \int_{\Sigma} |u_-(x_\Sigma + t \nu(x_\Sigma))|^2 \,d\sigma(x_\Sigma)\,dt \leq C \norm{u_-}_{H^s(\Omega_-;\C^N)}^2.
		\end{equation*} 
		This implies the assertion for $u \in \mathcal{D}(\overline{\Omega_+};\C^N) \oplus \mathcal{D}(\overline{\Omega_-};\C^N)$, which is a dense subspace of $H^s(\R^{\theta}\setminus\Sigma;\C^N) = H^s(\Omega_+;\C^N) \oplus H^s(\Omega_-;\C^N)$, see, e.g., \cite[Chapter~3]{M00}. Therefore, the assertion of the lemma follows for all $u\in  H^s(\R^{\theta}\setminus\Sigma;\C^N)$.
	\end{proof}

	\begin{proof}[Proof of Theorem~\ref{theo_main_2}]
		The proof is based on an idea that is also described below the proof of Theorem~2.6 in \cite[Section~8]{CLMT21} and the equality  
		\begin{equation}\label{eq_H_tilde_V_unitary_equivalence}
			H_{\widetilde{V}\delta_\Sigma} = U H_{(-4/\widetilde d)\widetilde{V} \delta_\Sigma} U,
		\end{equation} 
		where $U$ is the self-adjoint unitary multiplication operator induced by the function $w = \chi_{\Omega_+} - \chi_{\Omega_-}$ in $L^2(\R^\theta;\C^N)$. Recall that $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta$ is as in~\eqref{eq_magnetic_scaling}, $\widetilde{d} = \widetilde{\eta}^2-\widetilde{\tau}^2$, and by our assumptions we have $\inf_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| > 4$, so that all terms in~\eqref{eq_H_tilde_V_unitary_equivalence} are well-defined. Equation \eqref{eq_H_tilde_V_unitary_equivalence} can be proven as in, e.g., \cite[Lemma~5.11]{BHSS22}, \cite[Section~4]{CLMT21} or \cite[Theorem~1.1]{M17}. Furthermore, according to \eqref{eq_magnetic_scaling} we have
		\begin{equation*}
			\widetilde{V}  =\frac{-2}{\sqrt{d}\tan\bigl(\tfrac{\sqrt{d}}{2}\bigr)} V \quad \textup{and} \quad \widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2 = \frac{4}{\tan^2\bigl(\tfrac{\sqrt{d}}{2}\bigr)}. 
		\end{equation*}
		Set $ \widetilde{V}_{\textup{cl}} := \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) V $ and observe
		\begin{equation*}
			\frac{-4}{\widetilde d}\widetilde{V} = -\tan^2\bigl(\tfrac{\sqrt{d}}{2}\bigr) \frac{-2}{\sqrt{d}\tan\bigl(\tfrac{\sqrt{d}}{2}\bigr)} V 
			= \frac{\tan\bigl(\tfrac{\sqrt{d}}{2}\bigr)}{\frac{\sqrt{d}}{2}}  V
			= \widetilde{V}_{\textup{cl}}. 
		\end{equation*}
		In particular, 
		\begin{equation}\label{eq_H_tilde_V_cl}
		H_{\widetilde{V} \delta_\Sigma}= UH_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}U,
		\end{equation}
		and since $\widetilde{V}_{\textup{cl}} = \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) V$, which is the rescaling from Theorem~\ref{theo_main_1}, it follows from Theorem~\ref{theo_main_1} that 
		$H_{V_\varepsilon}$ converges to $H_{\widetilde{V}_{\textup{cl}} \delta_\Sigma}$ in the norm resolvent sense.
		We then proceed in a similar way as in \cite{CLMT21}, that is, we provide unitary multiplication operators $W_\varepsilon$ such that 
		\begin{equation}\label{herrje33}
			W_\varepsilon^*H_{V_\varepsilon} W_\varepsilon = H_{V_\varepsilon} + V_{m,\varepsilon},
		\end{equation}
		where $V_{m,\varepsilon}$ is the strongly localized magnetic potential introduced in \eqref{eq_V^m_eps}, and $W_\varepsilon \to U$ for $\varepsilon \to 0$, so that the left hand side of \eqref{herrje33} converges in the norm resolvent sense to 
		$U H_{\widetilde{V}_{\textup{cl}} \delta_\Sigma} U=H_{\widetilde{V} \delta_\Sigma}$.

		We now start the main part of the proof by defining for $\varepsilon \in (0,\varepsilon_1)$ the function 
		\begin{equation*}
			w_\varepsilon: \R^{\theta} \to \C, \qquad w_\varepsilon(x):= \begin{cases}1, & x \in \Omega_+ \setminus \Omega_\varepsilon, \\ e^{i \pi \int_{-1}^{t/\varepsilon} q(s) \,ds}, & x = \iota(x_\Sigma,t)\in \Omega_\varepsilon, \\ -1, & x  \in \Omega_- \setminus \Omega_\varepsilon.
			\end{cases}
		\end{equation*}
		This function is well-defined according to the text below \eqref{eq_iota}. We define $W_\varepsilon$ to be the unitary multiplication operator in $L^2(\R^{\theta};\C^N)$ induced by $w_\varepsilon$. Using $\int_{-1}^1 q(s) \,ds = 1$ and tubular coordinates one shows that $w_\varepsilon \in W^1_\infty(\R^{\theta})$. Moreover, by \cite[eq. (2.11)]{Z23} and \cite[eq. (3.10)]{CLMT21} we have 
		$\nabla (\iota^{-1}(x))_2 = \nu(x_\Sigma) $ for ${x = \iota(x_\Sigma,t)  \in \Omega_\varepsilon}$ ($(\iota^{-1}(x))_2 = t$) and therefore the chain rule implies
		\begin{equation*}
			\nabla w_\varepsilon(x) =\begin{cases}
				\nu(x_\Sigma) \frac{i\pi q\bigl(\tfrac{t}{\varepsilon}\bigr)}{\varepsilon}w_\varepsilon(x), &  x = \iota(x_\Sigma,t) \in \Omega_\varepsilon,\\
				0, & \textup{else}.
			\end{cases}
		\end{equation*}
		These considerations and the definition of $V_{m,\varepsilon}$ show  
		\begin{equation}\label{eq_H_V_eps_W_eps}
			W_\varepsilon^*H_{V_\varepsilon} W_\varepsilon = H_{V_\varepsilon} - i \overline{w_\varepsilon}(\alpha \cdot \nabla w_\varepsilon) = H_{V_\varepsilon} +  V_{m,\varepsilon};
		\end{equation}
		cf. \cite[Section~8, below the proof of Theorem~2.6]{CLMT21}. We note that $w_\varepsilon$ converges pointwise to $w = \chi_{\Omega_+} - \chi_{\Omega_-}$ and therefore $W_\varepsilon$ converges in the strong sense to the operator $U$. In addition,  Lemma~\ref{lem_int_u^2_estimate} shows that for $\varepsilon \in (0,\varepsilon_1)$ the estimate 
		\begin{equation}\label{eq_diff_W_eps_U_H^1}
			\begin{aligned}
				\norm{(W_\varepsilon^* -U)u}_{L^2(\R^{\theta};\C^N)}^2&= \int_{\Omega_\varepsilon} |(\overline{w_\varepsilon(x)}- \chi_{\Omega_+}(x)+\chi_{\Omega_-}(x))u(x)|^2 \,dx\\
				&\leq 4\int_{\Omega_\varepsilon} |u(x)|^2 \,dx\\
			 & \leq C \varepsilon  \norm{u}_{H^1(\R^\theta\setminus \Sigma;\C^N)}^2, \qquad  u \in H^1(\R^{\theta}\setminus \Sigma),
			 \end{aligned}
		\end{equation}
		is also valid. Moreover, since $(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma} -z)^{-1}$ is closed as an operator 
        from $L^2(\R^{\theta};\C^N)$ to $H^1(\R^{\theta}\setminus \Sigma;\C^N)$ and defined on $L^2(\R^{\theta};\C^N)$, it is also bounded
        from $L^2(\R^{\theta};\C^N)$ to $H^1(\R^{\theta}\setminus \Sigma;\C^N)$. Thus, \eqref{eq_diff_W_eps_U_H^1} implies for $\varepsilon \in (0,\varepsilon_1)$
		\begin{equation}\label{hurra12}
			\|(W_\varepsilon^* -U)(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \leq C \varepsilon^{1/2}.
		\end{equation}
		We use \eqref{eq_H_V_eps_W_eps} and \eqref{eq_H_tilde_V_cl} and estimate for $\varepsilon \in (0,\varepsilon')$ (with $\varepsilon'>0$ from Theorem~\ref{theo_main_1})
		\begin{equation*}%\label{eq_theo_main_2_1}
			\begin{aligned}
				\|(H_{V_\varepsilon} +& V_{m,\varepsilon} - z)^{-1} - (H_{\widetilde{V} \delta_\Sigma} - z)^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \\
				&=\| (W_\varepsilon^* H_{V_\varepsilon} W_\varepsilon - z)^{-1}- (UH_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}U-z)^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}\\
				&=\| W_\varepsilon^* (H_{V_\varepsilon}-z)^{-1} W_\varepsilon - U(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1}U\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}\\
				&\leq  \|W_\varepsilon^*((H_{V_\varepsilon}-z)^{-1}  -(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1})W_\varepsilon\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \\
				&\hspace{20 pt}+ \|(W_\varepsilon^*-U)(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1}W_\varepsilon\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}\\
				&\hspace{20 pt}+ \|U(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1}(W_\varepsilon - U)\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}.
			\end{aligned}
		\end{equation*}
		Furthermore, since $U$ is unitary and self-adjoint and $W_\varepsilon$ is unitary we can 
		continue the above estimate for $r \in (0,\tfrac{1}{2})$ and obtain
		\begin{equation*}
			\begin{aligned}
				\|(H_{V_\varepsilon} +& V_{m,\varepsilon} - z)^{-1} - (H_{\widetilde{V} \delta_\Sigma} - z)^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \\
				&\leq \|(H_{V_\varepsilon}-z)^{-1}  -(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)} \\
				&\hspace{20 pt}+ \|(W_\varepsilon^*-U)(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-z)^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}\\
				&\hspace{20 pt}+ \|(W_\varepsilon^* - U)(H_{\widetilde{V}_{\textup{cl}}\delta_\Sigma}-\overline{z})^{-1}\|_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N)}.\\
				&\leq C \varepsilon^{1/2-r} + C \varepsilon^{1/2} \\
				&\leq C \varepsilon^{1/2-r},
			\end{aligned}
		\end{equation*}
		where the norm resolvent convergence of $H_{V_\varepsilon}$ to $H_{\widetilde{V}_{\textup{cl}} \delta_\Sigma}$ (see Theorem~\ref{theo_main_1}) and 
		\eqref{hurra12} were used in the penultimate estimate.
	\end{proof}

	 In the next corollary we observe that every Dirac operator with a given $\delta$-shell potential $\widetilde{V} \delta_\Sigma$, $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta$, $\widetilde{\eta},\widetilde{\tau} \in C_b^1(\Sigma;\R)$, and $\widetilde{d} = \widetilde{\eta}^2 -\widetilde{\tau}^2$ such that
	\begin{equation}\label{eq_cond_d_tilde_cor}
		\sup_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)|<4 \quad \textup{or} \quad \inf_{x_\Sigma \in \Sigma}|\widetilde{d}(x_\Sigma)|>4
	\end{equation} 
	holds, can  be approximated by a sequence of Dirac operators with strongly localized potentials. 

	\begin{cor}\label{cor_main_1}
		Let $q\in L^\infty((-1,1);[0,\infty))$ with $\int_{-1}^1 q(s) \,ds =1$, let $\widetilde\eta, \widetilde\tau \in  C^1_b(\Sigma;\R)$ 
		and $\widetilde{V} = \widetilde{\eta}I_N + \widetilde{\tau}\beta$, and assume that $\widetilde d = \widetilde\eta^{\,2}-\widetilde\tau^{\,2}$
		satisfies the condition \eqref{eq_cond_d_tilde_cor}.
		Define
		the interaction strengths $\eta,\tau\in C^1_b(\Sigma)$ by 
		\begin{equation}\label{eq_cor_def_eta_tau}
			(\eta,\tau) =
			\begin{cases}
				\frac{2 \arctan\left(\frac{\sqrt{\widetilde d}}{2}\right)}{\sqrt{\widetilde{d}}} (\widetilde{\eta},\widetilde{\tau}), &\quad  \text{if } \sup_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| < 4,\\
				\frac{-2 \arctan\left(\frac{2}{\sqrt{\widetilde{d}}}\right)}{\sqrt{\widetilde{d}}} (\widetilde{\eta},\widetilde{\tau}), &\quad \text{if }\inf_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| > 4,
			\end{cases}
		\end{equation}
		and let $V=\eta I_N+ \tau\beta$ and $V_\varepsilon$ be  as in   \eqref{eq_V_eps}.
		Then, for all $r \in (0,\tfrac{1}{2})$ and $z \in \C\setminus \R$ there exist $C >0$ and $\varepsilon' \in (0,\varepsilon_1)$ such that the following is true:
		\begin{enumerate}[\upshape(i)]
			\item If $\sup_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| < 4$, then
		\begin{equation*}
			\norm{({H_{V_\varepsilon}} - z)^{-1} -(H_{\widetilde{V}\delta_\Sigma} - z)^{-1} }_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N)} \leq C \varepsilon^{1/2 -r}
		\end{equation*}
				for all   $\varepsilon \in (0, \varepsilon')$.
			\item If $\inf_{x_\Sigma \in \Sigma}|\widetilde{d}(x_\Sigma)|>4$, then
		\begin{equation*}
			\norm{({H_{V_\varepsilon}} + V_{m,\varepsilon} - z)^{-1} -(H_{\widetilde{V}\delta_\Sigma} - z)^{-1} }_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N) } \leq C \varepsilon^{1/2 -r}
		\end{equation*}
			for all  $\varepsilon \in (0, \varepsilon')$, where $V_{m,\varepsilon}$ is as in \eqref{eq_V^m_eps}.
	\end{enumerate}
	\end{cor}

	Note that in~\eqref{eq_cor_def_eta_tau} the convention $\frac{ \arctan(0)}{0} = 1$ is used. Moreover, we would like to point out that for constant $\widetilde{\eta}, \widetilde{\tau} \in \mathbb{R}$ the previous corollary is particularly interesting, as it shows that every Dirac operator with a $\delta$-potential and constant electrostatic and Lorentz-scalar interaction strengths satisfying  $|\widetilde{d}|\neq 4$ can be approximated by Dirac operators with strongly localized potentials.

	\begin{proof}[Proof of Corollary~\ref{cor_main_1}]
	Throughout this proof we use $\arctan^2(w) < \tfrac{\pi^2}{16}$ for $w \in [0,1]$ and $w \in i [0,1]$. 

	(i) The assumption $\sup_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| < 4$ implies for $d = \eta^2 - \tau^2$
	\begin{equation*}
		\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) = \sup_{x_\Sigma \in \Sigma} 4\arctan^2\Bigl(\tfrac{\sqrt{\widetilde{d}(x_\Sigma)}}{2}\Bigr)<\frac{\pi^2}{4}
	\end{equation*}
	and thus condition \eqref{eq_d_cond} is fulfilled. Hence, the assertion  follows from Theorem~\ref{theo_main_1}.

	(ii) The assumption $\inf_{x_\Sigma \in \Sigma} |\widetilde{d}(x_\Sigma)| > 4$ implies
	\begin{equation*}
		\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) = \sup_{x_\Sigma \in \Sigma} 4\arctan^2\Bigl(\tfrac{2}{\sqrt{\widetilde{d}(x_\Sigma)}}\Bigr)<\frac{\pi^2}{4}
	\end{equation*}
	and thus condition \eqref{eq_d_cond} is fulfilled. Furthermore, since $\widetilde d=\widetilde\eta^{\,2}- \widetilde\tau^{\,2} \in  C^1_b(\Sigma;\R)$ we also have $\inf_{x_\Sigma \in \Sigma} |d(x_\Sigma)| >0$.
	Hence, the assertion  follows from Theorem~\ref{theo_main_2}.
	\end{proof}

	\section{Counterexamples}\label{sec_counter}

	We show in this section that the condition \eqref{eq_d_cond} for the norm resolvent convergence of $H_{V_\varepsilon}$ is optimal by providing suitable counterexamples. Throughout this section we assume that $V$ has the form  $V = \eta I_N + \tau \beta$ with $\eta,\tau \in \R$. In this situation \eqref{eq_d_cond} simplifies to 
	$d=\eta^2-\tau^2 < \tfrac{\pi^2}{4}$ and by \eqref{eq_scaling} we have 
	\begin{equation}\label{nochamal}
		\widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2 = \textup{tanc}^2\bigl(\tfrac{\sqrt{d}}{2}\bigr) d= 4\tan^2\bigl(\tfrac{\sqrt{d}}{2}\bigr).
	\end{equation}

	In our first counterexample we treat the cases $d \geq \tfrac{\pi^2}{4}$ which lead to the critical interaction strength $\widetilde{d} = 4$. These are exactly the cases $d = (2k+1)^2 \tfrac{\pi^2}{4}$, $k \in \N_0$, and include, in particular, the important border case $d = \tfrac{\pi^2}{4}$. In this situation the operator
	$H_{\widetilde{V}\delta_\Sigma}$ is only essentially self-adjoint and hence $H_{V_\varepsilon}$ cannot converge in the  norm resolvent sense to $H_{\widetilde{V}\delta_\Sigma}$. However, if the interaction support $\Sigma$ is a compact $C^\infty$-hypersurface it turns out in Theorem~\ref{theo_main_counter_critical} that $H_{V_\varepsilon}$ does not even converge to the closure of $H_{\widetilde{V} \delta_\Sigma}$ 
	in the norm resolvent sense. In our second counterexample Theorem \ref{theo_main_3} we treat the case $d >  \tfrac{\pi^2}{4}$ and assume $d \neq (2k+1)^2 \tfrac{\pi^2}{4}$, $k \in \N_0$, 
	so that $\widetilde V$ is noncritical (i.e., $\widetilde{d} \neq 4$). If $\theta=2$ and the interaction support $\Sigma$ is the $y$-axis, 
	then we show that $H_{V_\varepsilon}$ does not converge to $H_{\widetilde{V} \delta_\Sigma}$ in the norm resolvent sense.

	\begin{theo}\label{theo_main_counter_critical} 
		Let $\Sigma \subset \R^{\theta}$ be a compact $C^\infty$-hypersurface, $q\in L^\infty((-1,1);[0,\infty))$ with $\int_{-1}^1 q(s) \,ds =1$, and 
		$\eta,\tau \in \R$ such that $d = \eta^2-\tau^2 = (2k+1)^2\tfrac{\pi^2}{4}$, $k \in \N_0$. Let
		$V=\eta I_N+ \tau\beta$ and $V_\varepsilon$ be  as in   \eqref{eq_V_eps}, and define $\widetilde V = \widetilde{\eta}I_N + \widetilde{\tau} \beta$ by \eqref{eq_scaling}. Then, $\widetilde{V}$ is critical (i.e., $\widetilde{d} = 4$), $H_{\widetilde{V} \delta_\Sigma}$ is essentially self-adjoint but not self-adjoint, and  $H_{V_\varepsilon}$ does not converge in the norm resolvent sense to the closure of $H_{\widetilde{V}\delta_\Sigma}$.
	\end{theo}

	\begin{proof}
		Since the convergence in norm resolvent sense is invariant with respect to bounded perturbations it is no restriction to assume $m>0$. 
		It is clear from \eqref{nochamal} that $d = (2k+1)^2 \tfrac{\pi^2}{4}$ leads to $\widetilde d=4$ and hence the interaction strength $\widetilde V$ is critical.
		The claims regarding the (essential) self-adjointness follow from \cite[Theorem~4.11]{BHOP20} for $\theta =2$ and from \cite[Theorem~3.1~(ii)]{Ben21} for $\theta =3$. Thus, it only remains to prove that $H_{V_\varepsilon}$ does not converge in the norm resolvent sense to the closure of $H_{\widetilde{V}\delta_\Sigma}$. 
		If $\Sigma$ is compact, then $\supp V_\varepsilon \subset \Omega_\varepsilon$ is compact and hence by \cite[Theorem~3.27~(ii)]{M00} $V_\varepsilon$ induces a compact operator from $H^1(\R^{\theta};\C^N)$ to $L^2(\R^{\theta};\C^N)$. In turn the resolvent difference
		\begin{equation*}
			(H-z)^{-1}-(H_{V_\varepsilon}-z)^{-1} = (H_{V_\varepsilon}-z)^{-1} V_\varepsilon (H-z)^{-1}
		\end{equation*}
		is compact in $L^2(\R^{\theta};\C^N)$, which shows 
		$$\sigma_{\textup{ess}}(H_{V_\varepsilon}) = \sigma_{\textup{ess}}(H) = (-\infty,-m]\cup[m,\infty).$$ Consequently, \cite[Satz~9.24~a)]{W00}  implies that if $H_{V_\varepsilon}$ would converge in norm resolvent sense to the closure of  $H_{\widetilde{V} \delta_\Sigma}$, 
		then also
		$$\sigma_{\textup{ess}}(\overline{H_{\widetilde{V}\delta_\Sigma}}) = \sigma_{\textup{ess}}(H) = (-\infty,-m] \cup [m, \infty).$$ 
		However, since $\widetilde{\eta}^2-\widetilde{\tau}^2 =4$ one has $\vert\widetilde\tau\vert <\vert\widetilde\eta\vert$ and 
		$$-\frac{\widetilde{\tau}}{\widetilde{\eta}} m \in \sigma_\textup{ess}(\overline{H_{\widetilde{V} \delta_\Sigma }})\cap (-m,m)$$ 
		according to \cite[Theorem~1.2 and  Theorem~1.3]{BHOP20} and \cite{BP24}; a contradiction. 
	\end{proof}

	Our second counterexample concerns the noncritical case and the special interaction support $\Sigma = \{0\} \times \R$ in $\R^2$. The idea of the proof is to use the direct integral method and to verify that
	$0 \in \sigma(H_{V_\varepsilon})$ for all $\varepsilon>0$ sufficiently small, while $0 \notin \sigma(H_{\widetilde{V} \delta_\Sigma})$; cf.
	Remark~\ref{remco} below for a further discussion. 



	\begin{theo}\label{theo_main_3}
		Let $\Sigma = \{0\} \times \R  \subset \R^2$, let $q = \tfrac{1}{2} \chi_{(-1,1)}$, and let $\eta,\tau \in \R$ be such that $d = \eta^2-\tau^2 >  \tfrac{\pi^2}{4}$ and $d \neq (2k+1)^2 \pi^2$, $k \in \N_0$. Let
		$V=\eta I_N+ \tau\beta$ and $V_\varepsilon$ be  as in \eqref{eq_V} and  \eqref{eq_V_eps}, and define $\widetilde V = \widetilde{\eta}I_N + \widetilde{\tau} \beta$ by \eqref{eq_scaling}. Moreover, assume that $\widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2 \neq 4$. Then, the operator $H_{V_\varepsilon}$ does not converge in norm resolvent sense to $H_{\widetilde{V}\delta_\Sigma}$.
	\end{theo}

	\begin{proof}
		 The main idea of the proof is to use the direct integral method and to show that if $\varepsilon >0$ is sufficiently small, then $0 \in \sigma(H_{V_\varepsilon})$. However, then norm resolvent convergence would imply $0 \in \sigma(H_{\widetilde{V}\delta_\Sigma})$, see, e.g., 
		 \cite[Chapter~IV, Theorem~3.1]{kato}, \cite[Theorem~VIII.23~(a)]{RS72} or \cite[Satz~9.24]{W00}. In the case that $\Sigma$ is the straight line the spectrum has been calculated explicitly in  \cite[eqs. (5.7), (6.7)]{BHT23}. In particular, if $m \neq 0$ and $(\widetilde{d}-4)m \widetilde{\tau} \leq 0$, then $0 \notin \sigma(H_{\widetilde{V}\delta_\Sigma})$, which yields  a contradiction. Note that it is no 
		 restriction to assume $m \neq 0$ and $(\widetilde{d}-4)m \widetilde{\tau}\leq 0$, since the bounded perturbation $m \beta$ does not influence the norm resolvent convergence. 

		 We show  $0 \in \sigma(H_{V_\varepsilon})$ by applying the direct integral method.
		For this observe first that in the special case of Theorem~\ref{theo_main_3}  the operator $H_{V_\varepsilon}$ can be represented by 
		\begin{equation*}
			\begin{aligned}
				H_{V_\varepsilon}  &=   \sigma_1(-i\partial_1) + \sigma_2(-i \partial_2) + m \sigma_3 + (\eta I_2 + \tau \sigma_3 )\frac{\chi_{(-\varepsilon,\varepsilon) \times \R}}{2\varepsilon},  \\
				\dom H_{V_\varepsilon} &= H^1(\R^2;\C^{2}) \subset L^2(\R^2;\C^2);
			\end{aligned}
		\end{equation*}	
		cf. \eqref{eq_V_eps}, \eqref{eq_H_V_eps} and Section~\ref{sec_not}~\eqref{it_Dirac_matrices}.
		By identifying $L^2(\R^2;\C^2)$ with $ \int_{\R}^\oplus L^2(\R;\C^2) \, d\xi$, we get similar to \cite[eq. (2.3) and the text below]{BHT23}
		\begin{equation*}
			\mathcal{F}_{2}	H_{V_\varepsilon}  \mathcal{F}^{-1}_{2} = \int_{\R}^\oplus H_{V_\varepsilon}[\xi] \, d\xi
		\end{equation*}
		with the fiber operators
		\begin{equation*}
		\begin{split}
		H_{V_\varepsilon}[\xi]  &=   -i\sigma_1 \frac{d}{dx}+ \xi \sigma_2  + m \sigma_3 + (\eta I_2 + \tau \sigma_3)\frac{\chi_{(-\varepsilon,\varepsilon)}}{2\varepsilon}, \\
		\dom H_{V_\varepsilon}[\xi] &= H^1(\R;\C^{2}),
		\end{split}
		\end{equation*}	
		for $\xi \in \R$.
		We split the proof of $ 0 \in \sigma(H_{V_\varepsilon})$ for $\varepsilon>0$ sufficiently small in 4 steps. In \textit{Step~1} we find a condition for $0$ being in the point spectrum of $H_{V_\varepsilon}[\xi]$. \textit{Step~2} is an intermediate step in which we consider the inverse of the function $ {[\tfrac{\pi}{2},\pi) \ni u \mapsto -u \cot(u)}$. Using this function we verify in \textit{Step~3} that if $\varepsilon>0$ is sufficiently small, then there always exists an $\xi_\varepsilon >0$ such that $0 \in \sigma_{\textup{p}}(H_{V_\varepsilon}[\xi_\varepsilon])$. Finally, we prove in \textit{Step~4} that this implies $0 \in \sigma(H_{V_\varepsilon})$. 

		\textit{Step~1.}
		In this step we prove  for $\xi \in \R$ that  $0 \in \sigma_{\textup{p}}(H_{V_\varepsilon}[\xi])$ is equivalent to the condition
		\begin{equation}\label{eq_cond_mu}
			\cos(\mu_{\xi,\varepsilon}) + \frac{d-\mu_{\xi,\varepsilon}^2-2 \varepsilon \tau  m}{\sqrt{d - \mu_{\xi,\varepsilon}^2 - 4\varepsilon \tau  m}} \textup{sinc}(\mu_{\xi,\varepsilon}) = 0,
		\end{equation}
		where $\mu_{\xi,\varepsilon} := \sqrt{ d - 4\varepsilon^2\upsilon_\xi^2-4 \varepsilon \tau m  }$ and $\upsilon_\xi := \sqrt{\xi^2 + m^2}$. 

		Let us assume that there exists a nonzero function $u \in H^1(\R;\C^2)$ such that $H_{V_\varepsilon} [\xi] u = 0$. Then,
		\begin{equation*}
			\begin{aligned}
				\frac{d}{dx} u &= -i\sigma_1\left( \xi \sigma_2 + m \sigma_3 + (\eta I_2 + \tau \sigma_3) \frac{\chi_{(-\varepsilon,\varepsilon)}}{2\varepsilon}\right) u
			\end{aligned}
		\end{equation*}
		a.e. on  $\R$. Thus, there exist $w_1, w_2, w_3 \in \C^2$ such that 
		\begin{equation}\label{eq_mu_cond_ef}
			u(x) = \begin{cases} \exp(Ax)w_1, &  x \in (-\infty,-\varepsilon), \\ \exp(Bx)w_2, &x \in (-\varepsilon,\varepsilon),\\
				\exp(Ax)w_3, & x \in  (\varepsilon,\infty),\end{cases}
		\end{equation}
		where
		\begin{equation*}
			A = -i\sigma_1\big( \xi \sigma_2 + m \sigma_3\big) =\begin{pmatrix} \xi & im  \\ -im  & -\xi \end{pmatrix}  \text{ and }  B = A-i\sigma_1 (\eta I_2 + \tau \sigma_3) \frac{1}{2\varepsilon}.
		\end{equation*} 
		Note that $A$ has the distinct eigenvalues $\pm \upsilon_\xi = \pm \sqrt{\xi^2+m^2}$ and the corresponding orthogonal eigenvectors are given by $a_+ =( -im , \xi - \upsilon_\xi)$ and $a_-=(\xi - \upsilon_\xi,  -im)$.
		Since $u \in H^1(\R;\C^2)$, $u(x)$ has to converge to zero for $x \to \pm \infty$. Hence, $w_1 = c_1 a_+$ and $w_3 = c_3 a_-$ with $c_1,c_3 \in \C$. Moreover, $u \in H^1(\R;\C^2) \subset C(\R;\C^2)$ yields the conditions
		\begin{equation}\label{eq_u_A_B}
			\begin{aligned}
				\exp(-A\varepsilon)w_1 &=c_1  e^{-\varepsilon\upsilon_\xi} a_+ = \exp(-B \varepsilon)w_2\\
				\exp(A\varepsilon)w_3 &=c_3  e^{-\varepsilon\upsilon_\xi} a_- = \exp(B \varepsilon)w_2;
			\end{aligned}
		\end{equation}
		this implies
		\begin{equation}\label{eq_ev}
			c_1 a_+ - c_3 \exp(-2B\varepsilon)a_- = 0.
		\end{equation}
		Next, we write 
		\begin{equation*}
			\exp(-2B \varepsilon) =  \cos(i2B \varepsilon) - 2B \varepsilon \textup{sinc}(i2B \varepsilon).
		\end{equation*} 
		Note that $(i2B \varepsilon)^2 = \mu_{\xi,\varepsilon}^2 I_2 $ and hence $\cos(i2B \varepsilon) = \cos(\mu_{\xi,\varepsilon}) I_2 $ as well as $\textup{sinc}(i2B \varepsilon) = \textup{sinc}(\mu_{\xi,\varepsilon}) I_2 $. These considerations and $2 B \varepsilon  = 2 A \varepsilon  -i \sigma_1(\eta I_2 + \tau \sigma_3)$ yield
		\begin{equation*}
			\begin{aligned}
				\exp(-2B \varepsilon) a_- &= \cos(\mu_{\xi,\varepsilon}) a_-  -2B \varepsilon \textup{sinc}(\mu_{\xi,\varepsilon}) a_- \\
				&=\cos(\mu_{\xi,\varepsilon}) a_-  -(2 A \varepsilon  -i \sigma_1 (\eta I_2 + \tau \sigma_3) ) \textup{sinc}(\mu_{\xi,\varepsilon}) a_- \\
				&= \big(\cos(\mu_{\xi,\varepsilon}) + 2 \varepsilon \upsilon_\xi \textup{sinc}(\mu_{\xi,\varepsilon}) \big) a_- +i \sigma_1(\eta I_2 + \tau \sigma_3)  \textup{sinc}(\mu_{\xi,\varepsilon}) a_- .
			\end{aligned}
		\end{equation*}
		Since $a_+$  and $a_-$ are an orthogonal basis of $\C^2$, \eqref{eq_ev} is fulfilled if the scalar product of \eqref{eq_ev} with $a_+$ and $a_-$ is zero. This yields the system
		\begin{equation}\label{eq_mu_cond_0}
			\begin{aligned}
				0 &= c_1 |a_+|^2 - c_3 \big\langle i \sigma_1(\eta I_2 + \tau \sigma_3)  \textup{sinc}(\mu_{\xi,\varepsilon}) a_-,a_+ \big\rangle \\
				0 &= c_3 \Big( (\cos(\mu_{\xi,\varepsilon}) + 2 \varepsilon \upsilon_\xi \textup{sinc}(\mu_{\xi,\varepsilon}))|a_-|^2  \\
				&\hspace{38 pt}+  \big\langle i \sigma_1(\eta I_2 + \tau \sigma_3)  \textup{sinc}(\mu_{\xi,\varepsilon}) a_-,a_- \big\rangle \Big).
			\end{aligned}
		\end{equation}
		Note that $c_3 \neq 0$, as otherwise $c_1 =0$ and \eqref{eq_u_A_B} would imply  $w_2 =0$, and thus $w_1 = w_2 =w_3=0$, which in turn would lead to $u =0$. However, $u\neq0$  by assumption. Thus, the second line of the above system implies
		\begin{equation*}
			0 = (\cos(\mu_{\xi,\varepsilon}) + 2 \varepsilon \upsilon_\xi \textup{sinc}(\mu_{\xi,\varepsilon}))|a_-|^2  + \big\langle i \sigma_1(\eta I_2 + \tau \sigma_3)  \textup{sinc}(\mu_{\xi,\varepsilon}) a_-,a_- \big\rangle .
		\end{equation*}
		Using the relations $ \sigma_1^* = \sigma_1$, $\sigma_1 a_- = a_+$, $a_+\perp a_-$,  $\langle\sigma_3 a_-, a_+ \rangle = 2im(\xi - \upsilon_\xi)$ and $|a_-|^2 = m^2 + (\xi-\upsilon_\xi)^2$ we can simplify this equation to
		\begin{equation}\label{eq_mu_cond_1}
			\begin{aligned}
				0 =\cos(\mu_{\xi,\varepsilon}) +  \Big(2\varepsilon \upsilon_\xi -  2\frac{ (\xi - \upsilon_\xi)\tau m}{m^2+ (\xi - \upsilon_\xi)^2}\Big)\textup{sinc}(\mu_{\xi,\varepsilon}).
			\end{aligned}
		\end{equation}
		Next, we  use $m^2 = \upsilon_\xi^2 - \xi^2 = -(\xi + \upsilon_\xi)(\xi-\upsilon_\xi)$ and $2\varepsilon \upsilon_\xi  = \sqrt{d-\mu_{\xi,\varepsilon}^2-4\varepsilon \tau  m}$ to rewrite 
		\begin{equation}\label{eq_mu_cond_2}
			\begin{aligned}
				2\varepsilon \upsilon_\xi -  \frac{2 (\xi - \upsilon_\xi)\tau m}{m^2+ (\xi - \upsilon_\xi)^2} &=2\varepsilon \upsilon_\xi  -  2\frac{ (\xi - \upsilon_\xi) \tau m}{(-(\xi + \upsilon_\xi)+ (\xi - \upsilon_\xi))(\xi-\upsilon_\xi)}\\
				& = 2\varepsilon \upsilon_\xi +\frac{\tau m}{\upsilon_\xi}\\
				&=\frac{1}{2\varepsilon \upsilon_\xi} \Big( (2 \varepsilon \upsilon_\xi)^2 + 2\varepsilon \tau m \Big) \\
				&= \frac{d-\mu_{\xi,\varepsilon}^2 - 2\varepsilon \tau m}{2\varepsilon \upsilon_\xi}\\
				&=\frac{d-\mu_{\xi,\varepsilon}^2 -2\varepsilon\tau m}{\sqrt{d - \mu_{\xi,\varepsilon}^2 - 4\varepsilon \tau  m}}.
			\end{aligned}
		\end{equation}
		Plugging \eqref{eq_mu_cond_2} into \eqref{eq_mu_cond_1} gives us \eqref{eq_cond_mu}. 

		Now, we argue that the reverse direction is also true. If \eqref{eq_cond_mu} is fulfilled, then using  \eqref{eq_mu_cond_2} implies that \eqref{eq_mu_cond_1} is valid. Then, we fix a arbitrary $c_3 \in \C \setminus \{0\}$. For this  $c_3$ there exists exactly one $c_1 \in  \C$ such that \eqref{eq_mu_cond_0} is satisfied. Furthermore, \eqref{eq_ev} is also true. The choices $w_1 = c_1 a_+, w_2 = \exp(B \varepsilon)\exp(-A \varepsilon)w_1$ and $w_3 = c_3 a_-$ yield with \eqref{eq_u_A_B} that $u$ defined by \eqref{eq_mu_cond_ef} is in $H^1(\R;\C^N) = \dom H_{V_\varepsilon}[\xi]$. Moreover, by construction $u \in (\ker H_{V_\varepsilon}[\xi])\setminus \{0\}$ which implies $0 \in \sigma_{\textup{p}}(H_{V_\varepsilon}[\xi])$.

		\textit{Step~2.}
		Consider the function $a_0:[\tfrac{\pi}{2},\pi) \mapsto [0,\infty)$, $a_0(u) = -u \cot(u)$.
		It easy to see that $a_0$ is continuous and $a_0([\tfrac{\pi}{2},\pi)) = [0,\infty)$. Furthermore,
		\begin{equation*}
			\begin{aligned}
				a_0'(u) &= - \cot(u) +\frac{u}{\sin^2(u)}  = \frac{-\cos(u)\sin(u)+u}{\sin^2(u)} \\
				&= \frac{-\frac{1}{2}\sin(2u)+u}{\sin^2(u)} \geq  \frac{-\frac{1}{2}+\frac{\pi}{2}}{\sin^2(u)}>0, \qquad u \in [\tfrac{\pi}{2},\pi),
			\end{aligned}
		\end{equation*}
		and hence $a_0$ is monotonically increasing and bijective. Thus, the same holds for its inverse function 
		\begin{equation*}
			u_0:= a_0^{-1}:  [0,\infty) \mapsto [\tfrac{\pi}{2},\pi).
		\end{equation*} 
		For $a \in [0,\infty)$ we have\ $a = -u_0(a) \cot(u_0(a))$ and therefore multiplying with $\textup{sinc}(u_0(a))$ shows that $u_0$ fulfils the relation
		\begin{equation}\label{eq_u_0_relation}
			\cos(u_0(a)) + a \textup{sinc}(u_0(a)) = 0, \qquad  a \in [0,\infty).
		\end{equation}

		\textit{Step~3.} Now we use the function $u_0$ from the previous step to find for sufficiently small $\varepsilon>0$ a $\xi_\varepsilon$ such that $0 \in \sigma_{\textup{p}}(H_{V_\varepsilon}[\xi_\varepsilon])$. We start by claiming that there exists an $a_\varepsilon>0$ which fulfils
		\begin{equation}\label{eq_def_a_eps}
			a_\varepsilon = \frac{d-u_0^2(a_\varepsilon) - 2 \varepsilon \tau m}{\sqrt{d - u_0^2(a_\varepsilon) - 4 \varepsilon\tau m}}.
		\end{equation} 
		In fact, if we set
		\begin{equation*}
			b_\varepsilon := \sqrt{\min\{d,\pi^2\} - 4\varepsilon(|\tau m| +1)}
		\end{equation*}
		and choose $\varepsilon>0$ sufficiently small we can guarantee $b_\varepsilon \in (\tfrac{\pi}{2},\pi) $, and hence $u_0^{-1}(b_\varepsilon) \in (0,\infty)$. Since $u_0$ is monotonically increasing and continuous,  the function 
		\begin{equation*}
			F:[0 , u_0^{-1}(b_\varepsilon)] \to \R,  \quad F(a) =  a - \frac{d-u_0^2(a)-2 \varepsilon \tau m}{\sqrt{d - u_0^2(a) - 4 \varepsilon \tau m}}
		\end{equation*}
		is continuous and well-defined. The properties of the function $u_0$  and the assumption $d > \tfrac{\pi^2}{4}$ show that 
		\begin{equation*}
			F(0) = -\frac{d-\frac{\pi^2}{4}-2 \varepsilon \tau  m}{ \sqrt{d- \frac{\pi^2}{4} -4 \varepsilon \tau  m}}
		\end{equation*}
		 is smaller than zero for sufficiently small $\varepsilon>0$. Moreover, since $u_0^{-1}$ is continuous and $\lim_{b \to \pi} u_0^{-1}(b) = \infty$, we get
		  \begin{equation*}
		  	\begin{aligned}
		  	\lim_{\varepsilon \to 0} F(u_0^{-1}(b_\varepsilon)) &=  \lim_{\varepsilon \to 0} \Bigl(u_0^{-1}(b_\varepsilon) - \frac{d-\min\{d,\pi^2\} + 4\varepsilon(|\tau m| +1) -2\varepsilon\tau m}{\sqrt{d-\min\{d,\pi^2\} + 4\varepsilon(|\tau m| +1) -4\varepsilon \tau m}}\Bigr).
		  	\\
		  	&= \begin{cases}
		  		u_0^{-1}(\sqrt{d}), & d < \pi^2,\\
		  		\infty, & d \geq \pi^2,
		  	\end{cases}\\
	  			&>0. 
	  		\end{aligned}
		  \end{equation*}
	  	Thus, $F(u_0^{-1}(b_\varepsilon)) >0$ if $\varepsilon >0$ is sufficiently small.
	  	Hence, there exists an $a_\varepsilon \in (0, u_0^{-1}(b_\varepsilon))$ such that \eqref{eq_def_a_eps} is fulfilled. 

		For this $a_\varepsilon $ we also have
		\begin{equation*}
			\begin{aligned}
				&d-u_0^2(a_\varepsilon)-4\varepsilon^2m^2 -4\varepsilon \tau m \\
				&\qquad > d- u_0^2(u_0^{-1}(b_\varepsilon)) -  4\varepsilon^2m^2 -4\varepsilon \tau m \\
				&\qquad= d-\min\{d,\pi^2\} + 4\varepsilon(|\tau m| +1) -4\varepsilon^2 m^2 -4\varepsilon \tau m \\
				&\qquad > 0
			\end{aligned}
		\end{equation*}
		for sufficiently small $\varepsilon>0$. Thus, 
		\begin{equation}\label{eq_def_xi_eps}
			\xi_{\varepsilon} := \frac{1}{2\varepsilon}\sqrt{d-u_0^2(a_\varepsilon)  - 4\varepsilon^2m^2-4\varepsilon \tau m} > 0
		\end{equation} 
		is well-defined. From \eqref{eq_def_xi_eps} and the definition of $\mu_{\xi,\varepsilon}$ below \eqref{eq_cond_mu} it follows that
		\begin{equation*}
			u_0(a_\varepsilon) = \sqrt{d - 4\varepsilon^2 \upsilon_{\xi_\varepsilon}^2 - 4 \varepsilon \tau m}= \mu_{\xi_\varepsilon,\varepsilon},
		\end{equation*}
		and plugging this expression into \eqref{eq_def_a_eps} yields 
		\begin{equation*}
			a_\varepsilon = \frac{d-\mu_{\xi_\varepsilon,\varepsilon}^2 - 2\varepsilon \tau  m}{\sqrt{d - \mu_{\xi_\varepsilon,\varepsilon}^2 - 4\varepsilon \tau  m}}.
		\end{equation*}
		Combining these relations with \eqref{eq_u_0_relation} shows that
		\eqref{eq_cond_mu} is fulfilled for $\xi = \xi_\varepsilon$. Thus, $0 \in \sigma_{\textup{p}}(H_{V_\varepsilon}[\xi_\varepsilon])$ by \textit{Step~1}.


		\textit{Step~4.}
		Finally, we show in this step $0 \in \sigma(H_{V_\varepsilon})$ for $\varepsilon>0$ chosen sufficiently small. This follows from  \cite[Theorem XIII.85 (d)]{RS77} if we can show that for all $\delta >0$ there is a $\gamma_\delta >0$  such that $(-\delta,\delta) \cap \sigma(H_{V_\varepsilon}[\xi]) \neq \emptyset$ for all $\xi \in (\xi_{\varepsilon} - \gamma_\delta, \xi_{\varepsilon} + \gamma_\delta)$.  We assume that our claim is not true. In this case there exists a $\delta' > 0$ and a sequence $(\xi_{n})_{n \in \N}$ such that $\xi_n \rightarrow \xi_{\varepsilon}$ for $n\to\infty$ and $(-\delta',\delta') \cap \sigma(H_{V_\varepsilon}[\xi_n]) = \emptyset$ for all $n \in \N$. Note that 
		\begin{equation*}
			\begin{aligned}
				&\norm{(H_{V_\varepsilon}[\xi_{\varepsilon}]-z)^{-1}-(H_{V_\varepsilon}[\xi_n]-z)^{-1}}_{ L^2(\R;\C^2) \to L^2(\R;\C^2)} \\
				&= \norm{(H_{V_\varepsilon}[\xi_{\varepsilon}]-z)^{-1}\sigma_2(\xi_n- \xi_{\varepsilon})(H_{V_\varepsilon}[\xi_n]-z)^{-1}} _{ L^2(\R;\C^2) \to L^2(\R;\C^2)}\\
				&\leq \frac{1}{(\textup{Im } z)^2} \abs{\xi_n - \xi_{\varepsilon}} \rightarrow 0,\quad n \to \infty,
			\end{aligned}
		\end{equation*}
		holds for $z \in \C \setminus \R$, i.e., $H_{V_\varepsilon}[\xi_n]$ converges in norm resolvent sense to $H_{V_\varepsilon}[\xi_{\varepsilon}]$. Moreover,  $(-\delta',\delta') \cap \sigma(H_{V_\varepsilon}[\xi_n]) = \emptyset$, $n \in \N$, and \cite[Theorem VIII.24 (a)]{RS72} imply the contradiction $(-\delta',\delta') \cap \sigma(H_{V_\varepsilon}[\xi_{\varepsilon}]) = \emptyset$.
	\end{proof}



	\begin{remark}\label{remco}
	    We note that in the situation of Theorem~\ref{theo_main_3} one can even show $\sigma(H_{V_\varepsilon}) = \R$ for all $\varepsilon>0$ which are sufficiently small; cf. \cite[Theorem~6.5]{SL24}. Furthermore, the statement of Theorem~\ref{theo_main_3}, that $H_{V_\varepsilon}$ does not converge in the norm resolvent sense to $H_{\widetilde{V} \delta_\Sigma}$, remains true in more general situations, e.g., if $\Sigma \subset \R^{\theta}$, $\theta \in \{2,3\}$, is as in  Section~\ref{sec_not}~\eqref{it_def_Sigma} and contains a flat part, see 
	    \cite[Theorem~6.7]{SL24} for more details.
	\end{remark}	




	\section{Approximation of Dirac operators with $\delta$-shell potentials supported on rotated $C^2_b$-graphs}\label{sec_C^2_b_graphs}

	The main aim of this section is to prove Theorem~\ref{theo_main_1} for the case that $\Sigma$ is a rotated $C^2_b$-graph. In this case, there exist $\zeta \in C^2_b(\R^{\theta-1};\R)$ and $\kappa \in \textup{SO}(\theta)$ such that 
	\begin{equation}\label{eq_rotated_graph}
		\begin{aligned}
			\Omega_+ &= \{\kappa (x',x_\theta): (x',x_\theta) \in \R^{\theta} \textup{ and } x_\theta < \zeta(x') \}, \\
			 \Omega_- &= \R^\theta \setminus \overline{\Omega_+} = \{\kappa (x',x_\theta):(x',x_\theta) \in \R^{\theta} \textup{ and } x_\theta > \zeta(x')  \}, \\
			\Sigma &= \partial \Omega_+ = \Sigma_{\zeta,\kappa} := \{ \kappa(x',\zeta(x')) : x' \in \R^{\theta-1}\}.
		\end{aligned}
	\end{equation}

	To emphasize the importance of this result, let us rephrase  Theorem~\ref{theo_main_1} for the special case of a rotated $C^2_b$-graph.
	\begin{theo}\label{theo_rotated_graph}
		Let  $\Sigma$ be a rotated $C^2_b$-graph, let $q\in L^\infty((-1,1);[0,\infty))$ with $\int_{-1}^1 q(s) \,ds =1$ and assume that
		$\eta, \tau \in  C^1_b(\Sigma;\R)$ satisfy the condition 
		\begin{equation}\label{eq_d_cond2}
		\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4}, \qquad d = \eta^2 - \tau^2.
	\end{equation}
		 Let $V$ and $V_\varepsilon$ be  as in \eqref{eq_V} and  \eqref{eq_V_eps}, and define $\widetilde V$ by \eqref{eq_scaling}.
		Then, for all $z \in \C\setminus\R$  and $r \in (0,\tfrac{1}{2} )$ there exist $C>0$ and $\varepsilon_3 \in (0,\varepsilon_1)$ such that
		\begin{equation*}
			\norm{(H_{V_\varepsilon}-z)^{-1} - (H_{\widetilde{V}\delta_\Sigma}-z)^{-1}}_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N)} \leq C \varepsilon^{1/2-r}, \quad  \varepsilon \in (0, \varepsilon_3).
		\end{equation*} 
		In particular, $H_{V_\varepsilon}$ converges to $H_{\widetilde{V}\delta_\Sigma}$ in the norm resolvent sense as $\varepsilon \to 0$. 
	\end{theo}
	This theorem is a direct consequence of Proposition~\ref{prop_resolvent_convergence},  Proposition~\ref{prop_inv_I+BVq} and Proposition~\ref{prop_uniform_bdd_inv_B_eps}.

	Section~\ref{sec_C^2_b_graphs} is devoted to proving these propositions. We proceed as follows: In Section~\ref{sec_free_Dirac} we introduce various integral operators associated to the free Dirac operator. Then, in Section~\ref{sec_res_conv} we recall comparable resolvent  formulas for $H_{\widetilde{V}\delta_\Sigma}$ and $H_{V_\varepsilon}$ from \cite{BHS23}. Moreover, relying again on results from \cite{BHS23} we provide convergence results for the operators involved in these resolvent formulas and end the section by stating Proposition~\ref{prop_resolvent_convergence} which gives abstract conditions for the norm resolvent convergence of $H_{V_\varepsilon}$. Afterwards, we show in Section~\ref{sec_B_0} and Section~\ref{sec_I+B_eps} (in Proposition~\ref{prop_inv_I+BVq} and Proposition~\ref{prop_uniform_bdd_inv_B_eps}, respectively) that these conditions are met if \eqref{eq_d_cond2} is fulfilled. 

	Finally, let us mention that the restriction to  rotated $C^2_b$-graphs is only necessary in Section~\ref{sec_I+B_eps} and all results  from the Sections~\ref{sec_free_Dirac}--\ref{sec_B_0} remain valid for the general class of hypersurfaces described in Section~\ref{sec_not}~\eqref{it_def_Sigma}.

	\subsection{The free Dirac operator and associated integral operators}\label{sec_free_Dirac}

	Let $m \in \mathbb{R}$ and recall that the Dirac matrices $\alpha_1, \dots, \alpha_\theta, \beta \in \mathbb{C}^{N \times N}$ are given by~\eqref{def_Dirac_matrices_2d}--\eqref{def_Dirac_matrices_3d}. The free Dirac operator $H$ is the differential operator in $L^2(\mathbb{R}^\theta; \mathbb{C}^N)$ given by
	\begin{equation}\label{eq_def_free_Dirac}
		\begin{aligned}
			H  &:= - i (\alpha \cdot \nabla)  + m \beta , \qquad \dom H := H^1(\R^\theta;\C^N).
		\end{aligned}
	\end{equation}
	With the help of the Fourier transform one gets that $H$ is self-adjoint in $L^2(\R^\theta;\C^N)$ and $\sigma(H) = \left(-\infty, -\abs{m}\right] \cup \left[\abs{m}, \infty \right)$, see for instance \cite[Section~2]{BHT23} for $\theta=2$ and \cite[Theorem 1.1]{T92} for $\theta =3$. For $z \in \rho(H) = \C \setminus \sigma(H)$ we have
	\begin{equation*}%\label{eq_resolvent_free_op}
		R_z u(x) := (H-z)^{-1} u(x) = \int_{\mathbb{R}^\theta} G_z(x-y) u(y) \,d y, \qquad u \in L^2(\mathbb{R}^\theta; \mathbb{C}^N), ~x \in \mathbb{R}^\theta,
	\end{equation*}
	where  $G_z$ is given for $\theta=2$ and $x \in \mathbb{R}^2 \setminus \{ 0 \}$ by
	\begin{equation}\label{eq_G_z_2D}
		\begin{aligned}
			G_z(x) &= \frac{\sqrt{ z^2-m^2}}{2\pi} K_1\big(-i \sqrt{ z^2-m^2}\abs{x}\big)\frac{\alpha \cdot x}{\abs{x}} 
			\\
			&\hspace{100 pt}+\frac{1}{2\pi} K_0\big(-i \sqrt{ z^2-m^2}\abs{x}\big)\left(m\beta +  z I_2\right)
		\end{aligned}
	\end{equation}	
	and for $\theta=3$ and $x \in \mathbb{R}^3 \setminus \{ 0 \}$ by
	\begin{equation}\label{eq_G_z_3D}
		G_ z(x) = \left(  z I_4 + m \beta + i\left( 1 - i \sqrt{ z^2 -m^2}\abs{x} \right) \frac{ \alpha \cdot x }{\abs{x}^2}\right)\frac{e^{i\sqrt{ z^2 -m^2} \abs{x}}}{4 \pi \abs{x}};
	\end{equation}
	cf., e.g., \cite{BHOP20, BHSS22, T92}.
	Here, $K_0$ and $K_1$ denote the modified Bessel functions of the second kind of order zero and one, respectively.
	Note that $R_z$ is bounded in $L^2(\mathbb{R}^\theta; \mathbb{C}^N)$ and it can also be viewed as a bounded operator from $L^2(\R^\theta;\C^N)$ to $H^1(\R^\theta;\C^N)$.

	We move on to the discussion of potential and boundary integral operators associated with the free Dirac operator. In the following, let $z \in \rho(H) = \mathbb{C} \setminus ((-\infty, -|m|] \cup [|m|, \infty))$ be fixed and let $\Omega_\pm$ and $\Sigma \subset \mathbb{R}^\theta$ be as in \eqref{eq_rotated_graph}. First, we introduce the potential operator $\Phi_z: L^2(\Sigma; \mathbb{C}^N) \rightarrow L^2(\mathbb{R}^\theta; \mathbb{C}^N)$ by
	\begin{equation} \label{def_Phi_z}
		\begin{aligned}
			\Phi_ z   \varphi(x) &:= \int_\Sigma G_ z (x-y_\Sigma) \varphi(y_\Sigma) \,d\sigma(y_\Sigma),  \qquad \varphi \in L^2(\Sigma; \mathbb{C}^N),~x \in \R^\theta.
		\end{aligned}
	\end{equation}
	We note that $\Phi_z$ is indeed well-defined and bounded, see \cite[Lemma 2.1]{AMV14}. 
	Further properties of $\Phi_z$ are summarized in the following proposition. These results are well-known and a proof can be found in \cite[Appendix C]{BHS23}.

	\begin{proposition}\label{prop_Phi_z}
		Let $z \in \rho(H) = \mathbb{C} \setminus ((-\infty, -|m|] \cup [|m|, \infty))$ and let $\Phi_z$ be given by~\eqref{def_Phi_z}. Then, the following is true:
		\begin{itemize}
			\item[$\textup{(i)}$] For any $ r \in [0, \tfrac{1}{2}]$ the operator $\Phi_z$ gives rise to a bounded operator
			\begin{equation*}
				\Phi_z :H^r(\Sigma;\C^N) \to H^{r+1/2}(\R^\theta \setminus \Sigma ;\C^N).\\
			\end{equation*}
			\item[$\textup{(ii)}$] For $\varphi \in H^{1/2}(\Sigma; \mathbb{C}^N)$ one has $(-i (\alpha \cdot \nabla) + m \beta - zI_N) (\Phi_z \varphi)_\pm = 0$. 
			\item[$\textup{(iii)}$] The adjoint $\Phi_z^*: L^2(\mathbb{R}^\theta; \mathbb{C}^N) \to  L^2(\Sigma; \mathbb{C}^N)$ of $\Phi_z$ acts on $u \in L^2(\mathbb{R}^\theta; \mathbb{C}^N)$ as
			\begin{equation*}% \label{eq_Phi_star}
				\Phi_{z}^* u(x_\Sigma) = \int_{\R^\theta} G_{\overline{ z}}(x_\Sigma -y) u(y) \, dy = \tr R_{\overline{z}} u(x_\Sigma), \qquad x_\Sigma \in \Sigma,
			\end{equation*}
			and $\Phi_z^*$ gives rise to a bounded operator $\Phi_z^*: L^2(\mathbb{R}^\theta; \mathbb{C}^N) \rightarrow H^{1/2}(\Sigma; \mathbb{C}^N)$.
		\end{itemize}
	\end{proposition}

	Finally, we introduce a family of boundary integral operators for the Dirac equation. Let $z \in \rho(H) = \mathbb{C} \setminus ((-\infty, -|m|] \cup [|m|, \infty))$. Then, we define the map $\mathcal{C}_z: H^{1/2}(\Sigma; \mathbb{C}^N) \rightarrow H^{1/2}(\Sigma; \mathbb{C}^N)$ by
	\begin{equation} \label{def_C_z}
		\mathcal{C}_z \varphi := \frac{1}{2} ( \tr^+  + \tr^-)\Phi_z \varphi, \qquad \varphi \in H^{1/2}(\Sigma; \mathbb{C}^N).
	\end{equation}
	We remark that the operator $\mathcal{C}_z$ can be represented as a strongly singular boundary integral operator, see for instance \cite[equation (4.5) and Proposition 4.4 (ii)]{BHSS22} for the case that $\Omega_+$ is bounded. However, for our purposes the representation in \eqref{def_C_z} is more convenient.
	The basic properties of $\mathcal{C}_z$ are stated in the following proposition. Again, a proof can be found in \cite[Appendix C]{BHS23}.

	\begin{proposition} \label{prop_C_z}
		Let $z \in \rho(H) = \mathbb{C} \setminus ((-\infty, -|m|] \cup [|m|, \infty))$ and let $\mathcal{C}_z$ be given by~\eqref{def_C_z}. Then, the following is true:
		\begin{itemize}
			\item[$\textup{(i)}$] For any $r \in [-\frac{1}{2},\frac{1}{2}]$ the map $\mathcal{C}_z$ has a bounded extension $\mathcal{C}_z: H^r(\Sigma;\C^N) \rightarrow H^r(\Sigma;\C^N)$.
			\item[$\textup{(ii)}$] For any $r \in(0,\frac{1}{2}]$ and $\varphi \in H^r(\Sigma;\C^N)$ one has
			\begin{equation*}%\label{eq_C_z_formula}
				\mathcal{C}_ z \varphi =  \pm \frac{i}{2}  (\alpha \cdot \nu) \varphi +  \tr^\pm \left(	\Phi_ z   \varphi\right)_{\pm}. 
			\end{equation*}
		\end{itemize}
	\end{proposition}

	\subsection{Formulas and corresponding convergence estimates for the resolvents of $H_{V_\varepsilon}$ and $H_{\widetilde{V}\delta_\Sigma}$}\label{sec_res_conv}
	In this section we introduce resolvent formulas for $H_{V_\varepsilon}$ and for  $H_{\widetilde{V}\delta_\Sigma}$ in terms of (Bochner) integral operators and study their convergence properties.

	Recall that $\mathcal{B}^0(\Sigma) = L^2((-1,1);L^2(\Sigma;\C^N))$ and that $W$ is the Weingarten map associated to $\Sigma$; cf. \cite[Definition 2.3]{BHS23} and \cite[Definition 2.2]{BEHL17}. We (formally) define for $\varepsilon>0$ and $z \in \rho(H)$ the following integral operators:
	\begin{subequations} %\label{def_ABC_integral_rep} 
		\begin{align}
			\label{def_A_eps}
			&\hspace{ 15pt}\begin{aligned}
				A_\varepsilon(z) &: \mathcal{B}^0(\Sigma) \to L^2(\R^{\theta};\C^N),\\
				A_\varepsilon( z)f(x) &:= \int_{-1}^1\int_{\Sigma} G_ z(x-y_\Sigma -\varepsilon s\nu(y_\Sigma))   f(s)(y_\Sigma)\\
				&\hspace{120 pt} \cdot \det(I-\varepsilon sW(y_\Sigma)) \, d\sigma(y_\Sigma) \,  ds,
			\end{aligned}\\
			\label{def_B_eps}
			&\begin{aligned}
				B_\varepsilon(z) &: \mathcal{B}^0(\Sigma) \to \mathcal{B}^0(\Sigma),\\
				B_\varepsilon( z)f(t)(x_\Sigma) &:=   \int_{-1}^1 \int_{\Sigma} G_ z(x_\Sigma +\varepsilon t\nu(x_\Sigma) -y_\Sigma - \varepsilon s\nu(y_\Sigma))   f(s)(y_\Sigma)\\
				&\hspace{120 pt }\cdot \det(I- \varepsilon sW(y_\Sigma)) \, d\sigma(y_\Sigma) \, ds,
			\end{aligned}\\
			\label{def_C_eps}
			&\begin{aligned}
				C_\varepsilon(z) &: L^2(\R^{\theta};\C^N) \to \mathcal{B}^0(\Sigma),  \\
				C_\varepsilon( z)u(t)(x_\Sigma) &:= \int_{\R^\theta} G_ z(x_\Sigma +  \varepsilon t\nu(x_\Sigma) -y) u(y)\, dy,
			\end{aligned}
		\end{align}
	\end{subequations}
	In the next proposition the well-definedness of these operators and also their connection to the resolvent of $H_{V_\varepsilon}$ are discussed.
	\begin{proposition}\label{prop_res_formula_eps}
		Let $z \in \rho(H)$, $q$ be as in \eqref{eq_q2}, $V$ be as in \eqref{eq_V}, $H_{V_\varepsilon} $ be  defined as in \eqref{eq_H_V_eps} and $\varepsilon_1>0$ be as below \eqref{eq_iota}. Then, for all $\varepsilon \in (0,\varepsilon_1)$ the operators given in \eqref{def_A_eps}--\eqref{def_C_eps} are well-defined and if $-1 \in \rho(B_\varepsilon(z)Vq)$, then $z \in \rho(H_{V_\varepsilon})$ and the resolvent identity
		\begin{equation*}%\label{eq_res_H_eps}
			(H_{V_\varepsilon}-z)^{-1} = (H-z)^{-1} - A_\varepsilon(z)Vq(I+B_\varepsilon(z)Vq)^{-1}C_\varepsilon(z)
		\end{equation*}
		holds.
	\end{proposition}
	\begin{proof}
		Note that $\varepsilon_1 > 0$ is chosen in exactly the same way as in \cite[Proposition~2.4]{BHS23}. Thus, the assertions follow from \cite[(3.1a)--(3.1c), Proposition~3.1 and Proposition~3.2]{BHS23}.
	\end{proof}
%	\begin{remark}\label{rem_eps}
%		If $\Sigma$ is a  hyperplane, then $\varepsilon_1$ can be chosen equal to $\infty$. This becomes apparent, when one sees how $\varepsilon_1$ is chosen in \cite[Proposition~2.4]{BHS23}. Moreover, in this case $W=0$.
%	\end{remark}
	Next, we introduce the operators $A_0(z)$, $B_0(z)$, and $C_0(z)$ which will turn out to be the limit operators of $A_\varepsilon(z)$, $B_\varepsilon(z)$, and $C_\varepsilon(z)$, respectively. For $z \in \rho (H)$, they are defined by
	\begin{equation*}% \label{def_ABC_integral_0} 
		\begin{aligned}
			A_0(z) &: \mathcal{B}^0(\Sigma) \to L^2(\R^{\theta};\C^N),\\
			A_0( z)f &:= \Phi_z \int_{-1}^1 f(t) \,dt, \\
			B_0(z) &: \mathcal{B}^0(\Sigma) \to \mathcal{B}^0(\Sigma),\\
			B_0( z) f(t)&:= \frac{i}{2}(\alpha \cdot \nu)\int_{-1}^1 \sign(t-s)f(s) \,ds + \mathcal{C}_z \int_{-1}^1  f(s) \, ds,\\
		C_0(z) &: L^2(\R^{\theta};\C^N) \to \mathcal{B}^0(\Sigma),  \\
			C_0( z)u(t) &:= \Phi_{\overline{z}}^*u,
		\end{aligned}
	\end{equation*}
	where  $\Phi_z$ is the operator defined in $\eqref{def_Phi_z}$  and $\mathcal{C}_z$ is the extension of the operator defined in  \eqref{def_C_z} to $L^2(\Sigma;\C^N)$, see also Proposition~\ref{prop_C_z}~(i). Using the identifications described in Section~\ref{sec_not}~\eqref{it_Bochner}, one sees that the operators $A_0(z)$, $B_0(z)$, and $C_0(z)$ are well-defined and bounded since by Proposition~\ref{prop_Phi_z}~(i) $\Phi_z$ is a bounded operator from $L^2(\Sigma;\C^N)$ to $L^2(\R^{\theta};\C^N)$ and by Proposition~\ref{prop_C_z}~(i) $\mathcal{C}_z$ is a bounded operator in $L^2(\Sigma;\C^N)$. The operator $B_0(z)$ can also be represented by 
	\begin{equation}\label{B_0_alt_rep}
		B_0(z) = T(\alpha \cdot \nu) + \mathfrak{I} \mathcal{C}_z \mathfrak{I}^*,
	\end{equation}
	where  $\mathfrak{J}$ is defined in Section~\ref{sec_not}~\eqref{it_Bochner} and
	\begin{equation*}% \label{def_TFI}
		\begin{aligned}
			T &:\mathcal{B}^0(\Sigma) \to \mathcal{B}^0(\Sigma), \qquad
			&Tf(t) &:= \frac{i}{2}  \int_{-1}^1 \textup{sign}(t-s)f(s) \,ds.
		\end{aligned}
	\end{equation*}
	Moreover, since $\mathcal{C}_z$  also acts as a bounded operator in $H^r(\Sigma;\C^N)$ for $r \in [-\tfrac{1}{2},\tfrac{1}{2}]$, see Proposition~\ref{prop_C_z}~(i), $B_0(z)$ acts also as a bounded operator in $\mathcal{B}^r(\Sigma)$ for $r \in [-\tfrac{1}{2},\tfrac{1}{2}]$.

	Our next goal is to show a  resolvent formula for $H_{\widetilde{V}\delta_\Sigma}$, which is defined by \eqref{eq_def_H_V_tilde}, in terms of $A_0(z), B_0(z)$, and $C_0(z)$. 
	\begin{proposition}\label{prop_H_V_tilde}
		Let  $z \in \rho(H)$, $q$ and $V= \eta I_N + \tau \beta$ be as described in \eqref{eq_q2} and \eqref{eq_V}, respectively, and $ d= \eta^2-\tau^2$ such that \eqref{eq_scaling_cond} is fulfilled. Moreover, let $(\widetilde{\eta},\widetilde{\tau}) = \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) (\eta,\tau)$, $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta$ and $\widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2$ fulfil \eqref{eq_d_tilde_non_crit}. If $-1 \in  \rho(B_0(z)Vq)$, then for the self-adjoint operator $H_{\widetilde{V} \delta_\Sigma}$ the resolvent identity 
		\begin{equation*}%\label{eq_resH_V_tilde}
			(H_{\widetilde{V}\delta_\Sigma}-z)^{-1} = (H-z)^{-1} - A_0(z)Vq(I+B_0(z)Vq)^{-1}C_0(z)
		\end{equation*}
		is valid.
	\end{proposition}
	\begin{proof}
		Since $\widetilde{d}$ fulfils \eqref{eq_d_tilde_non_crit}, $H_{\widetilde{V}\delta_\Sigma}$ is self-adjoint by the text above \eqref{eq_d_tilde_non_crit}. Moreover, in the same way as in \cite[below eq.~(4.15)]{BHS23} one can show that if $-1 \in  \rho(B_0(z)Vq)$,  then  for $u \in L^2(\R^\theta;\C^N)$ holds
		\begin{equation*}
			\big((H-z)^{-1} - A_0(z)Vq(I+B_0(z)Vq)^{-1}C_0(z)\big) u \in \dom H_{\widetilde{V}\delta_\Sigma}
		\end{equation*}
		and 
		\begin{equation*}
			(H_{\widetilde{V}\delta_\Sigma}-z)\big((H-z)^{-1} - A_0(z)Vq(I+B_0(z)Vq)^{-1}C_0(z)\big)u =u.
		\end{equation*}
		This shows that the resolvent identity is true. 
	\end{proof}
	In the next proposition we summarize the convergence properties of $A_\varepsilon(z)$,$B_\varepsilon(z)$, and $C_\varepsilon(z)$; cf. \cite[Proposition~3.7, Proposition~3.8, and Proposition~3.10]{BHS23} for the proof.
	\begin{proposition}\label{prop_conv_res}
		Let $z \in \rho(H)$ and $\varepsilon_1>0$ be as below \eqref{eq_iota}. Then, there exists an $\varepsilon_2 \in (0,\varepsilon_1)$ such that  $A_\varepsilon(z)$, $B_\varepsilon(z)$, and $C_\varepsilon(z)$
		are uniformly bounded operators with respect to  $\varepsilon \in (0, \varepsilon_2)$. Moreover,  $C_\varepsilon(z)$ and $C_0(z)$ act also as uniformly bounded operators from  $L^2(\R^{\theta};\C^N)$ to $\mathcal{B}^{1/2}(\Sigma)$ and for $r \in (0,\frac{1}{2})$ there exists a $C >0$ such that one has for $\varepsilon \in (0,\varepsilon_2)$
		\begin{equation*}
			\begin{aligned}
				\norm{A_\varepsilon(z)-A_0(z)}_{0 \to L^2(\R^{\theta};\C^N)} &\leq C \varepsilon^{1/2-r}, \\
				\norm{B_\varepsilon(z)-B_0(z)}_{1/2 \to 0} &\leq C \varepsilon^{1/2-r},\\
				\norm{C_\varepsilon(z)-C_0(z)}_{L^2(\R^{\theta};\C^N) \to 0} &\leq C \varepsilon^{1/2-r}.
			\end{aligned}
		\end{equation*}
	\end{proposition}


	After summarizing the convergence properties of $A_\varepsilon(z)$, $B_\varepsilon(z)$, and $C_\varepsilon(z)$ we state in Proposition~\ref{prop_resolvent_convergence} conditions for the norm resolvent convergence of $H_{V_\varepsilon}$. 



	\begin{proposition}[{\cite[Proposition~3.12 and Remark 4.5]{BHS23}}]\label{prop_resolvent_convergence}
		Let  the assumptions of Proposition~\ref{prop_H_V_tilde} hold. Moreover, let $r \in (0,\frac{1}{2})$ and $\varepsilon_2>0$ be as in Proposition \ref{prop_conv_res}. Assume that the following conditions hold: 
		\begin{itemize}
			\item[(i)] There exists an $\varepsilon_3 \in (0,\varepsilon_2)$ such that  $(I+B_\varepsilon(z)Vq)^{-1}$ exists for $\varepsilon \in (0,\varepsilon_3)$ and is uniformly bounded in $\mathcal{B}^0(\Sigma)$.
			\item[(ii)] $I + B_0(z)Vq$ is bijective in $\mathcal{B}^{1/2}(\Sigma)$.
		\end{itemize}
		Then,
		\begin{equation*}
			\norm{(H_{V_\varepsilon}-z)^{-1} - (H_{\widetilde{V}\delta_\Sigma}-z)^{-1}}_{L^2(\R^\theta;\C^N) \to L^2(\R^\theta;\C^N)} \leq C \varepsilon^{1/2-r} 
		\end{equation*}
		for $\varepsilon \in (0,\varepsilon_3)$. In particular, $H_{V_\varepsilon}$ converges for $\varepsilon \to 0$ to $H_{\widetilde{V}\delta_\Sigma}$ in norm resolvent sense.
	\end{proposition}
%	\begin{proof}
