%		\begin{equation*}
%			\norm{(H_{V_\varepsilon} -z)^{-1} -(H_{\widetilde{V}\delta_\Sigma}-z)^{-1}}_{L^2(\R^{\theta};\C^N) \to L^2(\R^{\theta};\C^N) } \leq C \varepsilon^{1/2-r}.
