	According to Proposition~\ref{prop_resolvent_convergence} it is essential to study the operators $I + B_0(z)Vq$ and $I + B_\varepsilon(z)Vq$ in order to find explicit conditions for the norm resolvent convergence of $H_{V_\varepsilon}$. In Section~\ref{sec_B_0} and Section~\ref{sec_I+B_eps} we show that \eqref{eq_d_cond2} guarantees that the requirements (i) and (ii) of Proposition~\ref{prop_resolvent_convergence} are met.

	\subsection{Analysis of $I + B_0(z)Vq$}\label{sec_B_0}
	We study the operator $I + B_0(z)Vq$ and are particularly interested under which conditions (ii) of Proposition~\ref{prop_resolvent_convergence} is fulfilled, i.e. under which conditions  $I + B_0(z)Vq$ is bijective in $\mathcal{B}^{1/2}(\Sigma)$. First, we state an auxiliary result about the invertibility of $I + \mathcal{C}_z \widetilde V$ with $\mathcal{C}_z$ defined by \eqref{def_C_z}, see also Proposition~\ref{prop_C_z}~(i).
	\begin{lemma}\label{lem_I+C_z_inverse}
		Let $z \in \C\setminus\R$, $r \in [0,\tfrac{1}{2}]$, $\widetilde{\eta},\widetilde{\tau} \in C^1_b(\Sigma;\R)$, and $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta$ such that $\widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2$ fulfils \eqref{eq_d_tilde_non_crit}.
		Then, the operator $I + \mathcal{C}_z \widetilde V$ is continuously invertible in $H^{r}(\Sigma;\C^N)$.   
	\end{lemma}
	\begin{proof}
		We split the proof in three steps. In \textit{Step~1} we show that   $\widetilde{V}$ and $\mathcal{C}_z$ act  as bounded operators in $H^r(\Sigma;\C^N)$ for $r \in [0,\tfrac{1}{2}]$ and $z \in \C \setminus \R$. Afterwards, we show in \textit{Step~2} that for $z \in \C \setminus \R$ the operator $I + \widetilde{V}\mathcal{C}_z$ is continuously invertible  in $H^{1/2}(\Sigma;\C^N)$. In \textit{Step~3} we use  \textit{Step~1~\&~2}  to  prove the assertion.

		\textit{Step~1.} Let $z \in \C \setminus \R$ and $r \in [0,\tfrac{1}{2}]$. The assumption $\widetilde{\eta},\widetilde{\tau} \in C^1_b(\Sigma;\R)$ implies $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta \in C^1_b (\Sigma;\C^{N \times N}) \subset W^1_\infty(\Sigma;\C^{N \times N})$. Hence, $\widetilde{V}$ induces a bounded multiplication operator in $H^r(\Sigma;\C^N)$  which is bounded by $\|\widetilde{V}\|_{W^1_\infty(\Sigma;\C^{N \times N})}$. Moreover, $\mathcal{C}_z$ acts as a bounded operator in $H^r(\Sigma;\C^N)$ by Proposition~\ref{prop_C_z}~(i).

		\textit{Step~2.} We already know from \textit{Step~1} that $\mathcal{C}_z$ and $\widetilde{V}$  act as bounded operators in $H^{1/2}(\Sigma;\C^N)$ for $z \in \C\setminus\R$. Hence, in order to prove that $I + \widetilde{V}\mathcal{C}_z$ is continuously invertible in $H^{1/2}(\Sigma;\C^N)$, it suffices to show that $I + \widetilde{V}\mathcal{C}_z$ is bijective in $H^{1/2}(\Sigma;\C^N)$. We begin with the injectivity. Let $\psi \in H^{1/2}(\Sigma;\C^N)$ such that $ (I+ \widetilde{V}\mathcal{C}_z)\psi = 0$. We set $u = \Phi_z \psi$ with $\Phi_z$ defined by \eqref{def_Phi_z}. Then, Proposition~\ref{prop_Phi_z}~(i) implies $u \in H^{1}(\R^\theta \setminus  \Sigma;\C^N)$. Furthermore, Proposition~\ref{prop_Phi_z}~(ii) yields  $(- i (\alpha \cdot \nabla) + m \beta -z I_N)u_{\pm} = 0$ and Proposition~\ref{prop_C_z}~(ii) gives us \begin{equation}\label{eq_u_trace_properties}
			i(\alpha \cdot \nu)(\tr^+ - \tr^-)u = \psi \quad \textup{and} \quad \frac{1}{2}(\tr^+ + \tr^-)u = \mathcal{C}_z \psi.
		\end{equation}
		Thus, \eqref{eq_u_trace_properties} leads to
		\begin{equation}\label{eq_u_trace_properties_0}
			i(\alpha \cdot \nu)(\tr^+ - \tr^-)u +  \widetilde{V}\frac{1}{2}(\tr^+ + \tr^-)u= \psi+   \widetilde{V}\mathcal{C}_z\psi= 0
		\end{equation}
		and hence $u \in \ker (H_{\widetilde{V}\delta_\Sigma} -z)$. Since $\widetilde{d}$ fulfils \eqref{eq_d_tilde_non_crit}, $H_{\widetilde{V}\delta_\Sigma}$ is by the text above \eqref{eq_d_tilde_non_crit} self-adjoint and therefore $\ker (H_{\widetilde{V}\delta_\Sigma} -z) = \{0\}$; implying $u =0$ and therefore \eqref{eq_u_trace_properties} shows $\psi = 0$. Now we turn to the surjectivity. Let $\varphi \in H^{1/2}(\Sigma;\C^N)$. Then, according to \cite[Theorem 2]{M87} there exist $w_\pm \in H^{1}(\Omega_\pm;\C^N)$ such that $\tr^\pm w_\pm = \frac{\mp i (\alpha \cdot \nu)}{2} \varphi \in H^{1/2}(\Sigma;\C^N)$. Next, we set $w = w_+ \oplus w_- \in H^{1}(\R^{\theta}\setminus\Sigma;\C^N)$ and see 
		\begin{equation}\label{eq_w_trace_properties}
			i(\alpha \cdot \nu)(\tr^+ - \tr^-)w  = \varphi \quad \textup{as well as} \quad \frac{1}{2}(\tr^+ + \tr^-)w  = 0.
		\end{equation} 
		Moreover, let 
		\begin{equation*}
			v:=(H_{\widetilde{V}\delta_\Sigma}-z)^{-1}[(-i(\alpha\cdot \nabla) + m\beta -zI_N) w_+  \oplus(-i(\alpha\cdot \nabla) + m\beta -zI_N) w_-] .
		\end{equation*}
		Then, $v \in \dom H_{\widetilde{V}\delta_\Sigma}$ and $(-i (\alpha \cdot \nabla) + m \beta - zI_N) (v-w)_\pm = 0$, and thus due to \cite[eq. (C.4) and the text below]{BHS23} there exists a $\psi \in H^{1/2}(\Sigma;\C^N)$ such that $\Phi_z \psi = w-v$. Hence, we use the relations \eqref{eq_u_trace_properties} (for $u  = \Phi_z \psi$) as in \eqref{eq_u_trace_properties_0}, \eqref{eq_w_trace_properties} and $v \in \dom H_{\widetilde{V}\delta_\Sigma}$ to obtain
		\begin{equation*}
			\begin{aligned}
				(I + \widetilde{V} \mathcal{C}_z)\psi 
				&= i(\alpha \cdot \nu)(\tr^+ - \tr^-)\Phi_z \psi  +   \widetilde{V}\frac{1}{2}(\tr^+ + \tr^-)\Phi_z \psi\\
				&= i(\alpha \cdot \nu)(\tr^+ - \tr^-)(w-v)   + \widetilde{V}\frac{1}{2}(\tr^+ + \tr^-)(w-v)  \\
				& =  i(\alpha \cdot \nu)(\tr^+ - \tr^-)w   +  \widetilde{V}\frac{1}{2}(\tr^+ + \tr^-)w  = \varphi.
			\end{aligned}
		\end{equation*}
		This proves the surjectivity and completes \textit{Step~2}.

		\textit{Step~3.}
		First, let $r =\tfrac{1}{2}$. In this case we already know from \textit{Step~2} that $I+ \widetilde{V}\mathcal{C}_z$ is continuously invertible in $H^{1/2}(\Sigma;\C^N)$. Hence, elementary calculations show that then $I - \mathcal{C}_z(I+\widetilde{V}\mathcal{C}_z)^{-1}\widetilde{V}$ is the inverse of $I + \mathcal{C}_z \widetilde{V}$. Moreover, it follows from \textit{Step~1 \& Step~2} that $I - \mathcal{C}_z(I+\widetilde{V}\mathcal{C}_z)^{-1}\widetilde{V}$ is also bounded as  an operator in $H^{1/2}(\Sigma;\C^N)$.
		Consequently, the assertion is true for $r=1/2$. Next, let us consider the case $r \in [0,\frac{1}{2})$. From the proof of \cite[Proposition 2.9]{BHS23} we obtain that $(\mathcal{C}_{\overline{z}} \upharpoonright H^{1/2}(\Sigma;\C^N))'$ (where $'$ is used to denote the anti-dual operator) is a continuous  extension of $\mathcal{C}_z$ to $H^{-1/2}(\Sigma;\C^N)$. Moreover, using the symmetry of $\widetilde{V}$ and the fact that $\widetilde{V}$ induces a bounded multiplication operator in $H^{1/2}(\Sigma;\C^N)$ shows that $\widetilde{V}$ can also be extended to a bounded multiplication operator in $H^{-1/2}(\Sigma;\C^N)$. Therefore, 
		\begin{equation}\label{eq_I+C_z_ext}
			\big((I+ \widetilde{V}\mathcal{C}_{\overline{z}}) \upharpoonright H^{1/2}(\Sigma;\C^N) \big)' = I+ (\mathcal{C}_{\overline{z}} \upharpoonright H^{1/2}(\Sigma;\C^N))' (\widetilde{V} \upharpoonright H^{1/2}(\Sigma;\C^N))' 
		\end{equation}is a continuous extension of $I+ \mathcal{C}_z\widetilde{V}$ in $H^{-1/2}(\Sigma;\C^N)$. \textit{Step~2} shows that $I+ \widetilde{V}\mathcal{C}_{\overline{z}}$ is continuously invertible in $H^{1/2}(\Sigma;\C^N)$ and therefore the operator in \eqref{eq_I+C_z_ext} has the bounded inverse $\big((I+ \widetilde{V}\mathcal{C}_{\overline{z}})^{-1} \upharpoonright H^{1/2}(\Sigma;\C^N) \big)'$. Hence, one can use interpolation to show the assertion for $r \in [0,\tfrac{1}{2}]$; cf. \cite[eq.~(2.2)]{BHS23} and \cite[Theorem~B.11]{M00}.
	\end{proof}

	\begin{proposition}\label{prop_inv_I+BVq}
		Let  $z \in \C\setminus\R$, $r \in [0,\tfrac{1}{2}]$, $q$ and $V= \eta I_N + \tau \beta$ be as described in \eqref{eq_q2} and \eqref{eq_V}, respectively, and $ d= \eta^2-\tau^2$ such that \eqref{eq_scaling_cond} is fulfilled. Moreover, let $(\widetilde{\eta},\widetilde{\tau}) = \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) (\eta,\tau)$, $\widetilde{V} = \widetilde{\eta} I_N + \widetilde{\tau} \beta$ and $\widetilde{d} = \widetilde{\eta}^2 - \widetilde{\tau}^2$ fulfil \eqref{eq_d_tilde_non_crit}.
		Then, the operator $I+ B_0(z)Vq$ is continuously invertible in the space $\mathcal{B}^r(\Sigma)$. In particular, assumption \textup{(ii)} of Proposition~\ref{prop_resolvent_convergence} is fulfilled in this case.
	\end{proposition}
	\begin{proof}
		We start by arguing that $I + B_0(z)Vq$ is a bounded operator in $\mathcal{B}^r(\Sigma)$. Due to the representation of $B_0(z)$ in \eqref{B_0_alt_rep} and the text below, $B_0(z)$ acts as a bounded operator in $\mathcal{B}^r(\Sigma)$. Moreover, $V \in W^1_\infty(\Sigma;\C^{N \times N})$ and $q \in L^{\infty}((-1,1);[0,\infty))$ imply that  $Vq$ induces a bounded operator in $\mathcal{B}^r(\Sigma)$, see Section~\ref{sec_not}~\eqref{it_Bochner}.  Hence, it remains to prove the bijectivity of $I + B_0(z)Vq$ in $\mathcal{B}^r(\Sigma)$.

		Let us start with the injectivity. To do so, we use the representation of $B_0(z)$ given by \eqref{B_0_alt_rep} and assume for $f \in \mathcal{B}^r(\Sigma)$
		\begin{equation}\label{eq_I+B_0_inj}
			(I +  B_0(z)Vq)f =(I +T(\alpha \cdot \nu)Vq)f + \mathfrak{I}\mathcal{C}_zV \mathfrak{I}^*qf = 0.
		\end{equation}
		By \cite[Lemma~4.2~(i)]{BHS23} $I + T(\alpha \cdot \nu)Vq$ is continuously invertible in in the space $\mathcal{B}^r(\Sigma)$ if $\cos\bigl(\tfrac{(\alpha\cdot\nu)V}{2}\bigr)^{-1} \in W^1_\infty(\Sigma;\C^{N \times N})$. Note that the structure of $V = \eta I_N + \tau \beta$ and the rules for the Dirac matrices from \eqref{eq_dirac_matrices} imply $((\alpha\cdot\nu)V)^2 = (\eta^2-\tau^2)I_N =d I_N$ and therefore
		\begin{equation*}%\label{eq_cos_conversion}
			\cos\bigl(\tfrac{(\alpha \cdot \nu) V}{2}\bigr) = \sum_{j=0}^\infty (-1)^{j}\frac{((\alpha \cdot \nu) V/2)^{2j}}{(2j)!} =  \sum_{j=0}^\infty (-1)^{j}\frac{(\sqrt{d}/2)^{2j}}{(2j)!} I_N = \cos\bigl(\tfrac{\sqrt{d}}{2}\bigr) I_N.
		\end{equation*}
		Consequently, $\cos\bigl(\tfrac{(\alpha\cdot\nu)V}{2}\bigr)^{-1} \in W^1_\infty(\Sigma;\C^{N \times N})$ since \eqref{eq_scaling_cond} is satisfied. Hence, we can apply $(I + T(\alpha \cdot \nu)Vq)^{-1}$ to \eqref{eq_I+B_0_inj}. This yields
		\begin{equation*}
			f + (I + T(\alpha \cdot \nu)Vq)^{-1}\mathfrak{I}\mathcal{C}_zV \mathfrak{I}^*qf =0.
		\end{equation*}
		Using \cite[Lemma 4.2~(ii)]{BHS23} and defining $Q(t) = \int_{-1}^t q(s) \,ds - \tfrac{1}{2}$, $t \in [-1,1]$,  gives us 
		\begin{equation*}
			(I+T(\alpha \cdot \nu)Vq)^{-1}\mathfrak{I} = \cos\bigl(\tfrac{(\alpha \cdot \nu)V}{2}\bigr)^{-1}\exp(-i(\alpha \cdot \nu) V Q) \mathfrak{I}
		\end{equation*}
		and therefore
		\begin{equation}\label{eq_I+B_0_invert_1}
			f + \cos\bigl(\tfrac{(\alpha \cdot \nu)V}{2}\bigr)^{-1}\exp(-i(\alpha \cdot \nu) V Q)\mathfrak{I} \mathcal{C}_zV \mathfrak{I}^*qf =0.
		\end{equation}
		By applying $\mathfrak{I}^*q$ and \cite[Lemma~4.3~(ii)]{BHS23} we obtain
		\begin{equation}\label{eq_I+B_0_invert_2}
			\begin{aligned}
				&\mathfrak{I}^*q f + \mathfrak{I}^*q\cos\bigl(\tfrac{(\alpha \cdot \nu)V}{2}\bigr)^{-1}\exp(-i(\alpha \cdot \nu) V Q)\mathfrak{I}\mathcal{C}_zV \mathfrak{I}^*qf\\
				&\hspace{160 pt}= (I+S \mathcal{C}_z V)\mathfrak{I}^*q f =0
			\end{aligned}
		\end{equation}
		with $S= \textup{sinc}\bigl(\tfrac{(\alpha\cdot\nu)V}{2}\bigr)\cos\bigl(\tfrac{(\alpha\cdot\nu)V}{2}\bigr)^{-1}$. Similar as we showed $\cos\bigl(\tfrac{(\alpha\cdot\nu)V}{2}\bigr) = \cos\bigl(\tfrac{\sqrt{d}}{2}\bigr)I_N$ one can show $\textup{sinc}\bigl(\tfrac{(\alpha\cdot\nu)V}{2}\bigr) = \textup{sinc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) I_N$ and therefore 
		\begin{equation} \label{equation_rescaling}
			V S = V \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) = \widetilde{V}.
		\end{equation}  
		Moreover, Lemma~\ref{lem_I+C_z_inverse} shows that $-1 \in \rho(\mathcal{C}_z\widetilde{V})$. By \cite[Proposition~2.1.8]{P94} there  holds $\rho(\mathcal{C}_z\widetilde{V}) \setminus  \{0\} = \rho(S\mathcal{C}_zV) \setminus  \{0\}$. Consequently, $-1 \in \rho(S\mathcal{C}_zV)$ and hence \eqref{eq_I+B_0_invert_2} implies $\mathfrak{J}^*qf=0$. This, in turn, implies  according to \eqref{eq_I+B_0_invert_1}  $f =0$.

		Next, we show the surjectivity of the operator $I + B_0(z)Vq$. Let $g \in \mathcal{B}^r(\Sigma)$. We set $f_g = (I +T(\alpha \cdot \nu)Vq)^{-1}(g +  \mathfrak{I}\psi)$, where 
		\begin{equation*}
			\psi =-(I+ \mathcal{C}_z\widetilde{V})^{-1}  \mathcal{C}_z\mathfrak{I}^* Vq(I +T(\alpha \cdot \nu)Vq)^{-1}g.
		\end{equation*}
		Item (iii) from \cite[Lemma 4.3]{BHS23}  yields together with~\eqref{equation_rescaling}
		\begin{equation*}
			(I +   B_0(z) Vq)(I +T(\alpha \cdot \nu)Vq)^{-1}\mathfrak{I} = \mathfrak{I}(I+ \mathcal{C}_z\widetilde{V}).
		\end{equation*}
		Thus, by  applying  $I +   B_0(z) Vq$ to $f_g$ and using $B_0(z) = T(\alpha\cdot\nu) + \mathfrak{I}\mathcal{C}_z \mathfrak{I}^*$, see \eqref{B_0_alt_rep},  we obtain
		\begin{equation*}
			\begin{aligned}
				(I +   B_0(z) Vq)f_g &= (I +   B_0(z) Vq)(I +T(\alpha \cdot \nu)Vq)^{-1}g \\ 
				&\qquad+ (I +   B_0(z) Vq)(I +T(\alpha \cdot \nu)Vq)^{-1}\mathfrak{I}\psi\\
				&= (I +T(\alpha \cdot \nu)Vq + \mathfrak{I}\mathcal{C}_z\mathfrak{I}^*Vq)(I +T(\alpha \cdot \nu)Vq)^{-1}g \\
				&\qquad+ \mathfrak{I}(I+ \mathcal{C}_z\widetilde{V}) \psi\\
				&= g+ \mathfrak{I}\mathcal{C}_z\mathfrak{I}^*Vq(I +T(\alpha \cdot \nu)Vq)^{-1}g + \mathfrak{I}(I+ \mathcal{C}_z\widetilde{V}) \psi\\
				&=g,
			\end{aligned}
		\end{equation*}
		which completes the proof.
	\end{proof}

	\subsection{Analysis of $I + B_\varepsilon(z)Vq$}\label{sec_I+B_eps}
	In this section we show  that if 
	\begin{equation*}
		\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4}, \qquad d = \eta^2-\tau^2,
	\end{equation*}  then (i) of Proposition~\ref{prop_resolvent_convergence} is fulfilled, i.e. $(I+B_\varepsilon(z)Vq)^{-1}$ is uniformly bounded in $\mathcal{B}^0(\Sigma)$. Combining this result with  Proposition~\ref{prop_resolvent_convergence} and Proposition~\ref{prop_inv_I+BVq} proves the norm resolvent convergence of $H_{V_\varepsilon}$. To prove the uniform boundedness of  $(I+B_\varepsilon(z)Vq)^{-1}$ a  careful and deep analysis of this operator is necessary. We do this by studying $(I+B_\varepsilon(z)Vq)^{-1}$ in the case that $\Sigma$ is a hyperplane and $\eta$ and $\tau$ are constant in detail in Section~\ref{sec_hyperplane}. Then, we use a parameter dependent partition of unity in Section~\ref{sec_loc_part} to transfer the results to  the case where 
	$\Sigma = \Sigma_{\zeta,\kappa}$,  $\zeta \in C^2_b(\R^{\theta-1};\R)$, $\kappa \in \textup{SO}(\theta)$,
	 is a rotated $C^2_b$-graph as in \eqref{eq_rotated_graph} and $\eta,\tau \in C^1_b(\Sigma;\R)$. 
	We start by introducing for $\varepsilon \in (0,\varepsilon_2)$ with $\varepsilon_2$ as in Proposition \ref{prop_conv_res} the auxiliary operator
	\begin{equation}\label{def_B_eps_bar}
		\begin{aligned}
			\overline{B}_\varepsilon(z) &: \mathcal{B}^0(\Sigma) \to \mathcal{B}^0(\Sigma),\\
			\overline{B}_\varepsilon( z)f(t)(x_\Sigma) &:=   \int_{-1}^1 \int_{\Sigma} G_ z(x_\Sigma +\varepsilon (t-s)\nu(x_\Sigma) -y_\Sigma )   f(s)(y_\Sigma) \, d\sigma(y_\Sigma) \, ds;
		\end{aligned}
	\end{equation} 
	cf. \cite[eq. (3.17), eq. (3.23) and Appendix~B]{BHS23}. According to \cite[eq. (3.29)]{BHS23}, 
	\begin{equation}\label{eq_B_diff}
		\norm{\overline{B}_\varepsilon(z)  -	B_\varepsilon(z)}_{0 \to 0} \leq C \varepsilon^{1/2} (1+\abs{\log(\varepsilon)})^{1/2}, \qquad  \varepsilon \in (0,\varepsilon_2).
	\end{equation}
	 Next, we transfer this operator to $\mathcal{B}^0(\R^{\theta-1})$. 
	To do so, we introduce the isomorphism
	\begin{equation}\label{def_iota}
		\iota_{\zeta,\kappa} :L^2(\Sigma;\C^N) \to L^2(\R^{\theta-1};\C^N), \quad	(\iota_{\zeta,\kappa} f)(x') := f\big(\kappa (x',\zeta(x'))\big).
	\end{equation}
	By transforming the integral on $\Sigma$ to an integral on $\R^{\theta-1}$ one obtains that the norm of $\iota_{\zeta,\kappa}$ and its inverse are given by
	\begin{equation}\label{eq_norm_iota}
		\begin{aligned}
			\|\iota_{\zeta,\kappa}\|_{L^2(\Sigma;\C^N) \to L^2(\R^{\theta-1};\C^N)} = \sup_{x' \in \R^{\theta-1}} (1+\abs{\nabla\zeta(x')}^2)^{-1/4} \\
			\textup{ and } 	\big\|\iota_{\zeta,\kappa}^{-1}\big\|_{ L^2(\R^{\theta-1};\C^N) \to L^2(\Sigma;\C^N)}  =\sup_{x' \in \R^{\theta-1}} (1+\abs{\nabla\zeta(x')}^2)^{1/4}.
		\end{aligned}
	\end{equation}
	Note that the definition of $H^r(\Sigma;\C^N)$, $r \in [0,2]$, see \cite{M00} or \cite[Section~2.1]{BHS23}, implies that $\iota_{\zeta,\kappa}$ also acts  as an isomorphic operator from  $H^r(\Sigma;\C^N)$ to $H^r(\R^{\theta-1};\C^N)$ for $r \in [0,2]$. Recall  that in this case $\iota_{\zeta,\kappa}$ can also be viewed as a bounded operator in $\mathcal{B}^r(\Sigma)$ to $\mathcal{B}^r(\R^{\theta-1})$ which has the same norm as the operator acting from $H^r(\Sigma;\C^N)$ to $H^r(\R^{\theta-1};\C^N)$.


	Next, we introduce for $\varepsilon \in (0,\varepsilon_2)$ the operators
	\begin{equation}\label{def_D_operators}
		\begin{aligned}
			D_\varepsilon^{\zeta,\kappa}(z)&:=  \iota_{\zeta,\kappa}\overline{B}_\varepsilon({z})  \iota_{\zeta,\kappa}^{-1} : \mathcal{B}^0(\R^{\theta-1}) \to \mathcal{B}^0(\R^{\theta-1})\\
			\text{and }D_0^{\zeta,\kappa}(z)&:=  \iota_{\zeta,\kappa}B_0({z})  \iota_{\zeta,\kappa}^{-1}\: : \mathcal{B}^0(\R^{\theta-1}) \to\mathcal{B}^0(\R^{\theta-1}).
		\end{aligned}
	\end{equation}
	The results from Proposition~\ref{prop_conv_res} and \eqref{eq_B_diff} imply that $D_\varepsilon^{\zeta,\kappa}(z)$ is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$ with respect to $\varepsilon \in (0,\varepsilon_2)$ and for $r \in (0,\frac{1}{2})$  the inequality
	\begin{equation}\label{eq_D_eps_conv}
		\begin{aligned}
		\|D_0^{\zeta,\kappa}(z) - D_\varepsilon^{\zeta,\kappa}(z)\|_{1/2 \to 0} & = 
		\|\iota_{\zeta,\kappa}\bigl(B_0({z})  - \overline{B}_\varepsilon({z})\bigr)   \iota_{\zeta,\kappa}^{-1}\|_{1/2 \to 0}\\
		&\leq C \bigl(\|B_0({z})  -  B_\varepsilon({z})\|_{1/2 \to 0} \\ & \qquad+\|B_\varepsilon({z})  -  \overline{B}_\varepsilon({z})\|_{1/2 \to 0} \bigr) \\
		&\leq C \bigl(\|B_0({z})  -  B_\varepsilon({z})\|_{1/2 \to 0} \\ & \qquad+\|B_\varepsilon({z})  -  \overline{B}_\varepsilon({z})\|_{0 \to 0} \bigr)\\
		 &\leq   C \varepsilon^{1/2-r}, \quad \varepsilon \in (0, \varepsilon_2),
		\end{aligned}
	\end{equation}
	holds.
	In particular, $D_\varepsilon^{\zeta,\kappa}(z)f$ converges for $\varepsilon \to 0$ to $D_0^{\zeta,\kappa}(z)f$ in $\mathcal{B}^0(\R^{\theta-1})$ for $f \in \mathcal{B}^{1/2}(\R^{\theta-1})$.  Furthermore, $\mathcal{B}^{1/2}(\R^{\theta-1})$ is by \cite[Lemma~1.2.19]{HNVW16} and \cite[the lines above eq.~(3.22)]{M00} a dense subset of  $\mathcal{B}^{0}(\R^{\theta-1})$. Combining these considerations with the uniform boundedness of $D_\varepsilon^{\zeta,\kappa}(z)$ in $\mathcal{B}^0(\R^{\theta-1})$ shows that for all $f \in \mathcal{B}^0(\R^{\theta-1})$
	\begin{equation}\label{eq_D_strong_conv}
		D_\varepsilon^{\zeta,\kappa}(z)f \to D_0^{\zeta,\kappa}(z)f \quad\textup{in } \mathcal{B}^0(\R^{\theta-1}), \textup{ as } \varepsilon \to 0.
	\end{equation}
	Using \eqref{def_B_eps_bar} and \eqref{def_iota}, and setting 
	\begin{equation}\label{eqref_x_nu_zeta_kappa}
		x_{\zeta,\kappa}= \kappa(\cdot,\zeta(\cdot))\quad \textup{and} \quad \nu_{\zeta, \kappa} = \nu\circ x_{\zeta,\kappa} =\frac{\kappa (-\nabla \zeta, 1)}{\sqrt{1 + \abs{\nabla \zeta}^2}}
	\end{equation} yields for $f \in \mathcal{B}^0(\R^{\theta-1})$ and a.e. $(t,x') \in (-1,1) \times \R^{\theta-1}$
	\begin{equation}\label{eq_D_eps_int_rep_0}	
		\begin{aligned}
			D_\varepsilon^{\zeta,\kappa}({z}) f (t)(x')&= \int_{-1}^1\int_{\R^{\theta-1}} G_{z}\big(x_{\zeta,\kappa}(x') - x_{\zeta,\kappa}(y') + \varepsilon(t-s) \nu_{\zeta,\kappa}(x') \big)\\
			&\hspace{115 pt}\cdot \sqrt{1+\abs{\nabla \zeta(y')}^2}f(s)(y') \,dy' \, ds.
		\end{aligned}
	\end{equation}
	Another useful representation is given by
	\begin{equation}\label{eq_D_eps_int_rep}
		D_\varepsilon^{\zeta,\kappa}({z}) f (t) = \int_{-1}^1 d_{\varepsilon(t-s)}^{\zeta,\kappa}({z})f(s) \, ds, \quad f \in \mathcal{B}^0(\R^{\theta-1}), t \in (-1,1),
	\end{equation}	
	where the integral is considered as a Bochner integral and 
	\begin{equation}\label{eq_d_eps}
		\begin{aligned}
			d_{\widetilde{\varepsilon}}^{\zeta,\kappa}({z}) &: L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N),\\
			d_{\widetilde{\varepsilon}}^{\zeta,\kappa}({z})g(x') 
			&=\int_{\R^{\theta-1}} G_{z}\big(x_{\zeta,\kappa}(x') - x_{\zeta,\kappa}(y') + \widetilde{\varepsilon} \nu_{\zeta,\kappa}(x') \big)\\
			&\hspace{130 pt}\cdot \sqrt{1+\abs{\nabla \zeta(y')}^2}g(y') \,dy',
		\end{aligned}
	\end{equation}
	for $\widetilde{\varepsilon} \in (-2\varepsilon_2,2\varepsilon_2)\setminus\{0\}$. For the interaction strengths  $\eta,\tau \in C^1_b(\Sigma;\R)$ we also define the  matrix valued function
	\begin{equation}\label{eq_Q_matrix}
		Q^{\zeta,\kappa}_{\eta,\tau}:= V \circ x_{\zeta,\kappa} = \eta \circ x_{\zeta,\kappa} I_N + \tau \circ x_{\zeta,\kappa}\beta.
	\end{equation} 
	There  holds $Q^{\zeta,\kappa}_{\eta,\tau} = \iota_{\zeta,\kappa} V\iota_{\zeta,\kappa}^{-1}$ in the sense of operators in $L^2(\R^{\theta-1};\C^N)$.



	\subsubsection{Hyperplanes and constant interaction strengths}\label{sec_hyperplane}

	In this section we assume that $\zeta$ is a constant function having the value $y_0 \in \R$, i.e. $\Sigma =  \Sigma_{\zeta,\kappa} = \Sigma_{y_0,\kappa}$ is an  affine $(\theta-1)$-dimensional hyperplane in $\R^{\theta}$. We also assume in this section that the interaction strengths are constant and given by $\eta,\tau \in \R$. This implies that  $Q^{y_0,\kappa}_{\eta,\tau}$ is equal to the constant matrix 
	\begin{equation}\label{eq_Q_const}
		Q_{\eta,\tau} := \eta I_N + \tau \beta 
	\end{equation}
	 in this case. The main goal of this section is to show that for every compact set $S \subset \R^2$ satisfying
	\begin{equation*}
		\max_{(\eta,\tau) \in S} \eta^2- \tau^2 < \frac{\pi^2}{4}
	\end{equation*} 
	there exists a $\delta_2 = \delta_2(S)$ such that  
	\begin{equation*}
		\|(I+ D^{y_0,\kappa}_\varepsilon(z)Q_{\eta,\tau})^{-1}\|_{0 \to 0}
	\end{equation*} 
	is uniformly bounded with respect to $(\varepsilon,y_0,(\eta,\tau),\kappa) \in (0,\delta_2)\times \R \times S \times\textup{SO}(\theta)$; cf. Corollary~\ref{cor_uniform_bdd_D}. This result will play a major role when we prove the uniform boundedness of $(I + B_\varepsilon(z)Vq)^{-1}$ in Section~\ref{sec_loc_part}. 
	To do so we proceed as follows: We start by using the Fourier transform to transform $D^{y_0,\kappa}_\varepsilon(z)$ into a decomposable direct integral operator with frequency  dependent fiber operators, see the considerations up to \eqref{eq_def_frak_d}. Then, up to Lemma~\ref{lem_frak_h_inv_estimate} we find and analyse suitable approximations for the fiber operators for high and low frequencies. Finally, we use these results to  prove the main statements (Proposition~\ref{prop_uniform_bdd_D} and Corollary~\ref{cor_uniform_bdd_D})  of this section. 

	Before we start, let us fix some notations. In the present setting the normal vector $\nu$ is constant and given by  $\kappa e_\theta$, where $e_\theta$ is the $\theta$-th euclidean unit vector. Let us also mention that $\varepsilon_2$ from  Proposition~\ref{prop_res_formula_eps} is according to \cite[eq. (3.11)]{BHS23} given by
	\begin{equation*}
		\varepsilon_2 = \min \biggl\{\frac{\varepsilon_1}{2}, \frac{1}{2 \norm{D \widetilde{\nu}}_{L^\infty(\R^{\theta};\R^{\theta \times \theta})}} \biggr\}.
	\end{equation*}
	where, $\varepsilon_1$ is chosen as below \eqref{eq_iota}, see also \cite[Proposition~2.4]{BHS23} and $\widetilde{\nu}$ is an extension $C^1_b$ of $\nu$ to $\R^{\theta}$; cf. \cite[the discussion above eq. (3.5)]{BHS23}. Next, we argue that $\varepsilon_2$ can be set independently of $\kappa$ to $\infty$. First, $\varepsilon_1$ is chosen  such that one can identify $\Omega_{\varepsilon_1}$ via the map $\iota$ in~\eqref{eq_iota} with $\Sigma \times (-\varepsilon_1,\varepsilon_1)$ and  the eigenvalues of $ \varepsilon_1 W(x_\Sigma)$, $x_\Sigma \in \Sigma$, are sufficiently small, so that this identification is bijective. However, in the current case $\Omega_{\varepsilon_1} = \kappa(\R^{\theta-1} \times (y_0-\varepsilon_1, y_0 + \varepsilon_1))$ can be identified with $\Sigma \times (-\varepsilon_1,\varepsilon_1) = \kappa(\R^{\theta-1} \times \{y_0\}) \times (-\varepsilon_1,\varepsilon_1)$ for arbitrary $\varepsilon_1>0$ and the Weingarten map is zero. Thus, we can set $\varepsilon_1$   independently of $y_0$ and $\kappa$ to $\infty$. Furthermore, as $\nu$ is constant, its constant extension is a $C^1_b$-extension of $\nu$. Hence,  $(2 \norm{D \widetilde{\nu}}_{L^\infty(\R^{\theta};\R^{\theta \times \theta})})^{-1} = \infty$ and therefore $\varepsilon_2 = \infty$. 
	Using \eqref{eq_D_eps_int_rep_0} and 
	\begin{equation*}
		x_{y_0,\kappa}(x')-x_{y_0,\kappa}(y') + \varepsilon (t-s) \nu_{y_0,\kappa}(x') = \kappa(x'-y',\varepsilon(t-s)), \,  x',y' \in \R^{\theta-1}, t,s \in (-1,1),
	\end{equation*}  
shows that $D_\varepsilon^{y_0,\kappa}(z) $  has for $\varepsilon \in (0,\infty)$ and $f \in \mathcal{B}^0(\R^{\theta-1})$ the representation
	\begin{equation}\label{eq_D_eps_straight}
		D^{y_0,\kappa}_{\varepsilon}(z)f(t)(x')  =
		\int_{-1}^1\int_{\R^{\theta-1}} G_{z}\big(\kappa(x'-y',\varepsilon (t-s))\big) f(s)(y') \,dy' \,ds
	\end{equation}
	for a.e. $(x',t) \in \R^{\theta-1}  \times (-1,1) $, which proves  that $D_\varepsilon^{y_0,\kappa}(z)$ is independent of $y_0 \in \R$. Furthermore,  \eqref{eq_D_strong_conv} implies that also $D_0^{y_0,\kappa}(z)$ is independent of $y_0$. Thus, w.l.o.g. we can set $y_0=0$. Before we state the next result, we define for convenience the matrices $\widetilde{\alpha}_j := \alpha \cdot \kappa e_j$, $j \in \{1,\dots, \theta\}$, $\widetilde{\alpha} \cdot \xi := \sum_{j=1}^{\theta} \widetilde{\alpha}_j \xi_j$, $\xi \in \R^{\theta}$, and $\widetilde{\alpha}' \cdot \xi' = \sum_{j=1}^{\theta-1} \widetilde{\alpha}_j \xi_{j}'$, $\xi'\in\R^{\theta-1}$. Note that $\widetilde{\alpha}_1, \dots, \widetilde{\alpha}_\theta$ satisfy the same anti-commutation relations as $\alpha_1, \dots, \alpha_\theta$; cf. \eqref{it_Dirac_matrices} of Section~\ref{sec_not}.

	We start by calculating the Fourier transform of the function $G_z(\kappa(\cdot,\widetilde{\varepsilon}))$ for fixed $\widetilde{\varepsilon} \neq 0$; cf. \cite[eqs. (44)--(45)]{R22a} for similar considerations. Recall that $\mathcal{F}$ is the $(\theta-1)$-dimensional Fourier transform defined in Section~\ref{sec_not}~\eqref{it_Fourier}.


	\begin{lemma}\label{lem_Fourier_transform_G_z_eps} 
		Let  $z \in \rho(H)$, $G_z$ be the integral kernel of $(H-z)^{-1}$ given by \eqref{eq_G_z_2D}--\eqref{eq_G_z_3D}, and $\widetilde{\varepsilon}\neq0$. Then, 
		\begin{equation*}
			\mathcal{F} G_z(\kappa(\cdot,\widetilde{\varepsilon})) = \bigg(\frac{\widetilde{\alpha}' \cdot(\cdot) + m \beta + zI_N)}{\sqrt{z^2-m^2-\abs{\cdot}^2}} + \widetilde{\alpha}_{\theta}\sign(\widetilde{\varepsilon})\bigg)\frac{ie^{\abs{\widetilde{\varepsilon}}i\sqrt{z^2-m^2-\abs{\cdot}^2}}}{ 2 \sqrt{(2\pi)^{\theta-1}}}.
		\end{equation*}
	\end{lemma}
	\begin{proof}
		Let $\mathcal{F}$, $\mathcal{F}_1$, $\mathcal{F}_2$ and $\mathcal{F}_{1,2}$ be  defined as in Section~\ref{sec_not}~\eqref{it_Fourier}. First, we consider $\mathcal{F}_1 G_z(\kappa(\cdot))$.  Since $G_z(\kappa(\cdot)) \in L^1(\R^\theta;\C^{N\times N}) \subset \mathcal{S}'(\R^{\theta};\C^{N\times N})$, see \eqref{eq_G_z_2D}--\eqref{eq_G_z_3D}, the expression $\mathcal{F}_1 G_z(\kappa(\cdot))$ is well-defined in $\mathcal{S}'(\R^{\theta};\C^{N\times N})$. Moreover,  $\mathcal{F}_1 G_z(\kappa(\cdot)) = \mathcal{F}_{2}^{-1}\mathcal{F}_{1,2} G_z (\kappa(\cdot))$. Thus, we calculate $\mathcal{F}_{1,2}G_z(\kappa(\cdot))$ next. The function $G_z$ satisfies the equation $(-i(\alpha \cdot \nabla )+m\beta- zI_N)G_z =  \delta I_N $, with $\delta$ denoting the $\delta$ distribution supported in $\{0\}$. Hence, the standard rules for the Fourier transform, see \cite[Chapter IX]{RS75}, show 
		\begin{equation*}
			\big(\alpha \cdot (\cdot)+ m\beta - zI_N\big)\mathcal{F}_{1,2}G_z= \frac{1}{\sqrt{(2\pi)^{\theta}}}I_N \quad \textup{in }\mathcal{S}'(\R^\theta;\C^{N\times N}). 
		\end{equation*}
		Furthermore, since $G_z \in L^1(\R^{\theta};\C^{N\times N})$, we have by the Riemann-Lebesgue lemma $\mathcal{F}_{1,2}G_z \in C_0(\R^\theta;\C^{N\times N})$. Using the properties of $\alpha_j$, $j \in \{1, \dots ,\theta\}$, and $\beta$ yields $(\alpha \cdot \xi+ m\beta - zI_N)^{-1} = \frac{\alpha \cdot \xi+ m\beta + zI_N}{\abs{\xi}^2 + m^2 - z^2}$ for $\xi \in \R^{\theta}$. Thus, 
		\begin{equation*}
			(\mathcal{F}_{1,2}G_z)(\kappa \xi)= \frac{\alpha \cdot (\kappa \xi) + m\beta + zI_N}{ (\abs{\kappa \xi}^2 + m^2 - z^2) \sqrt{(2\pi)^{\theta}}}, \quad  \xi \in \R^\theta.
		\end{equation*}
		Since $\kappa \in \textup{SO}(\theta)$, we obtain
		\begin{equation}\label{eq_G_z_Fourier_Transform_1}
			\mathcal{F}_{1,2}G_z(\kappa(\cdot))(\xi) = (\mathcal{F}_{1,2}G_z)(\kappa \xi)= \frac{\widetilde{\alpha} \cdot  \xi + m\beta + zI_N}{ (\abs{\xi}^2 + m^2 - z^2) \sqrt{(2\pi)^{\theta}} }, \quad \xi \in \R^{\theta }.
		\end{equation}
		Next, we determine $\mathcal{F}_2^{-1}\mathcal{F}_{1,2}G_z$. We claim that for a.e. $(\xi',x_\theta) \in \R^\theta$ the equation
		\begin{equation}\label{eq_G_z_Fourier_Transform_2}
			\begin{aligned}
				(\mathcal{F}_2^{-1}\mathcal{F}_{1,2}&G_z(\kappa(\cdot)))(\xi',x_\theta)\\
				&=\bigg(\frac{\widetilde{\alpha}'\cdot \xi'+ m \beta + zI_N}{\sqrt{z^2-m^2-|\xi'|^2}} + \widetilde{\alpha}_\theta\sign(x_{\theta})\bigg) \cdot\frac{ie^{\abs{x_\theta}i\sqrt{z^2-m^2-\abs{\xi'}^2}}}{2\sqrt{(2\pi)^{\theta-1}}}
			\end{aligned}
		\end{equation} 
		holds.
		We verify \eqref{eq_G_z_Fourier_Transform_2} by applying $\mathcal{F}_2$ and comparing the result with  \eqref{eq_G_z_Fourier_Transform_1}. Since the right hand side of \eqref{eq_G_z_Fourier_Transform_2} decays exponentially for $|x_\theta|\to \infty$, we can use the integral representation of the Fourier transform. Hence, simple integration gives us for $\xi= (\xi',\xi_\theta) \in \R^\theta$
		\begin{equation*}
			\begin{aligned}
				&\frac{1}{\sqrt{2\pi}}\int_\R \bigg(\frac{\widetilde{\alpha}'\cdot \xi'+ m \beta + zI_N}{\sqrt{z^2-m^2-|\xi'|^2}} + \widetilde{\alpha}_\theta\sign(x_\theta)\bigg) \\
				&\hspace{55 pt}\cdot\frac{ie^{i(-x_\theta \xi_\theta +\abs{x_\theta}\sqrt{z^2-m^2-\abs{\xi'}^2})}}{2 \sqrt{(2\pi)^{\theta-1}}} dx_\theta
				= \frac{\widetilde{\alpha} \cdot  \xi + m\beta + zI_N}{ (\abs{\xi}^2 + m^2 - z^2) \sqrt{(2 \pi)^{\theta}}},
			\end{aligned}
		\end{equation*}
		which verifies \eqref{eq_G_z_Fourier_Transform_2}. 
		Therefore, $\mathcal{F}_1 G_z(\kappa(\cdot))= \mathcal{F}_2^{-1}\mathcal{F}_{1,2}G_z(\kappa(\cdot))$ can be represented by the function 
		\begin{equation*}
			\begin{aligned}
				\R^{\theta} \ni	(\xi',x_\theta) \mapsto \bigg(\frac{\widetilde{\alpha}'\cdot \xi'+ m \beta + zI_N}{\sqrt{z^2-m^2-|\xi'|^2}} + \widetilde{\alpha}_\theta\sign(x_\theta)\bigg)
				\frac{ie^{|x_\theta|i\sqrt{z^2-m^2-|\xi'|^2}}}{2\sqrt{(2\pi)^{\theta-1}}}.
			\end{aligned}
		\end{equation*}
		Furthermore, since $G_z(\kappa(\cdot,\widetilde{\varepsilon}))\in L^1(\R^{\theta-1};\C^{N\times N})$ for $\widetilde{\varepsilon} \neq 0$, this shows that for $\widetilde{\varepsilon} \neq 0$ and $\xi' \in \R^{\theta-1}$ there holds
		\begin{equation*}
			\begin{aligned}
				\mathcal{F}G_z(\kappa(\cdot,\widetilde{\varepsilon})) (\xi') &=\frac{1}{\sqrt{(2\pi)^{\theta-1}}}\int_{\R^{\theta-1}} G_z(\kappa(x',\widetilde{\varepsilon}))e^{-i \langle x', \xi' \rangle} \, dx'  \\
				&= \mathcal{F}_1G_z(\kappa(\cdot))(\xi',\widetilde{\varepsilon}) \\
				&= \bigg(\frac{\widetilde{\alpha}'\cdot\xi' + m \beta + zI_N}{\sqrt{z^2-m^2-\abs{\xi'}^2}} + \widetilde{\alpha}_\theta\sign(\widetilde{\varepsilon})\bigg)\frac{ie^{\abs{\widetilde{\varepsilon}}i\sqrt{z^2-m^2-\abs{\xi'}^2}}}{2\sqrt{(2\pi)^{\theta-1}}}.
			\end{aligned}
		\end{equation*}
	\end{proof}

	\begin{proposition}\label{prop_Fourier_D}
		Let  $z \in \rho(H)$, $\varepsilon >0$, and $\mathcal{F}$ be the $(\theta-1)$-dimensional Fourier transform defined in Section~\ref{sec_not}~\eqref{it_Fourier}. Then, there holds for $f \in \mathcal{B}^0(\R^{\theta-1})$
		\begin{equation}\label{eq_Fourier_Transform_eps}
			\begin{aligned}
				&\mathcal{F}D_\varepsilon^{0,\kappa}(z)\mathcal{F}^{-1}f(t)(\xi') 
				= \int_{-1}^1 \bigg(\frac{\widetilde{\alpha}'\cdot \xi'   + m \beta + zI_N}{\sqrt{z^2-m^2-\abs{\xi'}^2}} + \widetilde{\alpha}_\theta\sign(t-s)\bigg) \\
				&\hspace{ 150 pt}\cdot\frac{ie^{\abs{\varepsilon(t-s)}i\sqrt{z^2-m^2-\abs{\xi'}^2 }}}{2}f(s)(\xi') \, ds
			\end{aligned}
		\end{equation}
		and 
		\begin{equation}\label{eq_Fourier_Transform_0}
			\begin{aligned} \mathcal{F}D_0^{0,\kappa}(z)\mathcal{F}^{-1}f(t)(\xi') &= \int_{-1}^1 \bigg(\frac{\widetilde{\alpha}'\cdot \xi'   + m \beta + zI_N}{\sqrt{z^2 - m^2 - \abs{\xi'}^2}} + 		\widetilde{\alpha}_\theta\sign(t-s)\bigg)\\
				&\hspace{150 pt}\cdot\frac{if(s)(\xi')}{2} \, ds
			\end{aligned}
		\end{equation}
		for a.e $(t,\xi') \in (-1,1) \times  \R^{\theta-1}$. In particular, the operators $D_\varepsilon^{0,\kappa}(z)$ and $D_0^{0,\kappa}(z)$ depend continuously on $\kappa \in \textup{SO}(\theta)$ with respect to the operator norm.
	\end{proposition}

	\begin{proof}
		We start with the case  $\varepsilon >0$. Equation \eqref{eq_D_eps_straight} shows 
		\begin{equation*}
			D_{\varepsilon}^{0,\kappa}(z)f(t) = \int_{-1}^1G_z\bigl(\kappa(\cdot,\varepsilon(t-s))\bigr)\ast f(s) \,ds
		\end{equation*} 
		for a.e. $t \in (-1,1)$ and all  $f \in \mathcal{B}^0(\R^{\theta-1})$. Thus, Lemma \ref{lem_Fourier_transform_G_z_eps} and \cite[Theorem~IX.4]{RS75}  prove the statement for $\varepsilon>0$. It remains to consider the operator $D_0^{0,\kappa}(z)$. We start by defining 
		\begin{equation*}
			\begin{aligned}
				\widetilde{D}_0^{0,\kappa}(z) &:  \mathcal{B}^0(\R^{\theta-1}) \to \mathcal{B}^0(\R^{\theta-1})\\
				\widetilde{D}_0^{0,\kappa}(z)f(t)(\xi') &:= \int_{-1}^1 \bigg(\frac{\widetilde{\alpha}'\cdot \xi'   + m \beta + zI_N}{\sqrt{z^2-m^2-\abs{\xi'}^2}} + 		\widetilde{\alpha}_\theta\sign(t-s)\bigg)\frac{i f(s)(\xi')}{2} \, ds.
			\end{aligned}
		\end{equation*}
		Next, let  $f \in \mathcal{B}^{0}(\R^{\theta-1})$. Using \eqref{eq_Fourier_Transform_eps}  and dominated convergence, see \cite[Proposition 1.2.5]{HNVW16}, one obtains that $\mathcal{F} D_\varepsilon^{0,\kappa}(z) \mathcal{F}^{-1}f$ converges for $\varepsilon \to 0$ to $\widetilde{D}_0^{0,\kappa}(z) f$ in $\mathcal{B}^0(\R^{\theta-1})$.  Thus, the boundedness of $\mathcal{F}$ and $\mathcal{F}^{-1}$ in $L^2(\R^{\theta-1};\C^N)$ (and therefore also in $\mathcal{B}^0(\R^{\theta-1})$; cf. Section~\ref{sec_not}~\eqref{it_Bochner}) implies that $D_\varepsilon^{0,\kappa}(z)f$ converges to $\mathcal{F}^{-1}\widetilde{D}_0^{0,\kappa}(z)\mathcal{F}f$ in $\mathcal{B}^0(\R^{\theta-1})$. Moreover, by \eqref{eq_D_strong_conv}  $D_\varepsilon^{0,\kappa}(z) f$ converges to $D_0^{0,\kappa}(z)f$ in $ \mathcal{B}^0(\R^{\theta-1})$. Hence, $D_0^{0,\kappa}(z) f = \mathcal{F}^{-1}\widetilde{D}_0^{0,\kappa}(z)\mathcal{F}f$ which proves \eqref{eq_Fourier_Transform_0}. 

		It remains to verify the continuous dependence on $\kappa$. Taking the definition of $\widetilde{\alpha}_1, \dots, \widetilde{\alpha}_\theta$, see the text before Lemma~\ref{lem_Fourier_transform_G_z_eps}, and $D_\varepsilon^{0,\kappa}(z)$ and $D_0^{0,\kappa}(z)$ in \eqref{eq_Fourier_Transform_eps} and \eqref{eq_Fourier_Transform_0}, respectively, into account, one sees that all terms that depend on $\kappa$ can be taken out of the integrals. This implies the claimed continuity.
	\end{proof}
	The structure of $\mathcal{F} D_\varepsilon^{0,\kappa}(z) \mathcal{F}^{-1}$ and $\mathcal{F} D_0^{0,\kappa}(z) \mathcal{F}^{-1}$ inspires us to change our viewpoint. Namely, instead of viewing theses operators in $\mathcal{B}^0(\R^{\theta-1})$ we consider them as operators in the isometrically isomorphic space $L^2(\R^{\theta-1};L^2((-1,1);\C^N))$. In \cite[Chapter~XIII.16]{RS77} and generally in the context of direct integrals the notation $\int_{\R^{\theta-1}}^\oplus L^2((-1,1);\C^N) \, d\xi'$ for this space is also common.
	Considered as operators acting in this space  $\mathcal{F} D_\varepsilon^{0,\kappa}(z) \mathcal{F}^{-1}$ and $\mathcal{F} D_0^{0,\kappa}(z) \mathcal{F}^{-1}$ are decomposable direct integral operators with fibers which are defined for 
	%\begin{definition}\label{def_frak_d}
	 $\varepsilon \geq  0$, $\xi' \in \R^{\theta-1}$, and $z \in \rho(H)$ by
		\begin{equation}\label{eq_def_frak_d}
			\begin{aligned}
				\mathfrak{D}_{\varepsilon,\xi'}({z})&: L^2((-1,1);\C^N) \to  L^2((-1,1);\C^N),\\
				\mathfrak{D}_{\varepsilon,\xi'}({z})f(t)&:=\int_{-1}^1 \bigg(\frac{\widetilde{\alpha}'\cdot \xi'   + m \beta + zI_N}{\sqrt{z^2-m^2-\abs{\xi'}^2}} + \widetilde{\alpha}_\theta\sign(t-s)\bigg)\\
				&\hspace{100 pt}\cdot\frac{ie^{\abs{\varepsilon(t-s)}i\sqrt{z^2-m^2-\abs{\xi'}^2}}}{2}f(s) \,ds.
%				\mathfrak{D}_{0,\xi'}({z})&: L^2((-1,1);\C^N) \to  L^2((-1,1);\C^N),
%				\mathfrak{D}_{0,\xi'}({z})f(t)&:=\int_{-1}^1 \bigg(\frac{\widetilde{\alpha}'\cdot \xi'  + m \beta + zI_N}{\sqrt{z^2-m^2-\abs{\xi'}^2}} + \widetilde{\alpha}_\theta\sign(t-s)\bigg)\frac{if(s)}{2} \,ds.
			\end{aligned}
		\end{equation}
	%\end{definition}
	\begin{remark}
		These operators still depend on the rotation matrix $\kappa \in \textup{SO}(\theta)$ since $\widetilde{\alpha}_1, \dots, \widetilde{\alpha}_\theta$ depend on $\kappa$. However, since we use these operators only as auxiliary operators in this section, we omit $\kappa$.
	\end{remark}

	Next, we explain the ideas described before \eqref{eq_def_frak_d} in a more rigorous way. Using 
	\begin{equation*}
		\begin{aligned}
			\mathcal{B}^0(\R^{\theta-1}) &= L^2((-1,1);L^2(\R^{\theta-1};\C^N)) \\
			&\simeq L^2((-1,1) \times \R^{\theta-1};\C^N) \simeq L^2(\R^{\theta-1};L^2((-1,1);\C^N)),
		\end{aligned}
	\end{equation*}
	see \cite[Corollary~1.2.23 and Proposition~1.2.24]{HNVW16}, allows us to define the isometric isomorphism
	\begin{equation*}
		\begin{aligned}
				\mathfrak{i}: \mathcal{B}^0(\R^{\theta-1}) &\to  L^2(\R^{\theta-1};L^2((-1,1);\C^N)),\\
			\mathfrak{i}  f(\xi')(t)&:= \mathcal{F}f(t)(\xi') \quad \text{for a.e. } (\xi',t) \in \R^{\theta-1}\times(-1,1). 
		\end{aligned}
	\end{equation*}
	Thus, by Proposition~\ref{prop_Fourier_D} and \eqref{eq_def_frak_d} we obtain for $\varepsilon\geq0$ that
	\begin{equation*}
			\mathfrak{i}  D^{0,\kappa}_\varepsilon({z}) \mathfrak{i}^{-1} :  L^2(\R^{\theta-1};L^2((-1,1);\C^N)) \to  L^2(\R^{\theta-1};L^2((-1,1);\C^N))
	\end{equation*}
	acts for $f \in L^2(\R^{\theta-1};L^2((-1,1);\C^N))$ and fixed $\xi' \in \R^{\theta-1}$  as 	$ \mathfrak{D}_{\varepsilon,\xi'}({z}) f(\xi')$,
	i.e.  $\mathfrak{i} D^{0,\kappa}_\varepsilon({z}) \mathfrak{i}^{-1}$ is a direct integral operator which can be decomposed in the fiber operators $\mathfrak{D}_{\varepsilon,\xi'}({z})$; cf. \cite[Chapter~XIII.16]{RS77}.


	Now, we  use the  theory of direct integrals in order to transfer results regarding $\mathfrak{D}_{\varepsilon,\xi'}({z})$ to ${D}^{0,\kappa}_\varepsilon({z})$ and vice versa.
	We formulate this in the upcoming lemma which follows from \cite[Theorem XIII.83 and Theorem XIII.84]{RS77}. There, we denote by $\mathcal{L}(L^2((-1,1);\C^N))$ the space of all bounded operators in $L^2((-1,1);\C^N)$.
	\begin{lemma}\label{lem_decomp_op}
		Let $\mathfrak{M} \in L^\infty(\R^{\theta-1};\mathcal{L}(L^2((-1,1);\C^N)))$ and $M$ be defined by
		\begin{equation*}
			M : \mathcal{B}^0(\R^{\theta-1}) \to \mathcal{B}^0(\R^{\theta-1}), \qquad
			\mathfrak{i}  M \mathfrak{i}^{-1} f(\xi') := \mathfrak{M}(\xi') f(\xi'). 
		\end{equation*}
		Then, 
		\begin{equation*}
			\begin{aligned}
			\| M \|_{0 \to 0} &=  \|\mathfrak{M}\|_{L^\infty(\R^{\theta-1};\mathcal{L}(L^2((-1,1);\C^N)))} \\
			&= \textup{ess sup}_{\xi' \in \R^{\theta -1}} \| \mathfrak{M}(\xi')\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N)}
			\end{aligned}
		\end{equation*}
		 and the operator $M$ is continuously invertible if and only if $\mathfrak{M}$ is continuously invertible a.e. and the inequality ${\|\mathfrak{M}^{-1}\|_{L^\infty(\R^{\theta-1};\mathcal{L}(L^2((-1,1);\C^N)))} < \infty}$ holds. Furthermore, in this case $\|M^{-1}\|_{0\to0} = \|\mathfrak{M}^{-1}\|_{L^\infty(\R^{\theta-1};\mathcal{L}(L^2((-1,1);\C^N)))} $.
	\end{lemma}



	Next, we study the operator $\mathfrak{D}_{\varepsilon,\xi'}(z)$ in detail. For this purpose, we introduce for $\rho \in (0,\infty)$ and $w' \in \R^{\theta-1}$ with $\abs{w'} = 1$ the auxiliary operator
	\begin{equation*}%\label{eq_def_frak_h}
		\begin{aligned}
			\mathfrak{H}_{\rho,w'} :L^2((-1,1);\C^N) &\to L^2((-1,1);\C^N) \\
			(\mathfrak{H}_{\rho,w'} f) (t) &:= \int_{-1}^{1} \big( \widetilde{\alpha}'\cdot w' +  i  \widetilde{\alpha}_\theta \sign(t-s) ) \frac{e^{-\rho\abs{t-s}}}{2}f(s)\,ds.
		\end{aligned}
	\end{equation*}
	It is not difficult to check that $\mathfrak{H}_{\rho,w'}$ is a self-adjoint Hilbert-Schmidt operator.

	\begin{lemma}\label{lem_diff_frak_operators} 
		Let  $\varepsilon > 0$, $ \xi' \in \R^{\theta-1} \setminus \{0\}$, and $z \in \rho(H)$. Then, there exists a constant $C_1>0$ which only depends on $m$ and $z$ such that
		\begin{equation*}
			\begin{aligned}
				\norm{ \mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{D}_{0,\xi'}({z}) }_{L^2( 	(-1,1); \C^N) \to L^2((-1,1) ; \C^N) }  &\leq  C_1 \varepsilon (1+\abs{\xi'}),\\
				\norm{ 	\mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}}_{L^2( (-1,1); \C^N) \to L^2((-1,1) ; \C^N) }  &\leq \frac{C_1}{1+\abs{\xi'}}.
			\end{aligned}
		\end{equation*}
	\end{lemma}
	\begin{proof}
	 	In this proof $C>0$ denotes a constant which may change in-between lines, but only depends on $m$ and $z$.	We start by estimating the kernel of the integral operator $\mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{D}_{0,\xi'}({z})$. It is easy to see that we can estimate this kernel by
		\begin{equation*}
			\begin{aligned}
				C\Bigl|1- e^{\varepsilon \abs{t-s}i\sqrt{z^2-m^2-\abs{\xi'}^2}} \Bigr| &\leq C\varepsilon \abs{t-s} \sqrt{ \abs{ z^2-m^2-\abs{\xi'}^2}} \\
				&\leq C \varepsilon  (1+\abs{\xi'}).
			\end{aligned}
		\end{equation*}
		With this estimate one finds a constant $C_1$ which only depends on $m$ and $z$ such that 
		\begin{equation*}
			\norm{\mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{D}_{0,\xi'}({z})}_{L^2((-1,1); \C^N) \to L^2((-1,1);\C^N)} \leq  C_1 \varepsilon  (1+\abs{\xi'}).
		\end{equation*}
		Next, we estimate the kernel of $\mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}} $  by
		\begin{equation}\label{eq_diff_frak_op_kernel}
			\begin{aligned}
				&\frac{1}{2}\biggl|\left( e^{-\varepsilon\abs{t-s}|\xi'|} -e^{\varepsilon\abs{t-s}i{\sqrt{m^2-z^2-\abs{\xi'}^2}}} \right)\left( \widetilde{\alpha}'\cdot \frac{\xi'}{|\xi'|} +  \widetilde{\alpha}_\theta i \sign(t-s)\right)\biggr| \\
				&\hspace{ 30 pt}+  \frac{1}{2}\Biggl|e^{\varepsilon\abs{t-s} i{\sqrt{z^2-m^2-\abs{\xi'}^2 }}} \Big(\widetilde{\alpha}'\cdot \frac{\xi'}{|\xi'|}\Big)\Bigg(1-\frac{i\abs{\xi'}}{\sqrt{z^2-m^2-\abs{\xi'}^2}}\Bigg)\Biggr| \\
				&\hspace{ 30 pt}+\frac{1}{2}  \Biggl|e^{\varepsilon\abs{t-s}i{\sqrt{z^2-m^2-\abs{\xi'}^2}}} \Bigg(\frac{m \beta + {z} I_N}{\sqrt{z^2-m^2-\abs{\xi'}^2 }} \Bigg)\Biggr|.
			\end{aligned}
		\end{equation}
		The first term in \eqref{eq_diff_frak_op_kernel} can be estimated for $\varepsilon \abs{t-s} \leq 1$ by
		\begin{equation*}
			\begin{aligned}
				C \Bigl|e^{-\varepsilon\abs{t-s}|\xi'|} -e^{\varepsilon\abs{t-s}i{\sqrt{z^2-m^2-\abs{\xi'}^2}}}\Bigr| &\leq C \varepsilon |t-s| \Big||\xi'|+i\sqrt{z^2-m^2-\abs{\xi'}^2} \Big|\\
				&\leq C \frac{|z^2-m^2|}{\Big||\xi'|-i\sqrt{z^2-m^2-\abs{\xi'}^2} \Big|}\\
				&\leq  \frac{ C}{1+\abs{\xi'}},
			\end{aligned}
		\end{equation*}
		where we used  $z \in \rho(H) = \C \setminus \big((-\infty,-|m|]\cup[|m|,\infty) \big)$ and   $\textup{Im } \sqrt{w} >0$ for $w \in \C \setminus [0,\infty)$. For $\varepsilon |t-s|> 1$ we get
		\begin{equation*}
			C \Bigl| e^{-\varepsilon\abs{t-s}|\xi'|} -e^{\varepsilon\abs{t-s}i{\sqrt{z^2-m^2-\abs{\xi'}^2}}} \Bigr| \leq C (e^{-\abs{\xi'}} + e^{- \textup{Im} \sqrt{z^2 - m^2 -\abs{\xi'}^2}})  
			\leq  \frac{ C}{1+\abs{\xi'}}.
		\end{equation*}
		Similarly as we estimated the first term in the case $\varepsilon \abs{t-s} \leq 1$, the second term in \eqref{eq_diff_frak_op_kernel} can be estimated by
		\begin{equation*}
			\begin{aligned}
				C \bigg| 1-\frac{i\abs{\xi'}}{\sqrt{z^2-m^2-\abs{\xi'}^2}} \bigg| &= C \frac{ |z^2-m^2|}{\big|\sqrt{z^2-m^2-\abs{\xi'}^2}+i|\xi'|\big| \big|\sqrt{z^2-m^2-\abs{\xi'}^2}\big|}\\
				&\leq \frac{C}{(1+|\xi'|)^2} \leq \frac{C}{1+|\xi'|}.
			\end{aligned}
		\end{equation*}
		One also sees that third term in \eqref{eq_diff_frak_op_kernel} is smaller than $\tfrac{C}{1+|\xi'|}$ for sufficiently large $C$. Summing up, we have that the kernel of $\mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}} $ can be bounded by $\tfrac{C}{1+|\xi'|}$ and therefore if $C_1$  is chosen sufficiently large, then
		\begin{equation*}
			\norm{ \mathfrak{D}_{\varepsilon,\xi'}({z})-\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}}_{L^2( (-1,1); \C^N) \to L^2((-1,1) ; \C^N) }  \leq \frac{C_1}{1+\abs{\xi'}}.
		\end{equation*}
	\end{proof}

	\begin{lemma}\label{lem_volterra}
		Let  $\rho>0$, $w' \in \R^{\theta-1}$ with $\abs{w'} =1$ and $q$ be as in \eqref{eq_q2}. Then, $\sigma(\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q}) \subset [-\tfrac{2}{\pi},\tfrac{2}{\pi}]$.
	\end{lemma}
	\begin{proof}
		To shorten notation we set $\widetilde{\alpha}_\pm := \widetilde{\alpha}' \cdot w' \pm i\widetilde{\alpha}_\theta$. Then, one has for $f \in L^2((-1,1);\C^N)$
		\begin{equation*}
			\mathfrak{H}_{\rho,w'}f(t) = \frac{1}{2}\int_t^1  e^{-\rho|t-s|}\widetilde{\alpha}_- f(s) \,ds   + \frac{1}{2}\int_{-1}^t   e^{-\rho|t-s|}\widetilde{\alpha}_+ f(s) \,ds.
		\end{equation*}
		Using the anti-commutation rules for $\widetilde{\alpha}' \cdot w'$ and $\widetilde{\alpha}_\theta$, and $(\widetilde{\alpha} \cdot w')^2 = \widetilde{\alpha}_\theta^2 = I_N$, see the definition of $\widetilde{\alpha}_1, \dots, \widetilde{\alpha}_\theta$ before Lemma~\ref{lem_Fourier_transform_G_z_eps} and \eqref{it_Dirac_matrices} in Section~\ref{sec_not}, shows that $\ran \widetilde{\alpha}_+ \perp \ran \widetilde{\alpha}_-$.  Hence, as $q \geq 0$,  we have for  $f \in L^2((-1,1); \C^N)$ 
		\begin{equation}\label{eq_volterra}
			\begin{aligned}
				\|\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q}f&\|_{L^2((-1,1);\C^N)}^2 \\
				=& \frac{1}{4} \int_{-1}^1 q(t) \bigg| \int_t^1 e^{-\rho|t-s|}\widetilde{\alpha}_-  \sqrt{q(s)} f(s)  \,ds  \bigg|^2 \,dt \\
				&+ \frac{1}{4} \int_{-1}^1 q(t) \bigg| \int_{-1}^t   e^{-\rho|t-s|}\widetilde{\alpha}_+ \sqrt{q(s)}f(s) \,ds  \bigg|^2 \,dt.
			\end{aligned}
		\end{equation}
		We start by estimating the first term on the right-hand side. To do so, we assume that $Q$ is the primitive function of $q$ such that $Q(1) =0$ and therefore by $\int_{-1}^1 q(s) \, ds =1$, $Q(-1) =-1$. Applying the Cauchy-Schwarz inequality and Fubini's theorem yields
		\begin{equation*}
			\begin{aligned}
				\frac{1}{4}\int_{-1}^1 q(t) &\biggl| \int_t^1  e^{-\rho|t-s|}\widetilde{\alpha}_-  \sqrt{q(s)} f(s)  \,ds  \biggr|^2 \,dt\\
				&= \frac{1}{4} \int_{-1}^1 q(t) \biggl| \int_t^1  \frac{\sqrt{\cos\bigl(\tfrac{\pi}{2}Q(s)\bigr)}}{\sqrt{\cos\bigl(\tfrac{\pi}{2}Q(s)\bigr)}}  e^{-\rho|t-s|}\widetilde{\alpha}_-  \sqrt{q(s)} f(s)  \,ds  \biggr|^2 \,dt\\
				&\leq \frac{1}{4} \int_{-1}^1 q(t) \bigg(\int_{t}^1 \cos\bigl(\tfrac{\pi}{2}Q(s)\bigr)q(s) \,ds \bigg) \bigg( \int_{t}^1 \frac{1}{\cos(\tfrac{\pi}{2}Q(s))}|\widetilde{\alpha}_-f(s)|^2\,ds \bigg) \, dt\\
				&= \frac{1}{2\pi} \int_{-1}^1  -\sin\bigl(\tfrac{\pi}{2}Q(t)\bigr) q(t)\bigg(\int_{t}^1 \frac{1}{\cos\bigl(\tfrac{\pi}{2}Q(s)\bigr)}|\widetilde{\alpha}_- f(s)|^2\,ds \bigg) \, dt\\
				&=  \frac{1}{2\pi} \int_{-1}^1  \bigg( \int_{-1}^s -\sin\bigl(\tfrac{\pi}{2}Q(t)\bigr)q(t) \,dt \bigg) \frac{1}{\cos\bigl(\tfrac{\pi}{2}Q(s)\bigr)}|\widetilde{\alpha}_- f(s)|^2\,ds \\
				&= \frac{1}{\pi^2} \int_{-1}^1 |\widetilde{\alpha}_- f(s)|^2 \, ds.
			\end{aligned}
		\end{equation*}
		The same trick with $Q +1$ instead of $Q$ yields that the second term of the right hand side of equation \eqref{eq_volterra} can be estimated by  $\tfrac{1}{\pi^2} \int_{-1}^1 |\widetilde{\alpha}_+ f(s)|^2 \, ds.$ Using these estimates and  $\ran \widetilde{\alpha}_+ \perp \ran \widetilde{\alpha}_-$ gives us
		\begin{equation*}
			\begin{aligned}
				\|\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q}f\|_{L^2((-1,1);\C^N)}^2 & \leq \frac{1}{\pi^2} \int_{-1}^{1} |\widetilde{\alpha}_- f(s)|^2 +|\widetilde{\alpha}_+ f(s) |^2 \,ds \\
				&= \frac{1}{\pi^2} \int_{-1}^{1} |(\widetilde{\alpha}_- + \widetilde{\alpha}_+) f(s) |^2 \,ds\\
				&= \frac{1}{\pi^2} \int_{-1}^{1} |2(\widetilde{\alpha}' \cdot w')f(s) |^2 \,ds \\
				& = \frac{4}{\pi^2} \norm{f}_{L^2((-1,1);\C^N)}^2.
			\end{aligned}
		\end{equation*}
		Since $\mathfrak{H}_{\rho,w'}$ is self-adjoint in $L^2((-1,1);\C^N)$, we obtain $\sigma(\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q}) \subset [-\tfrac{2}{\pi}, \tfrac{2}{\pi}]$. 
	\end{proof}

	Having studied the spectrum of $\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q}$, we employ this knowledge to study the bounded invertibility of $I + \mathfrak{H}_{\rho,w'}Q_{\eta,\tau}q$. Recall that $Q_{\eta,\tau} = \eta I_N + \tau \beta$ for $\eta,\tau \in \R$. 
