	\begin{lemma}\label{lem_frak_h_inv_estimate}
		Let $\rho > 0$, $w' \in \R^{\theta-1}$ with $\abs{w'}=1$, $\eta,\tau \in \R$, $Q_{\eta,\tau}= \eta I_N + \tau \beta$, $d = \eta^2-\tau^2$,
		\begin{equation*}
			c(d):= 
			\begin{cases}
				\frac{4 d}{\pi^2}, &  d \geq  0, \\
				0,  & d<0, 
			\end{cases}
		\end{equation*} 
		and  $q$ be as in \eqref{eq_q2}.
		If $d < \frac{\pi^2}{4}$, then  $I + \mathfrak{H}_{\rho,w'}Q_{\eta,\tau} q$ is continuously invertible in $L^{2}((-1,1);\C^N)$ and the norm of the inverse is bounded by the constant 
		\begin{equation}\label{eq_def_C_2}
			C_{2} = C_{2}(\eta,\tau) := 4\norm{q}_{L^\infty((-1,1))} (\abs{\eta}+\abs{\tau})\frac{1 + (\abs{\eta}+\abs{\tau})\frac{2}{\pi}}{(1-c(d))\pi}  + 1.
		\end{equation}
	\end{lemma}
	\begin{proof}
		Using $\mathfrak{H}_{\rho,w'} Q_{\eta,\tau} = Q_{\eta,-\tau} \mathfrak{H}_{\rho,w'}$ and $Q_{\eta,-\tau} Q_{\eta,\tau} = d I_N$, which follows from the anti-commutation relations for $\widetilde{\alpha}_1, \dots, \widetilde{\alpha}_\theta$, discussed before Lemma~\ref{lem_Fourier_transform_G_z_eps}, and $\beta$, gives us
		\begin{equation*}
			I -	d (\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q})^2 = ( I	-\sqrt{q}\mathfrak{H}_{\rho,w'}Q_{\eta,\tau}\sqrt{q} ) ( I+	\sqrt{q}\mathfrak{H}_{\rho,w'} Q_{\eta,\tau} \sqrt{q}) .
		\end{equation*}
		If $d<\tfrac{\pi^2}{4}$, then Lemma~\ref{lem_volterra} implies $1 \in \rho(d( \sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q})^2)$ and therefore  the operator $I + \sqrt{q}\mathfrak{H}_{\rho,w'}Q_{\eta,\tau}\sqrt{q} $ is also continuously invertible in $L^{2}((-1,1);\C^N)$ and 
		\begin{equation*}
			\begin{aligned}
				&\bigl\|(I+ \sqrt{q}\mathfrak{H}_{\rho,w'} Q_{\eta,\tau}\sqrt{q})^{-1}\bigr\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }   \\
				&\hspace{20 pt}= 	\bigl\|(I -	d (\sqrt{q}\mathfrak{H}_{\rho,w'}\sqrt{q})^2)^{-1}( I	-\sqrt{q}\mathfrak{H}_{\rho,w'}Q_{\eta,\tau}\sqrt{q} )\bigr\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }\\
				&\hspace{20 pt}\leq \frac{1 + (\abs{\eta}+\abs{\tau})\frac{2}{\pi}}{1-c(d)}. 
			\end{aligned}
		\end{equation*}
		Moreover,   $(I+\mathfrak{H}_{\rho,w'} Q_{\eta,\tau}q)^{-1} = I - \mathfrak{H}_{\rho,w'} Q_{\eta,\tau}\sqrt{q}(I+ \sqrt{q}\mathfrak{H}_{\rho,w'} Q_{\eta,\tau}\sqrt{q})^{-1} \sqrt{q} $ and  hence
		\begin{equation*}
			\begin{aligned}
				&\bigl\|(I+ \mathfrak{H}_{\rho,w'}  Q_{\eta,\tau}q)^{-1}\bigr\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }   \\
				&\hspace{15 pt}= 	\bigl\|\mathfrak{H}_{\rho,w'} Q_{\eta,\tau}\sqrt{q} (I+ \sqrt{q}\mathfrak{H}_{\rho,w'} Q_{\eta,\tau}\sqrt{q})^{-1}\sqrt{q} - I  \bigr\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }\\
				&\hspace{15 pt}\leq \norm{q}_{L^\infty((-1,1))} (\abs{\eta}+\abs{\tau}) \norm{\mathfrak{H}_{\rho,w'}   }_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } \frac{1 + (\abs{\eta}+\abs{\tau})\frac{2}{\pi}}{1-c(d)}  + 1\\
				&\hspace{15 pt}\leq 4\norm{q}_{L^\infty((-1,1))} (\abs{\eta}+\abs{\tau})\frac{1 + (\abs{\eta}+\abs{\tau})\frac{2}{\pi}}{(1-c(d))\pi}  + 1,
			\end{aligned}
		\end{equation*}
		where we used Lemma~\ref{lem_volterra} (for the constant function $q = \tfrac{1}{2}$) to estimate the term $\norm{\mathfrak{H}_{\rho,w'}   }_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }$  by $\tfrac{4}{\pi}$.
