	In the last part of Section~\ref{sec_hyperplane} we use our findings to prove  norm estimates for the operator $(I+D_\varepsilon^{0,\kappa}(z)Q_{\eta,\tau}q)^{-1}$.
	\begin{proposition}\label{prop_uniform_bdd_D}
		Let $z \in \C \setminus \R$,  $\kappa \in \textup{SO}(\theta)$, $\eta,\tau \in \R$ such that $d = \eta^2 - \tau^2< \tfrac{\pi^2}{4}$, and $q$ be as in \eqref{eq_q2}. Moreover, let 
		\begin{equation}\label{eq_def_C_3}
			C_3 = C_3(\eta,\tau,\kappa) :=2\max\{C_2, \| (I+D_{0}^{0,\kappa}(z)Q_{\eta,\tau}q)^{-1} \|_{0\to0} \},
		\end{equation}
		with $C_2 = C_2(\eta,\tau)$ as in \eqref{eq_def_C_2}, and  
		\begin{equation}\label{eq_def_delta_1}
			\delta_1 =\delta_1(\eta,\tau,\kappa):= ( C_3 C_1(|\eta| + |\tau|) \norm{q}_{L^\infty((-1,1))})^{-2},
		\end{equation} 
		with $C_1$ from  Lemma~\ref{lem_diff_frak_operators}. Then,
		\begin{equation*}%\label{eq_D_eps_bdd}
			\sup_{\varepsilon \in (0,\delta_1) } \norm{(I+D^{{0,\kappa}}_\varepsilon(z)Q_{\eta,\tau}q)^{-1}}_{0 \to 0} \leq C_3 < \infty.
		\end{equation*} 
	\end{proposition}
	\begin{proof}
		We claim that $C_3 < \infty$. Since $d< \tfrac{\pi^2}{4}$, the constant $C_2$ from \eqref{eq_def_C_2} is finite. Thus, it suffices to show $\| (I+D_{0}^{0,\kappa}(z)Q_{\eta,\tau}q)^{-1} \|_{0\to0} < \infty$ in order to proof the claim $C_3 < \infty$.

		 Applying  Proposition~\ref{prop_inv_I+BVq} (for $V= Q_{\eta,\tau} = \eta I_2+\tau\beta =\textup{const.}$ and $r=0$) shows that $I + B_0(z)Q_{\eta,\tau}q$ is continuously invertible in $\mathcal{B}^0(\Sigma_{0,\kappa})$. Let us shortly explain why  Proposition~\ref{prop_inv_I+BVq} is indeed applicable. The inequality $d < \tfrac{\pi^2}{4}$ implies $d \not= (2k+1)^2\pi^2$, $k \in \N_0$, and therefore \eqref{eq_scaling_cond} is fulfilled. In the same way as in Proposition~\ref{prop_inv_I+BVq}  we set $(\widetilde{\eta},\widetilde{\tau})  = \textup{tanc}\bigl(\tfrac{\sqrt{d}}{2}\bigr) (\eta,\tau) $. Then, $\widetilde{d} = \widetilde{\eta}^2-\widetilde{\tau}^2 = 4\tan\bigl(\tfrac{\sqrt{d}}{2}\bigr) < 4$, i.e. $\widetilde{d}$ fulfils \eqref{eq_d_tilde_non_crit}. Hence, the assumptions of Proposition~\ref{prop_inv_I+BVq} are satisfied and its application is justified. Together with \eqref{eq_norm_iota} and \eqref{def_D_operators}, this implies that  the operator $I + D_0^{0,\kappa}(z)Q_{\eta,\tau}q = \iota_{0,\kappa} (I + B_0(z)Q_{\eta,\tau}q) \iota_{0,\kappa}^{-1}$ is continuously invertible in $\mathcal{B}^0(\R^{\theta-1})$, which proves $\| (I+D_{0}^{0,\kappa}(z)Q_{\eta,\tau}q)^{-1} \|_{0\to0} < \infty$. Hence, $C_3 < \infty$.

		According to Lemma \ref{lem_diff_frak_operators} we have
		\begin{equation*}
			\begin{aligned}
				&\bigl\|\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q - \mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q \bigr\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } \\
				&\hspace{50 pt}\leq C_1 \norm{q}_{L^\infty((-1,1))}\frac{\abs{\eta}+\abs{\tau}}{1+|\xi'|} = \frac{\delta_1^{-1/2}}{C_3(1+|\xi'|)}
			\end{aligned}
		\end{equation*}	
		for $\xi' \in \R^{\theta-1}\setminus\{0\}$ and all $\varepsilon>0$. Hence, if we choose $R:=\delta_1^{-1/2}-1$, then the choices of $C_3$, $\delta_1$ and $R$, and Lemma~\ref{lem_frak_h_inv_estimate} yield for $0\neq |\xi'| \geq R$  and $\varepsilon>0$
		\begin{equation*}
			\begin{aligned}
				\bigl\|(I+&\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q)^{-1}\\
				&\cdot(\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q - \mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q)\bigr\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } \\
				&\leq C_2 \frac{\delta_1^{-1/2}}{C_3 (1+R)} \\
				& \leq \frac{C_3}{2} \cdot \frac{ \delta_1^{-1/2}}{ C_3 \delta_1^{-1/2}} \\
				&=  \frac{1}{2}.
			\end{aligned}
		\end{equation*}
 In particular,
		\begin{equation*}
			\mathfrak{P}_{\varepsilon,\xi'}:=	I +(I+\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q)^{-1}
			(\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q - \mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q)
		\end{equation*}
		is continuously invertible in $L^2((-1,1);\C^N)$ and the norm of its inverse can be bounded by $2$ for $0\neq |\xi'| \geq R$ and $\varepsilon >0$. This implies that also 
		\begin{equation*}
			I+\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q=(I+\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q) \mathfrak{P}_{\varepsilon,\xi'}
		\end{equation*}
		is continuously invertible in $L^2((-1,1);\C^N)$  and by Lemma~\ref{lem_frak_h_inv_estimate}  the corresponding norm estimate
		\begin{equation}\label{eq_uniform_bdd_D_1}
			\begin{aligned}
				&\norm{ (I+\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q)^{-1} }_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }  \\
				&\hspace{50 pt}=	\big\|\mathfrak{P}_{\varepsilon,\xi'}^{-1}(I+\mathfrak{H}_{\abs{\xi'}\varepsilon,\xi'/\abs{\xi'}}Q_{\eta,\tau}q)^{-1} \big\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }  \\
				&\hspace{50 pt} \leq 2 C_2 \\
				& \hspace{50 pt} \leq C_3
			\end{aligned}
		\end{equation}	
		is valid	for $0\neq |\xi'| \geq R$ and $\varepsilon >0$. 

		Having found an estimate for $0 \neq |\xi'| \geq R$, we aim to find a similar estimate for $0 \neq |\xi'| \leq R$.
		Again, according to  Lemma \ref{lem_diff_frak_operators}  we have for $\xi' \in \R^{\theta-1}\setminus\{0\}$ and $\varepsilon>0$
		\begin{equation*}
			\begin{aligned}
				&\norm{\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q - \mathfrak{D}_{0,\xi'}({z})Q_{\eta,\tau}q }_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }\\
				&\hspace{30 pt}\leq C_1 \norm{q}_{L^\infty((-1,1))}(\abs{\eta}+\abs{\tau})\varepsilon(1+|\xi'|)
				=\varepsilon \frac{\delta_1^{-1/2}(1+|\xi'|)}{C_3}.
			\end{aligned}
		\end{equation*}

		Moreover, Lemma \ref{lem_decomp_op} (with $\mathfrak{M}(\xi') =  I+\mathfrak{D}_{0,\xi'}({z})Q_{\eta,\tau}q$ for $\xi' \in \R^{\theta-1}$)  and \eqref{eq_def_C_3} imply 
		\begin{equation*}
			\begin{aligned}
				\textup{ess sup}_{\xi'\in\R^{\theta-1}} &\| (I+\mathfrak{D}_{0,\xi'}({z})Q_{\eta,\tau}q)^{-1} \|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } \\
				=&\|(I+D^{{0,\kappa}}_0(z)Q_{\eta,\tau}q)^{-1}\|_{0 \to 0} 
				\leq \frac{C_3}{2}.
			\end{aligned}
		\end{equation*}
		Hence, as $1+R = \delta_1^{-1/2}$, we can estimate similarly as in the first part of the proof for $\varepsilon \in (0,\delta_1)$
		\begin{equation}\label{eq_uniform_bdd_D_2}
			\begin{aligned}
				&\textup{ess sup}_{\abs{\xi'} \leq R} \norm{ (I+\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q)^{-1} }_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } \\
				&= \textup{ess sup}_{\abs{\xi'} \leq R} \big\| \big[I+(I+\mathfrak{D}_{0,\xi'}({z})Q_{\eta,\tau}q)^{-1}\bigl(\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q  -\mathfrak{D}_{0,\xi'}({z})Q_{\eta,\tau}q \bigr)\big]^{-1}\\
				&	\hspace{100 pt}\cdot(I+\mathfrak{D}_{0,\xi'}({z})Q_{\eta,\tau}q)^{-1} \big\|_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) }\\
				&\leq \frac{1}{1-\frac{C_3}{2} \cdot \frac{\varepsilon\delta_1^{-1/2}(1+R)}{C_3}} \cdot \frac{C_3}{2}\\
				&= \frac{1}{1-\frac{C_3}{2} \cdot \frac{\varepsilon\delta_1^{-1}}{C_3}} \cdot \frac{C_3}{2}  \leq C_3.
			\end{aligned}
		\end{equation}	
		Combining \eqref{eq_uniform_bdd_D_1} and  \eqref{eq_uniform_bdd_D_2}, and applying  Lemma~\ref{lem_decomp_op} gives us
		\begin{equation*}
			\begin{aligned}
				&\hspace{-10 pt}\norm{(I+D_{\varepsilon}^{0,\kappa}({z})Q_{\eta,\tau}q)^{-1} }_{0\to0}\\
				&= \max\big\{ \textup{ess sup}_{|\xi'| \geq R
				}\norm{(I+\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q)^{-1}}_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } , \\ 
				&\hspace{47 pt}\textup{ess sup}_{|\xi'| < R}\norm{(I+\mathfrak{D}_{\varepsilon,\xi'}({z})Q_{\eta,\tau}q)^{-1}}_{L^2((-1,1);\C^N) \to L^2((-1,1);\C^N) } \big\}  \\
				&\leq C_3
			\end{aligned} 
		\end{equation*}	
		for $\varepsilon \in (0,\delta_1)$.
	\end{proof}


	\begin{cor}\label{cor_uniform_bdd_D}
		Let $z \in \C \setminus \R$,   $q$ be as in \eqref{eq_q2}, $S \subset \R^2$ be compact and $\max_{(\eta,\tau) \in S} \eta^2-\tau^2 < \tfrac{\pi^2}{4}$. Then, there exists a $\delta_2= \delta_2(S) > 0$  such that 
		\begin{equation*}%\label{eq_D_eps_bdd_uni}
			\sup_{(\varepsilon, y_0, (\eta,\tau), \kappa ) \in (0,\delta_2) \times \R \times S \times  \textup{SO}(\theta)} \norm{(I+D^{{y_0,\kappa}}_\varepsilon(z)Q_{\eta,\tau}q)^{-1}}_{0 \to 0} < \infty.
		\end{equation*} 
	\end{cor}
	\begin{proof}
		Since $D_\varepsilon^{y_0,\kappa}(z) = D_\varepsilon^{0,\kappa}(z)$, see the text below \eqref{eq_D_eps_straight}, the assertion follows directly from Proposition~\ref{prop_uniform_bdd_D} if we can show
		\begin{equation*}
			\sup_{((\eta,\tau),\kappa) \in S \times \textup{SO}(\theta)} C_3(\eta,\tau,\kappa) < \infty \quad \textup{and} \quad \inf_{((\eta,\tau),\kappa) \in S \times \textup{SO}(\theta)} \delta_1(\eta,\tau,\kappa) >0,
		\end{equation*}
		with $C_3$ and $\delta_1$ as in Proposition \ref{prop_uniform_bdd_D}. Note also that as $S$ is bounded the first inequality  and \eqref{eq_def_delta_1} imply the second inequality in the above displayed formula. Moreover, the assumption $\max_{(\eta,\tau)\in S} \eta^2-\tau^2< \tfrac{\pi^2}{4}$ implies $\max_{(\eta,\tau) \in S}C_2(\eta,\tau)< \infty$, where $C_2$ was defined in \eqref{eq_def_C_2}. Hence, it follows from \eqref{eq_def_C_3} that the inequality  $\sup_{((\eta,\tau),\kappa) \in S \times \textup{SO}(\theta)} C_3(\eta,\tau,\kappa) < \infty $  is fulfilled if 
		\begin{equation}\label{eq_cor_D_uniform_bdd}
			\sup_{((\eta,\tau),\kappa)\in S\times\textup{SO}(\theta)} \|(I+D^{{0,\kappa}}_0(z)Q_{\eta,\tau}q)^{-1}\|_{0 \to 0} < \infty.
		\end{equation}
		Obviously, the operator $D^{{0,\kappa}}_0(z)Q_{\eta,\tau}q$ depends continuously on  $\eta$, $\tau$ with respect to the operator norm in $\mathcal{B}^0(\R^{\theta-1})$. According to    Proposition~\ref{prop_Fourier_D} $D^{{0,\kappa}}_0(z)Q_{\eta,\tau}q$ depends also continuously on $\kappa$ with respect to the operator norm. Moreover, Proposition~\ref{prop_uniform_bdd_D} gives us that the operator $I+ D^{{0,\kappa}}_0(z)Q_{\eta,\tau}q  $ is continuously invertible in $\mathcal{B}^0(\R^{\theta-1})$ for $((\eta,\tau), \kappa) \in S \times \textup{SO}(\theta)$. Thus, as $S \times \textup{SO}(\theta)$ is compact,  \eqref{eq_cor_D_uniform_bdd} is indeed true.
	\end{proof} 

	\subsubsection{$\Sigma$ is a rotated $C^2_b$-graph}\label{sec_loc_part}
	After treating the case of affine hyperplanes, we turn to the case where $\Sigma$ is a rotated $C^2_b$-graph as in \eqref{eq_rotated_graph}, i.e.  there exist ${\zeta \in C^2_b(\R^{\theta-1};\R)}$ and $\kappa \in \textup{SO}(\R^{\theta})$ such   that 
	\begin{equation*}
		\Sigma = \Sigma_{\zeta,\kappa} = \{\kappa(x',\zeta(x')): x' \in \R^{\theta -1} \}.
	\end{equation*}
	Moreover, recall that $x_{\zeta,\kappa}(x') = \kappa(x',\zeta(x'))$ and $\nu_{\zeta,\kappa}(x') = \nu(x_{\zeta,\kappa}(x'))$, $x' \in \R^{\theta-1}$, see \eqref{eqref_x_nu_zeta_kappa}. According to \cite[Proposition A.2 (i), first line of the proof of Proposition 2.4, and eq. (3.11)]{BHS23} there exists a $C_4 = C_4(\Sigma)>0$ such that for all $x',y' \in \R^{\theta-1}$ and $\widetilde{\varepsilon} \in (-2\varepsilon_2,2\varepsilon_2)$
	\begin{equation}\label{eq_est_x_Sigma}
		C_4^{-1}\big(|x'-y' | + |\widetilde{\varepsilon}|\big)  \leq|x_{\zeta,\kappa}(x') - x_{\zeta,\kappa}(y') + \widetilde{\varepsilon} \nu_{\zeta,\kappa}(x')| \leq C_4 \big(|x'-y' | + |\widetilde{\varepsilon}|\big),  
	\end{equation}
	with $\varepsilon_2>0$ chosen as in Proposition~\ref{prop_conv_res}.
	We are going to prove the uniform boundedness of $(I + B_\varepsilon(z)Vq)^{-1}$ in $\mathcal{B}^0(\Sigma)$ with respect to $\varepsilon \in (0,\varepsilon_3)$, for a suitable $\varepsilon_3 \in (0,\varepsilon_2)$.  It follows from \eqref{eq_B_diff}, \eqref{eq_norm_iota}, \eqref{def_D_operators}, and  \eqref{eq_Q_matrix} that this is equivalent to proving the uniform boundedness of  $(I + D_\varepsilon^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1} = \iota_{\zeta,\kappa}(I + \overline{B}_\varepsilon(z)Vq)^{-1} \iota_{\zeta,\kappa}^{-1}$.

	We start by analysing $D_\varepsilon^{\zeta,\kappa}(z)$ locally. To do so we need to introduce further notations. For $x_0' \in \R^{\theta-1}$ we define 
	\begin{equation}\label{eq_zeta_x_0'}
		\zeta_{x_0'}(x') := \zeta(x_0') + \langle\nabla \zeta(x_0'), x'-x_0' \rangle, \qquad  x'\in \R^{\theta-1}.
	\end{equation}
	Moreover, we define the localisation parameter $a_\varepsilon := \varepsilon^{1/6}$ for $\varepsilon \in (0,\varepsilon_2)$.
	Next, we introduce a family of auxiliary operators. For this, we choose a $C^\infty$-function $\omega$ with $0 \leq \omega \leq 1$, $\omega = 1$ on $\R^{\theta-1} \setminus B(0,1)$ and $\omega =0$ on $B(0,\frac{1}{2})$. We use this function to cut out the singular part of the integral kernel of $D_{\varepsilon}^{\zeta,\kappa}(z)$; cf. \eqref{eq_D_eps_int_rep_0}. More precisely, in analogy with  \eqref{eq_D_eps_int_rep} and  \eqref{eq_d_eps}, we define for $\varepsilon \in (0,\varepsilon_2)$ and $\widetilde{\varepsilon} \in (-2\varepsilon_2,2\varepsilon_2)\setminus \{0\}$ the operators
	\begin{equation}\label{def_e_eps}
		\begin{aligned}
			e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z) &: L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N),\\
			e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)  g (x') &:= \int_{\R^{\theta-1}} G_z(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x')) \omega\bigl(\tfrac{x' - y'}{a_\varepsilon}\bigr)\\
			&\hspace{150 pt}\cdot\sqrt{1+ \abs{\nabla \zeta(y')}^2} g(y') \,dy',
		\end{aligned}
	\end{equation}
	and 
	\begin{equation}\label{def_E_eps}
		E_{{\varepsilon}}(z) :\mathcal{B}^0(\R^{\theta-1}) \to \mathcal{B}^0(\R^{\theta-1}), \qquad 
		E_{{\varepsilon}}(z)  f(t):= \int_{-1}^1 e^{a_\varepsilon}_{\varepsilon(t-s)}(z)f(s) \,ds.
	\end{equation}

	We start by proving preliminary results for  $e_{\widetilde{\varepsilon}}^{a_\varepsilon}(z)$ and $d^{\zeta,\kappa}_{\widetilde{\varepsilon}}(z)$. Afterwards, we transfer these results to $E_\varepsilon(z)$ and $D^{\zeta,\kappa}_\varepsilon(z)$ in Proposition \ref{prop_local_prop}.
	For the estimates regarding   $e_{\widetilde{\varepsilon}}^{a_\varepsilon}(z)$ and $d^{\zeta,\kappa}_{\widetilde{\varepsilon}}(z)$ the following lemma turns out to be useful.
	\begin{lemma}\label{lem_est_G_z}
		Let $z \in \rho(H)$  and $G_z$ be defined by \eqref{eq_G_z_2D}--\eqref{eq_G_z_3D}. Then, there exist $C_5=C_5(z,m)>0$ and $C_6=C_6(z,m)>0$ such that for all $x \in \R^{\theta} \setminus \{0\}$ and $j \in \{1,\dots,\theta\}$
		\begin{equation}\label{eq_G_z_est_R_theta}
			\begin{aligned}
				|G_z(x)| &\leq  C_5|x|^{1-\theta}e^{-C_6 |x|}, \\ 	|\partial_j G_z(x)| &\leq C_5|x|^{-\theta}e^{-C_6 |x|}.
			\end{aligned}
		\end{equation}
		In particular, there holds for all $x',y' \in \R^{\theta-1}$, $j \in \{1,\dots,\theta\}$ and $\widetilde{\varepsilon} \in (-2\varepsilon_2,2\varepsilon_2)$
		\begin{equation}\label{eq_G_z_est_R_theta_prime}
			\begin{aligned}
				|G_z(x_{\zeta,\kappa}(x') - x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'))| &\leq  C_5C_4^{\theta-1}(|x'-y'| +|\widetilde{\varepsilon}|)^{1-\theta}e^{-\frac{C_6}{C_4} |x'-y'| }, \\	|\partial_j G_z(x_{\zeta,\kappa}(x') - x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'))| &\leq C_5C_4^\theta(|x'-y'| +|\widetilde{\varepsilon}|)^{-\theta}e^{-\frac{C_6}{C_4} |x'-y'| }.
			\end{aligned}
		\end{equation}
	\end{lemma}
	\begin{proof}
		Rough estimations and asymptotic expansions of the modified Bessel functions $K_1$ and $K_0$, see \cite[\S10.25~(ii) and \S10.30~(i)]{DLMF} and  \cite[eq. (B.8)]{BHS23}, lead to
		\begin{equation*}
				|G_z(x)| \leq  C(1+|x|^{1-\theta})e^{-\textup{Im}\sqrt{z^2-m^2} |x|} 
        \end{equation*}
        and
        \begin{equation*}
            |\partial_j G_z(x)| \leq C(1+|x|^{-\theta})e^{-\textup{Im}\sqrt{z^2-m^2} |x|}
		\end{equation*}
		for all $x \in \R^{\theta}\setminus \{0\}$ and $j \in \{1,\dots,\theta\}$, where $C = C(m,z)>0$ is a constant which only depends on $m$ and $z$. Thus, \eqref{eq_G_z_est_R_theta} is valid if one chooses $ C_6 \in (0,\textup{Im} \sqrt{z^2-m^2})$ and 
		\begin{equation*}
			C_5 = \sup_{x \in \R^{\theta}\setminus\{0\}, l \in \{\theta-1,\theta\}} C\frac{1+ |x|^{-l}}{|x|^{-l}} e^{-(\textup{Im }\sqrt{m^2-z^2} - C_6)|x|  } < \infty.
		\end{equation*}
		Furthermore,  combining these estimates with \eqref{eq_est_x_Sigma} implies \eqref{eq_G_z_est_R_theta_prime}.
	\end{proof}

	\begin{lemma}\label{lem_e_eps^r} 
		Let $z \in \rho(H)$, $\varepsilon \in (0,\varepsilon_2)$, $a_\varepsilon = \varepsilon^{1/6}$, and $\widetilde{\varepsilon} \in (-2\varepsilon_2,2\varepsilon_2)\setminus \{0\}$. Then, the operator $e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)$ acts as a bounded operator from $L^2(\R^{\theta-1};\C^N)$ to $H^1(\R^{\theta-1};\C^N)$ and 
		\begin{equation*}
			\norm{e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)}_{L^2(\R^{\theta-1};\C^N) \to H^1(\R^{\theta-1};\C^N)} \leq C\frac{1+\abs{\log(\varepsilon)}}{a_\varepsilon},
		\end{equation*}
		where $C>0$ does not depend on $\widetilde{\varepsilon}$ and  $\varepsilon$. Moreover, for $f \in L^2(\R^{\theta-1};\C^N)$ the mapping $(-2\varepsilon_2,2\varepsilon_2)\setminus\{0\}\ni \widetilde{\varepsilon} \mapsto e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)f \in H^1(\R^{\theta-1};\C^N)$ is continuous.
	\end{lemma}
	\begin{proof}
		We aim to prove the assertion by applying Lemma~\ref{lem_Schur_test}. To do so, it is necessary to find suitable estimates for the integral kernel of $e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)$ which is for $x',y' \in \R^{\theta-1}$ given by
		\begin{equation*}
			k(x',y') := G_z(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x')) \omega\bigl(\tfrac{x' - y'}{a_\varepsilon}\bigr)\sqrt{1+ \abs{\nabla \zeta(y')}^2}.
		\end{equation*} 
		We notice as $G_z \in C^\infty(\R^{\theta}\setminus\{0\};\C^{N \times N})$, $\zeta \in C_b^2(\R^{\theta-1};\R)$, and $\omega \in C_b^\infty(\R^{\theta-1};\R)$ and as $\omega$ cuts out the singularity of $G_z$, we have $k \in C_b^1(\R^{\theta-1} \times \R^{\theta-1};\C^{N \times N})$. Furthermore, using \eqref{eq_G_z_est_R_theta_prime}, $0 \leq \omega \leq 1$, $\supp \omega \subset \R^{\theta-1}\setminus B(0,\frac{1}{2})$ and $\zeta \in C^2_b(\R^{\theta-1};\R)$ immediately gives us for $x' \neq y' \in \R^{\theta-1}$
		\begin{equation*}
			\begin{aligned}
				|k(x',y')| &\leq C \chi_{\R^{\theta-1}\setminus B(0,1/2)}\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr) (|x'-y'| + |\widetilde{\varepsilon}|)^{1-\theta}e^{-c|x'-y'|}\\
				&\leq  C \chi_{\R^{\theta-1}\setminus B(0,1/2)}\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr) |x'-y'|^{1-\theta}e^{-c|x'-y'|},
			\end{aligned}
		\end{equation*}
		where $c = \tfrac{C_6}{C_4}$ with $C_4>0$ from \eqref{eq_est_x_Sigma} and $C_6$ from Lemma~\ref{lem_est_G_z}. Next, we estimate the derivatives with respect to $x'$ of $k$. The derivative with respect to $x_l'$, $l \in \{1,\dots\theta-1\}$, is given for for $x'\neq y' \in \R^{\theta-1}$ by
		\begin{equation*}
			\begin{aligned}
				\frac{d}{d x'_l}k(x',y')&= \sum_{j = 1}^{\theta} \Big((\partial_j G_z)(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'))\\
				&\hspace{50 pt}\cdot\frac{d}{d x'_l}(x_{\zeta,\kappa}(x')[j] + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x')[j])
				\omega\bigl(\tfrac{x' - y'}{a_\varepsilon}\bigr)\sqrt{1+ \abs{\nabla \zeta(y')}^2} \Big)\\
				&+ G_z(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'))\frac{1}{a_\varepsilon}(\partial_{l} \omega)\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr)\sqrt{1+ \abs{\nabla \zeta(y')}^2},
			\end{aligned}
		\end{equation*}
		where $v[j]$ denotes the $j$-th component of a vector $v$.
		Applying \eqref{eq_G_z_est_R_theta_prime}, the properties of $\omega$ and $\zeta$ again, we can estimate for $x' \neq y' \in \R^{\theta-1}$
		\begin{equation*}
			\begin{aligned}
				\Bigl|\frac{d}{d x'_l}k(x',y')\Bigr| &\leq  C \chi_{\R^{\theta-1}\setminus B(0,1/2)}\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr)\Bigl(  (|x'-y'| + |\widetilde{\varepsilon}|)^{-\theta}e^{-c|x'-y'|} \\
				&\hspace{110 pt} +  \frac{1}{a_\varepsilon}(|x'-y'| + |\widetilde{\varepsilon}|)^{1-\theta}e^{-c|x'-y'|} \Bigr)\\
				&\leq  C \chi_{\R^{\theta-1}\setminus B(0,1/2)}\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr)\Bigl(  |x'-y'|^{-\theta} +  \frac{1}{a_\varepsilon}|x'-y'|^{1-\theta} \Bigr)e^{-c|x'-y'|}.
			\end{aligned}
		\end{equation*}
		Thus, if we set $\widetilde{k}(z'):=  C \chi_{\R^{\theta-1}\setminus B(0,1/2)}\bigl(\tfrac{z'}{a_\varepsilon}\bigr)\Bigl(  |z'|^{-\theta} +  \tfrac{1}{a_\varepsilon}|z'|^{1-\theta} \Bigr)e^{-c|z'|}$ for $z' \in \R^{\theta-1}\setminus \{0\}$ we get
		\begin{equation}\label{eq_est_k_tilde}
			|k(x',y')|,\, \sum_{l=1}^{\theta-1} \Bigl|\frac{d}{d x'_l} k(x',y')\Bigr| \leq \widetilde{k}(x'-y'),  \quad x' \neq y' \in \R^{\theta-1}.
		\end{equation}
		Hence, by Lemma~\ref{lem_Schur_test} the map $e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)$ acts as a bounded operator from $L^2(\R^{\theta-1};\C^N)$ to $H^1(\R^{\theta-1};\C^N)$ and 
		\begin{equation*}
			\norm{e^{a_\varepsilon}_{\widetilde{\varepsilon}}(z)}_{L^2(\R^{\theta-1};\C^N) \to H^1(\R^{\theta-1};\C^N)} \leq C \|\widetilde{k}\|_{L^1(\R^{\theta-1})}. 
		\end{equation*}
		Now, the norm estimate in the assertion follows from
		\begin{equation*}
			\begin{aligned}
				\|\widetilde{k}\|_{L^1(\R^{\theta-1})} &= C \int_{\R^{\theta-1}}  \chi_{\R^{\theta-1}\setminus B(0,1/2)}\bigl(\tfrac{z'}{a_\varepsilon}\bigr)\Big(  |z'|^{-\theta} +  \frac{1}{a_\varepsilon}|z'|^{1-\theta} \Big)e^{-c|z'|} dz' \\
				&\leq C \int_{a_\varepsilon/2}^\infty \Big(r^{-\theta} + \frac{1}{a_\varepsilon}r^{1-\theta}\Big)e^{-cr} r^{\theta-2} \, dr\\
				&\leq C \bigg(\frac{1}{a_\varepsilon} + \frac{1+\abs{\log(a_\varepsilon)}}{a_\varepsilon}\bigg) \leq C \frac{1+\abs{\log(\varepsilon)}}{a_\varepsilon}.
			\end{aligned}
		\end{equation*}

		Finally, we prove the continuity. To do so, let $\widetilde{\varepsilon} \in (-2\varepsilon_2,2\varepsilon_2) \setminus \{0\}$ and $(\widetilde{\varepsilon}_n)_{n \in \N} $ be a sequence such that  $\widetilde{\varepsilon}_n \in (-2\varepsilon_2,2\varepsilon_2) \setminus \{0\}$ for all $n \in \N$ and  $\widetilde{\varepsilon}_n \overset{n \to \infty}\longrightarrow  \widetilde{\varepsilon}$. Using the dominated convergence theorem and \eqref{eq_est_k_tilde} shows that for $f \in L^2(\R^{\theta-1};\C^N)$ $e^{a_\varepsilon}_{\widetilde{\varepsilon}_n}f$ and $\partial_l e^{a_\varepsilon}_{\widetilde{\varepsilon}_n}f$, $l \in \{1,\dots,\theta-1\}$, converge pointwise to $e^{a_\varepsilon}_{\widetilde{\varepsilon}}f$ and $\partial_l e^{a_\varepsilon}_{\widetilde{\varepsilon}}f$, ${l \in \{1,\dots,\theta-1\}}$, respectively. Furthermore, \eqref{eq_est_k_tilde} shows that $|e^{a_\varepsilon}_{\widetilde{\varepsilon}_n}f|$ and $|\partial_l e^{a_\varepsilon}_{\widetilde{\varepsilon}_n}f|$, $l \in \{1,\dots,\theta-1\}$, are independently of $n \in \N$ pointwise  bounded by the function $|f| * \widetilde{k}$ which is by Young's inequality square integrable as $ f \in L^2(\R^{\theta-1};\C^N)$ and $\widetilde{k} \in L^1(\R^{\theta-1})$. Hence, applying the dominated converge theorem again shows that $e^{a_\varepsilon}_{\widetilde{\varepsilon}_n}f$ converges to $e^{a_\varepsilon}_{\widetilde{\varepsilon}}f$ in $H^1(\R^{\theta-1};\C^N)$.
	\end{proof}

	\begin{lemma}\label{lem_comuutator_d_eps}
		Let $z \in \rho(H)$, $\psi \in C^{1}_b(\R^{\theta-1})$, $x_0' \in \R^{\theta-1}$,  $\zeta_{x_0'} $ be as in \eqref{eq_zeta_x_0'}, and $\widetilde{\varepsilon}  \in (- 2\varepsilon_2,2\varepsilon_2)\setminus \{0\}$. Then,
		\begin{equation*}
			\big\|[d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z),\psi]\big\|_{L^2(\R^{\theta-1};\C^N) \to H^1(\R^{\theta-1};\C^N)} \leq C \norm{\psi}_{W^1_\infty(\R^{\theta-1})} (1+\abs{\log\abs{\widetilde{\varepsilon}}}),
		\end{equation*}
		where $C>0$ does not depend on $\widetilde{\varepsilon}\neq0$ and $x_0' \in \R^{\theta-1}$. Moreover, for $f \in L^2(\R^{\theta-1};\C^N)$ the mapping $(-2\varepsilon_2,2\varepsilon_2)\setminus\{0\}\ni \widetilde{\varepsilon} \mapsto [d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z),\psi]f \in H^1(\R^{\theta-1};\C^N)$ is continuous.
	\end{lemma}
	\begin{proof}
		We prove this result in the same vein as the previous lemma, i.e. we estimate the integral kernel of $[d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z),\psi]$ and its partial derivatives, and apply Lemma~\ref{lem_Schur_test}. The integral kernel of $[d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z),\psi]$ is given for $x',y' \in \R^{\theta-1}$ by 
		\begin{equation*}
			k(x',y'):= G_z(x_{\zeta_{x_0'},\kappa}(x') -x_{\zeta_{x_0'},\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta_{x_0'},\kappa}(x'))\sqrt{1+ \abs{\nabla \zeta_{x_0'}(y')}^2}(\psi(y')- \psi(x')).
		\end{equation*}
		Using 
		\begin{equation}\label{eq_lem_comm_d_eps_1}
			\begin{aligned}
				x_{\zeta_{x_0'},\kappa}(x') &= \kappa(x',\zeta(x_0')+\langle\nabla\zeta(x_0'),x'-x_0'\rangle), \\
				\nu_{\zeta_{x_0'},\kappa}(x') &= \frac{\kappa(-\nabla\zeta(x_0'),1)}{\sqrt{1+|\nabla \zeta(x_0')|^2}}  = \nu_{\zeta,\kappa}(x_0'),\\
				\nabla \zeta_{x_0'}(x') &= \nabla \zeta(x_0')
			\end{aligned}
		\end{equation}
		for $x' \in \R^{\theta-1}$ shows that $k$ can be simplified to
		\begin{equation*}
			k(x',y')= G_z\bigl(\kappa(x'-y', \langle \nabla \zeta(x_0'), x'-y' \rangle) + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'_0)\bigr)\sqrt{1+ \abs{\nabla \zeta(x_0')}^2}(\psi(y')- \psi(x')). 
		\end{equation*}
		Moreover, with \eqref{eq_lem_comm_d_eps_1}, $\kappa \in \textup{SO}(\theta)$, and the Pythagorean theorem one gets
		\begin{equation*}
			\begin{aligned}
				|\kappa(x'-y', \langle \nabla \zeta(x_0'), x'-y' \rangle) &+ \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'_0)|^2 \\
				&= |x'-y'|^2 + \langle \nabla \zeta(x_0'), x'-y' \rangle^2 + \widetilde{\varepsilon}^2 \\
				&\leq |x'-y'|^2(1+\|\nabla \zeta\|_{L^\infty(\R^{\theta-1};\R^{\theta-1})}^2) + \widetilde{\varepsilon}^2. 
			\end{aligned}
		\end{equation*}
		In particular, we can choose $C_4'>0$  which does not depend on $x_0' $ and $\widetilde{\varepsilon}$ such that 
		\begin{equation}\label{eq_lem_comm_d_eps_2}
			\begin{aligned}
				(C_4')^{-1}(|x'-y'| + |\widetilde{\varepsilon}|) &\leq |\kappa(x'-y', \langle \nabla \zeta(x_0'), x'-y' \rangle) + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'_0)| \\ 
				&\leq  	C_4'(|x'-y'| + |\widetilde{\varepsilon}|). 
			\end{aligned}
		\end{equation}
		Then, \eqref{eq_G_z_est_R_theta},  \eqref{eq_lem_comm_d_eps_2}, the Lipschitz continuity of $\psi \in C^1_b(\R^{\theta-1})$ and $\zeta \in C^2_b(\R^{\theta-1};\R)$ yield
		\begin{equation*}
			\begin{aligned}
				|k(x',y')| &\leq C (|x'-y'| + |\widetilde{\varepsilon}|)^{1-\theta}e^{-c'|x'-y'|} \norm{\psi}_{W^1_\infty(\R^{\theta-1})} |x'-y’|\\
				&\leq C\norm{\psi}_{W^1_\infty(\R^{\theta-1})}(|x'-y'| + |\widetilde{\varepsilon}|)^{2-\theta}e^{-c'|x'-y'|}, \quad  x',y' \in \R^{\theta-1},
			\end{aligned}
		\end{equation*} 
		where $c' = \tfrac{C_6}{C_4'}$ with $C_6$ from Lemma~\ref{lem_est_G_z}  and $C>0$ is independent of $x_0'$ and $\widetilde{\varepsilon}$.
		The derivative with respect to $x_l'$, $x' \in \R^{\theta-1}$, of $k$ is given by
		\begin{equation*}
			\begin{aligned}
				\frac{d}{d x'_l}k(x',y')&= \biggl(\sum_{j = 1}^{\theta} (\partial_j G_z)\bigl(\kappa(x'-y', \langle \nabla \zeta(x_0'), x'-y' \rangle) + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'_0)\bigr)\\
				&\hspace{100 pt} \cdot \bigl(\kappa(e_l',\partial_l \zeta(x_0'))\bigr)[j](\psi(y') - \psi(x'))\\
				&\hspace{10 pt}-G_z\bigl(\kappa(x'-y', \langle \nabla \zeta(x_0'), x'-y' \rangle) + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'_0)\bigr)(\partial_{l}\psi)(x') \biggr)\\
				&\hspace{180 pt}\cdot\sqrt{1+ \abs{\nabla \zeta(x_0')}^2}, 
			\end{aligned}
		\end{equation*}
		where $e_l'$ denotes the $l$-th Euclidean unit vector in $\R^{\theta-1}$ and $\bigl(\kappa(e_l',\partial_l \zeta(x_0'))\bigr)[j]$ denotes the $j$-th entry of the vector $\kappa(e_l',\partial_l \zeta(x_0'))$.
		Using  \eqref{eq_G_z_est_R_theta}, \eqref{eq_lem_comm_d_eps_2}, the Lipschitz continuity of $\psi \in C^1_b(\R^{\theta-1})$ and $\zeta \in C^2_b(\R^{\theta-1};\R)$ again gives us
		\begin{equation*}
			\begin{aligned}
				\Bigl|\frac{d}{d x'_l}k(x',y')\Bigr| &\leq C\norm{\psi}_{W^1_\infty(\R^{\theta-1})}\Big( (|x'-y'| + |\widetilde{\varepsilon}|)^{-\theta}e^{-c'|x'-y'|} |x'-y’|\\
				&\hspace{100 pt}+ (|x'-y'| + |\widetilde{\varepsilon}|)^{1-\theta}e^{-c'|x'-y'|}  \Big)\\
				&\leq C\norm{\psi}_{W^1_\infty(\R^{\theta-1})}(|x'-y'| + |\widetilde{\varepsilon}|)^{1-\theta}e^{-c'|x'-y'|} 
			\end{aligned}
		\end{equation*}
		for all $x',y' \in \R^{\theta-1}$, where $C>0$ can again be chosen independently of $x_0'$ and $\widetilde{\varepsilon}$.
		Setting for $z' \in \R^{\theta-1}$
		\begin{equation*}
			\widetilde{k}(z'):=  C \norm{\psi}_{W^1_\infty(\R^{\theta-1})}\big((|z'| + |\widetilde{\varepsilon}|)^{2-\theta}+ (|z'| + |\widetilde{\varepsilon}|)^{1-\theta}\big)e^{-c'|z'|}
		\end{equation*} 
		leads to
		\begin{equation*}
			|k(x',y')|, \, \sum_{l=1}^{\theta-1} \Bigl|\frac{d}{d x'_l}k(x',y')\Bigr| \leq \widetilde{k}(x'-y'),  \quad  x' , y' \in \R^{\theta-1}.
		\end{equation*}
		Now, Lemma~\ref{lem_Schur_test} shows

		\begin{equation*}
			\begin{aligned}
				\big\|[d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z)&,\psi]\big\|_{L^2(\R^{\theta-1};\C^N) \to H^1(\R^{\theta-1};\C^N)} \leq C \int_{\R^{\theta-1}} \widetilde{k}(z') \, dz'\\
				& \leq C\norm{\psi}_{W^1_\infty(\R^{\theta-1})} \int_0^\infty \big((r + \abs{\widetilde{\varepsilon}})^{2-\theta}+ (r+ \abs{\widetilde{\varepsilon}})^{1-\theta}\big)e^{-c'r} r^{\theta-2} \, dr\\
				&\leq C\norm{\psi}_{W^1_\infty(\R^{\theta-1})} \int_0^\infty \big(1+ (r+ |\widetilde{\varepsilon}|)^{-1}\big)e^{-c'r}  \, dr\\
				&\leq C\norm{\psi}_{W^1_\infty(\R^{\theta-1})}(1+ \abs{ \log\abs{\widetilde{\varepsilon}}}).
			\end{aligned}
		\end{equation*}
		The assertion regarding the continuity can be proven in a similar way as in Lemma~\ref{lem_e_eps^r}.
	\end{proof}

	\begin{lemma}\label{lem_diff_d}
		Let $z \in \rho(H)$, $x_0' \in \R^{\theta -1}$, $\zeta \in C^2_b(\R^{\theta-1};\R)$ be as described at the beginning of Section~\ref{sec_loc_part}, $\zeta_{x_0'} $ be as in \eqref{eq_zeta_x_0'}, $\varepsilon \in (0,\varepsilon_2)$, $a_\varepsilon = \varepsilon^{1/6}$, and $ \widetilde{\varepsilon}  \in (- 2\varepsilon_2,2\varepsilon_2)\setminus \{0\}$.  Then, there exists a $\delta_3 = \delta_3(\zeta) \in (0,\varepsilon_2)$ such that for all  $\varepsilon \in (0,\delta_3)$ the inequality
		\begin{equation*}
			\big\|\chi_{B(x_0',3a_\varepsilon)}\big(d^{\zeta,\kappa}_{\widetilde{\varepsilon}}(z)- d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z)  \big)\chi_{B(x_0',3a_\varepsilon)}\big\|_{L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N)} \leq C a_\varepsilon (1+\abs{\log\abs{\widetilde{\varepsilon}}})
		\end{equation*}
		holds,
		where $C>0$ does not depend on $\varepsilon$, $\widetilde{\varepsilon}$, and $x_0'$.
	\end{lemma}
	\begin{proof}
		We prove this statement by estimating the integral kernel of  the operator
		\begin{equation*}
			\chi_{B(x_0',a_\varepsilon)}\big( d^{\zeta,\kappa}_{\widetilde{\varepsilon}}(z) - d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z) \big)\chi_{B(x_0',a_\varepsilon)}
		\end{equation*} and applying Lemma \ref{lem_Schur_test}. The mentioned integral kernel is given for $x' , y' \in \R^{\theta-1}$ by
		\begin{equation*}
			\begin{aligned}
				k(x',y') :=& \chi_{B(x_0',3a_\varepsilon)}(x')\bigg(G_z(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x'))\sqrt{1+\abs{\nabla \zeta(y')}^2} \\
				&-G_z(\kappa(x'-y',\langle\nabla \zeta(x_0') , x'-y'\rangle) + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x_0'))\sqrt{1+\abs{\nabla \zeta(x_0')}^2}\bigg)\\
				&\hspace{200 pt} \cdot  \chi_{B(x_0',3a_\varepsilon)}(y').
			\end{aligned}
		\end{equation*}
		If $x' \not\in B(x_0',3a_\varepsilon)$ or $y' \not\in B(x_0',3a_\varepsilon)$, then $k(x',y') =0$. Thus, we assume from now on $x',y'\in B(x_0',3a_\varepsilon)$. 
		Using the mean value theorem for matrix-valued functions, cf. \cite[Lemma A.1]{BHS23}, \eqref{eq_G_z_est_R_theta}, and $\zeta \in C^2_b(\R^{\theta-1};\R)$ we find
		\begin{equation}\label{eq_d_diff_ker_1}
			\begin{aligned}
				|k(x',y')| &\leq \sqrt{\theta}\sup_{\upsilon \in [0,1],j\in \{1,\dots \theta\}} |\partial_j G_z(w_\upsilon)\sqrt{1+|\nabla \zeta(y')|^2} | |w_1 - w_0|\\
				&\hspace{50 pt} + \Bigl| G_z(w_0) \bigl(\sqrt{1+|\nabla \zeta(y')|^2} -\sqrt{1+|\nabla \zeta(x_0')|^2}\bigr)\Bigr| \\
				&\leq C 	\Big(\sup_{\upsilon \in [0,1]}|w_\upsilon|^{-\theta} |w_1 - w_0| + |w_0|^{1-\theta} |x_0'- y'|\Big)
			\end{aligned}
		\end{equation}
		with
		\begin{equation*}
			w_\upsilon =\upsilon\big(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') 
			+ \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x')\big) 
			+(1-\upsilon) \big( \kappa(x'-y',\langle\nabla \zeta(x_0'),x'-y'\rangle) + \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x_0')\big)
		\end{equation*}
		for $\upsilon \in [0,1]$. Note that the mean value theorem is applicable since $w_\upsilon  \neq 0$ for $\upsilon \in [0,1]$, see \eqref{eq_d_diff_ker_3} below. 
		 Next, we want to estimate
		\begin{equation*}
			\begin{aligned}
				|w_1 - &w_0| \\
				&= |x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') 
				+ \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x') -   \kappa(x'-y',\langle\nabla \zeta(x_0'),x'-y'\rangle) - \widetilde{\varepsilon}\nu_{\zeta,\kappa}(x_0') |\\
				&=|\kappa(x'-y',\zeta(x')-\zeta(y'))\\
				&\hspace{70 pt}-   \kappa(x'-y',\langle\nabla \zeta(x_0'),x'-y'\rangle) + \widetilde{\varepsilon}(\nu_{\zeta,\kappa}(x') - \nu_{\zeta,\kappa}(x_0'))  |\\
				&=|\kappa(0,\zeta(x')-\zeta(y') - \langle \nabla \zeta(x_0'),x'-y'\rangle) + \widetilde{\varepsilon}(\nu_{\zeta,\kappa}(x') - \nu_{\zeta,\kappa}(x_0') ) |.
			\end{aligned}
		\end{equation*}
		As $\zeta \in C^2_b(\R^{\theta-1};\R)$ and $\kappa \in \textup{SO}(\theta)$, there exists a $K=K(\zeta)>0$ such that
		\begin{equation*}
			\abs{\nu_{\zeta,\kappa}(x') - \nu_{\zeta,\kappa}(x_0')}  = \bigg| \frac{\kappa(-\nabla \zeta(x'),1)}{\sqrt{1+ |\nabla\zeta(x')|^2}}  - \frac{\kappa(-\nabla \zeta(x_0'),1)}{\sqrt{1+ |\nabla\zeta(x_0')|^2}} \bigg|\leq K \abs{x' - x_0'} \leq 3K a_\varepsilon
		\end{equation*} 
		and 
		\begin{equation*}
			\begin{aligned}
				|\kappa(0,\zeta(x') -\zeta(y') - \langle&\nabla \zeta(x_0'),x'-y' \rangle ) | \\
				&= | \zeta(x') -\zeta(y') - \langle \nabla \zeta(x_0'),x'-y'\rangle| \\
				&= \bigg|  \int_{0}^1 \langle \nabla\zeta(y' + t(x'-y')) - \nabla\zeta(x_0'), x'-y' \rangle \,dt\bigg|\\
				&\leq K\bigg|  \int_{0}^1 |t (x'- x_0') + (1-t)(y'-x_0')| |x'-y'|  \,dt\bigg| \\
				& \leq 3K a_\varepsilon |x'-y'|,
			\end{aligned}
		\end{equation*}
		where we used $x',y' \in B(x_0',3a_\varepsilon)$. Hence, if $\delta_3=\delta_3(\zeta) \in (0,\varepsilon_2)$ is chosen sufficiently small, then  for all $a_\varepsilon \in (0,\delta_3^{1/6})$ the inequality
		\begin{equation}\label{eq_d_diff_ker_2}
			|w_1 - w_0| \leq K3 a_\varepsilon (|x'-y'|+|\widetilde{\varepsilon}|) \leq \frac{1}{2 C_4}(|x'-y'|+|\widetilde{\varepsilon}|)
		\end{equation}
		holds with $C_4>0$ from \eqref{eq_est_x_Sigma}.
		Therefore, we can  use \eqref{eq_est_x_Sigma} to estimate $|w_\upsilon|$, $\upsilon \in [0,1]$,  from below by
		\begin{equation}\label{eq_d_diff_ker_3}
			\begin{aligned}
				|w_\upsilon| &= |\upsilon w_1 + (1-\upsilon)w_0| = |w_1+ (1-\upsilon) (w_0-w_1)| \geq |w_1| - |w_1-w_0| \\
				&\geq  \frac{1}{C_4}(|x'-y'| + |\widetilde{\varepsilon}|) - \frac{1}{2 C_4}(|x'-y'|+ |\widetilde{\varepsilon}|) = \frac{1}{2 C_4}(|x'-y'|+|\widetilde{\varepsilon}|).
			\end{aligned}
		\end{equation}
		Thus, plugging \eqref{eq_d_diff_ker_2} and \eqref{eq_d_diff_ker_3} into \eqref{eq_d_diff_ker_1} yields for $a_\varepsilon = \varepsilon^{1/6}$ with  $\varepsilon \in (0,\delta_3)$ 
		\begin{equation*}
			\abs{k(x',y')} \leq \begin{cases} 0 & \textup{if } x' \not \in B(x_0',3 a_\varepsilon) \textup{ or } y' \not \in B(x_0', 3a_\varepsilon),\\
				C a_\varepsilon (\abs{x'-y'} + \abs{\widetilde{\varepsilon}})^{1-\theta} &\textup{else}.
			\end{cases}
		\end{equation*}
		Applying Lemma \ref{lem_Schur_test} yields
		\begin{equation*}
			\begin{aligned}
				\big\|\chi_{B(x_0',3a_\varepsilon)}\big(d^{\zeta,\kappa}_{\widetilde{\varepsilon}}(z)-	 d^{\zeta_{x_0'},\kappa}_{\widetilde{\varepsilon}}(z)  \big)&\chi_{B(x_0',3a_\varepsilon)}\big\|_{L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N)} \\
				&\leq C a_\varepsilon \int_{B(0,6a_\varepsilon)}  (\abs{z'} + \abs{\widetilde{\varepsilon}})^{1-\theta} \, dz'\\
				& \leq C a_\varepsilon \int_0^{6a_\varepsilon} (r + \abs{\widetilde{\varepsilon}})^{1-\theta} r^{\theta-2} \, dr\\
				&\leq C a_\varepsilon \int_0^{6a_\varepsilon}  (r + \abs{\widetilde{\varepsilon}})^{-1} \,dr\\
				&\leq C a_\varepsilon(1+ \abs{\log\abs{\widetilde{\varepsilon}}}).
			\end{aligned}
		\end{equation*}
	\end{proof}



	\begin{cor}\label{cor_diff_d}
		Let $z \in \rho(H)$, $x_0' \in \R^{\theta -1}$, $\zeta \in C^2_b(\R^{\theta-1};\R)$ be as described at the beginning of Section~\ref{sec_loc_part}, $\zeta_{x_0'} $ be as in \eqref{eq_zeta_x_0'}, $\varepsilon \in (0,\delta_3)$ with $\delta_3$  chosen as in Lemma~\ref{lem_diff_d}, $a_\varepsilon = \varepsilon^{1/6} $, $ \widetilde{\varepsilon}  \in (- 2\varepsilon_2,2\varepsilon_2)\setminus \{0\}$, and $Q_{\eta,\tau}^{\zeta,\kappa}$ be as in \eqref{eq_Q_matrix}. Then,
		\begin{equation*}
			\begin{aligned}
				\big\|&\chi_{B(x_0',3a_\varepsilon)}\big( 
				d^{\zeta, \kappa}_{\widetilde{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa} \\
				&\hspace{7 pt}-d_{\widetilde{\varepsilon}}^{\zeta_{x_0'},\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa} (x_0')\big)\chi_{B(x_0',3a_\varepsilon)}\big\|_{L^2(\R^{\theta-1};\C^N) \to 	L^2(\R^{\theta-1};\C^N)} \leq C a_\varepsilon(1+\abs{\log\abs{\widetilde{\varepsilon}}}),
			\end{aligned}
		\end{equation*}
		where $C$ does not depend on $\varepsilon$, $\widetilde{\varepsilon}$, and $x_0'$. 
	\end{cor}
	\begin{proof}
		Lemma~\ref{lem_diff_d} and  $Q_{\eta,\tau}^{\zeta,\kappa}  \in C^1_b(\R^{\theta-1};\C^{N\times N})$ yield
		\begin{equation*}
			\begin{aligned}
				\big\|&\chi_{B(x_0',3a_\varepsilon)}\big( 
				d^{\zeta, \kappa}_{\widetilde{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa} \\
				&\hspace{80 pt}-d_{\widetilde{\varepsilon}}^{\zeta_{x_0'},\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa} (x_0')\big)\chi_{B(x_0',3a_\varepsilon)}\big\|_{L^2(\R^{\theta-1};\C^N) \to 	L^2(\R^{\theta-1};\C^N)}\\
				&\leq 	\big\|\chi_{B(x_0',3a_\varepsilon)} 
				d^{\zeta, \kappa}_{\widetilde{\varepsilon}}(z)\big(Q_{\eta,\tau}^{\zeta,\kappa} - Q_{\eta,\tau}^{\zeta,\kappa}(x_0') \big)\chi_{B(x_0',3a_\varepsilon)} \big\|_{L^2(\R^{\theta-1};\C^N) \to 	L^2(\R^{\theta-1};\C^N)} \\
				&\hspace{10pt}+\big\|\chi_{B(x_0',3a_\varepsilon)}\big(	d^{\zeta, \kappa}_{\widetilde{\varepsilon}}(z)\\
				&\hspace{80 pt}-  d_{\widetilde{\varepsilon}}^{\zeta_{x_0'},\kappa}(z)\big)\chi_{B(x_0',3a_\varepsilon)} Q_{\eta,\tau}^{\zeta,\kappa} (x_0')\big\|_{L^2(\R^{\theta-1};\C^N) \to 	L^2(\R^{\theta-1};\C^N)}\\
				& \leq C \bigl(\|d^{\zeta, \kappa}_{\widetilde{\varepsilon}}(z) \|_{L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N)} a_\varepsilon + a_\varepsilon(1+\abs{\log\abs{\widetilde{\varepsilon}}})\bigr),
			\end{aligned}
		\end{equation*}
		where $C$ does not depend on $\varepsilon$, $\widetilde{\varepsilon}$, and $x_0'$. Moreover,   \eqref{eq_d_eps}, \eqref{eq_G_z_est_R_theta_prime},  and $\zeta \in C^2_b(\R^{\theta-1};\R)$ imply for the integral kernel $k$ of $d_{\widetilde{\varepsilon}}^{\zeta,\kappa}(z)$ 
		\begin{equation*}
			|k(x',y')| \leq C (|x'-y'|+|\widetilde{\varepsilon}|)^{1-\theta}e^{-c|x'-y'|}, \quad x',y' \in \R^{\theta-1},
		\end{equation*}
		where $c = \tfrac{C_6}{C_4}>0$ with $C_4$ from \eqref{eq_est_x_Sigma} and $C_6$ from \eqref{eq_G_z_est_R_theta_prime}, 
		and therefore Lemma~\ref{lem_Schur_test} implies
		\begin{equation*}
			\begin{aligned}
				\|d^{\zeta, \kappa}_{\widetilde{\varepsilon}}(z) \|_{L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N)} &\leq C \int_{\R^{\theta-1}} (|z'| + |\widetilde{\varepsilon}|)^{1-\theta} e^{-c|z'|} \, dz'\\
				&\leq C \int_{0}^\infty (r + |\widetilde{\varepsilon}|)^{1-\theta} e^{-cr} r^{\theta-2} \,dr\\
				&\leq C (1+\abs{\log\abs{\widetilde{\varepsilon}}}),
			\end{aligned}
		\end{equation*}
		which completes the proof.
	\end{proof}

	Now, we transfer in Proposition~\ref{prop_local_prop} the results regarding  $e_{\widetilde{\varepsilon}}^{a_\varepsilon}(z)$ and $d^{\zeta,\kappa}_{\widetilde{\varepsilon}}(z)$  to $E_\varepsilon(z)$ and $D^{\zeta,\kappa}_\varepsilon(z)$. The first, second, and third estimate in Proposition~\ref{prop_local_prop} are consequences of Lemma~\ref{lem_e_eps^r}, Lemma~\ref{lem_comuutator_d_eps}, and Corollary~\ref{cor_diff_d}, respectively.
	Recall that $\zeta \in C^2_b(\R^{\theta-1};\R)$ is described in the beginning of Section~\ref{sec_loc_part}, $\zeta_{x_0'} $ is defined by~\eqref{eq_zeta_x_0'}, and $\delta_3$ is chosen as in  Lemma~\ref{lem_diff_d}.

	\begin{proposition}\label{prop_local_prop}
		Let $z \in \rho(H)$, $x_0' \in \R^{\theta -1}$,  $\varepsilon \in (0,\delta_3)$, $a_\varepsilon = \varepsilon^{1/6} $, $Q_{\eta,\tau}^{\zeta,\kappa}$ be as in \eqref{eq_Q_matrix}, and $\psi \in C^1_b(\R^{\theta-1})$. Then, the operators  $E_{\varepsilon}(z)$  and $[D_{\varepsilon}^{ \zeta, \kappa}(z),\psi]$ act as bounded operators from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$ and 
		\begin{equation*}
			\begin{aligned}
				&\|E_{\varepsilon}(z)\|_{0\to1} \leq C\frac{1+\abs{\log(\varepsilon)}}{a_\varepsilon},\\
				&\|[D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z),\psi]\|_{0\to1}\leq C \norm{\psi}_{W^1_\infty(\R^{\theta-1})} (1+\abs{\log(\varepsilon)}),\\
				&\big\|\chi_{B(x_0',3a_\varepsilon)}\big(D_{\varepsilon}^{ \zeta, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}- D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}(x_0')\big)\chi_{B(x_0',3a_\varepsilon)}\big\|_{0 \to 0} \leq C a_\varepsilon (1+\abs{\log(\varepsilon)}),
			\end{aligned}
		\end{equation*}
		where $C>0$ does not depend on $x_0'$ and $\varepsilon$.
	\end{proposition}
	\begin{proof}
		We start by showing that $[D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z),\psi]$ is well-defined as an operator from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$. Let $f \in \mathcal{B}^0(\R^{\theta-1})$ and set $g = [D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z),\psi]f$. It follows from \eqref{eq_D_eps_int_rep} that  $g$ has for $ t \in (-1,1)$ the representation 
		\begin{equation}\label{eq_g}
			g(t)= \int_{-1}^1 [d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]f(s)\,ds.
		\end{equation}
		Since $[d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]$ has the continuity property from Lemma~\ref{lem_comuutator_d_eps} and $f \in \mathcal{B}^0(\R^{\theta-1})$, \cite[Proposition~1.1.28]{HNVW16}  implies that the function
		\begin{equation*}
			(-1,1)\times(-1,1) \ni (t,s) \mapsto [d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]f(s) \in H^1(\R^{\theta-1};\C^N)
		\end{equation*}
		is measurable. According to Lemma~\ref{lem_comuutator_d_eps}  we have
		\begin{equation}\label{eq_small2big_1}
			\begin{aligned}
				&\int_{-1}^1\bigg(\int_{-1}^1\|[d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]f(s)\|_{H^1(\R^{\theta-1};\C^N)} \,ds\bigg)^2 \, dt \\
				&\hspace{5 pt}\leq C \|\psi \|_{W^1_\infty(\R^{\theta-1})}^2 \int_{-1}^1 \bigg(\int_{-1}^1(1+\abs{\log\abs{\varepsilon(t-s)}}) \| f(s) \|_{L^2(\R^{\theta-1};\C^N)}\,ds \bigg)^2 \,dt.
			\end{aligned}
		\end{equation}
		This expression can be estimated with the Cauchy-Schwarz inequality and Fubini's theorem by
		\begin{equation}\label{eq_small2big_2}
			\begin{aligned}
				&C\norm{\psi}_{W^1_\infty(\R^{\theta-1})}^2 \int_{-1}^{1} \biggl(\int_{-1}^1 (1+\abs{\log\abs{\varepsilon(t-s)}}) \,ds  \\
				&\hspace{100 pt}\cdot\int_{-1}^1(1+\abs{\log\abs{\varepsilon(t-s)}} ) \norm{f(s)}_{L^2(\R^{\theta-1};\C^N)}^2 \,ds \biggr)  \,dt\\
				& \leq C \norm{\psi}_{W^1_\infty(\R^{\theta-1})}^2 \bigg(\int_{-2}^2 (1+\abs{\log\abs{\varepsilon s}}) \,ds\bigg)^2 \int_{-1}^1 \norm{f(s)}_{L^2(\R^{\theta-1};\C^N)}^2 \,ds\\
				& \leq C \big(\norm{\psi}_{W^1_\infty(\R^{\theta-1})}(1+\abs{\log(\varepsilon)})\norm{f}_0\big)^2.
			\end{aligned}
		\end{equation}
		In particular, applying the Cauchy-Schwarz inequality again gives us
		\begin{equation*}
			\begin{aligned}
				\int_{-1}^1 \int_{-1}^1& \|[d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]f(s) \|_{H^1(\R^{\theta-1};\C^N)} \,ds \,dt \\
				&\leq \sqrt{2} 	\sqrt{\int_{-1}^1 \bigg(\int_{-1}^1 \| [d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]f(s) \|_{H^1(\R^{\theta-1};\C^N)} \,ds\bigg)^2 \,dt} < \infty.
			\end{aligned}
		\end{equation*}
		Thus, Fubini's theorem for Bochner integrals, see \cite[Proposition~1.2.7]{HNVW16}, shows that $g(t)$ in~\eqref{eq_g} is  well-defined  and measurable as a function from $(-1,1)$ to $H^1(\R^{\theta-1};\C^N)$. Moreover, \eqref{eq_g}, \eqref{eq_small2big_1}, and \eqref{eq_small2big_2} also give us the norm estimate as
		\begin{equation*}
			\begin{aligned}
				\Vert[D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z),\psi]f\Vert_{1}^2 
				&=\norm{g}_{1}^2\\
				 &=\int_{-1}^1 \|g(t)\|^2_{H^1(\R^{\theta-1};\C^N)} \, dt\\
				&\leq \int_{-1}^1\bigg(\int_{-1}^1\|[d_{\varepsilon(t-s)}^{\zeta_{x_0'},\kappa}(z),\psi]f(s)\|_{H^1(\R^{\theta-1};\C^N)} \,ds\bigg)^2 \, dt\\
				& \leq C \big(\norm{\psi}_{W^1_\infty(\R^{\theta-1})}(1+\abs{\log(\varepsilon)}) \norm{f}_0\big)^2.
			\end{aligned}
		\end{equation*}
			The proof of the assertion regarding $E_\varepsilon(z)$ follows along the same lines if one applies Lemma~\ref{lem_e_eps^r} instead of Lemma~\ref{lem_comuutator_d_eps}. Moreover, since    
			\begin{equation*}
				\chi_{B(x_0',3a_\varepsilon)}\big(D_{\varepsilon}^{ \zeta, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}- D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}(x_0')\big)\chi_{B(x_0',3a_\varepsilon)}
			\end{equation*}
		 is only considered as an operator in $\mathcal{B}^0(\R^{\theta-1})$, 
		 one only has to prove the norm estimate in this topology. The norm can be estimated in the same way as we estimated the norm of $E_\varepsilon(z)$ by applying Corollary~\ref{cor_diff_d} instead of Lemma~\ref{lem_comuutator_d_eps}.
	\end{proof}

	As the last part of our local analysis we state  a result concerning the inverse of $I+ D_{\varepsilon}^{\zeta_{x_0'},\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}(x_0')q$ for $x_0' \in \R^{\theta-1}$. This is an important result as these operators are going to play an essential role when constructing  the inverse of $I+ D_{\varepsilon}^{\zeta,\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}q$. Recall that $\zeta \in C^2_b(\R^{\theta-1};\R)$ and $\Sigma$ are as described in the beginning of Section~\ref{sec_loc_part}, $\zeta_{x_0'} $ is given by \eqref{eq_zeta_x_0'}, and $q$ is as in 	\eqref{eq_q2}.

	\begin{proposition}\label{prop_uniform_bdd_D_inv}
		Let $z \in \C \setminus \R$, $\eta,\tau \in C^1_b(\Sigma;\R)$, $d = \eta^2- \tau^2$ such that
		\begin{equation*}
			\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4},
		\end{equation*} 
		and $Q_{\eta,\tau}^{\zeta,\kappa}$ be as in \eqref{eq_Q_matrix}. Then, there exists a $\delta_4 > 0$  such that the operators $(I+D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}(x_0')q)^{-1}$ are uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$ with respect to $\varepsilon \in (0,\delta_4)$ and $x_0'\in\R^{\theta-1}$.
	\end{proposition}
	\begin{proof}
		Note that
		\begin{equation*}
				Q_{\eta,\tau}^{\zeta,\kappa} (x_0') 
				= \eta(x_{\zeta,\kappa}(x_0')) I_N + \tau(x_{\zeta,\kappa}(x_0')) \beta  =Q_{\eta(x_{\zeta,\kappa}(x_0')),\tau(x_{\zeta,\kappa}(x_0'))}
		\end{equation*}  
		for $x_0' \in \R^{\theta-1}$; cf. \eqref{eq_Q_matrix} and \eqref{eq_Q_const}. Moreover, for every $x_0' \in \R^{\theta-1}$ the set $\Sigma_{\zeta_{x_0'},\kappa}$ is an affine hyperplane in $\R^{\theta-1}$ and therefore  there exists a $y_0(x_0') \in \R$ and a $\widetilde{\kappa}(x_0')\in \textup{SO}(\theta)$ such that
		\begin{equation*}
			\begin{aligned}
				\Sigma_{\zeta_{x_0'},\kappa} &= \{\kappa(x',\zeta_{x_0'}(x')): x' \in \R^{\theta-1}\}  \\
				&= \widetilde{\kappa}(x_0') \big(\R^{\theta -1} \times \{y_0(x_0')\}\big) = \Sigma_{y_0(x_0'),\widetilde{\kappa}(x_0')}.
			\end{aligned}
		\end{equation*}
		Now, let $\overline{B}_{\varepsilon}^{\Sigma_{\zeta_{x_0'},\kappa}}(z) = \overline{B}_{\varepsilon}^{\Sigma_{y_0(x_0'),\widetilde{\kappa}(x_0')}}(z)$ be defined as $\overline{B}_\varepsilon(z)$ in \eqref{def_B_eps_bar} with $\Sigma$ substituted by $\Sigma_{\zeta_{x_0'},\kappa} = \Sigma_{y_0(x_0'),\widetilde{\kappa}(x_0')}$. According to Proposition~\ref{prop_uniform_bdd_D} the operator $I+D_{\varepsilon}^{y_0(x_0'), \widetilde{\kappa}(x_0')}(z)Q_{\eta(x_{\zeta,\kappa}(x_0')),\tau(x_{\zeta,\kappa}(x_0'))}q$ is continuously invertible in $\mathcal{B}^0(\R^{\theta-1})$. Moreover, we get from \eqref{def_D_operators}
		\begin{equation*}
			\begin{aligned}
			I&+D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa} (x_0')q = \iota_{ \zeta_{x_0'}, \kappa} \bigl(I+\overline{B}_{\varepsilon}^{\Sigma_{\zeta_{x_0'},\kappa}}(z)Q_{\eta(x_{\zeta,\kappa}(x_0')),\tau(x_{\zeta,\kappa}(x_0'))}q\bigr)\iota_{ \zeta_{x_0'}, \kappa }^{-1}\\
			&= \iota_{ \zeta_{x_0'}, \kappa} \bigl(I+\overline{B}_{\varepsilon}^{\Sigma_{y_0(x_0'),\widetilde{\kappa}(x_0')}}(z)Q_{\eta(x_{\zeta,\kappa}(x_0')),\tau(x_{\zeta,\kappa}(x_0'))}q\bigr)\iota_{ \zeta_{x_0'}, \kappa }^{-1}\\
			&=\iota_{ \zeta_{x_0'}, \kappa} \iota_{ y_0(x_0'),\widetilde{\kappa}(x_0')}^{-1} \bigl(I+D_{\varepsilon}^{y_0(x_0'), \widetilde{\kappa}(x_0')}(z)Q_{\eta(x_{\zeta,\kappa}(x_0')),\tau(x_{\zeta,\kappa}(x_0'))}q\bigr)\iota_{y_0(x_0'),\widetilde{\kappa}(x_0') } \iota_{ \zeta_{x_0'}, \kappa}^{-1}
			\end{aligned}
		\end{equation*}
		and from \eqref{eq_norm_iota} 
		\begin{equation*}
			\begin{aligned}
			&\norm{\iota_{\zeta_{x_0'},\kappa}}_{L^2(\Sigma_{\zeta_{x_0'},\kappa};\C^N) \to L^2(\R^{\theta-1};\C^N)} =  \norm{\iota_{\zeta_{x_0'},\kappa}^{-1}}_{L^2(\R^{\theta-1};\C^N) \to L^2(\Sigma_{\zeta_{x_0'},\kappa};\C^N)}^{-1}\\
			 &\hspace{143 pt}= (1+\abs{\nabla\zeta(x_0')}^2)^{-1/4},\\
		&\norm{\iota_{y_0(x_0'),\widetilde{\kappa}(x_0') }}_{L^2( \Sigma_{y_0(x_0'),\widetilde{\kappa}(x_0')};\C^N) \to L^2(\R^{\theta-1};\C^N)}	 	\\
		&\hspace{100 pt}=\norm{\iota_{y_0(x_0'),\widetilde{\kappa}(x_0') }^{-1}}_{L^2( \Sigma_{y_0(x_0'),\widetilde{\kappa}(x_0')};\C^N) \to L^2(\R^{\theta-1};\C^N)}^{-1} \\
		&\hspace{100 pt}= 1.
			\end{aligned}
		\end{equation*}
		These considerations show that $I+D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa} (x_0')q$ is also continuously invertible in $\mathcal{B}^0(\R^{\theta-1})$ and  
		\begin{equation*} 
			\begin{aligned}
				&\big\|(I+D_{\varepsilon}^{ \zeta_{x_0'}, \kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa} (x_0')q)^{-1}\big\|_{0 \to 0} \\
				&\hspace{70 pt}\leq\big\|(I+D_{\varepsilon}^{y_0(x_0'), \widetilde{\kappa}(x_0')}(z)Q_{\eta(x_{\zeta,\kappa}(x_0')),\tau(x_{\zeta,\kappa}(x_0'))}q)^{-1}\big\|_{0 \to 0}.
			\end{aligned}
		\end{equation*}
		Now, the result follows from applying Corollary~\ref{cor_uniform_bdd_D} (for $S = \overline{\ran(\eta,\tau)}$) if one chooses $\delta_4 = \delta_2(\overline{\ran(\eta,\tau)}) >0$, where $\delta_2$ was introduced in Corollary~\ref{cor_uniform_bdd_D}.
	\end{proof}




	Inspired by the local principle in \cite[Proposition~5]{R22a}, see also \cite{R20,R21}, we are going to construct partitions of unity which allow us to globalize the established local  results.  We start by choosing a partition of unity $(\phi_{n'})_{n' \in \Z^{\theta-1}}$ for $\R^{\theta-1}$ with uniformly bounded derivatives which satisfies  $\supp \phi_{n'} \subset B(n',1)$ for $n'\in\Z^{\theta-1}$.  Moreover, let $(\vartheta_{n'})_{n' \in \Z^{\theta-1}}$ be a sequence of functions with uniformly bounded derivatives which fulfils  $0\leq\vartheta_{n'} \leq 1$, $\vartheta_{n'} =1$ on $B(n',2)$ and $\supp \vartheta_{n'} \subset B(n',3)$ for $n' \in \Z^{\theta-1}$. According to Proposition~\ref{prop_part_unity} such sequences exist.
	By defining for $a \in (0,\varepsilon_2^{1/6})$ and $n' \in \Z^{\theta-1}$ the functions $\phi_{n'}^a(\cdot) = \phi_{n'}(\cdot/a)$ and $\vartheta_{n'}^a(\cdot) = \vartheta_{n'}(\cdot/a)$ we obtain similar sequences with scaled supports; in particular $(\phi_{n'}^a)_{n'\in \Z^{\theta-1}}$ is a partition of unity for $\R^{\theta-1}$. Furthermore, there exists a $C >0$ which does not depend on $a$ such that
	\begin{equation}\label{eq_part_of_unity_uniform_est}
		\sup_{n' \in \Z^{\theta-1}} \max\{\|\phi_{n'}^a\|_{W^1_\infty(\R^{\theta-1})},\|\vartheta_{n'}^a\|_{W^1_\infty(\R^{\theta-1})}\} < \frac{C}{a}.
	\end{equation}

	Before we can construct the inverse of $I + D_\varepsilon(z)Q_{\eta,\tau}^{\zeta,\kappa} q$ we have to deal with series of operators. Let $(A_{n'})_{n' \in \Z^{\theta-1}}$ be a family of bounded operators mapping from a Hilbert space $\mathcal{H}$ to a Hilbert space $\mathcal{G}$. 
	If the sequence of partial sums $S_n = \sum_{n ' \in \Z^{\theta-1}, \abs{n'} \leq n} A_{n'}$ converges in the strong sense to an operator, then we define
	\begin{equation*}
		\sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} A_{n'} := \underset{n \to \infty}{\textup{s-lim}} \, S_n.
	\end{equation*}
	According to the Banach-Steinhaus theorem, $\sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} A_{n'} $ is again a bounded operator mapping from $\mathcal{H}$ to $\mathcal{G}$.
	Moreover, the definition of the series implies that if $\mathcal{H}'$ and $\mathcal{G}'$ are Hilbert spaces, and $U:\mathcal{H}' \to \mathcal{H}$ and $V: \mathcal{G} \to \mathcal{G}'$ are bounded operators, then 
	\begin{equation*}
		\sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} VA_{n'}U : \mathcal{H}' \to \mathcal{G}'
	\end{equation*}
	is a well-defined bounded operator and 
	\begin{equation*}
		V \Big(\sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} A_{n'}\Big)U  =	\sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} V A_{n'} U
	\end{equation*} 
	holds.
	If $(\mathcal{A}_{n'})_{n' \in \Z^{\theta-1}}$ is a uniformly bounded sequence of operators in $\mathcal{B}^0(\R^{\theta-1})$, then according to Proposition~\ref{prop_part_series}  the series $\sum_{n' \in \Z^{\theta-1}}^\textup{st.} \vartheta^a_{n'} \mathcal{A}_{n'}\vartheta^a_{n'}$
	converges in the strong sense in $\mathcal{B}^0(\R^{\theta-1})$ and we have
	\begin{equation}\label{eq_series_est_020}
		\Big\| \sum_{n' \in \Z^{\theta-1}}^\textup{st.} \vartheta^a_{n'} \mathcal{A}_{n'}\vartheta^a_{n'} \Big\|_{0\to0} \leq 11^{\theta-1}\sup_{n' \in \Z^{\theta-1}} \| \mathcal{A}_{n'}\|_{0 \to 0}.
	\end{equation}  
	Moreover, if $(\mathcal{A}_{n'})_{n' \in \mathbb{Z}^{\theta-1}}$ is also uniformly bounded as a sequence of operators from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$, then $\sum_{n' \in \Z^{\theta-1}}^\textup{st.} \vartheta^a_{n'} \mathcal{A}_{n'}\vartheta^a_{n'}$ acts also as  a bounded operator from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$ and
	\begin{equation}\label{eq_series_est_021}
		\Big\| \sum_{n' \in \Z^{\theta-1}}^\textup{st.} \vartheta^a_{n'} \mathcal{A}_{n'}\vartheta^a_{n'} \Big\|_{0\to1} \leq \frac{C}{a} \sup_{n' \in \Z^{\theta-1}}\norm{\mathcal{A}_{n'}}_{0 \to 1}
	\end{equation}
	holds, with $C>0$ independent of $a$, see also Proposition~\ref{prop_part_series}. Before we use these essential observations in the proof of Proposition~\ref{prop_right_inverse}, we state a helpful preliminary lemma.

	\begin{lemma}\label{lem_right_inverse}
		Let $z \in \rho(H)$, $\varepsilon \in (0,\varepsilon_2)$, $a_\varepsilon = \varepsilon^{1/6} $, $D_{\varepsilon}^{\zeta,\kappa}(z)$ be as in \eqref{def_D_operators}, and $E_{\varepsilon}(z)$ be as in \eqref{def_E_eps}. Then, for any fixed $n' \in \mathbb{Z}^{\theta-1}$ 
		\begin{equation*}
			(1-\vartheta_{n'}^{a_\varepsilon})E_\varepsilon(z) \phi_{n'}^{a_\varepsilon} = (1-\vartheta_{n'}^{a_\varepsilon}) D_{\varepsilon}^{ \zeta, \kappa}(z) \phi_{n'}^{a_\varepsilon}.
		\end{equation*}
	\end{lemma}
	\begin{proof}
		We prove this by showing that the difference of the integral kernels of the operators $(1-\vartheta_{n'}^{a_\varepsilon})E_\varepsilon(z) \phi_{n'}^{a_\varepsilon}$ and $ (1-\vartheta_{n'}^{a_\varepsilon}) D_{\varepsilon}^{ \zeta, \kappa}(z) \phi_{n'}^{a_\varepsilon}$ is zero. By \eqref{eq_D_eps_int_rep_0}, \eqref{def_e_eps}, and \eqref{def_E_eps}  this  difference is given by
		\begin{equation}\label{eq_lem_right_inv_kernel}
			\begin{aligned}
				&(1-\vartheta_{n'}^{a_\varepsilon}(x'))\bigl(\omega\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr) -1\bigr)\phi_{n'}^{a_\varepsilon}(y') \\
				&\hspace{50 pt}\cdot G_z(x_{\zeta,\kappa}(x') -x_{\zeta,\kappa}(y') +\varepsilon(t-s)\nu_{\zeta,\kappa}(x')) 
				\sqrt{1+ \abs{\nabla \zeta(y')}^2}
			\end{aligned}
		\end{equation}
		for all $x',y' \in \R^{\theta-1}$ and $t,s \in (-1,1)$. If $y' \notin B(a_\varepsilon n',a_\varepsilon)$, then $\tfrac{y'}{a_\varepsilon} \notin B(n',1) \supset \supp \phi_{n'}$ and therefore 
		\begin{equation*}
			\phi_{n'}^{a_\varepsilon}(y') = \phi_{n'}\bigl(\tfrac{y'}{a_\varepsilon}\bigr)=0.
		\end{equation*}
		Furthermore, if $x' \in B(a_\varepsilon n', 2a_\varepsilon)$, then $\tfrac{x'}{a_\varepsilon} \in B(n',2)$ and  hence as $\vartheta_{n'} =1 $ on $B(n',2)$ we have 
		\begin{equation*}
			1-\vartheta_{n'}^{a_\varepsilon}(x') = 1-\vartheta_{n'}\bigl(\tfrac{x'}{a_\varepsilon}\bigr)=0.
		\end{equation*}
		These two observations show that if $x' \in  B(a_\varepsilon n', 2a_\varepsilon)$ or $y' \notin B(a_\varepsilon n',a_\varepsilon)$, then \eqref{eq_lem_right_inv_kernel} vanishes. Thus, it remains to consider the case $x' \notin B(a_\varepsilon n', 2 a_\varepsilon)$ and $y' \in B(a_\varepsilon n', a_\varepsilon)$. However, this implies $|x'-y'| > a_\varepsilon$. In this case we use $\omega = 1$ on $\R^{\theta-1} \setminus B(0,1)$, see the text above \eqref{def_E_eps}, to obtain 
		\begin{equation*}
			\omega\bigl(\tfrac{x'-y'}{a_\varepsilon}\bigr) -1 =0. 
		\end{equation*}
		This shows that \eqref{eq_lem_right_inv_kernel} vanishes for all $x',y'\in \R^{\theta-1}$ and $t,s \in(-1,1)$.
	\end{proof}

	\begin{proposition}\label{prop_right_inverse}
		Let $z \in \C \setminus \R$, $\zeta \in C^2_b(\R^{\theta-1};\R)$ and $\Sigma$ be as described in the beginning of Section~\ref{sec_loc_part}, $\eta,\tau \in C^1_b(\Sigma;\R)$,  $d = \eta^2- \tau^2$ satisfy
		\begin{equation*}%\label{eq_prop_right_inv_cond}
			\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4},
		\end{equation*}
		$Q_{\eta,\tau}^{\zeta,\kappa}$ be as in \eqref{eq_Q_matrix} and $q$ be as in \eqref{eq_q2}. Then, there exists a $\delta_5 \in (0,\varepsilon_2)$, with $\varepsilon_2>0$ from Proposition~\ref{prop_conv_res},  such   that  $I+D^{\zeta,\kappa}_{{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa}q$ has a bounded right inverse which is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$ with respect to $\varepsilon \in (0,\delta_5)$. 
	\end{proposition}
	\begin{proof}
		The proof is split into four steps. In \textit{Step~1} we define $R_\varepsilon$ which will turn out to be a first approximation for the right inverse of $I+D^{\zeta,\kappa}_{{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa}q$. Moreover, in this step we also show that $R_\varepsilon$ is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$  with respect to $\varepsilon$. Then, in \textit{Step~2} we calculate  $(I+D^{\zeta,\kappa}_{{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa}q) R_\varepsilon$. Afterwards, we find in \textit{Step~3} that  $(I+D^{\zeta,\kappa}_{{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa}q) R_\varepsilon $ equals $I + K_\varepsilon + L_\varepsilon$, where $K_\varepsilon$ and $L_\varepsilon$ fulfil the inequalities
		\begin{equation}\label{eq_est_K_eps_L_eps}
			\|K_{\varepsilon}\|_{0 \to 1}\leq  C \frac{  1+\abs{\log(\varepsilon)}}{a_\varepsilon^2} \\
			\quad \textup{and} \quad  \|L_{\varepsilon}\|_{0\to0} \leq C a_\varepsilon (1+\abs{\log (\varepsilon)}).
		\end{equation}
		Based on these observations we define in \textit{Step~4} an operator $\widetilde{R}_\varepsilon$  which is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$ with respect to $\varepsilon$ and fulfils $(I+D^{\zeta,\kappa}_{{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa}q) \widetilde{R}_\varepsilon = I+ \widetilde{L}_\varepsilon$, where $\|\widetilde{L}_\varepsilon\|_{0\to0}$ can be estimated by $C(1+|\log(\varepsilon)|) \varepsilon^{1/6-r}$ for an $r \in (0, \tfrac{1}{6})$. In particular, this shows that for sufficiently small $\varepsilon>0$  the right inverse of $I+D^{\zeta,\kappa}_{{\varepsilon}}(z)Q_{\eta,\tau}^{\zeta,\kappa}q$ is given by the operator $\widetilde{R}_\varepsilon(I+\widetilde{L}_\varepsilon)^{-1}$ and  uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$ with respect to $\varepsilon$.

		\textit{Step~1.}
		We define for $\varepsilon \in (0,\min\{\varepsilon_2,\delta_4\})$, where  $\varepsilon_2$ and $\delta_4$  are chosen as in Proposition~\ref{prop_conv_res} and  Proposition~\ref{prop_uniform_bdd_D_inv}, respectively,
		\begin{equation*}
			\begin{aligned}
				R_\varepsilon &: \mathcal{B}^0(\R^{\theta-1}) \to \mathcal{B}^0(\R^{\theta-1}), \\
				R_\varepsilon &:= \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}} \phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}\vartheta_{n'}^{a_\varepsilon}. 
			\end{aligned}
		\end{equation*}
		Here, $a_\varepsilon = \varepsilon^{1/6}$ and $R_{n',\varepsilon}:=(I+D^{\zeta_{a_\varepsilon n'},\kappa}_\varepsilon(z)  Q_{\eta,\tau}^{\zeta,\kappa}(a_\varepsilon n') q)^{-1}$ with $\zeta_{a_\varepsilon n'} = \zeta_{x_0'}$ as in \eqref{eq_zeta_x_0'} for $x_0' = a_\varepsilon n'$. The equality $\vartheta_{n'}^{a_\varepsilon} \phi_{n'}^{a_\varepsilon}=\phi_{n'}^{a_\varepsilon}$ implies
		\begin{equation*}
			R_\varepsilon = \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}} \vartheta_{n'}^{a_\varepsilon} \phi_n^{a_\varepsilon} R_{n',\varepsilon}\vartheta_{n'}^{a_\varepsilon} 
		\end{equation*} 
		and therefore Proposition~\ref{prop_uniform_bdd_D_inv} and \eqref{eq_series_est_020} show that $R_\varepsilon$ is well-defined and uniformly bounded by
		\begin{equation}\label{eq_R_eps_uniform_bdd}
			\norm{R_\varepsilon}_{0 \to 0} \leq 11^{\theta-1}\sup_{n' \in \Z^{\theta-1}} \norm{ (I+D^{\zeta_{a_\varepsilon n'},\kappa}_\varepsilon(z) Q_{\eta,\tau}^{\zeta,\kappa}(a_\varepsilon n')  q)^{-1}}_{0\to0}  \leq  C ,
		\end{equation}
		where $C>0$ does not depend on  $\varepsilon $.

		\textit{Step~2.}
		Applying $I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q$ to $R_\varepsilon$ yields
		\begin{equation*}
			\begin{aligned}
				(I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)R_\varepsilon 
				&= \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}(I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)\phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}  \\
				&=\sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}  \vartheta_{n'}^{a_\varepsilon}  (I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)\phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}\\
				&\hspace{10 pt}+ \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}(1-\vartheta_{n'}^{a_\varepsilon})D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q\phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}. 
			\end{aligned}
		\end{equation*}
		Moreover, using Lemma~\ref{lem_right_inverse} gives us
		\begin{equation*}
			\begin{aligned}
				(I+&D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)	R_\varepsilon 
				=\sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}  \vartheta_{n'}^{a_\varepsilon}  (I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)\phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}\\
				&\hspace{83 pt} + \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}(1-\vartheta_{n'}^{a_\varepsilon})E_\varepsilon(z)Q^{\zeta,\kappa}_{\eta,\tau}q\phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}  \\
				&=\sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}  \vartheta_{n'}^{a_\varepsilon}  (I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q - E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)\phi_{n'}^{a_\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}  \\
				&\hspace{10 pt}+  E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}qR_\varepsilon.
			\end{aligned}
		\end{equation*}
		Writing $D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q \phi_{n'}^{a_\varepsilon}$ as 
		\begin{equation*}
			\begin{aligned}
				&	 D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')q \phi_{n'}^{a_\varepsilon} +  \big(D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau} -  D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')\big)q\phi_{n'}^{a_\varepsilon} \\	
				& \qquad = 	 \phi_{n'}^{a_\varepsilon}D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')q +  [D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z), \phi_{n'}^{a_\varepsilon}]Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')q\\
				&\qquad \hphantom{=}+ \big(D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau} -  D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')\big)q\phi_{n'}^{a_\varepsilon} \
			\end{aligned}
		\end{equation*}
		and introducing the operators $L_{n',\varepsilon}:= \big(D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau} -  D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')\big)q\phi_{n'}^{a_\varepsilon}$ and  $K_{n',\varepsilon} := [D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z), \phi_{n'}^{a_\varepsilon}]Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')q - E_{\varepsilon}(z)Q^{\zeta,\kappa}_{\eta,\tau}q\phi_{n'}^{a_\varepsilon}$  yields
		\begin{equation}\label{eq_prop_right_inv_step1}
			\begin{aligned}
				(I+D_{{\varepsilon}}^{\zeta,\kappa}(z)&Q^{\zeta,\kappa}_{\eta,\tau}q)R_\varepsilon \\
				&=\sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}  \vartheta_{n'}^{a_\varepsilon} \phi_{n'}^{a_\varepsilon} (I+D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}(a_\varepsilon n')q) R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon} \\
				&\hphantom{=}+ \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}  \vartheta_{n'}^{a_\varepsilon}(K_{n',\varepsilon}  +L_{n',\varepsilon} ) R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon} 
				+E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}qR_\varepsilon \\
				&=I +  \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}  \vartheta_{n'}^{a_\varepsilon}(K_{n',\varepsilon}  +L_{n',\varepsilon} ) R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon} 
				+E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}qR_\varepsilon,
			\end{aligned}
		\end{equation}
		where 
		\begin{equation*}
			(I+D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}(a_\varepsilon n')q) R_{n',\varepsilon} = I  \quad \textup{and} \quad \sum_{n' \in \Z^{\theta-1}} \vartheta_{n'}^{a_\varepsilon} \phi_{n'}^{a_\varepsilon} \vartheta_{n'}^{a_\varepsilon} = \sum_{n' \in \Z^{\theta-1}} \phi_{n'}^{a_\varepsilon} =1
		\end{equation*}
		were used. 

		\textit{Step~3.}
		We start this step by setting
		\begin{equation*}
				K_{\varepsilon} := \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}\vartheta_{n'}^{a_\varepsilon} K_{n',\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon} +E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}qR_\varepsilon
        \end{equation*}
        and 
        \begin{equation*}
            L_{\varepsilon} 	:=  \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}} \vartheta_{n'}^{a_\varepsilon} L_{n',\varepsilon}  R_{n',\varepsilon} \vartheta_{n'}^{a_\varepsilon}.
		\end{equation*}
		Then, \eqref{eq_prop_right_inv_step1} shows 
		\begin{equation}\label{eq_I+D_approx_inv}
			(I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q_{\eta,\tau}^{\zeta,\kappa}q)R_\varepsilon  = I + K_{\varepsilon} +L_{\varepsilon}.
		\end{equation} 
	 Since $R_\varepsilon$ and $D_{{\varepsilon}}^{\zeta,\kappa}(z)$ are uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$, see \textit{Step~1} and the text above \eqref{eq_D_eps_conv}, respectively, this implies that also $K_{\varepsilon} +L_{\varepsilon}$ is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$. Moreover,  $Q_{\eta,\tau}^{\zeta,\kappa} \in C^1_b(\R^{\theta-1};\C^{N \times N})$, Proposition~\ref{prop_local_prop}, and~\eqref{eq_part_of_unity_uniform_est} imply
	 	\begin{equation*}
	 	\begin{aligned}
	 		\norm{K_{n',\varepsilon}}_{0 \to 1} &\leq  \norm{[D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z), \phi_{n'}^{a_\varepsilon}]Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')q}_{0 \to 1} + \norm{E_{\varepsilon}(z)Q^{\zeta,\kappa}_{\eta,\tau}q\phi_{n'}^{a_\varepsilon}}_{0 \to 1}\\
	 		& \leq C  \bigl(\norm{[D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z), \phi_{n'}^{a_\varepsilon}]}_{0 \to 1} + \norm{E_{\varepsilon}(z)}_{0 \to 1} \bigr)\\
	 		&\leq C \Bigl( \norm{\phi_{n'}^{a_\varepsilon}}_{W^1_\infty(\R^{\theta-1})}(1+ \abs{\log (\varepsilon)}) + \frac{1+ \abs{\log (\varepsilon)}}{a_\varepsilon}\Bigr)\\
	 		&\leq C \frac{1+ \abs{\log (\varepsilon)}}{a_\varepsilon}, \qquad  n' \in \Z^{\theta-1}.
	 	\end{aligned}
	 \end{equation*}
  In turn, with \eqref{eq_series_est_021}, \eqref{eq_R_eps_uniform_bdd}, $Q_{\eta,\tau}^{\zeta,\kappa} \in C^1_b(\R^{\theta-1};\C^{N \times N})$,  Proposition~\ref{prop_local_prop}, and Proposition \ref{prop_uniform_bdd_D_inv} we get 
		\begin{equation*}
			\begin{aligned}
				\norm{K_{\varepsilon}}_{0 \to 1} &\leq \Bigl\| \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}\vartheta_{n'}^{a_\varepsilon} K_{n',\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}\Bigr\|_{0 \to 1} + \|E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}qR_\varepsilon\|_{0 \to 1}\\
				& \leq \Bigl(\frac{C}{a_\varepsilon}\sup_{n' \in \Z^{\theta-1}} \|K_{n',\varepsilon}R_{n',\varepsilon}\|_{0\to1} +  \|E_{{\varepsilon}}(z)Q^{\zeta,\kappa}_{\eta,\tau}qR_\varepsilon\|_{0 \to 1}\Bigr)\\
				& \leq \Bigl(\frac{C}{a_\varepsilon}\sup_{n' \in \Z^{\theta-1}} \|K_{n',\varepsilon}\|_{0\to1} +  \|E_{{\varepsilon}}(z)\|_{0 \to 1}\Big)\\
				& \leq C \Bigl(\frac{1}{a_\varepsilon}\cdot\frac{1+ \abs{\log (\varepsilon)}}{a_\varepsilon} + \frac{1+ \abs{\log (\varepsilon)}}{a_\varepsilon}\Bigr)\\
				&\leq C \frac{1+\abs{\log(\varepsilon)}}{a_\varepsilon^2}.
			\end{aligned}
		\end{equation*}
		Similar we estimate $L_\varepsilon$ with \eqref{eq_series_est_020}, Proposition~\ref{prop_uniform_bdd_D_inv}, and Proposition~\ref{prop_local_prop}  by
		\begin{equation*}
			\begin{aligned}
				\|L_{\varepsilon}\|_{0 \to 0} &= \Big\| \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}\vartheta_{n'}^{a_\varepsilon} L_{n',\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}\Big\|_{0 \to 0} \\
				&= \Big\| \sum^{\textup{st.}}_{n' \in \Z^{\theta-1}}\vartheta_{n'}^{a_\varepsilon} \chi_{B(a_\varepsilon n',3 a_\varepsilon)} L_{n',\varepsilon} R_{n',\varepsilon}  \vartheta_{n'}^{a_\varepsilon}\Big\|_{0 \to 0}\\ 
				& \leq C \sup_{n' \in \Z^{\theta-1}} \|\chi_{B(a_\varepsilon n',3 a_\varepsilon)}L_{n',\varepsilon}\|_{0\to 0}\\
				&= C \sup_{n' \in \Z^{\theta-1}} \|\chi_{B(a_\varepsilon n',3 a_\varepsilon)}\big(D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau} -  D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')\big)q\phi_{n'}^{a_\varepsilon}\|_{0\to 0} \\
				&= C \sup_{n' \in \Z^{\theta-1}} \|\chi_{B(a_\varepsilon n',3 a_\varepsilon)} \\
				&\hspace{30 pt}\cdot\big(D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau} -  D_{{\varepsilon}}^{\zeta_{a_\varepsilon n'},\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}(a_\varepsilon n')\big)q\chi_{B(a_\varepsilon n',3 a_\varepsilon)}\phi_{n'}^{a_\varepsilon}\|_{0\to 0} \\
				&\leq C a_\varepsilon (1+\abs{\log(\varepsilon)}).
			\end{aligned}
		\end{equation*}
		This shows that \eqref{eq_est_K_eps_L_eps} is valid and hence completes \textit{Step~3}.

		\textit{Step~4.}
		We note that Proposition~\ref{prop_inv_I+BVq}, \eqref{def_iota},  \eqref{def_D_operators} and \eqref{eq_Q_matrix} imply that $I+D_0^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q$ is continuously invertible in $\mathcal{B}^0(\R^{\theta-1})$ and $\mathcal{B}^{1/2}(\R^{\theta-1})$.
		Furthermore, since $R_\varepsilon$ and $K_\varepsilon + L_\varepsilon$ are  uniformly bounded operators in $\mathcal{B}^0(\R^{\theta-1})$, the operator 
		\begin{equation*}
			\widetilde{R}_\varepsilon := R_\varepsilon -(I+D_0^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}( K_{\varepsilon} +L_{\varepsilon})
		\end{equation*}
		is also uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$. Moreover,
		applying $I+D_\varepsilon^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q$ to $\widetilde{R}_\varepsilon$ and \eqref{eq_I+D_approx_inv} give us 
		\begin{equation}\label{eq_right_inverse_R_eps_tilde}
			\begin{aligned}
				(I&+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q) \widetilde{R}_\varepsilon  \\
				&= I + K_\varepsilon + L_\varepsilon  - (I+D_\varepsilon^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)(I+D_0^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}( K_{\varepsilon} +L_{\varepsilon})\\
				& = I +  (D_0^{\zeta,\kappa}(z)-D_\varepsilon^{\zeta,\kappa}(z))Q^{\zeta,\kappa}_{\eta,\tau}q(I+D_0^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}( K_{\varepsilon} +L_{\varepsilon}) \\
				&= I + \widetilde{L}_\varepsilon
			\end{aligned}
		\end{equation}
		with
		\begin{equation*}
			\widetilde{L}_\varepsilon := (D_0^{\zeta,\kappa}(z)-D_\varepsilon^{\zeta,\kappa}(z))Q^{\zeta,\kappa}_{\eta,\tau}q(I+D_0^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}( K_{\varepsilon} +L_{\varepsilon}).
		\end{equation*}
		Thus, by using the estimates for $L_\varepsilon$ and $K_\varepsilon$ from \textit{Step~3} and \eqref{eq_D_eps_conv} for a fixed $r \in (0,\tfrac{1}{6})$ we obtain
		\begin{equation*}
			\begin{aligned}
				\| \widetilde{L}_\varepsilon \|_{0\to0}  
				&\leq  \|(D_{{0}}^{\zeta,\kappa}(z) -D_{\varepsilon}^{\zeta,\kappa}(z)) Q^{\zeta,\kappa}_{\eta,\tau}q(I+D_{{0}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}K_{\varepsilon}\|_{0\to0} \\
				&\hspace{10 pt}+\|(D_{{0}}^{\zeta,\kappa}(z) -D_{\varepsilon}^{\zeta,\kappa}(z)) Q^{\zeta,\kappa}_{\eta,\tau}q(I+D_{{0}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}L_{\varepsilon}\|_{0\to0} \\
				&\leq   \|(D_{{0}}^{\zeta,\kappa}(z) -D_{\varepsilon}^{\zeta,\kappa}(z)) Q^{\zeta,\kappa}_{\eta,\tau}q \|_{1/2 \to 0} \\
				&\hspace{70 pt} \cdot\|(I+D_{{0}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}\|_{1/2 \to 1/2}\|K_\varepsilon\|_{0\to 1/2} \\
				&\hspace{10 pt}+\|(D_{{0}}^{\zeta,\kappa}(z) -D_{\varepsilon}^{\zeta,\kappa}(z)) Q^{\zeta,\kappa}_{\eta,\tau}q \|_{0\to0}\\
				&\hspace{70 pt} \cdot \|(I+D_{{0}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}\|_{0\to0} \|L_\varepsilon\|_{0\to0}\\
				&\leq   \|(D_{{0}}^{\zeta,\kappa}(z) -D_{\varepsilon}^{\zeta,\kappa}(z)) Q^{\zeta,\kappa}_{\eta,\tau}q \|_{1/2 \to 0} \\
				&\hspace{70 pt} \cdot\|(I+D_{{0}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}\|_{1/2 \to 1/2}\|K_\varepsilon\|_{0\to 1} \\
				&\hspace{10 pt}+\|(D_{{0}}^{\zeta,\kappa}(z) -D_{\varepsilon}^{\zeta,\kappa}(z)) Q^{\zeta,\kappa}_{\eta,\tau}q \|_{0\to0} \\
				&\hspace{70 pt}\cdot \|(I+D_{{0}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q)^{-1}\|_{0\to0} \|L_\varepsilon\|_{0\to0}\\
				& \leq C \bigg( \frac{\varepsilon^{1/2-r} (1+\abs{\log(\varepsilon)})}{a_\varepsilon^{2}}  + a_\varepsilon (1+\abs{\log(\varepsilon)}) \bigg) \\
				&= C (1+\abs{\log(\varepsilon)}) (\varepsilon^{1/6-r} + \varepsilon^{1/6}) \\
				&\leq C (1+\abs{\log(\varepsilon)}) \varepsilon^{1/6-r}.
			\end{aligned}
		\end{equation*}
		This shows that if we choose $\delta_5>0$ sufficiently small, then $\| \widetilde{L}_\varepsilon\|_{0 \to 0} < \tfrac{1}{2}$ for all $\varepsilon \in (0,\delta_5)$ and $(I + \widetilde{L}_\varepsilon)^{-1}$ is uniformly bounded with respect to $\varepsilon \in (0,\delta_5)$. Thus,  as $\widetilde{R}_\varepsilon$ is also uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$,  $\widetilde{R}_\varepsilon(I+\widetilde{L}_\varepsilon)^{-1}$ is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$ with respect to $\varepsilon \in (0,\delta_5)$ and by \eqref{eq_right_inverse_R_eps_tilde} it is also the right inverse of $I+D_{{\varepsilon}}^{\zeta,\kappa}(z)Q^{\zeta,\kappa}_{\eta,\tau}q$.
	\end{proof}

	\begin{proposition}\label{prop_uniform_bdd_inv_B_eps}
		Let $\Sigma$ be a rotated graph as described in the beginning of Section~\ref{sec_loc_part}, $z \in \C\setminus\R$, $q$  be as in \eqref{eq_q2}, $V = \eta I_N + \tau \beta$ with $\eta,\tau \in C^1_b(\Sigma;\R)$, and $ d= \eta^2-\tau^2$ such that
		\begin{equation*}
			\sup_{x_\Sigma \in \Sigma} d(x_\Sigma) < \frac{\pi^2}{4}.
		\end{equation*} 
		 Then, there exists $\varepsilon_3 \in (0,\varepsilon_2) $, with $\varepsilon_2>0$ from Proposition~\ref{prop_conv_res}, such that  $I+B_\varepsilon(z)Vq$ has a bounded  inverse which is uniformly bounded in $\mathcal{B}^0(\Sigma)$ with respect to $\varepsilon \in (0,\varepsilon_3)$.
	\end{proposition}
	\begin{proof}
		We  directly get from Proposition~\ref{prop_right_inverse},  \eqref{eq_norm_iota}, \eqref{def_D_operators}, and \eqref{eq_Q_matrix}  that $I+\overline{B}_{{\varepsilon}}(z)Vq$ has a right inverse  which is uniformly bounded with respect to $\varepsilon \in (0,\delta_5)$ with $\delta_5$ from the previous proposition. Using \eqref{eq_B_diff} shows that then $I+B_{{\varepsilon}}(z)Vq$ has a right inverse which is uniformly bounded for $\varepsilon \in (0,\varepsilon_3)$ if $\varepsilon_3>0$ is chosen small enough. We denote this right inverse  $\mathcal{R}_\varepsilon(z)$. Then, the right inverse of $I+VqB_{{\varepsilon}}(\overline{z})$ is given by $I - Vq \mathcal{R}_\varepsilon(\overline{z}) B_\varepsilon(\overline{z})$. Hence, $(I+VqB_{{\varepsilon}}(\overline{z}))^* = I + (B_{{\varepsilon}}(\overline{z}))^*V q$ has the uniformly bounded left-inverse $\mathcal{L}_\varepsilon(z) := I - (Vq \mathcal{R}_\varepsilon(\overline{z}) B_\varepsilon(\overline{z}))^*$. Moreover, by \cite[Remark~3.11]{BHS23} the estimate
		\begin{equation*}
			\big\| B_\varepsilon(z) - (B_\varepsilon(\overline{z}))^*\big\|_{0 \to 0} \leq C \varepsilon, \quad  \varepsilon \in (0,\varepsilon_2)
		\end{equation*}
		holds.
		Thus,
		\begin{equation}\label{eq_prop_uniform_bdd_inv_B_eps}
			\mathcal{L}_\varepsilon(z) (I +B_\varepsilon(z)Vq) = I + \mathcal{L}_\varepsilon(z)(B_\varepsilon(z)- (B_\varepsilon(\overline{z}))^*)Vq
		\end{equation}
		converges in $\mathcal{B}^0(\R^{\theta-1})$ for $\varepsilon \to 0$ to  the identity operator $I$. In particular, if $\varepsilon_3>0$ is chosen small enough, then the right hand side of \eqref{eq_prop_uniform_bdd_inv_B_eps} is  invertible in $\mathcal{B}^0(\R^{\theta-1})$ for all $\varepsilon \in (0,\varepsilon_3)$, showing that $I + B_\varepsilon(z) Vq$ is  invertible in $\mathcal{B}^0(\R^{\theta-1})$, i.e.  
		\begin{equation*}
			\mathcal{R}_\varepsilon(z) = (I + B_\varepsilon(z)Vq)^{-1}.
		\end{equation*}
		This concludes the proof since we already know that $\mathcal{R}_\varepsilon(z)$ is uniformly bounded in $\mathcal{B}^0(\R^{\theta-1})$. 
	\end{proof}



	\appendix
	\section{Additional results for Section~\ref{sec_loc_part}}

	In this section we provide results which are used in Section~\ref{sec_loc_part}. We begin by stating a convenient version of the Schur test.
	\begin{lemma}\label{lem_Schur_test}
		Let $k $ be a measurable function in $\R^{\theta-1}\times \R^{\theta-1} $ with values in $\C^{N \times N}$ and $\widetilde{k} \in L^1(\R^{\theta-1})$ such that 
		\begin{equation*}
			\abs{k(x',y')} \leq \widetilde{k}(x'-y') \quad \textup{for a.e. } x',y' \in \R^{\theta-1}.
		\end{equation*}
		Then, the operator $K : L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N)$ acting as
		\begin{equation*}
		  Kf(x') = \int_{\mathbb{R}^{\theta-1}} k(x',y') f(y') dy'
		\end{equation*}
		is well-defined and bounded and $\| K \|_{L^2(\R^{\theta-1};\C^N) \to L^2(\R^{\theta-1};\C^N)} \leq \|\widetilde{k}\|_{L^1(\R^{\theta-1})}$. Moreover, if additionally $k \in C^1(\R^{\theta-1}\times \R^{\theta-1} ;\C^{N \times N})$  and
		\begin{equation*}
			\sum_{l=1}^{\theta-1} \Bigl|\frac{d}{d x'_l}k(x',y')\Bigr| \leq \widetilde{k}(x'-y') \quad \textup{for a.e. } x',y' \in \R^{\theta-1},
		\end{equation*}
		then $K$ also acts as bounded operator from  $L^2(\R^{\theta-1};\C^N)$ to $H^1(\R^{\theta-1};\C^N)$ and $\| K \|_{L^2(\R^{\theta-1};\C^N) \to H^1(\R^{\theta-1};\C^N)} \leq C\|\widetilde{k}\|_{L^1(\R^{\theta-1})}$.
	\end{lemma}
	\begin{proof}
		The first assertion is an immediate consequence of the Schur test, see for instance \cite[Chapter~III, Example~2.4]{kato}. Next, let us prove the second assertion. We start by choosing $g \in \mathcal{D}(\R^{\theta-1};\C^N)$. Since $k \in C^1(\R^{\theta-1}\times \R^{\theta-1} ;\C^{N \times N})$ and $g$ is compactly supported, dominated convergence shows that  $Kg$  is differentiable and 
		\begin{equation*}
			\partial_{l} (K g)(x') = \int_{\R^{\theta-1}} \frac{d}{d x'_l} k(x',y') g(y') \, dy'.
		\end{equation*}
		Hence, applying the Schur test shows 
		\begin{equation*}
			\norm{K g}_{H^1(\R^{\theta-1};\C^N)} \leq C \|\widetilde{k}\|_{L^1(\R^{\theta-1})} \norm{g}_{L^2(\R^{\theta-1};\C^N)}.
		\end{equation*}
		The rest follows from the fact that $\mathcal{D}(\R^{\theta-1};\C^N) $ is dense in $L^2(\R^{\theta-1};\C^N)$, the completeness of $H^1(\R^{\theta-1};\C^N)$,  and the continuity of $K$ in $L^2(\R^{\theta-1};\C^N)$.
	\end{proof}

	In the upcoming proposition we construct a partition of unity for $\R^{\theta-1}$ such that the functions have uniformly bounded derivatives.	
	\begin{proposition}\label{prop_part_unity}
		There exists a partition of unity $(\phi_{n'})_{n' \in \Z^{\theta-1}} $ for $\R^{\theta-1}$ subordinate to $(B(n',1))_{n' \in \Z^{\theta-1}}$  such that $\max_{n' \in\Z^{\theta-1}} \norm{\phi_{n'}}_{W^1_\infty(\R^{\theta-1})} < \infty$. Moreover, there exists a sequence of functions $(\vartheta_{n'})_{n' \in \Z^{\theta-1}}$ with $\supp \vartheta_{n'} \subset B(n',3)$, $0 \leq \vartheta_{n'}  \leq 1$,  $\vartheta_{n'} = 1 $ on $B(n',2)$ for all $n' \in \Z^{\theta-1}$ and $\max_{n'\in\Z^{\theta-1}} \norm{\vartheta_{n'}}_{W^1_\infty(\R^{\theta-1})} < \infty$. 
	\end{proposition}
	\begin{proof}
		Note that since $\theta \in \{2,3\}$, the family $(B(n',3/4))_{n'\in \Z^{\theta-1}}$ is also an open cover of $\R^{\theta-1}$. We start by choosing a function $\phi \in C^\infty(\R^{\theta-1})$ such that $0\leq \phi \leq 1$, $\phi = 1$ on $B(0,3/4)$ and $\supp \phi \subset B(0,1)$. Furthermore, we set ${\widetilde \phi}_{n'}: = \phi(\cdot - n')$	for $n' \in \Z^{\theta-1}$. Then, $0\leq{\widetilde \phi}_{n'} \leq 1$, ${\widetilde \phi}_{n'}= 1$ on $B(n',3/4)$ and $\supp {\widetilde \phi}_{n'}  \subset B(n',1)$.  Next, we fix a bijection $\mathcal{Z} : \N \to \Z^{\theta-1}$ and  set $\phi_{\mathcal{Z}(1)} := \widetilde{\phi}_{\mathcal{Z}(1)}$ and 
		\begin{equation*}
		  \phi_{\mathcal{Z}(j)}= (1-\widetilde\phi_{\mathcal{Z}(1)})\cdot\dots \cdot (1- \widetilde\phi_{\mathcal{Z}(j-1)})\widetilde\phi_{\mathcal{Z}(j)}, \quad j \in \N\setminus\{1\}.
        \end{equation*}
        Then, $\supp \phi_{n'} \subset \supp \widetilde{\phi}_{n'}$, $0 \leq \phi_{n'} \leq 1$ for $n' \in \Z^{\theta-1}$ and on gets via induction for $j \in \N$
		\begin{equation*}
			\sum_{k =1}^{j} \phi_{\mathcal{Z}(k)} = 1- \prod_{k=1}^{j}(1-\widetilde{\phi}_{\mathcal{Z}(k)}).
		\end{equation*}
		This implies $\sum_{n' \in \Z^{\theta-1}} \phi_{n'}(x') = \sum_{j=1}^{\infty} \phi_{\mathcal{Z}(j)}(x')=1$ for $x' \in \R^{\theta-1}$. Furthermore, let $j \in \N$, $l \in \{1,\dots,\theta-1\}$, and $x' \in \R^{\theta-1}$. We estimate
		\begin{equation*}
			\begin{aligned}
				|\partial_l\phi_{\mathcal{Z}(j)}(x')|=& \Big| \partial_l (\widetilde{\phi}_{\mathcal{Z}(j)}(x'))  \prod_{k=1}^{j-1}(1-\widetilde{\phi}_{\mathcal{Z}(k)}(x'))  \\
				&- \sum_{k=1}^{j-1} \widetilde{\phi}_{\mathcal{Z}(j)}(x')  (\partial_l \widetilde{\phi}_{\mathcal{Z}(k)}(x')) \prod_{r=1, r\neq k}^{j-1}(1-\widetilde{\phi}_{\mathcal{Z}(r)}(x')) \Big| \\
				\leq& \sum_{k =1}^j \big| \partial_l \widetilde{\phi}_{\mathcal{Z}(k)}(x')\big| = \sum_{k=1, x' \in B(\mathcal{Z}(k),1)}^j\big|\partial_l\widetilde{\phi}_{\mathcal{Z}(k)}(x')\big|  \\
				\leq& 2^{\theta-1}\norm{\partial _l\phi}_{L^\infty(\R^{\theta-1})},
			\end{aligned}
		\end{equation*}
		where we used that $x' \in \R^{\theta-1}$ can be in at most $2^{\theta-1}$ balls of the form $B(n',1)$ with $n' \in \Z^{\theta-1}$.  This shows that the derivatives of the $\phi_{n'}$'s are uniformly bounded by $2^{\theta-1}\norm{\phi}_{W^1_\infty(\R^{\theta-1};\R)}$. Next we construct the sequence $(\vartheta_{n'})_{n' \in \Z^{\theta-1}}$. To do so, we choose $\vartheta  \in C^\infty(\R^{\theta-1})$ such that $0\leq \vartheta \leq 1$, $\theta = 1$ on $B(0,2)$ and $\supp \vartheta \subset B(0,3)$. Then, we define $\vartheta_{n'}:= \vartheta(\cdot -n')$. The constructed sequence has the claimed properties.
	\end{proof}

	Our next goal is to use the functions $\vartheta_{n'}$, $n' \in \mathbb{Z}$, from Proposition~\ref{prop_part_unity} to construct operators based on a uniformly bounded sequence of operators. We start by providing an useful variant of the Cotlar-Stein lemma.

	\begin{lemma}\label{lem_cotlar_stein}
		Let $\mathcal{H}$ and $\mathcal{G}$ be Hilbert spaces, let $(\mathcal{A}_{n'})_{n' \in \Z^{\theta-1}}$ be a family of uniformly bounded operators acting from $\mathcal{H}$ to $\mathcal{G}$. Moreover, assume that there exists a number $N \in \N$ such that  for every $n' \in \Z^{\theta-1}$ exist at most $N$ indices $m'\in \Z^{\theta-1}$ such $\mathcal{A}_{n'}^* \mathcal{A}_{m'} $ and $\mathcal{A}_{n'} \mathcal{A}_{m'}^*$ are nonzero operators. Then, the sum $\sum_{n' \in \Z^{\theta-1}, |n'|<n} \mathcal{A}_{n'}$ converges for $n \to \infty$ in the strong sense to a bounded  operator $\mathcal{A}$ (which is also denoted by $\sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} \mathcal{A}_{n'}$). Moreover, its norm can be estimated by
		\begin{equation*}
			\| \mathcal{A}\|_{\mathcal{H} \to \mathcal{G}} \leq N \sup_{n' \in \Z^{\theta-1}} \| \mathcal{A}_{n'}\|_{\mathcal{H} \to \mathcal{G}}.
		\end{equation*}
	\end{lemma}
	\begin{proof}
		Our assumptions guarantee 
		\begin{equation*}%\label{eq_cotlar_stein}
				\sup_{n' \in \Z^{\theta-1}}\sum_{m' \in \Z^{\theta-1}} \| \mathcal{A}_{n'} \mathcal{A}_{m'}^*\|_{\mathcal{G} \to \mathcal{G}}^{1/2} \leq N \sup_{n' \in \Z^{\theta-1}} \|\mathcal{A}_{n'}\|_{\mathcal{H} \to \mathcal{G}}
        \end{equation*}
        and
        \begin{equation*}
				\sup_{n' \in \Z^{\theta-1}}\sum_{m' \in \Z^{\theta-1}} \| \mathcal{A}_{n'}^* \mathcal{A}_{m'}\|_{\mathcal{H} \to \mathcal{H}}^{1/2} \leq N \sup_{n' \in \Z^{\theta-1}} \|\mathcal{A}_{n'}\|_{\mathcal{H} \to \mathcal{G}}.
		\end{equation*}
		Hence, the assertions follow  form the Cotlar-Stein lemma, see \cite[Lemma~18.6.5]{H94}.
	\end{proof}
	\begin{proposition}\label{prop_part_series}
		Let $a \in (0,b)$ for a $b>0$, $(\vartheta_{n'})_{n'\in\Z^{\theta-1}}$ be the sequence from Proposition~\ref{prop_part_unity}, $\vartheta_{n'}^a := \vartheta_{n'}\bigl(\tfrac{\cdot}{a}\bigr)$ for $n'\in \Z^{\theta-1}$, and $(A_{n'})_{n' \in \Z^{\theta-1}}$ be a sequence of uniformly bounded operators in  $\mathcal{B}^0(\R^{\theta-1})$. Then, 
		\begin{equation*}
			A = \sum_{n' \in \Z^{\theta-1}}^{\textup{st.}} \vartheta_{n'}^a A_{n'} \vartheta_{n'}^a   
		\end{equation*}
		is  a well-defined operator in $\mathcal{B}^0(\R^{\theta-1})$ with
        $\| A \|_{0 \rightarrow 0} \leq 11^{\theta-1} \sup_{n' \in \Z^{\theta-1}}\norm{A_{n'}}_{0 \to 0}$.
        Moreover,  if $(A_{n'})_{n' \in \Z^{\theta-1}}$ is also a family of uniformly bounded operators acting from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$, then $A$ acts also as a bounded operator from  $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$ and $\norm{A}_{0\to1} \leq \tfrac{C}{a} \sup_{n' \in \Z^{\theta-1}}\norm{A_{n'}}_{0 \to 1}$, where $C>0$ does not depend on $a \in (0,b)$.
	\end{proposition}
	\begin{proof}
		Let us start by proving the assertion where we consider $A$ and $A_{n'}$, $n' \in \Z^{\theta-1}$, as operators acting from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^0(\R^{\theta-1})$.  We set $\mathcal{A}_{n'} := \vartheta_{n'}^a A_{n'} \vartheta_{n'}^a$.  Since a fixed ball $B(an',3a)$ overlaps with at most $11^{\theta-1}$ balls of the type $B(am',3a)$, $m'\in \Z^{\theta-1}$, there exist for every $n' \in \Z^{\theta-1}$ at most $N= 11^{\theta-1}$ indices $m' \in \Z^{\theta-1}$ such that $ \mathcal{A}_{n'} \mathcal{A}_{m'}^* \neq 0$ and $\mathcal{A}_{n'}^* \mathcal{A}_{m'} \neq 0$. Moreover, we have for all $n' \in \Z^{\theta-1}$ 
		\begin{equation*}
			\|\mathcal{A}_{n'}\|_{0\to 0} \leq \|\vartheta_{n'}^a\|_{0\to 0}  \|A_{n'}\|_{0\to 0} \|\vartheta_{n'}^a\|_{0\to 0} \leq \|A_{n'}\|_{0\to 0}.
		\end{equation*}
		Thus, by  Lemma~\ref{lem_cotlar_stein} we conclude $\| A \|_{0 \rightarrow 0} \leq 11^{\theta-1} \sup_{n' \in \Z^{\theta-1}}\norm{A_{n'}}_{0 \to 0}$.

		Next, we assume that $A_{n'}$, $n' \in \Z^{\theta-1},$ act as  uniformly bounded operators from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$. Using again the fact that a fixed ball $B(an',3a)$ overlaps with at most $11^{\theta-1}$ balls of the type $B(am',3a)$, $m'\in \Z^{\theta-1}$, shows that  there exist for every $n' \in \Z^{\theta-1}$ at most $N= 11^{\theta-1}$ indices $m' \in \Z^{\theta-1}$ such that $ \mathcal{A}_{n'} \mathcal{A}_{m'}^{0*1} \neq 0$ and $\mathcal{A}_{n'}^{0*1}\mathcal{A}_{m'} \neq 0$, where the  expressions $ {\mathcal{A}_{n'}}^{0*1}$   and  ${\mathcal{A}_{m'}}^{0*1}$ denote the adjoint  operators of $\mathcal{A}_{n'}$ and $\mathcal{A}_{m'}$, respectively, considered as operators mapping from $\mathcal{B}^0(\R^{\theta-1})$ to $\mathcal{B}^1(\R^{\theta-1})$.  Furthermore, for all $n' \in \Z^{\theta-1}$ the inequality
		\begin{equation*}
			\begin{aligned}
				\|\mathcal{A}_{n'}\|_{0\to 1} &\leq \|\vartheta_{n'}^a\|_{1\to 1}  \|A_{n'}\|_{0\to 1} \|\vartheta_{n'}^a\|_{0\to 0} \\
				&\leq \|\vartheta_{n'}^a\|_{1\to 1} \|A_{n'}\|_{0\to1} \\
				&\leq C \|\vartheta_{n'}^a\|_{W^1_\infty(\R^{\theta-1})} \|A_{n'}\|_{0\to 1} \\
				&\leq \frac{C}{a} \|\vartheta_{n'}\|_{W^1_\infty(\R^{\theta-1})} \|A_{n'}\|_{0\to 1}\\
				&\leq \frac{C}{a} \|A_{n'}\|_{0\to 1}
			\end{aligned}
		\end{equation*}
		is valid.
		Thus, Lemma~\ref{lem_cotlar_stein} yields $\norm{A}_{0\to1} \leq \tfrac{C}{a} \sup_{n' \in \Z^{\theta-1}}\norm{A_{n'}}_{0 \to 1}$.
	\end{proof}

