    \begin{equation*}
    \log M_t - \log M_0 = \phi(\log(p_t) - \log(p_0)) + \int_0^t \delta\left(\sigma_{1,s}, \sigma_{2,s}\right) ds+\psi_1(\sigma_{1,t}^2-\sigma_0^2) + \psi_2(\sigma_{2,t}^2 - \sigma_{2,0}^2)\,.
