d \log M_t = &~\phi d\log p_t + \delta\left(\sigma_{1,t}, \sigma_{2,t}\right)dt + \psi_1 d\sigma_{1,t}^2 + \psi_2 d\sigma_{2,t}^2 \\
 = & \left( \phi \mu\left(\sigma_{1,t} ,\sigma_{2,t}\right) + \delta(\sigma_{1,t}, \sigma_{2,t}) + \psi_1 m_1(\sigma_{1,t}) + \psi_2 m_2(\sigma_{2,t} )\right)dt + \phi \sigma_{1,t}dW_{1,t}^X +  \phi \sigma_{2,t}  dW_{2,t}^X +  \\
 &+  \psi_1 \Lambda_1 \sigma_{1,t} dW_{1,t}^{\sigma_1}  +  \psi_2 \Lambda_2 \sigma_{2,t}  dW_{2,t}^{\sigma_2}+ \phi c_X dJ_t\,.
\end{aligned}
\end{equation*}
Using Ito's Lemma we can derive the dynamics for the process $M_t$
\begin{equation*}
    d M_t = M_t d\log M^c_t + \frac{1}{2}M_t \Xi(\sigma_{1,t},\sigma_{2,t}) dt + M_t(e^{\phi c_X}-1)dJ_t\,,
\end{equation*}
where
\begin{equation*}
\Xi(\sigma_{1,t},\sigma_{2,t}) = \sigma_{1,t}^2\left(\phi^2 + 2\phi\rho_1\psi_1\Lambda_1 + \psi_1^2\right) + \sigma_{2,t}^2\left(\phi^2 + 2\phi\rho_2\psi_2\Lambda_2 + \psi_2^2\right)
\end{equation*}
and $M^c_t$ denotes the continuous part of $M_t$.
Now, define $Y_{1,t} = B_tM_t$, where $B_t = B_0 e^{rt}$ is the money market account process with $r$ the risk-free rate. The stochastic differential of $Y_{1,t}$ reads
\begin{equation*}
    \frac{dY_{1,t}}{Y_{1,t}} = \frac{dM_t}{M_t} + rdt\,.
\end{equation*}
To ensure the absence of arbitrage, $Y_{1,t}$ must be a martingale, meaning the drift is zero. We express this using the following notation $\frac{1}{dt}\mathbb{E}_t[Y_{1,t}] = 0$. We define the return risk premium as
\begin{equation*}
    \Tilde{\mu}(\sigma_{1,t}, \sigma_{2,t}) = \mu(\sigma_{1,t}, \sigma_{2,t}) - r + \frac{1}{2}(\sigma_{1,t}^2 + \sigma_{2,t}^2)\,.
\end{equation*}
Absence of arbitrage for $Y_{1,t}$ hence imply
\begin{equation*}
\delta(\sigma_{1,t}, \sigma_{2,t}) = -r(1 + \phi) - \phi \left( \tilde{\mu}(\sigma_{1,t},\sigma_{2,t}) - \frac{1}{2} (\sigma_{1,t}^2 + \sigma_{2,t}^2) \right) - \left(\psi_1 m_1(\sigma_{1,t}) + \psi_2 m_2(\sigma_{2,t})\right) - \frac{1}{2} \Xi - \lambda \mathbb{E}[e^{\phi c_X} - 1]\,. 
\end{equation*}
In the same way, consider $Y_{2,t} = p_t M_t$. By Ito's Lemma and using the result that $\mathbb{E}[dM_t/M_t]=-rdt$ we have
\begin{equation*}
    \frac{dY_{2,t}}{Y_{2,t}} = \frac{dM^c_t}{M_t} + \frac{dp^c_t}{p_t} + \left(\phi (\sigma_{1,t}^2 + \sigma_{2,t}^2) + \psi_1\Lambda_1 \rho_1 \sigma_{1,t}^2 +  \psi_2\Lambda_2 \rho_2 \sigma_{2,t}^2\right)dt + (e^{(\phi + 1)c_X} -1)dJ_t\,.
\end{equation*}
The absence of arbitrage implies that $\frac{1}{dt}\mathbb{E}_t[Y_{2,t}] = 0$ and we obtain the following equation
\begin{equation*}
    \Tilde{\mu}(\sigma_{1,t}, \sigma_{2,t}) = -\sigma_{1,t}^2(\phi + \psi_1\Lambda_1\rho_1) - \sigma_{2,t}^2(\phi + \psi_2\Lambda_2\rho_2)
    - \lambda\mathbb{E}[e^{\phi c_X}( e^{c_X}- 1)]\,.
\end{equation*}
Now consider $Y_{3,t} = M_t \Pi(t, p_t, \sigma_{1,t}^2, \sigma_{2,t}^2)$ where $\Pi(t, p_t, \sigma_{1,t}^2, \sigma_{2,t}^2)$ is the value at time $t$ of a traded asset with payoff $\Pi(p_T)$ at time $T$. Applying Ito's Lemma we get
\begin{equation*}
\begin{aligned}
    d\Pi_t = &\frac{\partial \Pi}{\partial t} dt + \frac{\partial \Pi}{\partial p} dp + \frac{1}{2} \frac{\partial^2 \Pi}{\partial p^2} (\sigma_{1,t}^2 + \sigma_{2,t}^2) p_t^2 dt+\frac{\partial \Pi}{\partial \sigma_{1}^2} d\sigma_{1,t}^2 +  \frac{\partial \Pi}{\partial \sigma_{2}^2} d\sigma_{2,t}^2 + \frac{\partial^2 \Pi}{\partial p \partial \sigma_{1}^2}p_t \rho_1 \Lambda_1 \sigma_{1,t}^2 dt \\
    &+  \frac{\partial^2 \Pi}{\partial p \partial \sigma_{2}^2} p_t \rho_2 \Lambda_2 \sigma_{2,t}^2 dt + \frac{1}{2} \frac{\partial^2 \Pi}{\partial \sigma_{1}^2} \Lambda_1^2 \sigma_{1,t}^2 dt + \frac{1}{2} \frac{\partial^2 \Pi}{\partial \sigma_{2}^2} \Lambda_2^2\sigma_{2,t}^2 dt \\
    &+ [\Pi(t,  p_t e^{c_X}, \sigma_{1,t}^2, \sigma_{2,t}^2) - \Pi(t, p_t, \sigma_{1,t}^2, \sigma_{2,t}^2)]dJ_t\,.
\end{aligned}
\end{equation*}
The dynamics of $Y_{3,t}$ can be specified in the following way
\begin{equation*}
\begin{aligned}
    \frac{dY_{3,t}}{Y_{3,t}} = &\frac{dM^c_t}{M_t} + \frac{d\Pi^c_t}{\Pi_t} + \frac{1}{\Pi_t } 
    \left(\frac{\partial \Pi}{\partial p} (\sigma_{1,t}^2(\phi + \psi_1\rho_1\Lambda_1)  + \sigma_{2,t}^2(\phi + \psi_2\rho_2\Lambda_2))p_t\right.\\
    & + \left.\frac{\partial \Pi}{\partial \sigma_{1}^2}\sigma_{1,t}^2 \Lambda_1(\phi \rho_1 + \psi_1\Lambda_1) + \frac{\partial \Pi}{\partial \sigma_{2}^2}\sigma_{2,t}^2 \Lambda_2(\phi \rho_2 + \psi_2\Lambda_2)\right) + c_{Y_{3,t}} dJ_t\,,
\end{aligned}
\end{equation*}
where \begin{equation*}
    c_{Y_{3,t}} = \frac{\Pi(t, p_t e^{c_X}, \sigma_{1,t}^2, \sigma_{2,t}^2)e^{\phi c_X} - \Pi(t,p_t, \sigma_{1}^2, \sigma_{2}^2)}{\Pi(t,p_t, \sigma_{1}^2, \sigma_{2}^2)}\,.
\end{equation*}
By setting $\frac{1}{dt}\mathbb{E}[dY_{3,t}/Y_{3,t}]=0$ and simplifying we get
\begin{equation*}
\begin{aligned}
    &-r\Pi(t, p_t, \sigma_{1,t}^2, \sigma_{2,t}^2) + \frac{\partial \Pi}{\partial t} + \frac{\partial \Pi}{\partial p}(r + \tilde{\mu}(\sigma_{1}^2, \sigma_2^2))p_t + \frac{\partial \Pi}{\partial \sigma_{1}^2}m_1(\sigma_{1,t}) + 
    \frac{\partial \Pi}{\partial \sigma_{2}^2}m_2(\sigma_{2,t}) + 
    \frac{1}{2} \frac{\partial^2 \Pi}{\partial p^2} (\sigma_{1,t}^2 + \sigma_{2,t}^2) p_t^2 \\
&+ \frac{1}{2}\frac{\partial^2 \Pi}{\partial \sigma_{1}^2}\Lambda^2_1\sigma_{1,t}^2 + \frac{1}{2}\frac{\partial^2 \Pi}{\partial \sigma_{2}^2}\Lambda^2_2 \sigma_{2,t}^2+ \frac{\partial^2 \Pi}{\partial p \partial \sigma_{1}^2} p_t \rho_1 \Lambda_1 \sigma_{1,t}^2  \\
    &+ \frac{\partial^2 \Pi}{\partial p \partial \sigma_{2}^2} p_t \rho_2 \Lambda_2 \sigma_{2,t}^2 + \frac{\partial \Pi}{\partial p} (\sigma_{1,t}^2 p_t(\phi + \psi_1\rho_1\Lambda_1)  + \sigma_{2,t}^2(\phi + \psi_2\rho_2\Lambda_2))\\
    & + \frac{\partial \Pi}{\partial \sigma_{1}^2}(\sigma_{1,t}^2 \Lambda_1(\phi \rho_1 + \psi_1\Lambda_1) + \frac{\partial \Pi}{\partial \sigma_{2}^2}(\sigma_{2,t}^2 \Lambda_2(\phi \rho_2 + \psi_2\Lambda_2))\\
    &+ \lambda \mathbb{E}[e^{\phi c_X}\left(\Pi(t,p_t e^{c_X}, \sigma_{1,t}^2, \sigma_{2,t}^2) - \Pi(t,p_t, \sigma_{1}^2, \sigma_{2}^2)\right)] = 0\,.
    \end{aligned}
\end{equation*}
Now, for every traded asset with price $\Pi(t, p_t, \sigma_{1,t}^2, \sigma_{2,t}^2)$ we have
\begin{equation*}
\begin{aligned}
    &-r\Pi( t, p_t, \sigma_{1,t}^2, \sigma_{2,t}^2) + \frac{\partial \Pi}{\partial t} + \frac{\partial \Pi}{\partial p}(r - \lambda^{*}\mathbb{E}[e^{c_X^{*}} -1 ])p_t + 
    \frac{\partial \Pi}{\partial \sigma_{1}^2} m^{*}_1 (\sigma_{1,t}) + \frac{\partial \Pi}{\partial \sigma_{2}^2} m^{*}_2(\sigma_{2,t}) \\
    &+ \frac{1}{2}\frac{\partial^2 \Pi}{\partial p^2} (\sigma_{1,t}^2 + \sigma_{2,t}^2)p_t^2 + \frac{1}{2}\frac{\partial^2 \Pi}{\partial \sigma_{1}^2} \Lambda^2_1 \sigma_{1,t}^2+ \frac{1}{2}\frac{\partial^2 \Pi}{\partial \sigma_{2}^2} {\Lambda^2_2} \sigma_{2,t}^2+ \frac{\partial^2 \Pi}{\partial p \partial \sigma_{1}^2}p_t \Lambda_1 \rho_1 \sigma_{1,t}^2 + \frac{\partial^2 \Pi}{\partial p \partial \sigma_{2}^2}p_t\Lambda_2 \rho_2 \sigma_{2,t}^2 \\
    &+ \lambda^* \mathbb{E}[\Pi(t,{\color{black}p_t e^{c_X^{*}}}, \sigma_{1,t}^2, \sigma_{2,t}^2) - \Pi(t,p_t, \sigma_{1}^2, \sigma_{2}^2)] = 0\,.
\end{aligned}
\end{equation*}
If we now compare the last two equations, we get
\begin{equation*}
    \begin{aligned}
        & m_1^{*}(\sigma_{1,t}) - m_1(\sigma_{1,t}) = \sigma_{1,t}^2(\phi \rho_1 \Lambda_1  + \psi_1 \Lambda_1^2) \\
        & m_2^{*}(\sigma_{2,t}) - m_2(\sigma_{2,t}) = \sigma_{2,t}^2( \phi \rho_2 \Lambda_2  + \psi_2 \Lambda_2^2) \\
        & {\color{black}\lambda^{*}\mathbb{E}[e^{c_X^*}-1] = \lambda \mathbb{E}[e^{\phi c_X}(e^{c_X}-1)]}\\
        & {\color{black}\lambda^{*}\mathbb{E}\left[\Pi\left(t, p_{t} e^{c_X^{*}}, \sigma_{1,t}^{2},\sigma_{2,t}^{2}\right)-\Pi\left(t, p_{t}, \sigma_{1,t}^{2},\sigma_{2,t}^{2}\right)\right]}\\
        & {\color{black}=\lambda \mathbb{E}\left[e^{\phi c_X}\left(\Pi\left(t, p_{t} e^{c_X}, \sigma_{1,t}^{2},\sigma_{2,t}^{2}\right)-\Pi\left(t, p_{t}, \sigma_{1,t}^{2},\sigma_{2,t}^{2}\right)\right)\right]}\,.
  \end{aligned}
\end{equation*}
From the last two relations, it follows that
$$
\lambda^{*} = \lambda \mathbb{E}[e^{\phi c_X}]
$$
and, for all $u \in \mathbb{R}$ 
\begin{equation*}
    \mathbb{E}[e^{iuc^*_X}] = \frac{\mathbb{E}\left[e^{iuc_X} (e^{\phi c_X})\right]}{\mathbb{E}\left[ e^{\phi c_X }\right]} =\exp{\left(\phi \sigma^2_X i u - \frac{1}{2}\sigma^2_X u^2 \right)}\,.
\end{equation*}
To conclude, the risk-neutral dynamics is given by
\begin{equation*}
\begin{aligned}
&d x_t=  {\left(r-q-\lambda^*\mathbb{E}[e^{c_X^*}-1]-\frac{1}{2}\left(\sigma_{1, t}^2+\sigma_{2, t}^2\right)\right) d t } +\sigma_{1, t}^2 d \Tilde{W}_{1,t}^{X}+\sigma_{2, t} d \Tilde{W}_{2, t}^{X}+c_X^* d \tilde{J}_t \\
&d \sigma_{1, t}^2= m_1^*(\sigma_{1,t})dt + \Lambda_1\sigma_{1,t} d\tilde{W}^{\sigma_1}_{1,t}\\
&d \sigma_{2, t}^2= m_2^*(\sigma_{2,t})dt + \Lambda_2\sigma_{2,t} d\tilde{W}^{\sigma_2}_{2,t}\,,
\end{aligned}
\end{equation*}
where we have
\begin{equation*}
    \begin{aligned}
        &\text{corr}(d \Tilde{W}_{1,t}^{X}, d\tilde{W}^{\sigma_1}_{1,t}) = \rho_1 \\
        &\text{corr}(d \Tilde{W}_{2,t}^{X}, d\tilde{W}^{\sigma_2}_{2,t}) = \rho_2\,.
    \end{aligned}
\end{equation*}
All other correlations, including those between the Poisson process and Brownian motions, are zero. \\
\end{proof}

\begin{proof}[Proof of \textbf{Lemma}~\ref{lem::chf}]
We derive the conditional CF of the 2-SVJ model, following the calculations in \cite{Duffie2000} and \cite{Heston++}. The CF takes the following form:
\begin{equation*}
\begin{aligned}
& \log \hat{f}_x(z ; \tau)=i\left(x_t+(r-q) \tau\right) z \\
& \quad+\sum_{j=1,2}\left(A_j^x(z ; \tau)+B_j^x(z ; \tau) \sigma_{j, t}^2\right)+C_{J}^x(z ; \tau),
\end{aligned}
\end{equation*}
where $\tau = T-t$ and the coefficients satisfy the following ODEs
\begin{equation*}
\begin{aligned}
& \frac{\partial A_j^x(z ; \tau)}{\partial \tau}=\kappa_j \omega_j B_j^x(z ; \tau) \\
& \frac{\partial B_j^x(z ; \tau)}{\partial \tau}=\frac{1}{2} \Lambda_j^2\left(B_j^x(z ; \tau)\right)^2-\left(\kappa_j-i z \rho_j \Lambda_j\right) B_j^x(z ; \tau)-\frac{1}{2} z(i+z) \\
& \frac{\partial C_{J}^x(z ; \tau)}{\partial \tau}=\lambda\left(\theta^{J}\left(z\right)-1-i \mathbb{E}[e^{c_X^*}-1] z\right)\,,
\end{aligned}
\end{equation*}
where $\theta^J (z)$ is the characteristic function of the jump sizes $c^*_X$. Given null initial condition at $\tau = 0$, the solution of this system of ODEs is
\begin{equation*}
\begin{aligned}
& A_j^x(z ; \tau)=\frac{\kappa_j \omega_j}{\Lambda_j^2}\left[\left(c_j-d_j\right) \tau-2 \log \left(\frac{1-g_j e^{-d_j \tau}}{1-g_j}\right)\right] \\
& B_j^x(z, \tau)=\frac{c_j-d_j}{\Lambda_j^2} \frac{1-e^{-d_j \tau}}{1-g_j e^{-d_j \tau}} \\
& C_{J}^x(z ; \tau)=\lambda \tau\left(\theta^{J}(z )-1-i \mathbb{E}[e^{c_X^*}-1] z\right)\,.
\end{aligned}
\end{equation*}
For simplicity, we have defined the following parameters:
\begin{equation*}
\begin{aligned}
c_j &= \kappa_j - i z \rho_j \Lambda_j \\
d_j &= \sqrt{c_j^2 + z (i + z) \Lambda_j^2}\\
g_j &= \frac{c_j - d_j}{c_j + d_j}\,.
\end{aligned}
\end{equation*}
The CF of nested models can be readily obtained from this result.
\end{proof}

