\section{Notation and Conventions}\label{sec:NC}

The notation is adopted from Ref. \cite{milehins_boucwen_2025}, and will not be restated fully. Essentially all of the definitions and results that are employed in this article are standard in the fields of set theory, general topology, analysis, ordinary differential equations, and nonlinear systems/control. They can be found in a number of textbooks and monographs on these subjects (e.g., see Refs. \cite{takeuti_introduction_1982, kelley_general_1955, bloch_real_2010, shurman_calculus_2016, ziemer_modern_2017, yoshizawa_stability_1966, yoshizawa_stability_1975, sontag_mathematical_1998, haddad_nonlinear_2011, khalil_nonlinear_2015}). Nonetheless, the article employs several concepts that have not appeared in Ref. \cite{milehins_boucwen_2025}. The majority of these concepts are related to the description of dynamics of time-variant systems.

\begin{definition}
Consider the following system of ordinary differential equations
\begin{equation}\label{eq:sys}
\dot{x} = f(t, x)
\end{equation}
where $f : \mathbb{R}_{\geq 0} \times \mathbb{R}^n \longrightarrow \mathbb{R}^n$ with $n \in \mathbb{Z}_{\geq 1}$ is the state function that is continuous in the first argument ($t$) and locally Lipschitz continuous in the second argument ($x$). Equation \eqref{eq:sys} augmented with an initial condition $x(t_0) = x_0 \in \mathbb{R}^n$ where $t_0 \in \mathbb{R}_{\geq 0 }$ shall be referred to as an initial value problem (IVP) associated with the system given by Eq. \eqref{eq:sys}. A differentiable function $x : J \longrightarrow \mathbb{R}^n$ with $J \triangleq [t_0, t_0 + T)$ and $T \in \mathbb{R}_{>0} \cup \{ + \infty \}$ is a solution of the IVP associated with the system given by Eq. \eqref{eq:sys} with the initial condition $x_0 \in \mathbb{R}^n$ if $x(t_0) = x_0$ and $\dot{x}(t) = f(t, x(t))$ for all $t \in J$. The system given by Eq. \eqref{eq:sys} may also have an output, which is expressed by the relation $y = g(x)$, where $g : \mathbb{R}^n \longrightarrow \mathbb{R}^m$ with $m \in \mathbb{Z}_{\geq 1}$ is a continuous function. 
\end{definition}

The following definitions were adopted from Ref. \cite{yoshizawa_stability_1975}:\footnote{$\lVert \cdot \rVert$ denotes an arbitrary norm on $\mathbb{R}^n$.}
\begin{definition}
The solutions of the system given by Eq. \eqref{eq:sys} are said to be uniofmly bounded if and only if for all $\alpha \in \mathbb{R}_{>0}$, there exists $\beta \in \mathbb{R}_{>0}$ such that $\lVert x(t) \rVert < \beta$ for all $t \in [t_0, t_0 + T)$ for every solution $x : [t_0, t_0 + T) \longrightarrow \mathbb{R}^n$ with $t_0 \in \mathbb{R}_{\geq 0}$ and $T \in \mathbb{R}_{>0} \cup \{ +\infty \}$ starting from the initial condition $x(t_0) = x_0 \in \mathbb{R}^n$ such that $\lVert x_0 \rVert \leq \alpha$.
\end{definition}



\section{Analysis of the BWSHCCM}\label{sec:ABWSHCCM}

Here, the NDBWSHCCM is considered under the assumption that the initial conditions are arbitrary and the values of the parameters are restricted to $B \in \mathbb{R}_{\geq 0}$, $\mathit{\Gamma} \in [-B, B]$, $\kappa \in (0, 1)$, $\sigma \in \mathbb{R}_{\geq 0}$, $n, p \in \mathbb{R}_{\geq 1}$ (as previously, $\kappa_c = 1 - \kappa$). 

Define $\mathcal{W} : \mathbb{R}^3 \longrightarrow \mathbb{R}$ as
\[
\mathcal{W}(\mathbf{X}) \triangleq  \frac{\kappa}{p + 1} \abs{X}^{p + 1} + \frac{\kappa_c}{p + 1} \abs{Z}^{p + 1} + \frac{1}{2} V^2
\]
for all $\mathbf{X} \triangleq (X, Z, V) \in \mathbb{R}^3$. Define $E : \mathbb{R}_{\geq 0} \longrightarrow \mathbb{R}$ as
\[
E(T) \triangleq \int_0^{T} \abs{U(s)} ds
\]
and denote 
\[
E(+\infty) \triangleq \lim_{T \rightarrow +\infty} \int_0^{T} \abs{U(s)} ds
\]
It should be noted that $E(+\infty) \in \mathbb{R}_{\geq 0}$. Define the Lyapunov candidate $\mathcal{V} : \mathbb{R}_{\geq 0} \times \mathbb{R}^3 \longrightarrow \mathbb{R}$ as\footnote{This form of the Lyapunov function was inspired by Example 10.1 in Ref. \cite{yoshizawa_stability_1975}.}
\[
\mathcal{V}(T, \mathbf{X}) \triangleq e^{-E(T)} \mathcal{W}(\mathbf{X})
\]
Define $\mathcal{W}' : \mathbb{R}^3 \longrightarrow \mathbb{R}$ as
\[
\mathcal{W}'(\mathbf{X}) \triangleq -\sigma \abs{X}^p V^2 - \kappa_c \abs{Z}^{p + n - 1} \left( B \abs{Z} \abs{V} + \mathit{\Gamma} Z V \right)
\]
for all $\mathbf{X} \in \mathbb{R}^3$. Referring to Ref. \cite{milehins_boucwen_2025}, note that 
\[
\dot{\mathcal{W}}(T, \mathbf{X}) = \mathcal{W}'(\mathbf{X}) + U(T) V
\]
for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$. Thus, 
\[
\dot{\mathcal{V}}(T, \mathbf{X}) = e^{- E(T)} \left( U(T) V - \abs{U(T)} \mathcal{W}(\mathbf{X}) \right) + e^{- E(T)} \mathcal{W}'(\mathbf{X})
\]
for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$. Define $K \in \mathbb{R}_{\geq 0}$ as
\[
K \triangleq \max \left( \frac{p + 1}{\kappa}, \frac{p + 1}{\kappa_c} \right)
\]

\begin{lem}\label{thm:EBWSHCCM_V_leq_0}
Under the restrictions on the values of the parameters stated above, $\dot{V}(T, \mathbf{X}) \leq 0$ for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$.\footnote{Note that $\lVert x \rVert_{\infty} \triangleq \max \left( \abs{x_1}, \ldots, \abs{x_n} \right)$ denotes the standard $\infty$-norm on $\mathbb{R}^n$.}
\end{lem}
\begin{proof}

Note that $\mathcal{W}'(\mathbf{X}) \leq 0$ for all $\mathbf{X} \in \mathbb{R}^3$ (a proof can be found in Ref. \cite{milehins_boucwen_2025}). Also, $2 \leq K$ because $(p + 1)/\kappa \leq K$, $\kappa \in (0, 1)$, and $1 \leq p$.

Fix $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$. Since $\mathcal{W}'(\mathbf{X}) \leq 0$, to show that $\dot{\mathcal{V}}(T, \mathbf{X}) \leq 0$, it suffices to show that $U(T) V \leq \abs{U(T)} \mathcal{W}(\mathbf{X})$. Thus, it suffices to show that $\abs{V} \leq \mathcal{W}(\mathbf{X})$. There are three cases to consider
\begin{compactitem}
\item Case I: $\lVert \mathbf{X} \rVert_{\infty} = \abs{X}$. It then follows that $(p + 1)/\kappa \leq K \leq \abs{X}$ or $1 \leq \kappa/(p + 1) \abs{X}$, $1 \leq \abs{X}$ and $\abs{V} \leq \abs{X}$. Therefore, 
\[
\abs{V} \leq \abs{X} \leq \abs{X}^{p} \leq \frac{\kappa}{p + 1} \abs{X}^{p + 1} \leq \mathcal{W} (\mathbf{X})
\]
\item Case II: $\lVert \mathbf{X} \rVert_{\infty} = \abs{Z}$. The proof of $\abs{V} \leq \mathcal{W} (\mathbf{X})$ follows from Case I mutatis mutandis.
\item Case III: $\lVert \mathbf{X} \rVert_{\infty} = \abs{V}$. Then, $2 \leq K \leq \abs{V}$. Thus, 
\[
\abs{V} \leq \frac{1}{2} V^2 \leq \mathcal{W} (\mathbf{X})
\]
\end{compactitem}
Thus, $\dot{\mathcal{V}}(T, \mathbf{X}) \leq 0$. By generalization, this holds for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$.
\end{proof}

\begin{prop}\label{thm:EBWSHCCM_EUB}
Under the restrictions on the values of the parameters stated above, there exists a unique solution of the NDBWSHCCM on any time interval $[T_0, T_0 + T)$ with $T_0 \in \mathbb{R}_{\geq 0}$ and $T \in \mathbb{R}_{>0} \cup \{ +\infty \}$ for every initial condition $(X_0, Z_0, V_0) \in \mathbb{R}^3$. Furthermore, the solutions of the NDBWSHCCM are uniformly bounded.
\end{prop}
\begin{proof}
Taking into account that the state function of the NDBWSHCCM is locally Lipschitz continuous in $\mathbf{X}$ and continuous in $T$, the solutions of the NDBWSHCCM exist and are unique on a non-empty maximal interval of existence (e.g., see Theorem 54 in Ref. \cite{sontag_mathematical_1998} or Theorem 2.38 in Ref. \cite{haddad_nonlinear_2011}). Noting that $\mathcal{W}$ and $\mathcal{V}$ are continuously differentiable, $\mathcal{W}$ is radially unbounded,
\[
e^{-E(+\infty)} \mathcal{W}(\mathbf{X}) \leq \mathcal{V} (T, \mathbf{X}) \leq \mathcal{W}(\mathbf{X})
\]
for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$, and $\dot{V}(T, \mathbf{X}) \leq 0$ for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^3$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$ (by Lemma \ref{thm:EBWSHCCM_V_leq_0}), the solutions of the NDBWSHCCM are uniformly bounded by Theorem 8.8 in Ref. \cite{yoshizawa_stability_1975}. Therefore, by the theorem on the extendability of the solutions (e.g., see Proposition C.3.6 in Ref. \cite{sontag_mathematical_1998} or Theorem 2.39 in Ref. \cite{haddad_nonlinear_2011}), each solution can be extended to a unique solution on $[T_0, +\infty)$.
\end{proof}


\section{Analysis of the BWMCM}\label{sec:ABWMCM}

Firstly, we note that the solutions of the model given by Eq. \eqref{eq:EBWMCM} and Eq. \eqref{eq:EBWMCM_w} are identical to the solutions of the model given by Eq. \eqref{eq:BWMCM} and Eq. \eqref{eq:BWMCM_xv} under the assumption that $u = 0$. Suppose that the outputs of both models are $(r, y, z, w, x, v)$. Given $v_0 \in \mathbb{R}_{>0}$, suppose that $(r, y, z, w, x, v)$ is the output of the model given by Eq. \eqref{eq:BWMCM} and Eq. \eqref{eq:BWMCM_xv}. Noting that $\dot{w} = -\ddot{r} + \dot{v}$ and integrating
it on both sides results in $w - w(0) = \dot{r} - \dot{r}(0) + v - v(0)$. This is equivalent to $w = \dot{r} + v$. Expanding $\dot{r}$ and taking into account that $\dot{y} = w$ yields
\[
\dot{y} = w = - \alpha \frac{k}{c} \abs{y}^{p - 1} y - \alpha_c \frac{k}{c} \abs{z}^{p - 1} z + v
\]
which implies that $w$, $y$, $z$ and $v$ satisfy the relation given by Eq. \eqref{eq:EBWMCM_w} and the second relation relation associated with Eq. \eqref{eq:EBWMCM}. Other relations associated with the state function of the model given by Eq. \eqref{eq:EBWMCM} are satisfied trivially. Therefore, every solution of the model given by Eq. \eqref{eq:BWMCM} and Eq. \eqref{eq:BWMCM_xv} is also a solution of the model given by Eq. \eqref{eq:EBWMCM} and Eq. \eqref{eq:EBWMCM_w}. It is also sufficiently simple to check that every solution of the model given by Eq. \eqref{eq:EBWMCM} and Eq. \eqref{eq:EBWMCM_w} is a solution of the model given by Eq. \eqref{eq:BWMCM} and Eq. \eqref{eq:BWMCM_xv}.

Since the state function of the model given by Eq. \eqref{eq:EBWMCM} is locally Lipschitz, its solutions are unique (so long as they exist). Suppose that the model given by Eq. \eqref{eq:BWMCM} and Eq. \eqref{eq:BWMCM_xv} has two distinct solutions starting from the same initial condition. Then, the model given by Eq. \eqref{eq:EBWMCM} and Eq. \eqref{eq:EBWMCM_w} has two distinct solutions starting from the same initial condition, which results in a contradiction. Therefore, the solutions of the model given by Eq. \eqref{eq:EBWMCM} and Eq. \eqref{eq:EBWMCM_w} are unique.

Further analysis will be performed on the NDBWMCM (given by Eq. \eqref{eq:EBWMCM_nd}). Firstly, it is remarked that the state $X$ can be recovered by noticing that $X = R + Y$. Thus, for the purposes of the analysis presented in this section, the model given by Eq. \eqref{eq:EBWMCM_nd} is reduced to
\begin{equation}\label{eq:ENDBWSHCCM_sf}
\begin{cases}
\dot{R} = \kappa \sigma \abs{Y}^{p - 1} Y + \kappa_c \sigma \abs{Z}^{p - 1} Z\\
\dot{Y} = - \kappa \sigma \abs{Y}^{p - 1} Y - \kappa_c \sigma  \abs{Z}^{p - 1} Z + V\\
\dot{Z} = \dot{Y} - B \abs{Z}^{n - 1} Z \abs{\dot{Y}} - \mathit{\Gamma} \abs{Z}^n \dot{Y} \\
\dot{V} = - \kappa \abs{Y}^{p - 1} Y - \kappa_c \abs{Z}^{p - 1} Z + U
\end{cases}
\end{equation}
It shall also be assumed that the initial conditions are arbitrary real numbers and the values of the parameters are restricted to $B \in \mathbb{R}_{\geq 0}$, $\mathit{\Gamma} \in [-B, B]$, $\kappa \in (0, 1)$, $\sigma \in \mathbb{R}_{> 0}$, $n, p \in \mathbb{R}_{\geq 1}$ (as previously, $\kappa_c = 1 - \kappa$). 

Define $\mathcal{W} : \mathbb{R}^4 \longrightarrow \mathbb{R}$ as
\[
\mathcal{W}(\mathbf{X}) \triangleq (R + \sigma V)^2 + \frac{\kappa}{p + 1} \abs{Y}^{p + 1} + \frac{\kappa_c}{p + 1} \abs{Z}^{p + 1} + \frac{1}{2} V^2
\]
for all $\mathbf{X} \triangleq (R, Y, Z, V) \in \mathbb{R}^4$. Define also $E : \mathbb{R}_{\geq 0} \longrightarrow \mathbb{R}$ as
\[
E(T) \triangleq \int_0^{T} \abs{U(s)} ds
\]
and denote 
\[
E(+\infty) \triangleq \lim_{T \rightarrow +\infty} \int_0^{T} \abs{U(s)} ds
\]
It should be noted that $E(+\infty) \in \mathbb{R}_{\geq 0}$. Define the Lyapunov candidate $\mathcal{V} : \mathbb{R}_{\geq 0} \times \mathbb{R}^4 \longrightarrow \mathbb{R}$ as\footnote{This form of the Lyapunov function was inspired by Example 10.1 in Ref. \cite{yoshizawa_stability_1975}.}
\[
\mathcal{V}(T, \mathbf{X}) \triangleq e^{-E(T)} \mathcal{W}(\mathbf{X})
\]
Define $\mathcal{W}' : \mathbb{R}^4 \longrightarrow \mathbb{R}$ as
\[
\mathcal{W}'(\mathbf{X}) \triangleq - \frac{1}{\sigma} \dot{R}^2 - \kappa_c \abs{Z}^{p + n - 1} \left( B \abs{Z} \abs{V - \dot{R}} + \mathit{\Gamma} Z (V - \dot{R}) \right)
\]
and $\mathcal{W}'' : \mathbb{R}^4 \longrightarrow \mathbb{R}$ as
\[
\mathcal{W}''(\mathbf{X}) \triangleq (2 \sigma^2 + 1) V + 2 \sigma R
\]
for all $\mathbf{X} \in \mathbb{R}^4$ (it should be remarked that $\dot{R}$ is used as an abbreviation for $\kappa \sigma \abs{Y}^{p - 1} Y + \kappa_c \sigma \abs{Z}^{p - 1} Z$). Referring to Ref. \cite{milehins_boucwen_2025}, note that 
\[
\dot{\mathcal{W}}(T, \mathbf{X}) = \mathcal{W}'(\mathbf{X}) + U(T) \mathcal{W}''(\mathbf{X})
\]
for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^4$. Thus, 
\[
\dot{\mathcal{V}}(T, \mathbf{X}) = e^{- E(T)} \left( U(T) \mathcal{W}''(\mathbf{X}) - \abs{U(T)} \mathcal{W}(\mathbf{X}) \right) + e^{- E(T)} \mathcal{W}'(\mathbf{X})
\]
for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^4$. Define $K \in \mathbb{R}_{\geq 0}$ as
\[
K \triangleq (2 \sigma^2 + 2 \sigma + 1) \max \left( 2 \sigma^2 + 1, \frac{p + 1}{\kappa}, \frac{p + 1}{\kappa_c} \right)
\]

\begin{lem}\label{thm:EBWMCM_V_leq_0}
Under the restrictions on the values of the parameters stated above, $\dot{V}(T, \mathbf{X}) \leq 0$ for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^4$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$.
\end{lem}
\begin{proof}

Note that $\mathcal{W}'(\mathbf{X}) \leq 0$ for all $\mathbf{X} \in \mathbb{R}^4$ (see Lemma C.1 in Ref. \cite{milehins_boucwen_2025} for a proof; it should be remarked that Lemma C.1 in Ref. \cite{milehins_boucwen_2025} holds also under the less restrictive ranges of the parameters that are used in this study). Fix $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^4$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$. Since $\mathcal{W}'(\mathbf{X}) \leq 0$, it suffices to show that \[
U(T) ((2 \sigma^2 + 1) V + 2 \sigma R) \leq \abs{U(T)} \mathcal{W}(\mathbf{X})
\]
Therefore, it suffices to show that 
\[
\abs{(2 \sigma^2 + 1) V + 2 \sigma R} \leq \mathcal{W}(\mathbf{X})
\]
or
\[
(2 \sigma^2 + 1) \abs{V} + 2 \sigma \abs{R} \leq \mathcal{W}(\mathbf{X})
\]
There are four cases to consider
\begin{compactitem}
\item Case I: $\lVert \mathbf{X} \rVert_{\infty} = \abs{R}$. Then, $\abs{V} \leq \abs{R}$ and
\[
(2 \sigma^2 + 2 \sigma + 1) (2 \sigma^2 + 1) \leq K \leq \abs{R}
\] 
or
\[
\abs{R} \leq (2 \sigma^2 + 2 \sigma + 1)^{-1} (2 \sigma^2 + 1)^{-1} R^2
\]
Therefore, 
\[
\begin{aligned}
(2 \sigma^2 + 1) \abs{V} + 2 \sigma \abs{R} & \leq (2 \sigma^2 + 2 \sigma + 1) \abs{R} \leq \frac{1}{2 \sigma^2 + 1} R^2\\
& \leq (R + \sigma V)^2 + \frac{1}{2} V^2 \leq \mathcal{W}(\mathbf{X})
\end{aligned}
\]
\item Case II: $\lVert \mathbf{X} \rVert_{\infty} = \abs{Y}$. Then, $\abs{R} \leq \abs{Y}$, $\abs{V} \leq \abs{Y}$, and $1 \leq \abs{Y}$. Furthermore,
\[
(2 \sigma^2 + 2 \sigma + 1) \frac{p + 1}{\kappa} \leq K \leq \abs{Y}
\] 
or
\[
\abs{Y} \leq (2 \sigma^2 + 2 \sigma + 1)^{-1} \frac{\kappa}{p + 1} Y^2
\]
Therefore, 
\[
\begin{aligned}
(2 \sigma^2 + 1) \abs{V} + 2 \sigma \abs{R} & \leq (2 \sigma^2 + 2 \sigma + 1) \abs{Y} \leq \frac{\kappa}{p + 1} Y^2\\
& \leq \frac{\kappa}{p + 1} \abs{Y}^{p + 1} \leq \mathcal{W}(\mathbf{X})
\end{aligned}
\]
\item Case III: $\lVert \mathbf{X} \rVert_{\infty} = \abs{Z}$. The proof of $\abs{V} \leq \mathcal{W} (\mathbf{X})$ follows from Case II mutatis mutandis.
\item Case IV: $\lVert \mathbf{X} \rVert_{\infty} = \abs{V}$. Then, $\abs{R} \leq \abs{V}$ and $1 \leq \abs{V}$. Furthermore,
\[
2 (2 \sigma^2 + 2 \sigma + 1) \leq K \leq \abs{V}
\] 
or
\[
\abs{V} \leq \frac{1}{2} (2 \sigma^2 + 2 \sigma + 1)^{-1} V^2
\]
Therefore, 
\[
(2 \sigma^2 + 1) \abs{V} + 2 \sigma \abs{R} \leq (2 \sigma^2 + 2 \sigma + 1) \abs{V} \leq \frac{1}{2} V^2 \leq \mathcal{W}(\mathbf{X})
\]
\end{compactitem}
Thus, $\dot{\mathcal{V}}(T, \mathbf{X}) \leq 0$. By generalization, this holds for all $T \in \mathbb{R}_{\geq 0}$ and $\mathbf{X} \in \mathbb{R}^4$ such that $K \leq \lVert \mathbf{X} \rVert_{\infty}$.
\end{proof}

\begin{prop}\label{thm:EBWMCM_EUB}
Under the restrictions on the values of the parameters stated above, there exists a unique solution of the NDBWMCM on any time interval $[T_0, T_0 + T)$ with $T_0 \in \mathbb{R}_{\geq 0}$ and $T \in \mathbb{R}_{>0} \cup \{ +\infty \}$ for every initial condition $(R_0, Y_0, Z_0, V_0) \in \mathbb{R}^4$. Furthermore, the solutions of the NDBWMCM are uniformly bounded.
\end{prop}
\begin{proof}
The proof is similar to the proof of Proposition \ref{thm:EBWSHCCM_EUB}.
\end{proof}

