\title{Improved Lower Bounds on Multiflow-Multicut Gaps}

\author{
  Sina Kalantarzadeh\thanks{Email: \texttt{s4kalant@uwaterloo.ca}}, Nikhil Kumar\thanks{Email: \texttt{nikhil.kumar2@uwaterloo.ca}} \\
  University of Waterloo
