    \centering
    \caption{An illustration of the 1-sum operation}
    \label{figure: cut vertex operation}
\end{figure}

Let $\mathcal{G}$ be a family of graphs. We say that $\mathcal{G}$ is closed under the 1-sum operation if for any $G_{1},\ldots,G_{k}\in \mathcal{G}$ and $r_i \in G_i$, the graph obtained by taking 1-sum of $G_{1},\ldots,G_{k}$ at $r_1,r_2,\ldots,r_k$ is a graph in $\mathcal{G}$. Many natural classes of family are closed under the 1-sum operation, such as trees, cactus graphs and planar graphs. Note that 1-sum is a special case of a well known and a more general notion of clique-sums. 

%\begin{Remark}
 %   The family of trees, cactus and planar graphs are closed under the 1-sum operation.
%\end{Remark}

We note down a few more definitions before stating the main theorem of this section. Let $G$ be a graph and $r\in V(G)$ be an arbitrary vertex. Recall that $\mathcal{F}_{2w}(G)$ denotes the set of all $2w$-diameter decompositions of $G$. For $k \in \{1,\ldots,w\}$, we use $\mathcal{F}^{k}_{2w}(G,r)$ to denote the set of all $2w$-diameter decompositions of $G$ such that every vertex in the connected component containing $r$ is within distance strictly less than $k$ from it. More precisely, 
$$\mathcal{F}^{k}_{2w}(G,r)=\{F\in \mathcal{F}_{2w}(G)~|~rad_{F}(r) < k\}.$$



\begin{Definition}
Let \( G \) be a graph, and let \( \mathcal{F}_{2w}(G) \) be the family of \( 2w \)-diameter decompositions of \( G \). We say that \( y = \{y_F \mid F \in \mathcal{F}_{2w}(G)\} \) is a \textit{p-load} distribution if the following conditions hold:
\begin{align*}
    \sum_{F \in \mathcal{F}_{2w}(G)} y_F &= 1, \\
    \sum_{ F \in \mathcal{F}_{2w}(G),e \in F} y_F &\leq p \quad \forall e \in E(G), \\
    y_F &\geq 0 \quad \forall F \in \mathcal{F}_{2w}(G).
\end{align*}
If such a \( \pload \) distribution exists, we say that \( G \) accepts a \( \pload \) distribution. We also say that a family \( \mathcal{G} \) accepts a \textit{p-load} distribution if every graph \( G \in \mathcal{G} \) accepts a \( \textit{p-load} \) distribution.
\end{Definition}
\noindent Note that if we have a $\pload$ distribution, then we can use this to sample a $2w$-diameter decomposition of $G$ such that each edge is picked in the decomposition with probability at most $p$. 
\begin{Corollary}\label{Corollary: pload}
    Let $\mathcal{G}$ be a family of graphs. Let $p=\frac{\alpha_{\mathcal{M}(\mathcal{G})}}{2w}$, then $\mathcal{G}$ accepts a $\pload$ distribution.
\end{Corollary}
\begin{proof}
    Recall that we assumed that all edges have unit length. Corollary~\ref{cor: xe=1/2w} gives a direct proof by setting $t=2w$.
\end{proof}
Suppose that $\mathcal{G}$ is a family of graphs closed under 1-sum for the rest of the section. Let $p=\frac{\alpha}{2w}$, where $\alpha=\alpha_{\mathcal{\mathcal{M}(G)}}$. Corollary~\ref{Corollary: pload} implies that $\mathcal{G}$ accepts a $\pload$ distribution. In Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution}, we show that if $\mathcal{G}$ is closed under the 1-sum operation and accepts a $\pload$ distribution, then for any \( G \in \mathcal{G} \) and \( r \in V(G) \), there exists a distribution over \( 2w \)-diameter decompositions \( \mathcal{F}_{2w}(G) \) such that if we sample a decomposition \( F \in \mathcal{F}_{2w}(G) \) from this distribution, we are guaranteed that \( \text{rad}_F(r) \leq w - 1 \), i.e. $F\in \mathcal{F}_{2w}^{w}(G,r)$. Note that this is similar to the first item of Observation~\ref{Observation: trees}. 

\begin{Theorem}\label{Theorem: rooted (p,2w)-diameter distribution}
     Suppose that $\mathcal{G}$ is closed under 1-sum and accepts a $\pload$ distribution. Let $G\in \mathcal{G}$ and $r\in V(G)$ be an arbitrary vertex. Then there exists a $\pload$ distribution $y=\{y_{F}~|~F\in \mathcal{F}_{2w}(G)\}$ such that $\sum_{F\in \mathcal{F}^{w}_{2w}(G,r)}y_{F}=1 $.
\end{Theorem}
\begin{proof}
Let $\mathcal{F}_{2w}=\mathcal{F}_{2w}(G)$ and $\mathcal{F}_{2w}^{w}(r)=\mathcal{F}_{2w}^{w}(G,r)$ for simplicity. It is sufficient to show that the following LP is feasible and has optimal value $0$.
   \begin{align*}
    \min \sum_{F \in \mathcal{F}_{2w} \setminus \mathcal{F}^{w}_{2w}(r)} y_F & \\
    \sum_{ F \in \mathcal{F}_{2w},e \in F} y_F \leq & ~p \quad \forall e \in E(G) \\
    \sum_{F \in \mathcal{F}_{2w}} y_F = & 1 \\
    y_F \geq & 0 \quad \forall F \in \mathcal{F}_{2w}
\end{align*}
The above LP is feasible since $\mathcal{G}$ accepts a $\pload$ distribution. For the sake of contradiction, assume that the optimal value of the above LP is $z>0$. Let $m>\frac{1}{z}$ be a natural number. Let $G_{1},\ldots,G_{m}$ be $m$ disjoint copies of $G$ and $r_{i}$ be the vertex of $G_i$ which corresponds to $r$. Let $G'$ be formed by taking 1-sum of $G_{1},\ldots,G_{m}$ at $r_{1},\ldots,r_{m}$. See the following figure for an illustration.
%    \textcolor{red}{representative, center vertex?} of $r$ in $G_{i}$ for $i=1,\ldots,m$. 
%\begin{figure}[ht!]
\begin{figure}[H]
    \centering
    \input{Theorem_1_G_prime_Figure}
    % \caption{Caption}
    \label{fig:enter-label}
\end{figure}


\noindent Note that \( G' \in \mathcal{G} \) since \( \mathcal{G} \) is closed under the 1-sum operation. Let \( \mathcal{F}_{2w}' =\mathcal{F}_{2w}(G')\) be the set of all \( 2w \)-diameter decompositions of \( G' \). By the assumption of the theorem, every graph in \( \mathcal{G} \) accepts a \( \pload \) distribution. Let \( \{ g_{F'} \}_{F' \in \mathcal{F'}_{2w}} \) denote such a distribution for \( G' \). Let \( G_i = (V_i, E_i) \) and \( \mathcal{F}_{2w}(G_{i}) \) be the set of all \( 2w \)-diameter decompositions of \( G_i \) for \( i = 1, 2, \dots, m \).\footnote{Note that \( \bigcap_{i=1}^{m} V_i = \{ r \} \).} The distribution \( g \) over \( \mathcal{F}_{2w}' \) defines a distribution \( g^i \) over \( \mathcal{F}_{2w}(G_i) \) as follows:
\[
g^i_F = \sum_{F' \in \mathcal{F}^{'}_{2w}, F' \cap E_i = F} g_{F'} \quad \text{for all} \quad F \in \mathcal{F}_{2w}(G_i).
\]

Since \( g^i \) is a projection of \( g \) onto \( G_i \) and \( g \) is a \( \pload \) distribution, it follows that \( g^i \) is also a \( \pload \) distribution (see Appendix \ref{Appendix: Projection} for a short proof). Furthermore, since \( G_i \) is an identical copy of \( G \) and \( g^i \) is a feasible solution to the LP mentioned above, we have that,
\[
\sum_{F \in \mathcal{F}_{2w}(G_i) \setminus \mathcal{F}_{2w}^{w}(G_i, r)} g^i_F \geq z \quad \text{for} \quad i = 1, 2, \dots, m.
\]
Recall that \( \mathcal{F}_{2w}^{w}(G_i, r) \) denotes the set of all \( 2w \)-diameter decompositions of \( G_i \) in which the distance of every vertex in the connected component containing \( r \) is at most \( w-1 \) from it. Let \( T_i \) be the event that, when sampling \( F' \in \mathcal{F}_{2w}' \) according to the distribution \( g \), the intersection \( F' \cap E_i \) does not belong to \( \mathcal{F}_{2w}^{w}(G_i, r) \). From the above discussion, it follows that \( \text{Pr}[T_i] \geq z \). Since \( m > \frac{1}{z} \), we have
\[
\sum_{i=1}^{m} \text{Pr}[T_i] \geq z \cdot m > 1.
\]
This implies that the events \( T_1, \dots, T_m \) are not disjoint, and there exist indices \( i, j \) such that \( \text{Pr}[T_i \cap T_j] \neq \emptyset \). Therefore, there exists a \( F' \in \mathcal{F}_{2w}' \), and vertices \( u \in V_i \), \( v \in V_j \) such that:
\begin{enumerate}
    \item \( g_{F'} > 0 \),
    \item \( u \) and \( v \) are in the connected component containing \( r \) in \( G' - F' \),
    \item the distance of \( u \) and \( v \) from \( r \) is at least \( w \).
\end{enumerate}
But then, the diameter of \( F' \) is at least \( 2w \), which contradicts the fact that \( F' \in \mathcal{F}_{2w}' \). This implies that $z=0$, and completes the proof of the theorem.
\end{proof}

\noindent We say that a graph $G$ and one of its vertex $r$ accepts a $(r,p)$-$\text{load distribution}$ if there exists a $\pload$ distribution $y$ over $2w$-diameter decompositions $\mathcal{F}_{2w}(G)$ such that $$\sum_{F\in \mathcal{F}^{w}_{2w}(G,r)}y_{F}=1.$$ We say that a graph class $\mathcal{G}$ accepts a \emph{strong}-$p$-$\emph{load distribution}$ if for every $G \in \mathcal{G}$ and $r \in V(G)$, there exists a $(r,p)$-load distribution.

In Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution}, we proved that if a class of graphs $\mathcal{G}$, closed under the 1-sum operation, accepts a $\pload$ distribution, then it also accepts a strong-$\pload$ distribution. In Theorem~\ref{Theorem: radius rooted (p,2w)-diameter distribution}, we generalize Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution} to arbitrary radii. To prove this theorem, we assume, in addition to the graph class being closed under the 1-sum operation, that the class also includes \( K_2 \), the complete graph on two vertices, i.e.~a single edge.

\begin{Theorem}\label{Theorem: radius rooted (p,2w)-diameter distribution}
 Suppose that $\mathcal{G}$ is closed under 1-sum such that $K_2 \in \mathcal{G}$ and accepts a strong-$\pload$ distribution. Let $G\in \mathcal{G}, r\in V(G)$ and $k\in\{1,\ldots,w\}$. Then there exists a $(r,p)$-\text{load distribution} $y=\{y_{F}~|~F\in \mathcal{F}_{2w}(G)\} $ such that, $$\sum_{F\in \mathcal{F}^{k}_{2w}(G,r)}y_{F}\geq 1-p(w-k).$$
\end{Theorem}

\begin{proof}
Let $\mathcal{F}_{2w}=\mathcal{F}_{2w}(G), \mathcal{F}_{2w}^{w}(r)=\mathcal{F}_{2w}^{w}(G,r)$ and $\mathcal{F}_{2w}^{k}(r)=\mathcal{F}_{2w}^{k}(G,r)$ for simplicity. It is sufficient to show that the following LP is feasible and has optimal value $0$.
    \begin{align*}
     \min\sum_{F\in \mathcal{F}_{2w}\setminus \mathcal{F}_{2w}^{w}(r)} y_{F}&\\
     \sum_{F\in \mathcal{F}_{2w}^{k}(r)}y_{F}\geq &1-p(w-k)\\
    \sum_{F\in \mathcal{F}_{2w},e\in F} y_{F}\leq &p \quad\forall e\in E(G)\\
    \sum_{F\in \mathcal{F}_{2w}} y_{F}=&1\\
    y_{F}\geq &0\quad\forall F\in \mathcal{F}_{2w}
\end{align*} \label{LP:2}
\noindent For now, assume that the LP is feasible and its optimal value is $z>0$. The proof that LP is feasible will also follow from the discussion below. Let $m>\frac{1}{z}$ and $G_{1},\ldots,G_{m}$ be $m$ disjoint copies of $G$. Let $r_{i}$ be the vertex of $G_i$ which corresponds to $r$ and $G'$ be formed by taking 1-sum of $G_{1},\ldots,G_{m}$ at $r_{1},\ldots,r_{m}$. We construct $H$ by adding a path of length $w-k$ to $G'$ at $r$. Let $P=\{e_1,e_2,\ldots,e_{w-k}\}$ be the set of edges on this path, where $e_1=(r,v_1),e_2=(v_1,v_2),\ldots,e_{w-k}=(v_{w-k-1},v)$. See the following figure for an illustration.


\begin{figure}[H]
    \centering
    \input{Theorem_2_H_Figure}
    % \caption{Caption}
    \label{fig:enter-label}
\end{figure}
Since $\mathcal{G}$ is closed under taking 1-sum and $K_2 \in \mathcal{G}$, we can conclude that $H \in \mathcal{G}$. 
%Let $\mathcal{F'}_{2w}^{w}(v)=\mathcal{F}^{w}_{2w}(H,v)$. 
By Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution}, there exists a probability distribution $x=\{x_{F'} \geq 0~|~F'\in \mathcal{F}^{w}_{2w}(H,v)\}$, such that $$\sum_{F' \in \mathcal{F}^{w}_{2w}(H,v)} x_{F'}=1,~\text{and},~\sum_{F' \in \mathcal{F}_{2w}^{w}(H,v),e\in F' } x_{F'} \leq p~\text{for all}~e\in E(H).$$ 

\noindent Let $A=\{F' \in \mathcal{F}^{w}_{2w}(H,v)~|~F' \cap E(P) \neq \emptyset \}$ and $B=\{F' \in \mathcal{F}^{w}_{2w}(H,v)~|~F' \cap E(P) =\emptyset \}$. Let $A_{i}=\{F' \in  A~|~e_{i}\in F'\}$ for $i=1,\ldots,w-k$. Note that $\sum_{F' \in A}x_{F'}+\sum_{F' \in B}x_{F'}=1$. Since $\sum_{F' \in A_{i}} x_{F'} \leq p$, and $A=\cup_{i=1}^{w-k}A_{i}$, it follows that: $$\sum_{F'\in A} x_{F'} \leq (w-k)p ~~\Rightarrow~~\sum_{F' \in B}x_{F'}\geq 1-(w-k)p.$$ Let \( G_i = (V_i, E_i) \) and \( \mathcal{F}_{2w}(G_i) \) be the set of all \( 2w \)-diameter decompositions of \( G_i \) for \( i= 1, 2, \dots, m \). Recall that \( \mathcal{F}_{2w}^{w}(G_i, r),\mathcal{F}_{2w}^{k}(G_i, r) \) is the set of \( 2w \)-diameter decompositions of \( G_i \) in which the distance of every vertex in the connected component containing \( r \) is at most $w-1$ and $k-1$ from it, respectively.  
For $F \in \mathcal{F}_{2w}(G_i)$, let $$y^{i}_{F}=\displaystyle \sum_{F' \in \mathcal{F}_{2w}^{w}(H,v),F' \cap E_i = F} x_{F'}.$$ In other words, $y^i_F$ is the projection of $x$ to the graph $G_i$. The next claim shows that the projection of the distribution $x$ onto $G_i$ is a feasible solution to the LP~\ref{LP:2}.
\begin{Claim}
$y^{i}=\{y^{i}_{F}~|~F \in \mathcal{F}_{2w}(G_i)\}$ is a feasible solution to the LP~\ref{LP:2}.
\end{Claim}\label{claim: y_j feasible}
\begin{proof}
Appendix \ref{Appendix: Projection} implies that $y^{i}$ is a $\pload$ distribution for $G_{i}$. Let $B_{i}=\{F'\cap E_i~|~F'\in B\}$. Observe that $B_{i}\in \mathcal{F}_{2w}(G_i)$. Let $F\in B_{i}$. Then there exists $F'\in B$ such that $F=F'\cap E_i$. Furthermore, for any $F' \in B$, we have $F' \in \mathcal{F}_{2w}^{w}(H,v)$ and $F'\cap E(P)=\emptyset$. Hence we can conclude that $F \in \mathcal{F}^{k}_{2w}(G_i,r)$. Thus, $$\sum_{F\in \mathcal{F}^{k}_{2w}(G_i,r)} y^{i}_{F} \geq \sum_{F\in B_{i}} y^{i}_{F}=\sum_{F\in B_{i}}~~\sum_{F'\in B,F'\cap E_i=F} x_{F'}=\sum_{F'\in B} x_{F'}\geq 1-(w-k) \cdot p.$$

\end{proof}
\noindent Since $G_i$ is an identical copy of $G$ and $\mathcal{F}_{2w}(G_{i})$ is also an identical copy of $\mathcal{F}_{2w}=\mathcal{F}_{2w}(G)$, Claim~\ref{claim: y_j feasible} shows that $y^{i}$ is a feasible solutions for LP~\ref{LP:2} for $G_i$, it follows that LP~\ref{LP:2} is feasible. Since $z$ is the optimal solution of LP~\ref{LP:2}, for each $y^{i}$, we have,
$$\sum_{F\in \mathcal{F}_{2w}(G_i)\setminus \mathcal{F}_{2w}^{w}(G_i,r)} y^{i}_{F}\geq z.$$
This implies that,
$$\sum_{i=1}^{m}~~\sum_{F\in \mathcal{F}_{2w}(G_i)\setminus \mathcal{F}_{2w}^{w}(G_i,r)} y^{i}_{F} \geq mz >1.$$ 
Using same argument as in the proof of Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution}, we can show that there exists $1\leq i\neq j\leq m$ and $F' \in \mathcal{F}_{2w}^{w}(H,v)$ such that $$y_{F'} >0,~F' \cap E_i \notin \mathcal{F}^{w}_{2w}(G_{i},r)~\text{and}~F' \cap E_j \notin \mathcal{F}^{w}_{2w}(G_j,r).$$ This means that there exists a vertex $a \in V_i,b\in V_j$ such that the distance of $a$ and $b$ from $r$ is  at least $w$, and they are both included in the connected component containing $r$ in $H-F'$. Hence $u$ and $v$ are at least $2w$ distance apart, and this contradicts the fact that $F'$ is a $2w$-diameter decomposition. Hence $z=0$ and this completes the proof of the theorem.
%$dist(u_{a},r=r_{a})>w-1,dist(u_{b},r=r_{b})>w-1$, and $u_{a},u_{b},r$ are within the same connected component of $E(G\setminus F')$. Contradiction.
\end{proof}
\noindent So far, we have shown that probability distributions over $2w$-diameter decompositions for any class of graphs closed under 1-sum are consistent with those observed for trees, for a fixed value of $k$\footnote{Note that for trees, this property holds for all values of $k$ simultaneously; however, here we can only guarantee it for a fixed value of $k$.}. We now state a simple claim that will be useful in proving the lower bound. From this point onward, by Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution} and Theorem~\ref{Theorem: radius rooted (p,2w)-diameter distribution}, we can restrict ourselves to $\mathcal{F}_{2w}^{w}(G,r)$ instead of $\mathcal{F}_{2w}(G)$ for a given graph $G$ and vertex $r\in V(G)$.
\begin{Lemma} \label{lemma:upperbound}
    Let $G\in \mathcal{G}$, and $r\in V(G)$ be an arbitrary vertex. Let $\mathcal{F}^{w}_{2w}(G,r)$ be defined as before. Let $P$ be an arbitrary shortest path with length $w$, starting at $r$. Denote the other endpoint of $P$ as $r'$. If $y=\{y_{F}~|~F\in \mathcal{F}_{2w}^{w}(G,r)\} $ is a $(r,p)$-load distribution then $F\cap E(P)\neq \emptyset~\text{for all}~F\in \mathcal{F}_{2w}^{w}(G,r)$, and,
    $$\displaystyle \sum_{F \in \mathcal{F}_{2w}^{w}(G,r),|F\cap E(P)|\geq 2} y_{F}\leq (w \cdot p)-1.$$
    \end{Lemma}
\begin{proof}
    If there exists $F\in \mathcal{F}_{2w}^{w}(G,r)$ such that $F \cap E(P)=\emptyset$, then $r,r'$ are within the same connected component in $G- F$, which contradicts the fact that $F \in \mathcal{F}_{2w}^{w}(G,r)$. Let, 
    $$A=\{F\in \mathcal{F}_{2w}^{w}(G,r)~|~|F\cap E(P)|\geq 2 \}~\text{and}~B=\{F\in \mathcal{F}_{2w}^{w}(G,r)~|~|F\cap E(P)|=1\}.$$ 
    Note that $A,B$ forms a partition of $\mathcal{F}_{2w}^{w}(G,r)$. Using the definition of $A$ and $B$, and the fact that $\sum_{F\in A} y_{F} + \sum_{F\in B} y_{F}=1$, we can derive the statement of the theorem as follows:
    $$\sum_{F\in A} y_{F}+1= 2 \cdot \sum_{F\in A} y_{F} + \sum_{F\in B} y_{F} \leq \sum_{e\in E(P)}~~\sum_{e\in F,F\in \mathcal{F}_{2w}^{w}(G,r)} y_{F} \leq~\sum_{e\in E(P)}p~\leq~w \cdot p.$$ 
    Note that the first inequality can be derived by showing that $y_{F}$ appears at least twice in the right hand side if $F\in A$, and exactly once if $F\in B$.\end{proof}


\section{Lower Bound For Cactus Graphs}\label{sec:proof_main_thm}

\noindent We are now ready to prove our main theorem. We will apply the tools developed in the previous sections to the family of cactus graphs. Let \( \mathcal{G} \) be the family of cactus graphs, and define \( \alpha = \alpha_{\mathcal{M}(\mathcal{G})} \). Let \( q = \frac{\alpha}{2w} \). First, since \( \mathcal{G} \) is closed under 1-sum, Corollary~\ref{Corollary: pload} implies that \( \mathcal{G} \) accepts a \textit{q-load} distribution and Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution} ensures that \( \mathcal{G} \) also accepts a strong \textit{q-load} distribution. In Theorem~\ref{Theorem Cactus 20/9}, we show that if \( \mathcal{G} \) accepts a \( \pload \) distribution, then \( w \cdot p \geq \frac{10}{9} \). This implies that  $w \cdot q = w \cdot \frac{\alpha}{2w} \geq \frac{10}{9}$, and hence  $\alpha \geq \frac{20}{9}$. This concludes the proof of our main theorem, i.e.~Theorem~\ref{theorem: main}.  

\begin{Theorem}\label{Theorem Cactus 20/9}
     Let $\mathcal{G}$ be the family of cactus graphs. If $\mathcal{G}$ accepts a $\pload$ distribution, then $w\cdot p \geq \frac{10}{9}$.
\end{Theorem}
\begin{proof}

Let $H$ be a cycle of length $2w$. Let $r$, $u$, $r'$, and $v$ be four vertices of the cycle in anti-clockwise order, such that $l(r,u) = l(u,r') = l(r',v) = l(v,r)=\frac{w}{2}$.  We construct $G$ from $H$ by attaching paths $u-u'$ and $v-v'$ of length $\frac{w}{2}$ from $u$ and $v$, respectively. We denote the path of length $\frac{w}{2}$ from $r$ to $u$ by $P_u$, from $u$ to $r'$ by $P_a$, from $r'$ to $v$ by $P_b$, and from $v$ to $r$ by $P_v$. We denote the path from $u$ to $u'$ by $P_c$ and the path from $v$ to $v'$ by $P_d$. See the figure below for an illustration. Note that $G \in \mathcal{G}$.


\begin{figure}[H]
    \centering
\input{Last_Lemma_the_cycle_with_2_legs_Figure}
    % \caption{Caption}
    \label{fig:enter-label}
\end{figure}
For the sake of contradiction, assume that $w\cdot p < \frac{10}{9}$. Let $k=\frac{w}{2}$, $\mathcal{F}=\mathcal{F}^{w}_{2w}(G,r)$ and $A=\mathcal{F}^{k}_{2w}(G,r)$. Since $K_2 \in \mathcal{G}$ and $\mathcal{G}$ is closed under 1-sum, we can use Theorem~\ref{Theorem: rooted (p,2w)-diameter distribution} and Theorem~\ref{Theorem: radius rooted (p,2w)-diameter distribution} to conclude that there exists $(r,p)$-load distribution $y=\{y_{F}~|~F\in \mathcal{F}^{w}_{2w}(G,r)\} $ such that, $$\sum_{F \in A} y_F = \sum_{F\in \mathcal{F}^{k}_{2w}(r)}y_{F} \geq 1-(w-k) \cdot p=1- \dfrac{w}{2}\cdot p=1-\dfrac{w \cdot p}{2}.$$ 
    Suppose that $F\in A$. Since $l(u,r)=k=\frac{w}{2}$ and $l(v,r)=k=\frac{w}{2}$, we have that $F\cap E(P_{v}) \neq \emptyset$ and $F \cap (P_{u})\neq \emptyset$. The next claim shows that under the assumption that $w \cdot p < \frac{10}{9}$, there exists $F \in A$ which does not pick any edges from $P_a, P_b, P_c,P_d$. This will lead to a contradiction, as $u'$ and $v'$ are $2w$ distance apart, and since $F$ is a $2w$-diameter decomposition, they should have been separated by $F$. This implies that $w \cdot p \geq \frac{10}{9}$ and completes the proof of the theorem. 
    \begin{Claim}
        There exists $F\in A$ such that $F\cap E(P_{a}),F\cap E(P_{b}),F\cap E(P_{c}), F\cap E(P_{d})=\emptyset$.
    \end{Claim}
    \begin{proof}

        Let $P'_{a},P'_{b}$ be the two paths between $r,r'$ containing $P_{a},P_{b}$ respectively. Also, let $P'_{u},P'_{v}$ be the unique shortest paths starting at $r$ and ending at $u',v'$, respectively. Let $A_{a}=\{F\in A~|~F \cap E(P_{a})\neq \emptyset\}$ and $F\in A_{a}$. This implies that $|F\cap E(P^{'}_{a})|\geq 2$. Since $P'_{a}$ is a shortest path with length $w$ from $r$, using Lemma~\ref{lemma:upperbound}, we have, 
        $$\sum_{F \in \mathcal{F}, |F\cap E(P^{'}_{a})| \geq 2}y_{F}\leq (w \cdot p)-1 ~\Rightarrow~\sum_{F\in A_{a}}y_{F}\leq (w \cdot p)-1.$$
         Similarly, we define, 
         $$A_{b}=\{F\in A~|~F \cap E(P_{b})\neq \emptyset \},A_{c}=\{F\in A~|~F \cap E(P_{c})\neq \emptyset\},A_{d}=\{F\in A~|~F \cap E(P_{d})\neq \emptyset\},$$ and doing the same argument for $P'_{b},P'_{u},P'_{v}$, we obtain,
         $$\sum_{F\in A_{b}}y_{F} \leq (w \cdot p)-1;~\sum_{F\in A_{c}}y_{F} \leq (w \cdot p)-1;~\sum_{F\in A_{d}}y_{F}\leq (w \cdot p)-1.$$ Let $A^{*}=A\setminus(A_{a}\cup A_{b}\cup A_{c} \cup A_{d})$. From the discussion above, it follows that,
         $$\sum_{F\in A^{*}}y_{F}=\sum_{F\in A}y_{F}-\sum_{F\in A_{a}\cup A_{b}\cup A_{c}\cup A_{d}} y_{F} \geq \left(1-\dfrac{w \cdot p}{2}\right)-4 \cdot (w \cdot p-1)=5-\dfrac{9 \cdot w \cdot p}{2}>0.$$
        This shows that $A^{*}\neq \emptyset$ and completes the proof of the claim.
    \end{proof} \end{proof}


\section{An Explicit Construction}
Inspired by the proof presented in the previous sections, we now give an explicit example on a cactus graph where the integrality gap is at least $\frac{20}{9}$. In particular, given an $\epsilon>0$, we are going to give an instance of the minimum multicut problem $M$ on a cactus graph $G$ such that, $$\frac{\text{OPT}_{IP}(M)}{\text{OPT}_{LP}(M)}\geq \frac{20}{9}-\epsilon.$$ 
We will construct the graph $G$ by using two $1-sum$ operations. Let $H$ be the following graph,

