\section{Proof of Theorem~\ref{Theorem: the existence of uniform random distribution}}

\begin{proof} \label{proof: multicut_sdd_equiv}
Suppose the statement does not hold. Then the following linear system is infeasible.
\begin{align*}
    \sum_{F\in \mathcal{F}}y_{F}&=1\\ 
    \sum_{F\in \mathcal{F},e\in F}y_{F}&\leq \alpha \cdot x(e)\quad\quad \forall e\in E(G)\\
    y_{F}&\geq 0
\end{align*}
This implies that the following system is infeasible as well. The reason is that if the system below is feasible, then we can scale down the feasible solution appropriately and obtain a feasible solution for the system above. 

\begin{align}
\sum_{F\in \mathcal{F}}y_{F}&\geq 1 \label{eq: sum yf>=1} \\
\sum_{F\in \mathcal{F},e\in F}y_{F}&\leq \alpha \cdot x(e)\quad\quad \forall e \in E(G)\\
y_{F}&\geq 0
\end{align}


By reversing the inequality \ref{eq: sum yf>=1}, we obtain that the following system is also infeasible,
\begin{align*}
    \sum_{F\in \mathcal{F}}-y_{F}&\leq -1 \\
    \sum_{F\in \mathcal{F},e\in F}y_{F}&\leq \alpha \cdot x(e)\quad\quad \forall e \in E(G)\\
    y_{F}&\geq 0
\end{align*}
Now, we use the following variant of Farkas Lemma (see~\cite{SchrijverFarkasLemma} for a proof).
\begin{Lemma}\label{Farkas Lemma}
    $\{x\in \mathbb{R}^{n}|Ax\leq b,x\geq 0\}=\emptyset$ iff there exists a vector $u$ such that $A^{T} u \geq 0,u \geq 0$ and $b^{T} u <0$. 
\end{Lemma}

\noindent For a feasible multicut $F$, let $\chi_F \in \{0,1\}^E$ denote its indicator vector. By Lemma~\ref{Farkas Lemma}, there exists $u\geq 0$ and $c \geq 0$ such that $c^{T}\chi_{F}-u\geq 0$ for all $F\in \mathcal{F}$ and $-u + \alpha \cdot c^{T} x<0$. This means that $c^{T}\chi_{F}\geq u$ for all $F\in \mathcal{F}$, and $\alpha \cdot c^{T}x < u$. Thus, $c^{T}\chi_{F}\geq u>\alpha \cdot c^{T}x$ for all $F\in\mathcal{F}$. Therefore with respect to the cost function $c$, $\OPT_{LP}\leq \frac{u}{\alpha}$ and $\OPT_{IP}>u$. This implies that integrality gap of the multicut instance $M$ is $> \alpha$, a contradiction.
\end{proof}
\section{Projection of $\pload$ Distribution}\label{Appendix: Projection}
\begin{Claim}
    Let $G$ be a graph and let $x$ be a $\pload$ distribution of $G$. Let $H$ be a subgraph of $G$, and for any $F\in \mathcal{F}_{2w}(H)$, let
    $$y_{F}=\displaystyle \sum_{F':  F' \in \mathcal{F}_{2w}(G),F' \cap E(H) = F} x_{F'}.$$
    then $y$ is a $\pload$ distribution for $H$.
\end{Claim}
 \begin{proof}
     For an edge $e\in E(H)$, we have: $$\sum_{e\in F}y_{F}=\sum_{e\in F}~~\sum_{e\in F,F'\cap E(H)=F,F'\in \mathcal{F}_{2w}(G)}x_{F'}=\sum_{e\in F',F'\in \mathcal{F}_{2w}(G)}x_{F'}\leq p.$$ Finally, note that $y\geq 0$, and $y$ forms a distribution: 
$$\sum_{F\in \mathcal{F}_{2w}(H)} y_{F}=\sum_{F\in \mathcal{F}_{2w}(H)}~~ \sum_{F'\cap E(H)= F , F'\in \mathcal{F}_{2w}(G)} x_{F'}=\sum_{F'\in \mathcal{F}_{2w}(G)} x_{F'}=1.$$
 \end{proof}




