\title{Hydrodynamic bend instability of motile particles on a substrate}

%Order-disorder transition in polar flocks with nematic interaction {\em or}

\author{Sameer Kumar$^\dag$}
\affiliation{Niels Bohr Institute, University of Copenhagen, Copenhagen, Denmark}
