    \rho \partial_t \Omega ({\bm q},t)=q_m\left[ \lambda(8C +Kq^2) q_n -i (\alpha - \beta(8C+Kq^2)) \right]\delta p({\bm q}) \\
    +\left[\frac{Kq^2}{2}(\lambda(q_m^2-q_n^2)-q^2)+i q_n (\alpha -\beta K q^2)\right] \theta({\bm q}) -(\eta q^2 +f) \Omega({\bm q})   
\end{split}
\label{eq: apx3}
\end{equation}

