\title {Robin problem with measure data and singular nonlinearities on the boundary}
\author {Andrzej Rozkosz\\
{\small Faculty of Mathematics and Computer Science,
Nicolaus Copernicus University} \\
{\small  Chopina 12/18, 87--100 Toru\'n, Poland}\\
e-mail: rozkosz@mat.umk.pl}
\date{}
\maketitle
\begin{abstract}
We consider the Robin problem for a uniformly elliptic divergence operator with measure data on the right-hand side of the equation and an absorption term on the boundary involving blowing up terms.
We prove the existence of a  positive renormalized solution and provide it stochastic representation, which can be viwed as a  generalized nonlinear Feynman--Kac formula. From this representation we derive some additional regularity results for the solution and some uniqueness results.
\end{abstract}
{\small \noindent{\bf Mathematics Subject Classification (2010).} Primary 35J25; Secondary 35J65, 60H30.}
\smallskip\\	
{\bf Keywords.} Elliptic equation, nonlinear Robin problem,  measure data, nonlinear Feynman--Kac formula.


\section{Introduction}
\label{sec1}


Let $D$ be a bounded Lipschitz domain in $\BR^d$, $d\ge3$. We are interested in existence, uniqueness and regularity of positive solutions of the nonlinear Robin problem (also called Fourier problem or third boundary-value problem)
\begin{equation}
\label{eq1.1}
-L u=\mu\quad\mbox{in }D,\qquad-\frac{\partial u}{\partial{\gamma_a}}
+\beta\cdot u=h\cdot g(u)\quad \mbox{on }\partial D,
\end{equation}
where  $L$ is a uniformly elliptic divergence form operator  defined by
\begin{equation}
\label{eq1.10}
L=\sum^{d}_{i,j=1}\frac{\partial}{\partial x_i}
\Big(a_{ij}(x)\frac{\partial}{\partial x_j}\Big)
\end{equation}
for some symmetric matrix-valued function $a:\bar D\rightarrow\BR^d\otimes\BR^d$ and $\gamma_a=a\cdot\mathbf{n}(x)$, where $\mathbf{n}(x)$
is the unit inward normal vector  at $x\in \partial D$.
As for the data, we assume that  $\mu$ is a smooth measure on $D$ (with respect to the capacity associated with $L$),  %$f:D\rightarrow\BR$
$h:\partial D\rightarrow\BR$ is a Borel  measurable function such that
\begin{equation}
\label{eq1.2}
h\ge0\,\,\, \sigma\mbox{-a.e.},\quad \mu(D)+\|h\|_{L^1(\partial D;\sigma)}<\infty,\quad \mu(D)+\|h\|_{L^{1}(\partial D;\sigma)}>0,
\end{equation}
where %$m$ is the Lebesque measure and
$\sigma$ is the surface measure on $\partial D$,
and $\beta:\partial D\rightarrow\BR$ is a Borel measurable function such that
\begin{equation}
\label{eq1.3}
\beta\in L^{\infty}(\partial D;\sigma),\quad  \beta\ge0\quad\sigma\mbox{-a.e.},\quad \|\beta\|_{L^1(\partial D;\sigma)}>0.
\end{equation}
We assume that in (\ref{eq1.1}),  in the nonlinear term, $g:(0,\infty)\rightarrow[0,\infty)$  is a continuous function such that
\begin{equation}
\label{eq1.4}
c_1\le g(y)y^{\gamma}\le c_2,\quad y>0,
\end{equation}
for some constants $c_1,c_2,\gamma>0$. Therefore  $h\cdot g(u)$ forms a blowing up term.
In fact, we also deal with   mixed nonlinearities of the form $hg^1(u)+hg^2(u)$, where $g^1,g^1$ are continuous and for some constants $\gamma_1,\gamma_2>0$ satisfy
\begin{equation}
\label{eq1.7}
c_1\le g^1(y)y^{-\gamma_1}\le c_2,\quad c_1\le g^2(y)y^{-\gamma_2}\le c_2,\quad y>0.
\end{equation}

Problem of the form (\ref{eq1.1}) was  recently addressed in \cite{DOS}
for equation with $L^1$-data, i.e. when $\mu(dx)=f(x)\,dx$ for some $f\in L^1(D;dx)$.  Let us stress, however, that in \cite{DOS} the authors also consider equations with more general than $L$ operators of Leray--Lions type
and with the term $\beta\cdot u$ replaced by $\beta q(u)$ with some nonnegative nonlinear  $q$ (for instance, for $L$  given by (\ref{eq1.10}) it is allowed that $q$ is continuous  such that $q(0)=0$, $q(y)\ge y$, $y\ge0$). Robin problem with $L^1$ or measure data and different boundary conditions (with no blowing up terms) are  considered for instance in \cite{AMST,GO,Pr}. For recent results on Robin problem with homogeneous boundary data but nonlinear terms on the right-hand side of the equation (involving the gradient of the solution as well) we refer the reader to \cite{DP,GMM} and the refrences therein.

Our work is motivated by \cite{DOS} and is strongly related to this paper. It is also strongly related  to \cite{K:JFA} (and to some extent to \cite{BO}) although in \cite{K:JFA} the Robin problem is not mentioned and links between (\ref{eq1.1}) and the problem considered in \cite{K:JFA} are not self-evident at all.
Below we briefly describe our main results and approach to (\ref{eq1.1}) in the case where $L=\Delta$, i.e. when  $a$ is the $d$-dimensional identity matrix. Let  $\BD$ denote the classical Dirichlet form on $L^2(\bar D)$ defined by
\[
\BD(u,v)=\int_D\nabla u\cdot\nabla v\,dx,\quad u,v\in D(\BD):=H^1(D),
\]
and let $\BD^{\beta\cdot\sigma}$ be the form $\BD$ perturbed by the measure $\beta\cdot\sigma$, i.e.
\[
\BD^{\beta\cdot\sigma}(u,v)=\BD(u,v)+\int_{\partial D}uv\beta\,d\sigma, \qquad u,v\in D(\BD^{\beta\cdot\sigma}):=H^1(D)\cap L^2(\bar D;\beta\cdot\sigma).
\]
Both $\BD$ and $\BD^{\beta\cdot\sigma}$ are regular Dirichlet forms on $L^2(\bar D;dx)$.  The generator of $\BD$, which we denote by $\Delta_N$, may be called the  Laplace operator with Neumann boundary conditions. The generator of the perturbed form can be formally written as $\Delta_N-\beta\cdot\sigma$. As a matter of fact, in the present paper we regard (\ref{eq1.1}) as equation of he form
\begin{equation}
\label{eq1.5}
(-\Delta_N+\beta\cdot\sigma)u=\mu+hg(u)\cdot\sigma\quad\mbox{in }\bar D,
\end{equation}
i.e. a Schr\"odinger equation for $\Delta_N$ with potential $\beta\cdot\sigma$ and a nonliner term involving measures on the right-hand side. The reason is that properly defined weak solutions of (\ref{eq1.5}) are weak solutions of (\ref{eq1.1})
and vice versa, and similarly, renormalized solutions of (\ref{eq1.1}) are renormalized solutions of (\ref{eq1.5}). On the other hand, equation (\ref{eq1.5}) falls within the scope of semilinear equations with Dirichlet operators and smooth  measure data, and therefore can be effectively studied by probabilistic methods. In fact, in our proofs we apply or modify  methods used before in \cite{K:JFA,KR:NoD,KR:PA}. It is worth noting here that the transfer of (\ref{eq1.1}) to equation (\ref{eq1.5}) involving the  measure $\sigma$ is useful even in case  $\mu(dx)=f\,dx$ for some nonnegative $f$. A similar idea of transfering  the study of  a Robin problem to the study, by probabilistic methods, of
a related problem with measure data was used in \cite{RS}. Another examples of effective  applications of probabilistic methods to the study of Robin problems are found in \cite{DP,M}.

Our main result says that under the assumptions (\ref{eq1.2}), (\ref{eq1.3}) and (\ref{eq1.4}) or (\ref{eq1.7}) there exists a positive renormalized solution $u$ of (\ref{eq1.1}) such that $hg(u)\in L^1(\partial D;\sigma)$. If moreover $g$ is nondecreasing, then it is unique. We also give some regularity results for $u$. For instance, we prove that
for every $k>0$, $T_k(u):=(u\wedge k)\in H^1(D)$ and
\begin{equation}
\label{eq1.8}
\EE^{\kappa}(T_k(u),T_k(u))\le k(\mu(D)+\|hg(u)\|_{L^1(\partial D;\sigma)}).
\end{equation}
If, in addition, $\mu=0$, then $u^{(\gamma+1)/2}\in H^1(D)$ and for some constant $c(\gamma)>0$ we have
\begin{equation}
\label{eq1.9}
\EE^{\kappa}(u^{(1+\gamma)/2}, u^{(1+\gamma)/2})
\le c(\gamma)\|h\|_{L^1(\partial D;\sigma)}.
\end{equation}
As already mentioned, as compared with \cite{DOS},  the  novelty is that we consider general smooth bounded measures $\mu$ and not only $L^1$-data. For that reason we consider renormalized solutions and not entropy solutions as in \cite{DOS}. Furthermore, our approach allows us to treat in a unified way equations with  mixed nonlinerities of the form (\ref{eq1.7}).

A remarkable feature of our approach is that we find solutions of (\ref{eq1.1}) that are quasi continuous with respect to the capacity associated with  $\BD$ and satisfy quasi everywhere the integral equation
\begin{equation}
\label{eq1.6}
u(x)=\int_DG^{\beta\cdot\sigma}(x,y)\,\mu(dy)+\int_{\partial D}G^{\beta\cdot\sigma}(x,y)h(y)g(u(y))\,\sigma(dy),%=R^Af(x)+R^A(hg(u)\cdot\sigma)(x).
\quad x\in\bar D,
\end{equation}
where $G^{\beta\cdot\sigma}$ is the Green function on $\bar D$ for the operator $\Delta_N-\beta\cdot\sigma$. By using the probabilistc potential theory one can show that the above equation can be written in probabilistic terms involving the process $\BM$ associated with $\BD$ (reflected Brownian motion in $\bar D$) and additive functionals of $\BM$ in the Revuz correspondence with the measures $\mu $ and $\sigma$ (see Section \ref{sec3}). This probabilistic version of (\ref{eq1.6})  may be viewed as a nonlinear, generalized Feynman--Kac formula, which in turn provides a link between (\ref{eq1.6}) and some backward stochastic differential equations (BSDEs).  In fact we  use this link and methods from the theory of BSDEs to get (\ref{eq1.6}). Once the existence of $u$ satisfying (\ref{eq1.6}) is shown,  no further work is required. From the probabilistic counterpart of (\ref{eq1.6}) and general results proved in \cite{K:JFA,KR:JFA,KR:NoD} it follows that $u$ is a renormalized solution and  satisfies (\ref{eq1.8}), (\ref{eq1.9}). From (\ref{eq1.8}) and known results proved in \cite{BBGGPV} it also follows that $u,\nabla u$  belong to  Marcinkiewicz spaces of orders $r$ determined by $d$. As another simple application of links between (\ref{eq1.6}) and BSDEs we show that if $g$ is nonincreasing, $u_n$ is the unique renormalized solution of (\ref{eq1.1}) with $\mu_n(dx)=f_n(x)\,dx$ and $f_n\rightarrow f$ in $L^1(D)$, then $u_n\rightarrow u$ quasi everywhere, where $u$ is the renormalized solution of (\ref{eq1.1}) with $\mu(dx)=f(x)\,dx$.

In fact, the results described above hold true for the form $\BD$ replaced by the form associated with $L$. An additional work is required to show that  renormalized solutions of (\ref{eq1.1}) are weak  solutions. We are able to show this is when $a$ is smooth,  $\mu(dx)=f(x)\,dx$ with nontrivial $f$ and $f\in L^p(D)$, $h\in L^q(\partial D;\sigma)$ with suitably chosen $p,q$.


\section{Preliminaries}

In the paper, $D$ is a bounded domain in $\BR^d$, $d\ge3$, with  Lipschitz  boundary,
$\bar D=D\cup\partial D$. We denote by  $\partial$ an isolated point adjoint to $\bar D$ and we adopt the convention that every function $f$ on $\bar D$ is extended to $\bar D\cup\{\partial\}$ by setting $f(\partial)=0$.
For $E\subset \bar D$,  $\BB^+(E)$ is the set of all nonnegatve Borel measurable functions on $E$.

We denote by $m$ or $dx$  the Lebesgue measure on $D$ and by $\sigma$ the surface measure on $\partial D$. For $E\subset\bar D$, a measure $\nu$ on $E$ and  a function $f:E\rightarrow\BR$  we use occasionally the notation
\[
\langle \nu,f\rangle=\int_Ef(x)\,\nu(dx)
\]
whenever the integral is well defined.


\subsection{Dirichlet forms and perturbed Dirichlet forms}

Let $I_d$ denote the $d$-dimensional identity matrix. In the paper,   $a:\bar D\rightarrow\BR^d\otimes\BR^d$ is a measurable, symmetric matrix-valued function which for some $\Lambda\ge1$ satisfies the condition
\begin{equation}
\label{eq2.7}
\Lambda^{-1} I_d\le a(\cdot)\le \Lambda I_d
\end{equation}
in the sense of nonnegatve definite matrices.
We consider the  form
\[
\EE(u,v)=\sum^d_{i,j}\int_Da_{ij}(x)\frac{\partial u}{\partial x_i}(x)
\frac{\partial v}{\partial x_j}(x)\,dx,\quad u,v\in D(\EE):=H^1(D),
\]
and for $\lambda\ge0$ we set $\EE_{\lambda}(u,v)=\EE(u,v)+\lambda(u,v)$, where $(\cdot,\cdot)$ is the standard inner product in $L^2(D;m)$ and $H^1(D)$ is the usual Sobolev space of order 1. By the results proved in \cite{FT1, FT2} (for more general domains), $\EE$ is a regular Dirichlet form on $L^2(\bar D;m)$.

It is known (see \cite{FT1,FT2} or \cite[Example 5.2.2]{FOT} for the case $a=I_d$) that $\sigma$ is a smooth measure relative to $\EE$.
To shorten notation, for $\beta\in L^{\infty}(\partial D;\sigma)$ we let stand $\kappa$ for the measure $\beta\cdot\sigma$, i.e. $\kappa$ is  defined for Borel subsets of $\bar D$ by  $\kappa(B)=\int_{B\cap\partial D}\beta(x)\,\sigma(dx)$.
We denote  by  $(\EE^{\kappa},D(\EE^{\kappa}))$ the form perturbed by $\kappa$, that is
\[
\EE^{\kappa}(u,v)=\EE(u,v)+\int_{\partial D}uv\beta\,d\sigma, \qquad u,v\in D(\EE^{\kappa}):=H^1(D)\cap L^2(\bar D;\kappa).
\]
By \cite[Lemma 6.1.1]{FOT},  $(\EE^{\kappa},D(\EE^{\kappa}))$ is a regular Dirichlet form on $L^2(\bar D;m)$. By the classical trace theorem (see, e.g., \cite[Chapter 2, Theorem 4.2]{N}) if $u\in H^1(D)$, then $u\in L^2(\bar D;\fch_{\partial D}\cdot\sigma)$, and hence $u\in L^2(\bar D;\kappa)$ if $\beta\in L^{\infty}(\partial D;\sigma)$. Thus, for essentially bounded  nonnegative $\beta$ we have $D(\EE^{\kappa})=H^1(D)$.

Suppose that $\beta$ satisfies (\ref{eq1.3}). For $u\in H^1(D)$ set $\|u\|^2_{\kappa}=\EE^{\kappa}(u,u)$. Then
\begin{equation}
\label{eq2.1}
c_1\|u\|_{H^1(D)}\le\|u\|_{\kappa}\le c_2\|u\|_{H^1(D)}
\end{equation}
for some strictly positive constants $c_1,c_2$. For the first inequality see, e.g., \cite[Appendix I, Lemma 4.1]{G}. The second inequality follows from the trace theorem.
Notice that  the first inequality in (\ref{eq2.1}) implies that the form $\EE^{\kappa}$ is transient because for
$u\in H^1(D)$ we have
\[
\int_D|u|\,dx\le (m(D))^{1/2}\|u\|_{L^2(D;m)}\le (m(D))^{1/2}\|u\|_{H^1(D)}\le c (\EE^{\kappa}(u,u))^{1/2},
\]
i.e. condition \cite[(1.5.6)]{FOT} is satisfied with the reference function equal to 1.
A probabilistic argument showing  transience of $\EE^{\kappa}$ is given right after (\ref{eq2.6}). Moreover, (\ref{eq2.1}) implies that $(\EE^{\kappa},H^1(D))$   is the same as its extended Dirichlet space.

In the present paper, we define quasi notions (capacity, quasi continuity, exceptional sets)  as in \cite[Section 2.1]{FOT} with respect to the form $(\EE,H^1(D))$. We will say that a property of points in $\bar D$ holds quasi everywhere (q.e. in abbreviation) if it holds outside some exceptional set.

We denote by $\SM$ the set of all smooth measures on $\bar D$ relative to the form $\EE$. By \cite[Lemma 6.1.2]{FOT}, $\SM=\SM^{\kappa}$, where $\SM^{\kappa}$ denotes the set of all smooth measures on $\bar D$ relative to $\EE^{\kappa}$.

In the whole paper we assume  that $\mu$ is a Borel measure on $\bar D$ such $\mu(\bar D)=\mu(D)<\infty$ and $\mu\in\SM$. By \cite[(4.4.14)]{FOT}, the form $(\EE,H^1_0(D))$ can be considered as the part of the form $(\EE,H^1(D))$ on $D$, so  from \cite[Theorem 4.4.3(ii)]{FOT} it follows that $\mu$ is a somooth measure with respect to the capacity associated with $(\EE,H^1_0(D))$. Therefore from \cite[Theorem 2.1]{BGO} (or \cite[Example 4.1]{KR:BPAN})
%and the well known characterization of the dual space of $H^1_0(D)$
it follows that $\mu$ has the representation $\mu(dx)=f-\dyw(F)$ for some $f\in L^1(D;m)$ and $F=(F_1,\dots,F_d)$ with $F_i\in L^2(D;m)$, $i=1,\dots,d$.

A Radon measure $\nu$ on $\bar D$ is said to be of finite 0-energy integral relative to the form $\EE^{\kappa}$ ($\nu\in S^{(0),\kappa}_0$ in notation) if for some $c>0$,
\[
\langle \nu,v\rangle\le c \|v\|_{\kappa},\quad v\in D(\EE^{\kappa})\cap C(\bar D).
\]
By \cite[Lemma 2.2.3, Eq. (2.2.22)]{FOT}, $S^{(0),\kappa}_0\subset\SM^{\kappa}$.
Note also that $\sigma\in S^{(0),\kappa}_0$ because by the trace theorem and (\ref{eq2.1}),
\[
\int_{\partial D}v\,d\sigma\le C\|v\|_{L^2(\partial D;\sigma)}\le  C_1\|v\|_{H^1(D)}\le C_2\|v\|_{\kappa}.
\]

If $\nu\in S^{(0),\kappa}_0$, then by \cite[Theorem 2.2.5]{FOT}
there exists a function $U^{\kappa}\nu\in H^1(D)$, called the potential of $\nu$ (relative to $\EE^{\kappa}$), such that
\begin{equation}
\label{eq2.5}
\EE^{\kappa}(U^{\kappa}\nu,v)=\langle\nu,\tilde v\rangle,\quad v\in H^1(D),
\end{equation}
where $\tilde v$ is a quasi continuous version of $v$.

\subsection{Markov processes}

It is known (see \cite{FT1, FT2}) that there exists a conservative diffusion process $\BM=\{(X,(\FF_t)_{t\ge0},P_x),x\in\bar D\}$ on $\bar D$ associated with the Dirichlet form $\EE$. We denote by $E_x$ the expectation with respect to $P_x$. When $a=(1/2)I_d$, then $\BM$ is nothing else but  a reflecting standard Brownian motion (see \cite[Exercises 4.5.3, 5.2.2]{FOT}). Let  $p_t$ be the transition kernel of $\BM$, i.e. $p_t(x,B)=P_x(X_t\in B)$, $t>0,x\in\bar D$, $B\in\BB(\bar D)$, and  $(P_t)$ be the semigroup
associated with  $\BM$, i.e.  $P_tf(x)=\int_{\bar D}f(y)p_t(x,dy)=E_xf(X_t)$ for $f\in\BB_b(\bar D)$ and  $t>0$, $x\in\bar D$. It is  known (see \cite{FT1, FT2}) that  the semigropup $(P_t)$ is strong Feller and $p_t$ satisfies the following absolute continuity condition: $p_t(x,\cdot)\ll m$ for any $t>0$ and $x\in\bar D$.

For $\nu\in\SM$ let  $A^{\nu}$ denote the positive continuous additive functional (PCAF) of $\BM$ in the Revuz correspondence with $\nu$.
By \cite[Lemma 5.1, Theorem 5.1]{FT2},  the surface measure $\sigma$ belongs to the space of smooth measures in the strict sense (relative to $\EE$), and hence, by \cite[Theorem 5.1.7]{FOT}, there is  a unique PCAF $A^{\sigma}$ of $\BM$ in the strict sense with the Revuz measure $\sigma$.
In the paper, we denote by $A$  the PCAF of $\BM$ in the Revuz correspondence with $\kappa$, and by $B$ the PCAF of $\BM$ with the Revuz measure $\mu$,  i.e.
\[
A_t=A^{\kappa}_t=(\beta\cdot A^{\sigma})_t=\int^t_0\beta(X_s)\,dA^{\sigma}_s,\qquad B_t=A^{\mu}_t,\quad t\ge0.
\]
Let $\BM^A=\{(X^A,(\FF^A_t)_{t\ge0},P^A_x), x\in\bar D\}$ be the canonical subprocess of $\BM$  with respect to the multiplicative functional $(e^{-A_t})$ (see \cite[Theorem A.2.11]{FOT}). We denote by $\zeta^A$ its life time and by $E^A_x$ the expectation with respect to $P^A_x$.  The transition semigroup associated with $\BM^A$ has the form
\begin{equation}
\label{eq2.6}
P_t^Af(x)=E^Af(X^A_t)=E_x(e^{-A_t}f(X_t)), \quad f\in\BB_b(\bar D),\quad t>0,\,x\in\bar D.
\end{equation}
If $\beta$ satisfies (\ref{eq1.3}), then  $\kappa$ is nontrivial, which implies that for every $x\in\bar D$ there is $t>0$ such that   $P^A_t1(x)=E_xe^{-A_t}<1$. This and \cite[Lemma 1.6.5]{FOT} imply that the semigroup $(P^A_t)$ is transient, and hence, by \cite[Theorem 1.5.1]{FOT}, that $\EE^{\kappa}$ is transient %p \cite[s. 178, 182]{CF}.

We denote by $(R^A_{\alpha}f)_{\alpha>0}$ the resolvent associated with $\BM^A$ (or the semigroup $(P^A_t)$), i.e.
\[	
R^A_{\alpha}f(x)=E_x\int^{\infty}_0e^{-\alpha t}P^A_tf(x)\,dt
=E\int^{\infty}_0e^{-\alpha t-A_t}f(X_t)\,dt,\quad f\in\BB^+(\bar D),\quad x\in\bar D.
\]
%(the second equality is a consequence of our convention that $f(\partial)=0$ and the fact %that $X^A_t=\partial $ on the set $\{t\ge\zeta^A\}$.
We also set $Rf=R_0f$. By \cite[Exercise 6.1.1]{FOT}, $\BM^A$ satisfies the absolute continuity condition and hence, by \cite[Lemma 4.2.4]{FOT}, for every $\alpha>0$ there is a nonnegative jointly measurable symmetric function $G^{\kappa}_{\alpha}(x,y)$, $x,y\in\bar D$  which is $\alpha$-excessive (relative to $\BM^A$) in each variable and has the property that for any $f\in\BB^+(\bar D)$ and $x\in\bar D$,
\begin{equation}
\label{eq2.2}	
R^A_{\alpha}f(x)=G^{\kappa}_{\alpha}f(x),\quad\mbox{where}\quad
G^{\kappa}_{\alpha}f(x)=\int_{\bar D}G^{\kappa}_{\alpha}(x,y)f(y)\,dy
\end{equation}
%\begin{equation}
%\label{eq2.2}
%R^A_{\alpha}f(x)=\int_{\bar D}r^A_{\alpha}(x,y)f(y)\,dy, \quad  f\in\BB^+(\bar D),\quad %x\in\bar D.
%\end{equation}
Furthermore, $G^{\kappa}_{\alpha}(x,y)$ increases as $\alpha\downarrow0$. We set $G^{\kappa}(x,y)=\lim_{\alpha\downarrow0}G^{\kappa}_{\alpha}(x,y)$. The function  $G^{\kappa}$ is jointly measurable,  symmetric and $0$-excessive in each variable. By monotone convergence, letting $\alpha\downarrow0$ in (\ref{eq2.2}) we get %(p. tez [s. 256, BG])
\begin{equation}
\label{eq2.3}
R^Af(x)=G^{\kappa}f(x),\quad f\in\BB^+(\bar D),\quad x\in\bar D,
\end{equation}
where
\begin{equation}
\label{eq2.4}
R^Af(x)=E_x\int^{\infty}_0e^{-A_t}f(X_t)\,dt,\qquad G^{\kappa}f(x)
=\int_DG^{\kappa}(x,y)f(y)\,dy.
\end{equation}
In the terminology used in \cite{FOT},  $G^{\kappa}(x,y)$ is  called the resolvent density of  $\BM^A$ (and is denoted by $r^A(x,y)$; see \cite[Exercise 6.1.1]{FOT}).
We denote it by $G^{\kappa}(x,y)$ because in the situation considered in the present paper it is the Green function on $\bar D$ for the operator associated with $\EE^{\kappa}$.


\section{Probabilistic  and integral solutions}
\label{sec3}

In what follows we assume that $f,h, g,\beta$ are Borel measurable and nonnegative.

\subsection{Basic definitions and auxiliary results}
\begin{definition}
%P. \cite[p. 937]{K:JFA}, ale stosujemy do procesu z forma zaburzona).
A function $u$ defined q.e. on $\bar D$ is a probabilistic solution of (\ref{eq1.1}) if $u$ is quasi continuous, $u>0$ q.e. in $\bar D$ and for q.e. $x\in\bar D$,
\begin{equation}
\label{eq3.2}
u(x)=E^A_x\int^{\infty}_0dB_t
+E^A_x\int^{\infty}_0h(X^A_t)g(u(X^A_t))\,dA^{\sigma}_t.
\end{equation}
\end{definition}

\begin{remark}
\label{rem3.2}
(i) Since every quasi continuous function is finite q.e. (this follows for instance from
\cite[Theorem 2.1.2]{FOT}),  (\ref{eq3.2}) means in particular that both integrals on the right-hand side  are finite for q.e. $x\in \bar D$.
\smallskip\\
(ii) $B$ can be regarded as a PCAF of $\BM^A$ with the Revuz measure $\mu$ again (see \cite[Theorem (2.22)]{FG} and also \cite[p. 331]{FOT}).
In particular, $B_t=B_{t\wedge\zeta^A}$, $t\ge0$, $P_x$-a.s. for q.e. $x\in\bar D$. Similarly, if $\nu=\mu+h\cdot\sigma$, then $A^{\nu}$ can be regarded as a PCAF of $\BM^A$ with the Revuz measure $\nu$.
\smallskip\\
(iii) Let $\nu=\mu+\sigma$, $\psi(x,y)=\fch_{D}(x)+\fch_{\partial D}h(x)g(y)$. Then (\ref{eq3.2}) can be written in the form
\[
u(x)=E^A_x\int^{\infty}_0\psi(X^A_t,u(X^A_t))\,dA^{\nu}_t
=E^A_x\int^{\zeta^A}_0\psi(X^A_t,u(X^A_t))\,dA^{\nu}_t.
\]
\end{remark}

\begin{definition}
A function $u$ defined q.e. on $\bar D$ is an integral solution of (\ref{eq1.1}) if $u$ is quasi continuous, $u>0$ q.e. in $\bar D$ and (\ref{eq1.6}) is satisfied for q.e. $x\in\bar D$.
\end{definition}

We shall see that probabilistic solutions are integral solutions in the sense that (\ref{eq1.6}) is satisfied. To see this we need a  result extending (\ref{eq2.3}). To state it, for  $\nu\in\SM$  we set
\[
G^{\kappa}\nu(x)=\int_{\bar D}G^{\kappa}(x,y)\,\,\nu(dy),\quad x\in\bar D.
\]
This notation is in agreement with our previous notation (\ref{eq2.4}).
\begin{lemma}
\label{lem3.5}
If $\nu\in S^{(0),\kappa}_0$, then  $G^{\kappa}\nu$ is an $m$-version of the potential $U^{\kappa}\nu$.
\end{lemma}
\begin{proof}
The measure $\nu$ is of finite energy (relative to $\EE^\kappa$) in the sense defined in \cite[Section 2.2]{FOT}. For $\alpha>0$ let $U^{\kappa}_{\alpha}\nu$ denote its $\alpha$-potential. By \cite[Exercise 4.2.2]{FOT} applied to the form $\EE^{\kappa}$, for every $\alpha>0$ the function $G^{\kappa}_{\alpha}\nu$ is an $m$-version of the potential $U^{\kappa}_{\alpha}\nu$.
By monotone convergence, $G^{\kappa}_{\alpha}\nu\rightarrow G^{\kappa}\nu$ pointwise  and by \cite[Lemma 2.2.11]{FOT}, $\|U^{\kappa}_{\alpha}\nu-U^{\kappa}\nu\|_{\kappa}\rightarrow0$  as $\alpha\downarrow0$, which gives the desired result.
\end{proof}

\begin{lemma}
\label{lem3.6}
Let $\nu\in\SM$. Then $E^A_xA^{\nu}_{\infty}=G^{\kappa}\nu(x)$ for q.e. $x\in\bar D$. If, in addition, $\nu(\bar D)<\infty$, then $G^{\kappa}\nu(x)<\infty$ for q.e. $x\in\bar D$.
\end{lemma}
\begin{proof}
%Korzystamy z rozumowania  w dowodzie \cite[Lemma 6.1.1]{CF}.
By the 0-order version of \cite[Theorem 2.2.4]{FOT}, there exists an $\EE^{\kappa}$-nest $\{F_k\}$ such that $\nu_k:=\fch_{F_k}\nu\in S^{(0),\kappa}_0$ for every $k\ge1$. From the proof of \cite[Lemma 6.1.1]{CF} (applied to $\EE^{\kappa}$) it follows that for each $k\ge1$ the function $x\mapsto E^A_xA^{\nu_k}$ is a quasi continuous version of $U^{\kappa}\nu_k$. By this and Lemma \ref{lem3.5},  $E^A_xA^{\nu_k}=G^{\kappa}\nu_k$, $k\ge1$ for q.e. $x\in\bar D$. Letting $k\rightarrow\infty$ shows the first assertion.
Since $\EE^{\kappa}$ is transient, the second assertion follows from the first  one and \cite[Lemma 4.3, Proposition 5.13]{KR:JFA}.
\end{proof}

\begin{proposition}
\label{prop3.3}	
A function $u$ is a probabilistic solution of \mbox{\rm(\ref{eq1.1})} if and only if it is an integral solution of \mbox{\rm(\ref{eq1.1})}.
\end{proposition}
\begin{proof}
Let $\varphi\in\BB^+(\bar D)$. Then for q.e. $x\in\bar D$ we have
\begin{equation}
\label{eq3.14}
E^A_xB_{\infty}=G^{\kappa}\mu(x),\qquad E^A_x\int^{\infty}_0\varphi(X^A_t)\,dA^{\sigma}_t
=G^{\kappa}(\varphi\cdot\sigma)(x).
\end{equation}
Indeed, the first equality follows from Lemma \ref{lem3.6} applied to $\nu:=\mu$. To get  the second one we apply Lemma \ref{lem3.6}  to $\nu_n=(\varphi\wedge n)\cdot\sigma$ and then pass to the limit as $n\rightarrow\infty$. Clearly (\ref{eq3.14}) implies the desired result.
\end{proof}

