Probabilistic solutions of (\ref{eq1.1}) are closely related to the backward stochastic differential equations (BSDEs) of the form
\begin{align}
\label{eq3.4}
Y^x_t&=Y^x_{T\wedge\zeta^A}+\int^{T\wedge\zeta^A}_{t\wedge\zeta^A}dB_s\nonumber\\
&\quad+\int^{T\wedge\zeta^A}_{t\wedge\zeta^A}h(X^A_s)g(Y^x_s)\,dA^{\sigma}_s
-\int^{T\wedge\zeta^A}_{t\wedge\zeta^A}dM^x_s,\quad t\in[0,T].
\end{align}

We say that a c\`adl\`ag $(\FF^A_t)$-adapted process $Y$ is of class D under $P^A_x$ if
the collection $\{Y_{\tau}:\tau\mbox{ is a finite $(\FF^A_t)$-stopping time}\}$   is uniformly integrable under $P^A_x$.

\begin{definition}
Let $x\in\bar D$. We say that a pair $(Y^x,M^x)$ is a solution of (\ref{eq3.4}) if
\begin{enumerate}[(a)]
\item $Y^x$ is an $(\FF^A_t)$-progressively measurable c\`adl\`ag process, $Y^x$ is of class D under $P^A_x$ and $M^x$ is a c\`adl\`ag $(\FF_t)$-local martingale under $P^A_x$;

\item $E^A_x\int^{T\wedge\zeta^A}_0dB_s
+E^A_x\int^{T\wedge\zeta^A}_0h(X^A_t)g(Y^x_t)\,dA^{\sigma}_t<\infty$ $P^A_x$-a.s. for every $T>0$;

\item $Y^x_{T\wedge\zeta^A}\rightarrow0$ $P^A_x$-a.s. as $T\rightarrow\infty$ and for every $T>$ equation (\ref{eq3.4}) is satisfied $P^A_x$-a.s.
\end{enumerate}
\end{definition}

