\subsection{Existence and uniqueness results}

In what follows we first prove the existence of probabilistic  solutions of (\ref{eq1.1}) for continuous nonincreasing $g$ satisfying (\ref{eq1.4}) and then for  general continuous $g$ satisfying (\ref{eq1.4}). In the first case the solution is unique. This follows from the following comparison result.


\begin{proposition}
\label{prop3.11}
Let $\mu_1,\mu_2$ be smooth measures on $D$ and $h_1,h_2:\partial D\rightarrow\BR$, $g_1,g_2:(0,\infty)\rightarrow\BR$ be nonnegative Borel measurable functions. Assume that  $\mu_1\le\mu_2$, $h_1\le h_2$,  $g_1(y)\le g_2(y)$ for $y>0$ and either $g_1$ or $g_2$ is nonincreasing. Assume also that for  $i=1,2$ there exists a probabilistic solution $u_i$ of \mbox{\rm(\ref{eq1.1})} with $\mu,h,g$ replaced by $\mu_i,h_i,g_i$, respectively.  Then $u_1\le u_2$ q.e. in $\bar D$.
\end{proposition}
\begin{proof}
%P. \cite[Proposition 3.2]{K:JFA}.
Suppose that $g_2$ is nonincreasing. By Proposition \ref{prop3.7}, there exist processes $M^1,M^2$ such that for q.e. $x\in\bar D$ they are martingales under $P^A_x$ and for $i=1,2$ the pair
$(Y^i=u_i(X^A),M^i)$ is a solution of (\ref{eq3.4}) with $\mu,h,g$ replaced by $\mu_i,h_i,g_i$. Hence
\[
Y^i_t=Y^i_0-B^i_t-\int^{t}_0h_i(X^A_s)g_i(Y^i_s)\,dA^{\sigma}_s
+\int^t_0dM^i_s,\quad t\ge0,
\]
for $i=1,2$. By the  It\^o--Tanaka formula (see, e.g., \cite[Theorem IV.68]{P}),
\[
(Y^1_t-Y^2_t)^+-(Y^1_0-Y^2_0)^+\ge\int^t_0\fch_{\{Y^1_s-Y^2_s>0\}}\,d(Y^1_s-Y^2_s),\quad t\ge0.
\]
Since $B^1_t-B^2_t=A^{\mu_1-\mu_2}_t\le0$, $t\ge0$, it follows from the above inequality that for q.e. $x\in\bar D$,
\begin{equation}
\label{eq3.10}
(u_1-u_2)^+(x)\le E^A_x\int^{\infty}_0\fch_{\{u_1-u_2>0\}}(X^A_s)
(h_1g_1(u_1)-h_2g_2(u_2))(X^A_s)\,dA^{\sigma}_s.
\end{equation}
%\begin{align*}
%(u_1-u_2)^+(x)&\le E_x\int^{\zeta^A}_0\fch_{\{u_1-u_2>0\}}(X^A_s)
%(h_1g_1(u_1)-h_2g_2(u_2))(X^A_s)\,dA^{\sigma}_s\\
%&= E_x\int^{\zeta^A}_0\fch_{\{u_1-u_2>0\}}(X^A_s)
%(h_1g_1(u_1)-h_2g_2(u_1))(X^A_s)\,dA^{\sigma}_s\\
%&\quad+ E_x\int^{\zeta^A}_0\fch_{\{u_1-u_2>0\}}(X^A_s)
%(h_2g_2(u_1)-h_2g_2(u_2))(X^A_s)\,dA^{\sigma}_s.
%\end{align*}
Since $h_1g_1(u_1)-h_2g_2(u_2)=(h_1g_1(u_1)-h_1g_1(u_1))+(h_1g_2(u_1)-h_2g_2(u_2))\le0$ if $u_1>u_2$, the righ-hand side of (\ref{eq3.10}) is nonpositive. Hence  $(u_1-u_2)^+=0$ q.e. which implies that $u_1\le u_2$ q.e. A similar argument applies in case $g_1$ is nonincreasing.
%Since $h_1g_1\le h_2g_2$ and $g_2$ is nonincreasing, both integrals on  the righ-hand side %of the above inequality are nonpositive. Hence  $(u_1-u_2)^+=0$ q.e. which implies that %$u_1\le u_1$ q.e.  Drugi przypadek: uzywamy rozkladu
%\[
%h_1g_1(u_1)-h_2g_2(u_2)=(h_1g_1(u_1)-h_1g_1(u_2))+(h_1g_1(u_2)-h_2g_2(u_2))
%\]
\end{proof}

For $k>0$ we define the  truncation operator by
\[
T_k(s)=\max(-k,\min(s,k)),\quad s\in\BR.
\]

\begin{theorem}
\label{th3.4}
Assume that \mbox{\rm(\ref{eq1.2})--(\ref{eq1.4})} are satisfied, and moreover $g$ is continuous and nonincreasing.  Then there exists a unique probabilistic  solution $u$ of \mbox{\rm(\ref{eq1.1})}.
\end{theorem}
\begin{proof}
%(p. dowod \cite[Theorem 3.9]{K:JFA}).
Uniqueness follows from Proposition \ref{prop3.11}. To prove the existence of a solution,
for $n\ge1$ we define  $g_n:\BR\rightarrow[0,\infty)$ by $g_n(y)=g(y+1/n)$ if $y>0$ and $g_n(y)=g(1/n)$ if $y\le0$.  Clearly $g_n$ is nonincreasing, continuous and bounded.
By \cite[Theorem 4.3]{KR:PA} and Remark \ref{rem3.2}(iii), there exists a quasi continuous function $u_n$ and a c\`adl\`ag $(\FF^A_t)$ -adapted process $M^n$ such that $M^n$ is a   uniformly integrable martingale under $P^A_x$ for q.e. $x\in \bar D$ and   the pair $(Y^n,M^n)$ with $Y^n=u_n(X^A)$ is the unique solution of the BSDE
\begin{equation}
\label{eq3.12}
Y^n_t=\int^{\infty}_tdB_s+\int^{\infty}_th(X^A_s)g_n(Y^n_s)\,dA^{\sigma}_s
-\int^{\infty}_tdM^n_s,\quad t\ge0.
\end{equation}
Taking $t=0$ and intergrating with respect to $P^A_x$ shows that for q.e. $x\in\bar D$ we have
\begin{equation}
\label{eq3.1}
u_n(x)=E^A_xB_{\infty}+E^A_x\int^{\infty}_0h(X^A_t)g_n(u_n(X^A_t))\,dA^{\sigma}_t.
\end{equation}
Clearly $u_n\ge0$. From (\ref{eq1.2}) it follows that in fact $u_n>0$ q.e. for all sufficiently large $n\ge1$. Indeed, if  $\mu(D)>0$, then by Lemmas \ref{lem3.6} and \ref{lem3.4} we have
$E^A_xB_{\infty}=G^{\kappa}\mu(x)>0$ for q.e. $x\in \bar D$.
Suppose now that
$\|h\|_{L^1(\partial D;\sigma)}>0$. Let $g^1_n(y)=c_1(y+1/n)^{-\gamma}$ if  $y>0$ and $g^1_n(y)=c_1(1/n)^{-\gamma}$ if $y\le0$. Since $g^1$ satisfies the same assumptions as $g$, there is a quasi continuous function $u^1_n$ such that $u^1_n$ satisfies (\ref{eq3.1}) with $g_n$ replaced by $g^1_n$. By Proposition \ref{prop3.11}, $u_n\ge u^1_n$ q.e. On the other hand,
\[
u^1_n(x)\ge E_x\int^{\infty}_0h(X^A_t)g^1_n(u^1_n(X^A_t))\,dA^{\sigma}_t
%&= c_1 E_x\int^{\infty}_0h(X^A_t)(u^1_n(X^A_t)+1/n)^{-\gamma}\,dA^{\sigma}_t\\
=E_x\int^{\infty}_0\varphi(X^A_t)\,dA^{\sigma}_t
\]
with $\varphi(x)=c_1h(x)(u^1_n(x)+1/n)^{-\gamma}$. By (\ref{eq3.14}) and Lemma \ref{lem3.4},
$u^1_n(x)\ge G^{\kappa}(\varphi\cdot\sigma)(x)>0$
for q.e. $x\in\bar D$.
Since  $h\ge0$ and  $g_{n}\le g_{n+1}$, it follows from  Proposition \ref{prop3.11} that $u_n\le u_{n+1}$, $n\ge1$, q.e. Set $u=\limsup_{n\rightarrow\infty}u_n$. By what has already been proved,  $u\ge u^1_n>0$ q.e.
Define $w(x)=E^A_xB_{\infty}$ and  $Z^n_t=Y^n_t-\int^{\infty}_tdB_s$. Clearly $u_n\ge w$.
By  It\^o's formula,
\begin{align*}
(Z^n_t)^{\gamma+1}-(Z^n_0)^{\gamma+1}&=(\gamma+1)\int^t_0(Z^n_s)^{\gamma}\,dZ^n_s
+\frac12(\gamma+1)\gamma\int^t_0(Z^{n}_s)^{\gamma-1}\,d[Z^n]_s\\
&\ge-(\gamma+1)\int^t_0(Z^n_s)^{\gamma}h(X^A_s)g_n(Y^n_s)\,dA^{\sigma}_s  +(\gamma+1)\int^t_0(Z^n_s)^{\gamma}\,dM^n_s.
\end{align*}
Let $(\tau_k)$ be a localizing sequence for the local martingale $t\mapsto\int^t_0(Z^n_s)^{\gamma}\,dM^n_s$. By the above inequality we have
\begin{equation}
\label{eq3.20}
E(Z^n_0)^{\gamma+1}\le E(Z^n_{t\wedge\tau_k})^{\gamma+1}
+(\gamma+1)E\int^{t\wedge\tau_k}_0(Z^n_s)^{\gamma}h(X^A_s)g_n(Y^n_s)\,dA^{\sigma}_s.
\end{equation}
By (\ref{eq1.4}), $g_n(y)y^{\gamma}=g(y+1/n)y^{\gamma}\le g(y+1/n)(y+1/n)^{\gamma}\le c_2$. Therefore
letting $k\rightarrow\infty$ and then $t\rightarrow\infty$ in (\ref{eq3.20}) and using fact that  $E_x(Z^n_t)^{\gamma+1}\rightarrow0$ we get
\begin{align}
\label{eq3.19}
(u_n-w)^{\gamma+1}(x)&\le (\gamma+1)E^A_x\int^{\zeta^A}_0(u_n-w)(X^A_s))^{\gamma}
h(X^A_s)g_n(u_n(X^A_s))\,dA^{\sigma}_s\nonumber\\
	&\le c_2(\gamma+1)E^A_x\int^{\zeta^A}_0h(X^A_s)\,dA^{\sigma}_s.
\end{align}
Since  $\mu(D)<\infty$,  $w=G^{\kappa}\mu<\infty$ q.e. in $\bar D$ by Lemma \ref{lem3.6}. Therefore from (\ref{eq3.19}) it follows that
$\sup_{n\ge1}u^{\gamma+1}_n(x)< \infty$ for q.e. $x\in\bar D$.
Let $F_k=\{u_1\ge1/k\}$ and $\tau_k=\inf\{t>0: X^A_t\notin F_k\}$.
From (\ref{eq3.1}), by  using the strong Markov property and the fact that $B,A^{\sigma}$ are additive functionals of $\BM^A$, we get
%p. tekst zakomentowany w dowodzie Theorem \ref[th3.6}.
\[
u_n(x)=E^A_xu_n(X^A_{\tau_k})+E^A_xB_{\tau_k}+E^A_x\int^{\tau_k}_0
h(X^A_t)g_n(u_n(X^A_t))\,dA^{\sigma}_t
\]
for all $n,k\ge1$. For every $x\in F_k$,
\[
g(u_n(x)+1/n)\le g(u_1(x)+1/n)\le c_2u_1^{-\gamma}(x)\le c_2k^{-\gamma},
\]
so letting $n\rightarrow\infty$ and applying the dominated convergence theorem we obtain
\[
E^A_x\int^{\tau_k}_0
h(X^A_t)g_n(u_n(X^A_t))\,dA^{\sigma}_t
\rightarrow E^A_x\int^{\tau_k}_0
h(X^A_t)g(u(X^A_t))\,dA^{\sigma}_t.
\]
%K:\\
%Poniewaz $u_n\rightarrow u$ q.e., to istnieje zbior exceptional i borelowski $N$ taki, ze %$u_n(y)\rightarrow y(y)$ dla $y\in E\setminus N$. Z drugiej strony $P_x(\sigma_N<\infty)=0$, wiec %$X_t\notin N$. Dlatego $u_n(X^A_t)\rightarrow u(X^A_t)$ punktowo dla kazdego $t$.\\
%KK\\
Hence, for each $k\ge1$,
\begin{equation}
\label{eq3.6}
u(x)=E^A_xu(X^A_{\tau_k})+E^A_xB_{\tau_k}+E^A_x\int^{\tau_k}_0
h(X^A_t)g(u(X^A_t))\,dA^{\sigma}_t.
\end{equation}
From the definition of $\tau_k$ it follows that $u_1(X^A_{\tau_k})\le1/k$
%\\
%K:\\Ustalmy $\omega$ i $k$. Z definicji kresu, istnieja $t_n$ takie, ze %$t_n\downarrow\tau_k
%$ oraz $u_1(X^A_{t_n})<(1/k)$. Poniewaz $u_1$ jest quasi ciagla, to %$u_1(X^A_{t_n})\rightarrow u_1(X^A_{\tau_k})$, a wiec $u_1(X^A_{\tau_k})\le(1/k)$. %\\
%KK\\
and $\tau_k\nearrow\tau$ as $k\rightarrow\infty$ for some stopping time $\tau$. Furthermore, since $u_1$ is quasi continuous, we  have
\begin{equation}
\label{eq3.9}
P^A_x(0=\lim_{k\rightarrow\infty}u_1(X^A_{\tau_k})=u_1(X^A_{\tau}),\tau<\zeta^A)
=P^A_x(\tau<\zeta^A)
\end{equation}
for q.e. $x\in\bar D$.
%(korzystamy z ciaglosci trajektorii albo w ogolnosci z quasilewostronnej ciaglosci.
We know that  $u_1>0$ q.e. Let $N\subset\bar D$ be a Borel $\EE^{\kappa}$-exceptional set such that $u_1>0$ on  $\bar D\setminus N$ and let $\sigma_N=\inf\{t>0:X^A_t\in N\}$.
Since $\mbox{Cap}^{\kappa}(N)=0$, where $\mbox{Cap}^{\kappa}$ is the capacity associated with $\EE^{\kappa}$,  there is a decreasing sequence of relatively compact open sets $(U_n)$ such that $N\subset\bigcap_{n\ge1}U_n$ and $\mbox{Cap}^{\kappa}(U_n)\downarrow0$. By \cite[Theorem 4.2.1]{FOT}, $P_x(\lim_{n\rightarrow\infty}\sigma_{U_n}=\infty)=1$ for  q.e. $x\in\bar D$, so $P_x(\sigma_N=\infty)=1$. % bo $\sigma_N\ge\sigma_{A_n}$.
Hence $P^A_x(\sigma_N<\zeta^A)=0$ for q.e. $x\in\bar D$.
%Uwaga. Mozna tez powolac sie bezposrednio na \cite[Proposition IV.5.30]{MR},
On the other hand, by (\ref{eq3.9}) and the definition of $N$, for
$x\in\bar D$  we have
\[
P^A_x(\tau<\zeta^A)%=P^A_x(u_1(X^A_{\tau})=0,\tau<\zeta^A)
=P^A_x(X^A_{\tau}\in N,\tau<\zeta^A)=P^A_x(\sigma_N\le\tau,\tau<\zeta^A),
\]
%\\
%K:\\
%Z (\ref{eq3.9}) wynika, ze $P_x(u_1(X^A_{\tau})=0,\tau<\zeta^A)=P_x(\tau<\zeta^A)$.
%Ale $u_1(X^A_{\tau})=0$ oznacza, ze  $X^A_{\tau}\in\bigcap_{k\ge1}F^c_k\subset N$. %\\
%KK\\
so $P^A_x(\tau<\zeta^A)=0$ for q.e. $x\in\bar D$. Consequently,
$P^A_x(\lim_{k\rightarrow\infty}\tau_k\ge\zeta^A)=1$ for q.e. $x\in\bar D$.
We next show that $Y:=u(X^A)$ is of class D. Indeed, by the strong Markov property,
%p. tekst zakomentowany w dowodzie \ref{th3.6}
for a finite $(\FF^A_t)$-stopping time $\sigma$ we have $w(X^A_{\sigma})=E^A_x(B_{\infty}\circ\theta_{\sigma}|\FF^A_{\sigma})=
E^A_x(B_{\infty}-B_{\sigma}|\FF^A_{\sigma})\le E^A_x(B_{\infty}|\FF^A_{\sigma})$, which together with the fact that $w<\infty$ q.e. in $\bar D$ implies that for q.e. $x\in\bar D$ the process $w(X^A)$ is of class D under $P^A_x$. Using (\ref{eq3.19}) and the strong Markov property we also show that
\[
|(u-w)(X^A_{\sigma})|^{\gamma+1}\le c_2(\gamma+1)E^A_x\Big(\int^{\zeta^A}_0h(X^A_s)\,dA^{\sigma}_s|\FF^A_{\sigma}\Big).
\]
Hence  $\sup_{\sigma}E^A_x|u(X^A_{\sigma})|^{\gamma+1}<\infty$, which implies that
the process $(u-w)(X^A)$ is of class D under $P^A_x$.
Consequently, for q.e. $x\in\bar D$, the process $u(X^A)$ is of class D under $P^A_x$. As a result,   $E^A_xu(X^A_{\tau_k})\rightarrow0$  for q.e. $x\in\bar D$ since $u(X^A_{\tau_k})\rightarrow0$ $P_x$-a.s.
Therefore letting $k\rightarrow\infty$ in (\ref{eq3.6}) shows that  $u$ satisfies (\ref{eq3.2}), so  $u$ is a probabilistic solution of (\ref{eq1.1}).
\end{proof}

We now turn to (\ref{eq1.1}) with general continuous $g$ satisfying (\ref{eq1.4}). It is convenient to consider first the problem  with bounded $h$ and then the general case.

\begin{proposition}
\label{prop3.5}
Assume that  $\mu$ satisfies \mbox{\rm(\ref{eq1.2})}, $h$ is   bounded, $g$ is continuous and bounded. Then there exists   a probabilistic solution of  \mbox{\rm(\ref{eq1.1})}.
\end{proposition}
\begin{proof}
%\cite[Proposition 3.7]{K:JFA}? P. tez \cite[Lemma 3.7]{DOS}.
Our proof is a modification of the proof of \cite[Proposition 3.7]{K:JFA}. By \cite[Lemma 6.1.2]{FOT}, the measure  $\sigma$ is smooth relative to $\EE^{\kappa}$. Since this form is transient, by the 0-order version of \cite[Theorem 2.2.4]{FOT} (see the remarks following \cite[Corollary 2.2.2]{FOT}) there exists a nest $(F_k)$ in $\bar D$ such
%an  increasing sequence  $(F_k)$ of closed subsets of $\bar D$
such that $\mu_k=\fch_{F_k}\cdot\mu$, $\sigma_k:=\fch_{F_k}\cdot\sigma\in S^{(0),\kappa}_0$ and $\|U^{\kappa}\mu_k\|_{\infty}+\|U^{\kappa}\sigma_k\|_{\infty}<\infty$  for each $k$.
%and  $\sigma(\bar D\setminus\bigcup_{k\ge1}F_k)=0$.
By Lemma \ref{lem3.5}, $\|G^{\kappa}\mu_k\|_{\infty}+\|G^{\kappa}\sigma_k\|_{\infty}<\infty$, $k\ge1$. We will show that there exists $u_k$ such that for q.e. $x\in\bar D$ we have
\begin{equation}
\label{eq3.16}
u_k(x)=G^{\kappa}\mu_k(x)+G^{\kappa}(hg(u_k)\cdot\sigma_k)(x).
\end{equation}
To this end, we define $\Phi:H^1(D)\rightarrow H^1(D)$ by $\Phi(u)=G^{\kappa}\mu_k+G^{\kappa}(h(g(u)\cdot\sigma_k))$. Then $\|\Phi(u)\|_{\infty}\le\|G^{\kappa}\mu_k\|_{\infty}
+\|h\|_{\infty}\|g\|_{\infty}\|G^{\kappa}\sigma_k\|_{\infty}:=M$. Consider the subset $K$ of $H^1(D)$ defined by $K=\{u\in H^1(D):\|u\|_{\infty}\le M\}$. It is closed,  convex and
$\Phi:K\rightarrow K$. Since the usual norm in $H^1(D)$ is equivalent to the norm $\|\cdot\|_{\kappa}$, in much the same way as in the proof of \cite[Proposition 3.7]{K:JFA} (we apply the arguments to $\EE^{\kappa}$) we show that $\Phi$ is continuous
and that for any sequence in $\Phi(K)$  there is a subsequence converging in $H^1(D)$, i.e. $\Phi(K)$ is relatively compact in $H^1(D)$. Therefore we can apply Schauder's fixed point theorem to get a fixed point $u_k$ of $\Phi$, which is a solution of (\ref{eq3.16}).
By  (\ref{eq2.4}) and (\ref{eq3.14}),  for q.e. $x\in\bar D$,
\begin{equation}
\label{eq3.11}
u_k(x)=E^A\int^{\infty}_0\fch_{F_k}(X^A_t)\,dB_t
%+E_x\int^{\infty}_0e^{-A_t}g(u_k(X_t))\fch_{F_k}(X_t)\,dA^{\sigma}_t.
+E^A_x\int^{\infty}_0g(u_k(X^A_t))\fch_{F_k}(X^A_t)\,dA^{\sigma}_t.
\end{equation}
Since $\{F_k\}$ is a nest, $\fch_{F_k}(X^A_t)\rightarrow1$, $t\in[0,\zeta^A)$, $P_x$-a.s. for q.e $x\in \bar D$. Furthermore, by the argument at the and of the proof of \cite[Proposition 3.7]{K:JFA}, there is a subsequence, still denoted by $(u_k)$, such that $(u_k)$ converges q.e. to some $u$. Letting $k\rightarrow\infty$ in (\ref{eq3.11}) and
using the Lebesgue dominated convergence theorem shows that $u$ is an integral solution of (\ref{eq1.1}) and hence a probabilistic solution by Proposition \ref{prop3.3}.
\end{proof}

\begin{theorem}
\label{th3.6}
Assume that \mbox{\rm(\ref{eq1.2})--(\ref{eq1.4})} are satisfied and $g$ is continuous. Then there exists a probabilistic solution $u$ of \mbox{\rm(\ref{eq1.1})} such that $hg(u)\in L^1(\partial D;\sigma)$.
\end{theorem}
\begin{proof}
%(p. dowod \cite[Theorem 3.10]{K:JFA}).
Define $h_n=T_n(h)$ and $g_n$ as in the proof of Theorem \ref{th3.4}. By Proposition \ref{prop3.5}, for every $n\ge1$ there exists a solution $u_n$	of the problem
\begin{equation}
\label{eq3.5}
-\Delta u_n=\mu\quad\mbox{in }D,\qquad-\frac{\partial u_n}{\partial{\mathbf{n}}}
+\beta\cdot u_n=h_n(x)g_n(u_n)\quad \mbox{on }\partial D.
\end{equation}
Let
$g^1(y)=c_1y^{-\gamma}$, $g^2=c_2y^{-\gamma}$, $y>0$ and
$g^1_n(y)=g^1(y+1/n)$, $g^2_n(y)=g^2(y+1/n)$, $y>0$. By Proposition \ref{prop3.5} and Theorem \ref{th3.4}, there exists  a unique probabilistic solution $u^1_n$ of (\ref{eq3.5}) with $g_n$ replaced by $g^1_n$, and similarly, there exists  a unique solution $u^2_n$ of (\ref{eq3.5}) with $g_n$ replaced by $g^2_n$. Furthermore, since $\mu(D)+\|h_n\|_{L^1(\partial D;\sigma)}>0$ for all sufficiently large $n$, we have $u^1_n>0$, $u^2_n>0$ q.e. for all suficiently large $n$. By  Proposition \ref{prop3.11} we also have $u^1_n\le u_n\le u^2_n$, $n\ge1$, q.e.
It follows in particular that
\begin{equation}
\label{eq3.7}
g(u_n+1/n)\le c_2(u_n+1/n)^{-\gamma}\le (c_2/c_1)g^1_n(u^1_n),\quad n\ge1,\quad\mbox{q.e.}
\end{equation}
Let $u^1,u^2$ be the unique probabilistic solutions of problems (\ref{eq1.1}) with $g$ replaced by $g^1$ and $g$ replaced by $g^2$, respectively.
%They exist and are unique by Theorem \ref{th3.4} and Proposition \ref{prop3.11}.
From the proof of Theorem \ref{th3.4} it follows that $u^1_n\rightarrow u^1$ q.e. Hence
\begin{equation}
\label{eq3.8}
h_n(X^A)g^1_n(u^1_n(X^A))\rightarrow h(X^A)g^1(u^1(X^A))\quad P^A_x\otimes dA^{\sigma}\mbox{-a.s.}
\end{equation}
for q.e. $x\in \bar D$, where $P^A_x\otimes dA^{\sigma}$ is the product of the measure $P^A_x$ and the kernel $dA^{\sigma}$ from $\Omega$ to $\BB(\BR_+)$.  Moreover,
\[
u^1_n(x)=E^A_xB_{\infty}+E^A_x\int^{\infty}_0
h_n(X^A_t)g^1_n(u^1_n(X^A_t))\,dA^{\sigma}_t
\rightarrow u^1(x),
\]
which together with (\ref{eq3.8}) implies that  the family $\{h_n(X^A)g^1_n(u^1_n(X^A))\}$ is uniformly integrable  with respect to the measure $P^A_x\otimes dA^{\sigma}$ for q.e. $x\in \bar D$. By this and (\ref{eq3.7}), $\{h_n(X^A)g_n(u_n(X^A))\}$ is uniformly integrable. Consequently, for q.e. $x\in \bar D$ we have
\[
\lim_{t\rightarrow0^+}\sup_{n\ge1}
E_x\int^t_0h_n(X^A_s)g_n(u_n(X^A_s))\,dA^{\sigma}_s=0.
\]
By the Markov property,
\[
u_n(x)=E^A_xB_t+E^A_x\int^t_0h_n(X^A_s) g_n(u_n(X^A_s))\,dA^{\sigma}_s+P^A_tu_n(x),\quad t\ge0,
\]
%K:\\ Mamy $B_{s+t}=B_t+B_s\circ\theta^A_t$.  Letting $s\rightarrow\infty$ we get %$B_{\infty}=B_t+B_{\infty}\circ\theta^A_t$. (Dla $B_t=\int^t_0f(X^A_s)\,ds$ oznacza to %$\int^{\infty}_0f(X^A_s)\,ds=\int^t_0...+\int^{\infty}_t
