%\[
%w(x)=E^A_x(B_t+B_{\infty}\circ\theta^A_t)=E^A_xB_t+E^A_{X^A_t}B_{\infty}=
%E^A_xB_t+w(X^A_t)=E^A_xB_t+P^A_tw(x).
%\]
%Podobne rozumowanie stosujemy do $B^n_t:=(h_ng_n(u_n))\cdot A^{\sigma})_t$.\\
