Hence, for q.e. $x\in\bar D$,
\[
\lim_{t\rightarrow t^+}\sup_{n\ge1}|u_n(x)-P^A_tu_n(x)|=0,
\]
which means that condition ($\mbox{M}_1$) of  \cite{K:PA} is satisfied. Let $\BB_1=\{v\in\BB^+(\bar D):v(x)\le1,x\in\bar D\}$. By \cite[Proposition 2.4]{K:PA}, the triple  $(\BM^A,\BB_1,m)$ has the compactness property, so by \cite[Proposition 4.2]{K:PA}, $(\BM^A,[0,u^2],m)$ has the compactness property. Since $u_n\le u^2_n\le u^2$ for $n\ge1$, applying \cite[Theorem 2.2]{K:PA} shows that there is a subsequence (still denoted by $(u_n)$) such that $(u_n)$ converges q.e. as $n\rightarrow\infty$. As in the proof of Theorem \ref{th3.4} we show that its limit $u$ is a probabilistic solution of (\ref{eq1.1}).
We next show that $hg(u)\in L^1(\partial D;\sigma)$.
Let $Y^{n,1}_t=u^1_n(X^A_t)$, $t\ge0$. Then $Y^{n,1}$ is the first component of the solution $(Y^{n,1},M^{n,1})$ of (\ref{eq3.12}) with $g_n$ replaced by $g^1_n$ and $h$ replaced by $h_n$.  By \cite[Theorem IV.68]{P}, for every $t\ge0$,
\begin{align*}
E_x(Y^{n,1}_t-1)^--E_x(Y^{n,1}_0-1)^-
&\ge- E_x\int^t_0\fch_{\{Y^{n,1}_s\le 1\}}\,dY^{n,1}_s\\
&=E_x\int^t_0\fch_{\{Y^{n,1}_s\le 1\}} \{dB_s+h_n(X^A_s)g^1_n(Y^{n,1}_s)\,dA^{\sigma}_s\}.
\end{align*}
Hence
\[
E_x\int^t_0\fch_{\{Y^{n,1}_s\le 1\}}h_n(X^A_s)g_n(Y^{n,1}_s)\,dA^{\sigma}_s\le E_x(Y^{n,1}_t-1)^-,\quad t\ge0.
\]
Letting $t\rightarrow\infty$ yields
\begin{equation}
\label{eq3.13}
E_x\int^{\infty}_0\fch_{\{Y^{n,1}_s\le 1\}} h_n(X^A_s)g^1_n(Y^{n,1}_s)\,dA^{\sigma}_s\le 1.
\end{equation}
Set $\nu_n=\fch_{\{u^1_n\le1\}}h_ng^1_n(u^1_n)\cdot\sigma$. Then  $\nu_n\in S^{(0),\kappa}_0$ since $h_ng^1_n(u^1_n)$ is bounded. Furthermore,
since $1\in H^1(D)$, by (\ref{eq2.5}) we have
$\EE^{\kappa}(U^{\kappa}\nu_n,1)=\langle\nu_n,1\rangle$.
By Lemma \ref{lem3.5}, $G^{\kappa}\nu_n$ is a quasi continuous version of $U^{\kappa}\nu_n$, and  by Schwartz's inequality, $\EE(U^{\kappa}\nu_n,1)=0$ since
$\EE(1,1)=0$. Therefore
\[
\langle\nu_n,1\rangle=\EE^{\kappa}(U^{\kappa}\nu_n,1)=\langle\kappa,G^{\kappa}\nu_n\rangle.
\]
But $G^{\kappa}\nu_n=G^{\kappa}(\varphi_n\cdot\sigma)$ with
$\varphi_n=\fch_{\{u^1_n\le 1\}}h_ng^1_n(u^1_n)$, so   by (\ref{eq3.14})
and (\ref{eq3.13}),
\[
G^{\kappa}\nu_n(x)=E^A_x\int^{\infty}_0 \fch_{\{Y^{n,1}_s\le 1\}} h_n(X^A_s)g^1_n(Y^{n,1}_s)\,dA^{\sigma}_s\le 1.
\]
As a result we obtain
\[
\nu_n(\bar D)\le \kappa(\bar D)=\|\beta\|_{L^1(\partial D;\sigma)}.
\]
Since $u^1_n\nearrow u^1$, letting $n\rightarrow\infty$ and using Fatou's lemma
shows that $\fch_{\{u^1\le 1\}}hg^1(u^1)\in L^1(\partial D;\sigma)$, hence that $hg^1(u^1)\in L^1(\partial D;\sigma)$. From this, inequalities (\ref{eq3.7})
and the fact that $u_n\rightarrow u$ it follows that
$hg(u)\in L^1(\partial D;\sigma)$.
\end{proof}

\subsection{Equations with mixed nonlinearities}

We consider the problem
\begin{equation}
\label{eq3.15}
-L u=\mu\quad\mbox{in }D,\qquad-\frac{\partial u}{\partial{\gamma_a}}
+\beta\cdot u=h(g^1(u)+g^2(u))\quad \mbox{on }\partial D,
\end{equation}
with  $g^1,g^2$ satisfying (\ref{eq1.7}). The proof of the theorem below is a slight modification of the proof of \cite[Theorem 3.11]{K:JFA}.

\begin{theorem}
Assume that $\mu,h$ satisfy \mbox{\rm(\ref{eq1.2})}, $g^1,g^2:(0,\infty)\rightarrow[0,\infty)$ are continuous nonincreasing functions satisfying \mbox{\rm(\ref{eq1.7})}. Then there exsists a unique probabilistic solution of problem \mbox{\rm(\ref{eq3.15})}.
\end{theorem}
\begin{proof}
%P. \cite[Theorem 3.11]{K:JFA}.
Set $h_n=T_n(h)$, $g^1_n(y)=g(y+1/n)$, $g^2_n(y)=g^2(y+1/n)$, $y>0$. By Propositions \ref{eq3.11} and \ref{prop3.5}, there exists a unique probabilistic solution $u_n$ of  problem (\ref{eq3.15}) with $h,g^1,g^2$ replaced by $h_n,g^1_n,g^2_n$, i.e.
\begin{equation}
\label{eq3.18}
u_n(x)=E^A_xB_{\infty}+E^A_x\int^{\infty}_0
(h_n(u^1_n)(X^A_t)+h_n(u^2_n(X^A_t)))\,dA^{\sigma}_t
\end{equation}
for q.e. $x\in\bar D$. By Proposition \ref{prop3.11}, $u_n\le u_{n+1}$, $n\ge1$, q.e. Since $c_1y^{-\gamma_1}\le(g^1+g^2)(y)$ and  $c_1y^{-\gamma_2}\le(g^1+g^2)(y)$, applying Proposition \ref{prop3.11} we also get
\begin{equation}
\label{eq3.17}
v_n\le u_n,\quad w_n\le u_n,\quad n\ge1,\quad\mbox{q.e.}
\end{equation}
where $u^i_n$, $i=1,2$,  is the solution of the problem
\[
(-L+\beta\cdot\sigma)u^i_n=\mu+c_1h_n(u^i_n+1/n)^{-\gamma_i}.
\]
By (\ref{eq3.17}), $u^1_n+u^2_n\le 2u_n$, $n\ge1$, q.e. As in the proof of \cite[Theorem 3.11]{K:JFA},  from this inequality and (\ref{eq1.7}) we deduce that
\begin{equation}
\label{eq3.3}
g^1(u_n+1/n)+g^2(u_n+1/n)\le c_22^{\gamma_1}(u^1_n+1/n)^{-\gamma_1}+c_22^{\gamma_2}(u^2_n+1/n)^{-\gamma_2}.
\end{equation}
The argument following (\ref{eq3.8}) shows that  for $i=1,2$, the sequences $\{(u^i_n+1/n)^{-\gamma_i}\}$ are uniformly integrable with respect to the measure $P^A_x\otimes dA^{\sigma}$, which together with (\ref{eq3.3}) implies that $\{(h_ng^1_n(u^1_n)+h_ng^2_n(u^2_n))(X^A)\}$ is uniformly integrable with respect to $P^A_x\otimes dA^{\sigma}$. Therefore letting $n\rightarrow\infty$ in (\ref{eq3.18}) shows that $u$ defined by $u=\lim_{n\rightarrow\infty}u_n$ is a probabilistic solution of (\ref{eq3.15}).
\end{proof}

\section{Renormalized and weak solutions}

As in previous sections, we assume that $\mu$ is a smooth measure on $D$,   $h, g,\beta$ are nonnegative Borel measurable functions,  and we write $\kappa=\beta\cdot\sigma$.

\subsection{Renormalized solutions}

We begin with renormalized solutions. The following definition is an adaptation of \cite[Definition 3.4]{KR:NoD} to  problem (\ref{eq1.1}) which actually  is regarded as  problem (\ref{eq1.5}) with $\Delta_N$ replaced by the operator associated with the form $\EE$.

Let $\nu$ be a signed Borel measure on $\bar D$, and let $\nu^+$ and $\nu^-$ denote its  positive and negative part, respectively. We call it smooth if $|\nu|=\nu^++\nu^-$ is smooth.  We denote by  $\MM_{0,b}(\bar D)$ the set of all smooth signed  measures $\nu$ on $\bar D$, with respect to the form $\EE$, such that $\|\nu\|_{TV}:=|\nu|(\bar D)<\infty$. By \cite[Lemma 6.1.2]{FOT}, $\nu$ is smooth with respect to $\EE$ if and only if $\nu$  is smooth with respect to $\EE^{\kappa}$.

\begin{definition}
%P. \cite[Definition 3.4]{KR:NoD}, book {def8.7}
Assume that $\mu(D)<\infty$ and  $h\in L^{\infty}(\partial D;\sigma)$. A quasi continuous function $u$ defined q.e on $\bar D$ is a renormalized solution of (\ref{eq1.1}) if

\begin{enumerate}
\item[(a)] $u$ is quasi continuous, $u>0$ q.e. in $\bar D$, $hg(u)\in L^1(\partial D;\sigma)$ and $T_k(u)\in H^1(D)$ for every $k>0$;

\item[(b)] there exists a sequence $\{\nu_k\}\subset\MM_{0,b}(\bar D)$ such that $\lim_{k\rightarrow\infty}\|\nu_k\|_{TV}=0$ and for every $k>0$
	and every bounded quasi continuous version $\tilde v$ of  $v\in H^1(D)$,
\[
\EE^{\kappa}(T_k(u),v) =\langle \mu+hg(u)\cdot\sigma,\tilde
v\rangle +\langle\nu_{k},\tilde v\rangle.
\]
\end{enumerate}

Note that by \cite[Theorem 2.1.3]{FOT}, each $v\in H^1(D)$ has a quasi continuous modification.
%(Czy $\nu_k$ sa nieujemne? Jeszcze entropijne?)
\end{definition}

\begin{theorem}
\label{th4.2}
Under the assumptions of Theorem \ref{th3.6} there exists a renormalized solution of \mbox{\rm(\ref{eq1.1})} such that $hg(u)\in L^1(\partial D;\sigma)$. If moreover $g$ is nonincreasing, then there is a unique renormalized solution   and it is the unique probabilistic solution.
\end{theorem}
\begin{proof}
From Theorem \ref{th3.6} we know that there exists a probabilistic solution $u$ such that $hg(u)\in L^1(\partial D;\sigma)$. Since $\mu,\sigma$ are smooth bounded measures,  $\mu+hg(u)\cdot\sigma\in\MM_{0,b}(\bar D)$. Therefore $u$ is a renormalized solution by
\cite[Theorem 3.5]{KR:NoD} applied to the form $\EE^{\kappa}$. The second part follows from the first one, Theorem \ref{th3.4} and \cite[Theorem 3.5]{KR:NoD} again.
\end{proof}

The following regularity results follow directly from general results for equations with smooth measure data and operators associated with transient symmetric Dirichlet forms.

\begin{proposition}
\label{prop4.3}
Let the assumptions of Theorem \ref{th3.6} hold and let $u$ be a renormalized solution of \mbox{\rm(\ref{eq1.1})} such that $hg(u)\in L^1(\partial D;\sigma)$. Then,
for every $k>0$, $T_k(u)\in H^1(D)$ and \mbox{\rm(\ref{eq1.8})} is satisfied.
If, in addition, $\mu=0$, then $u^{(\gamma+1)/2}\in H^1(D)$ and \mbox{\rm(\ref{eq1.9})} is satisfied for some constant $c(\gamma)>0$.
\end{proposition}
\begin{proof}
The first part follows from \cite[Proposition 5.9]{KR:JFA} and the second from \cite[Theorem 4.6]{K:JFA}.
\end{proof}

For $r>0$ we denote by $M^r(D;m)$ the Marcinkiewicz space of order $r$. It is the set of  measurable functions $v$ on $D$ such that the distribution function corresponding to  $m$, that is
the function $\lambda_m(t)=m(\{x\in D: |v(x)|\ge t\})$, $t>0$, satisfies  estimate of the form $\lambda_m(t)\le Ct^{-r}$ for some $C>0$. Similarly, by using the distribution function corresponding  to $\sigma$, we define the Marcinkiewicz space $M^r(\partial D;\sigma)$.

\begin{corollary}
Under the assumptions of Theorem \ref{th3.6},  $u$ of Proposition \ref{prop4.3} has the property that
$u\in M^{(d-1)/(d-2)}(\partial D;\sigma)$ and
$u\in M^{d/(d-2)}(D;m)$, $|\nabla u|\in M^{d/(d-1)}(D;m)$.
\end{corollary}
\begin{proof}
Follows from (\ref{eq1.8}), (\ref{eq2.1}) and known results (see \cite[Lemmas 4.1, 4.2]{BBGGPV} and  \cite[p. 11]{DOS}).
\end{proof}
