From Theorem \ref{th4.2} we know that for nonincreasing $g$ renormalized solutions coincide with  probabilistic solutions. As a simple  application of this fact and Proposition \ref{prop3.7} we get the following stability result.

\begin{proposition}
Assume that  $\mu=f\cdot m$, $\mu_n=f_n\cdot m$, $n\ge1$, for some $f,f_n\in L^1(D;m)$. Assume also that
$\beta,h,g$ satisfy the assumptions of Theorem \ref{th3.4} and $\|h\|_{L^1(\partial D;\sigma)}>0$. Let $u$ be the unique renormalized solution of \mbox{\rm(\ref{eq1.1})} and $u_n$ be the renormalized solution of \mbox{\rm(\ref{eq1.1})} with $\mu$ replaced by $\mu_n$. 	If $f_n\rightarrow f $ in $L^1(D;m)$ and $f_n\le F$ for some $F\in L^1(D;m)$. Then $u_n\rightarrow u$ q.e. in $\bar D$.
\end{proposition}
\begin{proof}	
By Proposition \ref{prop3.7}, for each $n\ge1$ there exists a process $M^n$ such that $M^n$ is a martingale under $P^A_x$ for q.e. $x\in\bar D$ and  the pair $(Y^n=u_n(X^A),M^n)$ is the solution of (\ref{eq3.4}) with $B$ replaced by $B^n_t=\int^t_0f_n(X^A_s)\,ds$, $t\ge0$. Hence
\[
Y^n_t=Y^n_0-\int^t_0f_n(X^A_s)\,ds-\int^t_0h(X^A_s)g(Y^n_s)\,dA^{\sigma}_s
+\int^t_0dM^n_s,\quad t\ge0.
\]	
Similarly, 	for $(Y=u(X^A),M)$ of Proposition \ref{prop3.7} we have
\[
Y_t=Y_0-\int^t_0f(X^A_s)\,ds-\int^t_0h(X^A_s)g(Y_s)\,dA^{\sigma}_s
+\int^t_0dM_s,\quad t\ge0.
\]	
Applying the It\^o--Tanaka formula we get
\[
|Y^n_t-Y_t|-|Y^n_0-Y_0|\ge\int^t_0\mbox{sgn}(Y^n_s-Y_s)\,d(Y^n_s-Y_s),\quad t\ge0,\quad P_x\mbox{-a.s.}
\]
for q.e. $x\in \bar D$. Hence
\begin{align*}
E_x|Y^n_0-Y_0|&\le E^A_x\int^{\infty}_0\mbox{sgn}(Y^n_s-Y_s)(f_n(X^A_s)-f(X^A_s))\,ds\\
&\quad+E^A_x\int^{\infty}_0\mbox{sgn}(Y^n_s-Y_s)
h(X^A_s)(g(Y^n_s)-g(Y_s))\,dA^{\sigma}_t.
\end{align*}
The second integral on the rigt-hand side of the above inequality is less then or equal to zero. Therefore
\begin{equation}
\label{eq4.2}
|u_n(x)-u(x)|\le E^A_x\int^{\infty}_0|f_n-f|(X^A_s)\,ds=G^{\kappa}|f_n-f|(x).
\end{equation}		
For q.e. $x\in\bar D$, $G^{\kappa}(x,y)|f_n-f|(y)\le 2G^{\kappa}(x,y)F(y)$, $y\in D$, and,
since $F\in L^1(D;m)$, $G^{\kappa}F(x)=R^AF(x)<\infty$ for q.e. $x\in\bar D$. Hence,  for   q.e. $x\in\bar D$, the function $D\ni y\mapsto G^{\kappa}(x,y)F(y)$ is integrable. Therefore letting $n\rightarrow\infty$ in (\ref{eq4.2}) and applying the dominated convergence theorem shows that $u_n(x)\rightarrow u(x)$ for q.e. $x\in\bar D$.
%\[
%G^{\kappa}|f_n-f|(x)=\int_{D}G^{\kappa}(x,y)|f_n(y)-f(y)|\,dy\rightarrow0
%\]
%by the dominated convergece theorem (bo  $G^{\kappa}(x,\cdot)|f_n-f|\rightarrow0$ for %$m$-a.e. $y\in D$).
\end{proof}


\subsection{Weak solutions}

\begin{definition}
A function $u\in H^1(D)$ is a weak solution of (\ref{eq1.1}) if $u>0$ $m$-a.e. and
\begin{equation}
\label{eq4.1}
\EE^{\kappa}(u,v)=\langle\mu,v\rangle+\int_{\partial D}hg(u)v\,d\sigma,
\quad v\in H^1(D)\cap L^{\infty}(\partial D;\sigma).
\end{equation}
\end{definition}

\begin{proposition}
\label{prop4.5}
If $u$ is a probabilistic solution of \mbox{\rm(\ref{eq1.1})} such that $\nu\in S^{(0),\kappa}_0$, where $\nu=\mu+hg(u)\cdot\sigma$,  then $u$ is a weak solution.
%If $u$ is a weak solution  and $f\in L^1(D;m)$, $hg(u)\in L^1(\partial D;\sigma)$, then %$\tilde u$ is a probabilistic solution (potrzebne?)
\end{proposition}
\begin{proof}
%(P. book, prop8.11).
By Proposition \ref{prop3.3}, $u=G^{\kappa}\nu$. Since $\nu\in S^{(0),\kappa}_0$,  the function $G^{\kappa}\nu$ is an $m$-version of the potential $U^{\kappa}\nu$.
Therefore $u\in H^1(D)$ and, by (\ref{eq2.5}), it satisfies (\ref{eq4.1}).
\end{proof}

Unfortunately, we are able to check that $\nu$ of Proposition \ref{prop4.5} is of class
$S^{(0),\kappa}_0$ only in some very special situations.

In the remainder of this subsection, we assume that $\mu(dx)=f\cdot m$ for some nonnegative Borel function on $D$.

\begin{proposition}
\label{prop4.6}
Let  the assumptions of Theorem \ref{th3.6} hold and let $u$ be a solution such that $u\ge\delta$ for some constant $\delta>0$.  If, in addition,
 $f\in L^p(D;m)$ with $p=2d/(d+2)$ and $h\in L^q(\partial D;\sigma)$ with $q=
2(d-1)/d$, then $u$ is a weak solution of \mbox{\rm(\ref{eq1.1})}.
\end{proposition}
\begin{proof}
By Proposition \ref{prop4.5}, it suffices to check that $f\cdot m,hg(u)\cdot\sigma $ are measures of finite 0-energy  integral. Write $p'=2d/(d-2)$, $q'=2(d-1)/(d-2)$.
By H\"older's inequality  and Sobolev's inequality, for $v\in H^1(D)\cap C(\bar D)$ we have
\[
\int_D|v|f\,dx\le \|f\|_{L^{p}(D;m)}\|v\|_{L^{p'}(D;m)},\quad
\|v\|_{L^{p'}(D;m)}\le c\|v\|_{H^1(D)}.
\]
Hence $f\cdot m\in S^{(0),\kappa}_0$. Furthermore, by H\"older's inequality and the  trace theorem (see, e.g., \cite[Chapter 2, Theorem 4.2]{N}, % \cite[(1.5)]{DOS}), (p. \cite[(2.12)]{DOS},
\[
\int_{\partial D}|v|h\,d\sigma\le
\|h\|_{L^{q}(\partial D;\sigma)}\|v\|_{L^{q'}(\partial D;\sigma)},\qquad \|v\|_{L^{q'}(\partial D;\sigma)}\le c\|v\|_{H^1(D)},
\]
which implies that $g(u)\cdot\sigma\in S^{(0),\kappa}_0$ since $g(u)\le c_2\delta^{-\gamma}$.
\end{proof}

\begin{remark}
\label{rem4.8}
The argument used in Proposition \ref{prop4.6}  to prove that $g(u)\cdot\sigma\in S^{(0),\kappa}_0$ does not take into account assumption (\ref{eq1.4}). Using (\ref{eq1.4}) one can show the existence of a weak solution under slightly weaker  integrability assumption imposed on $h$. Namely, as observed in \cite{DOS}, it suffices to assume that $h\in L^r(\partial D;\sigma)$ with $r=2(d-1)/(d+\gamma(d-2))$.
%To see this, we can argue as follows. Let  $h_n=T_n(h)$. From Proposition \ref{prop4.6} it %follows that there exists a weak solution $u_n$ of (\ref{eq1.1}) with $h$ replaced by %$h_n$ ($\delta$ musi byc niezalezne od $n$), i.e. (dalej zakomentowane)
%\[
%\EE^{\kappa}(u_n,u_n)\le %c\|f\|_{L^p(D;m)}\|u_n\|_{H^1(D)}+\bar\beta^{1-\gamma}\|h\|_{L^1(\partial D;\sigma)}
%\]
%Using (\ref{eq2.1}) and Young's inequality we get $\sup_{n\ge1}\|u_n\|_{H^1(D)}<\infty$ i %dalej rozumujemy jak w \cite[s. 8]{DOS}.
\end{remark}

We shall see that the condition  $u\ge\delta$ appearing in Proposition \ref{prop4.6} is satisfied in the case where $\BM^A$ strong Feller. A known probabilistic criterion for this to hold is given below.

\begin{lemma}
\label{lem4.9}
If
\begin{equation}
	\label{eq4.7}
	\lim_{t\downarrow0}\sup_{x\in\bar D}E_x(1-e^{-A_t})=0,
\end{equation}
then the semigroup $(P^A_t)_{t>0}$ is strong Feller.
\end{lemma}
\begin{proof}
For any bounded $f\in\BB^+(\bar D)$ and $s>0$,
\[
\sup_{x\in\bar D}|P^A_sf(x)-P_sf(x)|\le\|f\|_{\infty}\sup_{x\in\bar D}E_x(1-e^{-A_s}).
\]
Furthermore, for any $0\le s<t$, $P_sP^A_{t-s}f$ is continuous  (since $\BM$ is strong Feller) and
\begin{align*}
	\sup_{x\in\bar D}|P^A_tf(x)-P_sP^A_{t-s}f(x)|&=\sup_{x\in\bar D} |P^A_sP^A_{t-s}f(x)-P_sP^A_{t-s}f(x)|\\
	&\le\|f\|_{\infty}\sup_{x\in\bar D}|P^A_sf(x)-P_sf(x)|.
\end{align*}
from which the results follows.
\end{proof}

\begin{proposition}
\label{prop4.9}
Let \mbox{\rm(\ref{eq4.7})} hold. If $f\in\BB^+(D)$ and  $\|f\|_{L^1(D;m)}>0$, then there is $\delta>0$ such that  $R^Af(x)\ge\delta$ for all $x\in\bar D$.
\end{proposition}
\begin{proof}
Choose $k>0$ so that $\|f_k\|_{L^1(D;m)}>0$, where $f_k=f\wedge k$. By Lemma \ref{lem4.9}, $P^A_tf_k\in C_b(\bar D)$ for $t>0$, so
$R^A_1f_k$ is continuous on $\bar D$, and hence attains its minimum, say $\delta$, in $D$. On the other hand, from  Lemma \ref{lem3.4} it follows that  $R^A_1f_k>0$ q.e. in $\bar D$. Thus, in fact, $R^A_1f_k(x)\ge\delta$ for $x\in\bar D$. This proves the proposition since obviously $R^Af\ge R^A_1f_k\ge R^A_1f_k$.
\end{proof}

\begin{corollary}
\label{cor4.11}
Let $\beta$ satisfy  \mbox{\rm(\ref{eq1.3})},    $f\in\BB^+(D)$ and  $\|f\|_{L^1(D;m)}>0$, $f\in L^p(D;m)$ with $p=2d/(d+2)$,  $h\in L^r(\partial D;\sigma)$ with $r=2(d-1)/(d+\gamma(d-2))$ and $g$ be a continuous function satisfying \mbox{\rm(\ref{eq1.4})}. If $a$ is smooth, then  there exists a weak solution of \mbox{\rm(\ref{eq1.1})}.
\end{corollary}
\begin{proof}
From  \cite[Proposition 6.1]{M} it follows that  (\ref{eq4.7}) is satisfied for bounded Lipschitz domains and smooth $a$ satisfying (\ref{eq2.7}). Therefore the desired result follows from Propositions \ref{prop4.6}, \ref{prop4.9}  and Remark \ref{rem4.8}.
\end{proof}

By applying Corollary \ref{cor4.11} to  $a=I_d$ (i.e. to $L=\Delta$) we get \cite[Theorem 2.2]{DOS}.

